module decoder_64b66b (
    input  logic         clk_in,                // Clock signal
    input  logic         rst_in,                // Asynchronous reset (active high)
    input  logic         decoder_data_valid_in, // Input data valid signal
    input  logic [65:0]  decoder_data_in,       // 66-bit encoded input
    output logic [63:0]  decoder_data_out,      // Decoded 64-bit data output
    output logic [7:0]   decoder_control_out,   // Decoded 8-bit control output
    output logic         sync_error,            // Sync error flag
    output logic         decoder_error_out      // Type field error flag
);

    logic [1:0]  sync_header;
    logic [7:0]  type_field;
    logic [63:0] data_in;
    logic        type_field_valid;
    logic        decoder_wrong_ctrl_received;
    logic        decoder_wrong_type_field;

    assign sync_header = decoder_data_in[65:64];
    assign type_field  = decoder_data_in[63:56];
    assign data_in     = decoder_data_in[55:0];

    // Canonical control-character values
    localparam logic [7:0] C_I = 8'h07; // Idle
    localparam logic [7:0] C_S = 8'hFB; // Start of frame
    localparam logic [7:0] C_T = 8'hFD; // End of frame
    localparam logic [7:0] C_E = 8'hFE; // Error
    localparam logic [7:0] C_Q = 8'h9C; // Ordered set

    // Input data bytes (the low 56 bits hold up to seven data bytes B0..B6)
    logic [7:0] b0, b1, b2, b3, b4, b5, b6;
    assign b0 = data_in[7:0];
    assign b1 = data_in[15:8];
    assign b2 = data_in[23:16];
    assign b3 = data_in[31:24];
    assign b4 = data_in[39:32];
    assign b5 = data_in[47:40];
    assign b6 = data_in[55:48];

    // Data-only-mode payload (hoisted out of the procedural block)
    wire [63:0] data_pass = decoder_data_in[63:0];

    // Combinational decode for control/mixed mode (sync_header == 2'b10)
    logic [63:0] ctrl_data;
    logic [7:0]  ctrl_ctrl;
    logic        type_valid;

    always_comb begin
        type_valid = 1'b1;
        ctrl_ctrl  = 8'b0;
        ctrl_data  = 64'b0;
        case (type_field)
            8'h1E: begin ctrl_ctrl = 8'b11111111; ctrl_data = {C_E, C_E, C_E, C_E, C_E, C_E, C_E, C_E}; end
            8'h33: begin ctrl_ctrl = 8'b00011111; ctrl_data = {b6,  b5,  b4,  C_S, C_I, C_I, C_I, C_I}; end
            8'h78: begin ctrl_ctrl = 8'b00000001; ctrl_data = {b6,  b5,  b4,  b3,  b2,  b1,  b0,  C_S}; end
            8'h87: begin ctrl_ctrl = 8'b11111110; ctrl_data = {C_I, C_I, C_I, C_I, C_I, C_I, C_I, C_T}; end
            8'h99: begin ctrl_ctrl = 8'b11111110; ctrl_data = {C_I, C_I, C_I, C_I, C_I, C_I, C_T, b0 }; end
            8'hAA: begin ctrl_ctrl = 8'b11111100; ctrl_data = {C_I, C_I, C_I, C_I, C_I, C_T, b1,  b0 }; end
            8'hB4: begin ctrl_ctrl = 8'b11111000; ctrl_data = {C_I, C_I, C_I, C_I, C_T, b2,  b1,  b0 }; end
            8'hCC: begin ctrl_ctrl = 8'b11110000; ctrl_data = {C_I, C_I, C_I, C_T, b3,  b2,  b1,  b0 }; end
            8'hD2: begin ctrl_ctrl = 8'b11100000; ctrl_data = {C_I, C_I, C_T, b4,  b3,  b2,  b1,  b0 }; end
            8'hE1: begin ctrl_ctrl = 8'b11000000; ctrl_data = {C_I, C_T, b5,  b4,  b3,  b2,  b1,  b0 }; end
            8'hFF: begin ctrl_ctrl = 8'b10000000; ctrl_data = {C_T, b6,  b5,  b4,  b3,  b2,  b1,  b0 }; end
            8'h2D: begin ctrl_ctrl = 8'b00011111; ctrl_data = {b6,  b5,  b4,  C_Q, C_I, C_I, C_I, C_I}; end
            8'h4B: begin ctrl_ctrl = 8'b11110001; ctrl_data = {C_I, C_I, C_I, C_I, b2,  b1,  b0,  C_Q}; end
            8'h55: begin ctrl_ctrl = 8'b00010001; ctrl_data = {b6,  b5,  b4,  C_Q, b2,  b1,  b0,  C_Q}; end
            8'h66: begin ctrl_ctrl = 8'b00010001; ctrl_data = {b6,  b5,  b4,  C_S, b2,  b1,  b0,  C_Q}; end
            default: begin type_valid = 1'b0; ctrl_ctrl = 8'b0; ctrl_data = 64'b0; end
        endcase
    end

    assign type_field_valid = type_valid;

    // Next-state decode (combinational) registered with one cycle of latency
    logic [63:0] nxt_data;
    logic [7:0]  nxt_ctrl;
    logic        nxt_sync_err;
    logic        nxt_dec_err;

    always_comb begin
        nxt_data                    = 64'b0;
        nxt_ctrl                    = 8'b0;
        nxt_sync_err                = 1'b0;
        decoder_wrong_type_field    = 1'b0;
        decoder_wrong_ctrl_received = 1'b0; // no control-pattern mismatch modelled
        if (decoder_data_valid_in) begin
            case (sync_header)
                2'b01: begin
                    // Data-only mode: the lower 64 bits are payload data
                    nxt_data = data_pass;
                    nxt_ctrl = 8'b0;
                end
                2'b10: begin
                    // Control / mixed mode: decode via the type field
                    if (type_valid) begin
                        nxt_data = ctrl_data;
                        nxt_ctrl = ctrl_ctrl;
                    end else begin
                        decoder_wrong_type_field = 1'b1;
                        nxt_data = 64'b0;
                        nxt_ctrl = 8'b0;
                    end
                end
                default: begin
                    // Invalid sync header
                    nxt_sync_err = 1'b1;
                    nxt_data     = 64'b0;
                    nxt_ctrl     = 8'b0;
                end
            endcase
        end
        nxt_dec_err = decoder_wrong_type_field | decoder_wrong_ctrl_received;
    end

    always_ff @(posedge clk_in or posedge rst_in) begin
        if (rst_in) begin
            decoder_data_out    <= 64'b0;
            decoder_control_out <= 8'b0;
            sync_error          <= 1'b0;
            decoder_error_out   <= 1'b0;
        end else begin
            decoder_data_out    <= nxt_data;
            decoder_control_out <= nxt_ctrl;
            sync_error          <= nxt_sync_err;
            decoder_error_out   <= nxt_dec_err;
        end
    end

endmodule

module encoder_64b66b (
    input  logic         clk_in,              // Clock signal
    input  logic         rst_in,              // Asynchronous reset (active high)
    input  logic [63:0]  encoder_data_in,     // 64-bit data input
    input  logic [7:0]   encoder_control_in,  // 8-bit control input
    output logic [65:0]  encoder_data_out     // 66-bit encoded output
);

    // Area-optimised 64b/66b encode (control-only / mixed mode).  The original
    // get_output() ran sixteen full-width data comparators and a parallel 56-bit
    // payload case that re-tested the same patterns; for every legal block-type
    // the type field is determined by the control word (with a single-byte tie-
    // breaker for the three multi-type controls 0xFF / 0x1F / 0x11) and the
    // payload is a fixed lane re-arrangement of the data, so the wide comparators
    // are redundant LUT mass.  This collapses both type and payload to a compact
    // control-keyed form, preserving the encode mapping while cutting cells/wires.
    function automatic [63:0] encode64(input [63:0] d, input [7:0] c);
        reg [7:0]  tf;
        reg [55:0] pw;
        begin
            case (c)
                8'b11111111: begin
                    tf = (d[7:0] == 8'hFD) ? 8'h87 : 8'h1e;
                    pw = (d[7:0] == 8'hFE) ? {8{7'h1E}} : 56'h0;
                end
                8'b00011111: begin
                    tf = (d[39:32] == 8'h9C) ? 8'h2d : 8'h33;
                    pw = {d[63:40], (d[39:32] == 8'h9C) ? 4'hF : 4'h0, 28'h0};
                end
                8'b00000001: begin tf = 8'h78; pw = d[63:8]; end
                8'b11111110: begin tf = 8'h99; pw = {48'h0, d[7:0]};  end
                8'b11111100: begin tf = 8'haa; pw = {40'h0, d[15:0]}; end
                8'b11111000: begin tf = 8'hb4; pw = {32'h0, d[23:0]}; end
                8'b11110000: begin tf = 8'hcc; pw = {24'h0, d[31:0]}; end
                8'b11100000: begin tf = 8'hd2; pw = {16'h0, d[39:0]}; end
                8'b11000000: begin tf = 8'he1; pw = {8'h0,  d[47:0]}; end
                8'b10000000: begin tf = 8'hff; pw = d[55:0]; end
                8'b11110001: begin tf = 8'h4b; pw = {28'h0, d[31:8], 4'hF}; end
                8'b00010001: begin
                    tf = (d[39:32] == 8'h9C) ? 8'h55 : 8'h66;
                    pw = {d[63:40], (d[39:32] == 8'h9C) ? 8'hFF : 8'h0F, d[31:8]};
                end
                default: begin tf = 8'h00; pw = 56'h0; end
            endcase
            encode64 = {tf, pw};
        end
    endfunction

    // Single registered output stage (one clock-cycle latency).  Folding the
    // encode ahead of one 66-bit register removes the duplicated data path and
    // ~half the flops the original carried while preserving the latency.
    logic [65:0] encoded_next;

    assign encoded_next = (encoder_control_in == 8'b00000000)
        ? {2'b01, encoder_data_in}
        : {2'b10, encode64(encoder_data_in, encoder_control_in)};

    always_ff @(posedge clk_in or posedge rst_in) begin
        if (rst_in)
            encoder_data_out <= 66'b0;
        else
            encoder_data_out <= encoded_next;
    end

endmodule

module ahb_clock_counter #(
    parameter ADDR_WIDTH = 32, // Width of the address bus
    parameter DATA_WIDTH = 32  // Width of the data bus
)(
    input wire HCLK,                       // AHB Clock
    input wire HRESETn,                    // AHB Reset (Active Low)
    input wire HSEL,                       // AHB Select
    input wire [ADDR_WIDTH-1:0] HADDR,     // AHB Address
    input wire HWRITE,                     // AHB Write Enable
    input wire [DATA_WIDTH-1:0] HWDATA,    // AHB Write Data
    input wire HREADY,                     // AHB Ready Signal
    output reg [DATA_WIDTH-1:0] HRDATA,    // AHB Read Data
    output reg HRESP,                      // AHB Response
    output reg [DATA_WIDTH-1:0] COUNTER    // Counter Output
);

    // Register address map
    localparam [DATA_WIDTH-1:0] ADDR_START    = 'h00; // write 1 to start/resume
    localparam [DATA_WIDTH-1:0] ADDR_STOP     = 'h04; // write 1 to stop
    localparam [DATA_WIDTH-1:0] ADDR_COUNTER  = 'h08; // read current counter
    localparam [DATA_WIDTH-1:0] ADDR_OVERFLOW = 'h0C; // read overflow flag
    localparam [DATA_WIDTH-1:0] ADDR_MAXCNT   = 'h10; // write max-count limit

    // Internal state
    reg                  enable;     // counting enabled
    reg                  overflow;   // sticky overflow flag
    reg [DATA_WIDTH-1:0] max_count;  // configurable overflow limit

    // AHB address-phase pipeline (signals captured one cycle ahead of data)
    reg [ADDR_WIDTH-1:0] addr_phase_addr;
    reg                  addr_phase_write;
    reg                  addr_phase_sel;

    // Capture the address phase when the bus is ready
    always @(posedge HCLK or negedge HRESETn) begin
        if (!HRESETn) begin
            addr_phase_addr  <= {ADDR_WIDTH{1'b0}};
            addr_phase_write <= 1'b0;
            addr_phase_sel   <= 1'b0;
        end else if (HREADY) begin
            addr_phase_addr  <= HADDR;
            addr_phase_write <= HWRITE;
            addr_phase_sel   <= HSEL;
        end
    end

    // Register writes (data phase) and counter / overflow behaviour
    always @(posedge HCLK or negedge HRESETn) begin
        if (!HRESETn) begin
            enable    <= 1'b0;
            overflow  <= 1'b0;
            max_count <= {DATA_WIDTH{1'b0}};
            COUNTER   <= {DATA_WIDTH{1'b0}};
        end else begin
            // Data-phase register write
            if (addr_phase_sel && addr_phase_write && HREADY) begin
                case (addr_phase_addr)
                    ADDR_START:  enable    <= 1'b1; // start / resume
                    ADDR_STOP:   enable    <= 1'b0; // stop, retain value
                    ADDR_MAXCNT: max_count <= HWDATA;
                    default:     ; // no-op
                endcase
            end

            // Counting: increment while enabled until the limit is reached,
            // then latch the sticky overflow flag (cleared only by reset).
            if (enable && !overflow) begin
                if (COUNTER == max_count)
                    overflow <= 1'b1;
                else
                    COUNTER <= COUNTER + {{(DATA_WIDTH-1){1'b0}}, 1'b1};
            end
        end
    end

    // Combinational read data based on the captured (address-phase) address
    always @(*) begin
        case (addr_phase_addr)
            ADDR_COUNTER:  HRDATA = COUNTER;
            ADDR_OVERFLOW: HRDATA = {{(DATA_WIDTH-1){1'b0}}, overflow};
            ADDR_MAXCNT:   HRDATA = max_count;
            default:       HRDATA = {DATA_WIDTH{1'b0}};
        endcase
    end

    // Always OKAY
    always @(*) begin
        HRESP = 1'b0;
    end

endmodule : ahb_clock_counter

// APB DSP Operation Module (fixed: PSLVERR added, glitch-free clock selection,
// CDC-safe clock-domain select, no-wait-state APB handshake).
module apb_dsp_op #(
    parameter ADDR_WIDTH = 'd8,
    parameter DATA_WIDTH = 'd32
) (
    input  logic                  clk_dsp,    // Faster clock to DSP operation
    input  logic                  en_clk_dsp, // Enable DSP operation with faster clock
    input  logic                  PCLK,       // APB clock
    input  logic                  PRESETn,    // Active low asynchronous APB Reset
    input  logic [ADDR_WIDTH-1:0] PADDR,      // APB address
    input  logic                  PWRITE,     // Write/Read enable
    input  logic [DATA_WIDTH-1:0] PWDATA,     // Write data
    input  logic                  PSEL,       // DSP selector
    input  logic                  PENABLE,    // APB enable
    output logic [DATA_WIDTH-1:0] PRDATA,     // Read data
    output logic                  PREADY,     // Ready signal
    output logic                  PSLVERR     // Error signal
);

    // ── Glitch-free clock selection (replaces the direct combinational MUX) ──
    // Each clock domain owns a 2-flop enable, cross-coupled for mutual
    // exclusion and clocked on the falling edge so the gating enable only
    // changes while its clock is low.  On reset the PCLK path is selected.
    logic dsp_clk_sel;
    logic en0_meta, en0;   // PCLK path enable (selected when en_clk_dsp == 0)
    logic en1_meta, en1;   // clk_dsp path enable (selected when en_clk_dsp == 1)

    always_ff @(negedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            en0_meta <= 1'b1;
            en0      <= 1'b1;
        end else begin
            en0_meta <= ~en_clk_dsp & ~en1;
            en0      <= en0_meta;
        end
    end
    always_ff @(negedge clk_dsp or negedge PRESETn) begin
        if (!PRESETn) begin
            en1_meta <= 1'b0;
            en1      <= 1'b0;
        end else begin
            en1_meta <= en_clk_dsp & ~en0;
            en1      <= en1_meta;
        end
    end
    assign dsp_clk_sel = (PCLK & en0) | (clk_dsp & en1);

    // Internal registers address map
    localparam ADDRESS_A         = 32'h0;  // 0x00
    localparam ADDRESS_B         = 32'h4;  // 0x04
    localparam ADDRESS_C         = 32'h8;  // 0x08
    localparam ADDRESS_O         = 32'hC;  // 0x0C
    localparam ADDRESS_CONTROL   = 32'h10; // 0x10
    localparam ADDRESS_WDATA     = 32'h14; // 0x14
    localparam ADDRESS_SRAM_ADDR = 32'h18; // 0x18

    // Control modes
    localparam SRAM_WRITE     = 32'd1;
    localparam SRAM_READ      = 32'd2;
    localparam DSP_READ_OP_A  = 32'd3;
    localparam DSP_READ_OP_B  = 32'd4;
    localparam DSP_READ_OP_C  = 32'd5;
    localparam DSP_WRITE_OP_O = 32'd6;

    localparam SRAM_DEPTH = 64;

    // Internal registers
    logic [DATA_WIDTH-1:0] reg_operand_a;
    logic [DATA_WIDTH-1:0] reg_operand_b;
    logic [DATA_WIDTH-1:0] reg_operand_c;
    logic [DATA_WIDTH-1:0] reg_operand_o;
    logic [DATA_WIDTH-1:0] reg_control;
    logic [DATA_WIDTH-1:0] reg_wdata_sram;
    logic [DATA_WIDTH-1:0] reg_addr_sram;

    logic signed [DATA_WIDTH-1:0] wire_op_a;
    logic signed [DATA_WIDTH-1:0] wire_op_b;
    logic signed [DATA_WIDTH-1:0] wire_op_c;
    logic signed [DATA_WIDTH-1:0] wire_op_o;
    logic        [DATA_WIDTH-1:0] sram_data_in;
    logic                         sram_we;
    logic        [DATA_WIDTH-1:0] sram_addr;
    logic        [DATA_WIDTH-1:0] sram_data_out;

    // Address-validity + SRAM-bounds checks for PSLVERR
    logic paddr_valid;
    logic sram_oob;
    always_comb begin
        paddr_valid = (PADDR == ADDRESS_A[ADDR_WIDTH-1:0])       ||
                      (PADDR == ADDRESS_B[ADDR_WIDTH-1:0])       ||
                      (PADDR == ADDRESS_C[ADDR_WIDTH-1:0])       ||
                      (PADDR == ADDRESS_O[ADDR_WIDTH-1:0])       ||
                      (PADDR == ADDRESS_CONTROL[ADDR_WIDTH-1:0]) ||
                      (PADDR == ADDRESS_WDATA[ADDR_WIDTH-1:0])   ||
                      (PADDR == ADDRESS_SRAM_ADDR[ADDR_WIDTH-1:0]);
        // An SRAM access whose target index is beyond the array is out of bounds
        sram_oob = ((reg_control == SRAM_WRITE) || (reg_control == SRAM_READ)) &&
                   (reg_addr_sram >= SRAM_DEPTH);
    end

    // APB write registers (synchronous)
    always_ff @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            reg_operand_a  <= 'd0;
            reg_operand_b  <= 'd0;
            reg_operand_c  <= 'd0;
            reg_operand_o  <= 'd0;
            reg_control    <= 'd0;
            reg_wdata_sram <= 'd0;
            reg_addr_sram  <= 'd0;
        end else if (PSEL && PENABLE && PWRITE) begin
            case (PADDR)
                ADDRESS_A[ADDR_WIDTH-1:0]         : reg_operand_a  <= PWDATA;
                ADDRESS_B[ADDR_WIDTH-1:0]         : reg_operand_b  <= PWDATA;
                ADDRESS_C[ADDR_WIDTH-1:0]         : reg_operand_c  <= PWDATA;
                ADDRESS_O[ADDR_WIDTH-1:0]         : reg_operand_o  <= PWDATA;
                ADDRESS_CONTROL[ADDR_WIDTH-1:0]   : reg_control    <= PWDATA;
                ADDRESS_WDATA[ADDR_WIDTH-1:0]     : reg_wdata_sram <= PWDATA;
                ADDRESS_SRAM_ADDR[ADDR_WIDTH-1:0] : reg_addr_sram  <= PWDATA;
                default                           : ; // invalid -> flagged via PSLVERR
            endcase
        end
    end

    // APB read / handshake (no wait states: PREADY & PSLVERR valid in access phase)
    always_comb begin
        PREADY  = 1'b0;
        PSLVERR = 1'b0;
        PRDATA  = {DATA_WIDTH{1'b0}};
        if (PSEL && PENABLE) begin
            PREADY  = 1'b1;
            PSLVERR = (~paddr_valid) | sram_oob;
            if (!PWRITE) begin
                if (reg_control == SRAM_READ) begin
                    PRDATA = sram_data_out;
                end else begin
                    case (PADDR)
                        ADDRESS_A[ADDR_WIDTH-1:0]         : PRDATA = reg_operand_a;
                        ADDRESS_B[ADDR_WIDTH-1:0]         : PRDATA = reg_operand_b;
                        ADDRESS_C[ADDR_WIDTH-1:0]         : PRDATA = reg_operand_c;
                        ADDRESS_O[ADDR_WIDTH-1:0]         : PRDATA = reg_operand_o;
                        ADDRESS_CONTROL[ADDR_WIDTH-1:0]   : PRDATA = reg_control;
                        ADDRESS_WDATA[ADDR_WIDTH-1:0]     : PRDATA = reg_wdata_sram;
                        ADDRESS_SRAM_ADDR[ADDR_WIDTH-1:0] : PRDATA = reg_addr_sram;
                        default                           : PRDATA = {DATA_WIDTH{1'b0}};
                    endcase
                end
            end
        end
    end

    // SRAM logic
    logic [DATA_WIDTH-1:0] mem [SRAM_DEPTH-1:0];

    always_comb begin
        sram_data_in = (reg_control == SRAM_WRITE) ? reg_wdata_sram : wire_op_o;

        if ((reg_control == SRAM_WRITE) || (reg_control == DSP_WRITE_OP_O)) begin
            sram_we = 1'b1;
        end else begin
            sram_we = 1'b0;
        end

        case (reg_control)
            DSP_READ_OP_A  : sram_addr = reg_operand_a;
            DSP_READ_OP_B  : sram_addr = reg_operand_b;
            DSP_READ_OP_C  : sram_addr = reg_operand_c;
            DSP_WRITE_OP_O : sram_addr = reg_operand_o;
            default        : sram_addr = reg_addr_sram;
        endcase
    end

    // SRAM in the DSP clock domain (consistency with the DSP operation)
    always_ff @(posedge dsp_clk_sel) begin
        if (sram_we && (sram_addr < SRAM_DEPTH)) begin
            mem[sram_addr[$clog2(SRAM_DEPTH)-1:0]] <= sram_data_in;
        end else if (sram_addr < SRAM_DEPTH) begin
            sram_data_out <= mem[sram_addr[$clog2(SRAM_DEPTH)-1:0]];
        end
    end

    // DSP operation
    always_ff @(posedge dsp_clk_sel) begin
        case (reg_control)
            DSP_READ_OP_A  : wire_op_a <= sram_data_out;
            DSP_READ_OP_B  : wire_op_b <= sram_data_out;
            DSP_READ_OP_C  : wire_op_c <= sram_data_out;
            default        : ;
        endcase
    end

    assign wire_op_o = (wire_op_a * wire_op_b) + wire_op_c;

endmodule

// apb_dsp_unit : APB-configured DSP unit with an internal 1 KB SRAM.
// CSR registers hold the memory addresses of the operands; addition or
// multiplication of the two addressed memory words is exposed at address 0x5.
module apb_dsp_unit (
    input  wire        pclk,        // APB clock
    input  wire        presetn,     // Active-low asynchronous reset

    // APB interface
    input  wire [9:0]  paddr,       // Address bus (CSR + memory)
    input  wire        pselx,       // Select
    input  wire        penable,     // Enable (access phase)
    input  wire        pwrite,      // Write (1) / read (0)
    input  wire [7:0]  pwdata,      // Write data
    output reg         pready,      // Ready (always high)
    output reg  [7:0]  prdata,      // Read data
    output reg         pslverr,     // Error response

    // SRAM write strobe
    input  wire        sram_valid   // rising edge latches r_write_data -> r_write_address
);

    // ---- Configuration registers (addresses 0x0 .. 0x4) ----
    reg [7:0] r_operand_1;     // 0x0 : memory address of operand 1
    reg [7:0] r_operand_2;     // 0x1 : memory address of operand 2
    reg [7:0] r_Enable;        // 0x2 : 0 off, 1 add, 2 mul, 3 data-write
    reg [7:0] r_write_address; // 0x3 : memory write address
    reg [7:0] r_write_data;    // 0x4 : memory write data

    // ---- Result register (address 0x5, read-only) ----
    reg [7:0] r_result;

    // ---- 1 KB SRAM ----
    reg [7:0] sram [0:1023];

    // Access-phase strobe
    wire access = pselx & penable;

    // Operand reads + arithmetic (combinational)
    wire [7:0]  op1_val = sram[r_operand_1];
    wire [7:0]  op2_val = sram[r_operand_2];
    wire [8:0]  add_res = op1_val + op2_val;
    wire [15:0] mul_res = op1_val * op2_val;

    // ---- APB combinational response (no wait states) ----
    always @(*) begin
        pready  = 1'b1;
        prdata  = 8'b0;
        pslverr = 1'b0;
        if (access) begin
            if (pwrite) begin
                // Only 0x0..0x4 are writable; 0x5 is read-only result
                if (paddr > 10'h4)
                    pslverr = 1'b1;
            end else begin
                case (paddr)
                    10'h0:   prdata = r_operand_1;
                    10'h1:   prdata = r_operand_2;
                    10'h2:   prdata = r_Enable;
                    10'h3:   prdata = r_write_address;
                    10'h4:   prdata = r_write_data;
                    10'h5:   prdata = r_result;
                    default: begin
                        // memory read region
                        prdata = sram[paddr];
                    end
                endcase
            end
        end
    end

    // ---- Configuration writes + result computation (pclk domain) ----
    always @(posedge pclk or negedge presetn) begin
        if (!presetn) begin
            r_operand_1     <= 8'b0;
            r_operand_2     <= 8'b0;
            r_Enable        <= 8'b0;
            r_write_address <= 8'b0;
            r_write_data    <= 8'b0;
            r_result        <= 8'b0;
        end else begin
            if (access && pwrite) begin
                case (paddr)
                    10'h0: r_operand_1     <= pwdata;
                    10'h1: r_operand_2     <= pwdata;
                    10'h2: r_Enable        <= pwdata;
                    10'h3: r_write_address <= pwdata;
                    10'h4: r_write_data    <= pwdata;
                    default: ; // read-only / memory
                endcase
            end
            // Result of the selected arithmetic operation
            case (r_Enable)
                8'd1: r_result <= add_res[7:0]; // addition
                8'd2: r_result <= mul_res[7:0]; // multiplication
                default: ; // disabled / data-write mode: hold
            endcase
        end
    end

    // ---- SRAM write : latch r_write_data into r_write_address on sram_valid ----
    always @(posedge sram_valid) begin
        sram[r_write_address] <= r_write_data;
    end

endmodule

module cvdp_copilot_apb_gpio #(
  parameter GPIO_WIDTH = 8
)(
  // Clock and Reset Signals
  input logic pclk,       // Clock signal
  input logic preset_n,   // Active-low reset signal

  // APB Interface Inputs
  input logic psel,           // Peripheral select
  input logic [7:2] paddr,    // APB address bus (bits [7:2])
  input logic penable,        // Transfer control signal
  input logic pwrite,         // Write control signal
  input logic [31:0] pwdata,  // Write data bus

  // APB Interface Outputs
  output logic [31:0] prdata, // Read data bus
  output logic pready,        // Device ready signal
  output logic pslverr,       // Device error response

  // GPIO Interface Inputs and Outputs
  input logic [GPIO_WIDTH-1:0] gpio_in,     // GPIO input signals
  output logic [GPIO_WIDTH-1:0] gpio_out,   // GPIO output signals
  output logic [GPIO_WIDTH-1:0] gpio_enable, // GPIO output enable signals

  // Interrupt Outputs
  output logic [GPIO_WIDTH-1:0] gpio_int, // Individual interrupt outputs
  output logic comb_int                   // Combined interrupt output
);

  // Signals for Read/Write Controls
  logic read_enable;                     // Read enable signal
  logic write_enable;                    // Write enable signal
  logic write_enable_reg_04;             // Write enable for Data Output register
  logic write_enable_reg_08;             // Write enable for Output Enable register
  logic write_enable_reg_0C;             // Write enable for Interrupt Enable register
  logic write_enable_reg_10;             // Write enable for Interrupt Type register
  logic write_enable_reg_14;             // Write enable for Interrupt Polarity register
  logic write_enable_reg_18;             // Write enable for Interrupt State register
  logic write_enable_reg_1C;             // Write enable for Direction Control register
  logic write_enable_reg_20;             // Write enable for Power Management register
  logic write_enable_reg_24;             // Write enable for Interrupt Reset register
  logic [GPIO_WIDTH-1:0] read_mux;       // Read data multiplexer
  logic [GPIO_WIDTH-1:0] read_mux_d1;    // Registered read data

  // Control Registers
  logic [GPIO_WIDTH-1:0] reg_dout;       // Data Output register
  logic [GPIO_WIDTH-1:0] reg_dout_en;    // Output Enable register
  logic [GPIO_WIDTH-1:0] reg_int_en;     // Interrupt Enable register
  logic [GPIO_WIDTH-1:0] reg_int_type;   // Interrupt Type register
  logic [GPIO_WIDTH-1:0] reg_int_pol;    // Interrupt Polarity register
  logic [GPIO_WIDTH-1:0] reg_int_state;  // Interrupt State register
  logic [GPIO_WIDTH-1:0] reg_dir;        // Direction Control register (1=output, 0=input)
  logic                  reg_pwr_down;   // Power Management (global power-down)

  // I/O Signal Path and Interrupt Logic
  logic [GPIO_WIDTH-1:0] data_in_sync1;            // First stage of input synchronization
  logic [GPIO_WIDTH-1:0] data_in_sync2;            // Second stage of input synchronization
  logic [GPIO_WIDTH-1:0] data_in_pol_adjusted;     // Polarity-adjusted input data
  logic [GPIO_WIDTH-1:0] data_in_pol_adjusted_dly; // Delayed version of polarity-adjusted input data
  logic [GPIO_WIDTH-1:0] edge_detect;              // Edge detection signals
  logic [GPIO_WIDTH-1:0] raw_int;                  // Raw interrupt signals
  logic [GPIO_WIDTH-1:0] int_masked;               // Masked interrupt signals
  logic [GPIO_WIDTH-1:0] clear_interrupt;          // Clear interrupt signals (0x18)
  logic [GPIO_WIDTH-1:0] reset_interrupt;          // Software interrupt reset (0x24)

  // Read and Write Control Signals
  assign read_enable = psel & (~pwrite); // Read enable
  assign write_enable = psel & (~penable) & pwrite; // Write enable

  // Write Enable Signals for Specific Registers
  assign write_enable_reg_04 = write_enable & (paddr[7:2] == 6'd1); // Address 0x04
  assign write_enable_reg_08 = write_enable & (paddr[7:2] == 6'd2); // Address 0x08
  assign write_enable_reg_0C = write_enable & (paddr[7:2] == 6'd3); // Address 0x0C
  assign write_enable_reg_10 = write_enable & (paddr[7:2] == 6'd4); // Address 0x10
  assign write_enable_reg_14 = write_enable & (paddr[7:2] == 6'd5); // Address 0x14
  assign write_enable_reg_18 = write_enable & (paddr[7:2] == 6'd6); // Address 0x18
  assign write_enable_reg_1C = write_enable & (paddr[7:2] == 6'd7); // Address 0x1C
  assign write_enable_reg_20 = write_enable & (paddr[7:2] == 6'd8); // Address 0x20
  assign write_enable_reg_24 = write_enable & (paddr[7:2] == 6'd9); // Address 0x24

  // Write Operations for Control Registers

  // Data Output Register (reg_dout)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_dout <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_04)
      reg_dout <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Output Enable Register (reg_dout_en)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_dout_en <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_08)
      reg_dout_en <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Interrupt Enable Register (reg_int_en)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_int_en <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_0C)
      reg_int_en <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Interrupt Type Register (reg_int_type)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_int_type <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_10)
      reg_int_type <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Interrupt Polarity Register (reg_int_pol)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_int_pol <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_14)
      reg_int_pol <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Direction Control Register (reg_dir) — default all outputs for backward
  // compatibility with the original (output-enable-only) behaviour.
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_dir <= {GPIO_WIDTH{1'b1}};
    else if (write_enable_reg_1C)
      reg_dir <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Power Management Register (reg_pwr_down) — only bit[0] is meaningful.
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_pwr_down <= 1'b0;
    else if (write_enable_reg_20)
      reg_pwr_down <= pwdata[0];
  end

  // Read Operation: Multiplexing Register Data Based on Address
  always_comb begin
    case (paddr[7:2])
      6'd0: read_mux = data_in_sync2;          // Input Data Register at address 0x00
      6'd1: read_mux = reg_dout;               // Data Output Register at address 0x04
      6'd2: read_mux = reg_dout_en;            // Output Enable Register at address 0x08
      6'd3: read_mux = reg_int_en;             // Interrupt Enable Register at address 0x0C
      6'd4: read_mux = reg_int_type;           // Interrupt Type Register at address 0x10
      6'd5: read_mux = reg_int_pol;            // Interrupt Polarity Register at address 0x14
      6'd6: read_mux = reg_int_state;          // Interrupt State Register at address 0x18
      6'd7: read_mux = reg_dir;                // Direction Control Register at address 0x1C
      6'd8: read_mux = {{(GPIO_WIDTH-1){1'b0}}, reg_pwr_down}; // Power Management at 0x20
      6'd9: read_mux = {GPIO_WIDTH{1'b0}};     // Interrupt Reset at 0x24 (write-only, reads 0)
      default: read_mux = {GPIO_WIDTH{1'b0}};  // Default to zeros if address is invalid
    endcase
  end

  // Registering Read Data for Timing Alignment
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      read_mux_d1 <= {GPIO_WIDTH{1'b0}};
    else
      read_mux_d1 <= read_mux;
  end

  // Output Read Data to APB Interface
  assign prdata = (read_enable) ? {{(32-GPIO_WIDTH){1'b0}}, read_mux_d1} : {32{1'b0}};
  assign pready = 1'b1; // Always ready
  assign pslverr = 1'b0; // No error

  // Driving GPIO Outputs and Output Enables.  A pin drives only when it is both
  // output-enabled and configured as an output, and the block is not powered down.
  assign gpio_enable = reg_dout_en & reg_dir & {GPIO_WIDTH{~reg_pwr_down}};
  assign gpio_out    = reg_dout;

  // Input Synchronization to Avoid Metastability
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n) begin
      data_in_sync1 <= {GPIO_WIDTH{1'b0}};
      data_in_sync2 <= {GPIO_WIDTH{1'b0}};
    end else begin
      data_in_sync1 <= gpio_in;
      data_in_sync2 <= data_in_sync1;
    end
  end

  // Interrupt Logic

  // Adjusting Input Data Based on Interrupt Polarity
  assign data_in_pol_adjusted = data_in_sync2 ^ reg_int_pol; // Polarity adjustment

  // Registering Polarity-Adjusted Input Data and Delaying for Edge Detection
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n) begin
      data_in_pol_adjusted_dly <= {GPIO_WIDTH{1'b0}};
    end else begin
      data_in_pol_adjusted_dly <= data_in_pol_adjusted;
    end
  end

  // Edge Detection Logic for Interrupts
  assign edge_detect = data_in_pol_adjusted & (~data_in_pol_adjusted_dly); // Rising edge detection

  // Selecting Interrupt Type (Edge or Level-Triggered)
  assign raw_int = (reg_int_type & edge_detect) | (~reg_int_type & data_in_pol_adjusted); // Interrupt source

  // Applying Interrupt Enable Mask
  assign int_masked = raw_int & reg_int_en; // Masked interrupts

  // Clear Interrupt Signals (write-1-to-clear on the Interrupt State register, 0x18)
  assign clear_interrupt = pwdata[GPIO_WIDTH-1:0] & {GPIO_WIDTH{write_enable_reg_18}};

  // Software Interrupt Reset (write-1-to-clear on the Interrupt Reset register, 0x24)
  assign reset_interrupt = pwdata[GPIO_WIDTH-1:0] & {GPIO_WIDTH{write_enable_reg_24}};

  // Updating Interrupt State Register
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n) begin
      reg_int_state <= {GPIO_WIDTH{1'b0}};
    end else begin
      integer i;
      for (i = 0; i < GPIO_WIDTH; i = i + 1) begin
        if (reset_interrupt[i]) begin
          // Software-controlled interrupt reset has priority
          reg_int_state[i] <= 1'b0;
        end else if (reg_int_type[i]) begin
          // Edge-triggered interrupt
          if (clear_interrupt[i]) begin
            reg_int_state[i] <= 1'b0;
          end else if (int_masked[i]) begin
            reg_int_state[i] <= 1'b1;
          end
        end else begin
          // Level-triggered interrupt
          reg_int_state[i] <= int_masked[i];
        end
      end
    end
  end

  // Connecting Interrupt Outputs
  assign gpio_int = reg_int_state;     // Individual interrupt outputs
  assign comb_int = |reg_int_state;    // Combined interrupt output

endmodule

module APBGlobalHistoryRegister (
    input  wire        pclk,                 // APB clock
    input  wire        presetn,              // Active-low asynchronous reset

    // APB interface
    input  wire [9:0]  paddr,                // Address bus
    input  wire        pselx,                // Select
    input  wire        penable,              // Enable (access phase)
    input  wire        pwrite,               // Write (1) / read (0)
    input  wire [7:0]  pwdata,               // Write data
    output reg         pready,               // Ready (always high)
    output reg  [7:0]  prdata,               // Read data
    output reg         pslverr,              // Error response

    // History shift interface
    input  wire        history_shift_valid,  // Update strobe (its own clock)

    // Clock gating enable
    input  wire        clk_gate_en,          // 1 = gate pclk internally

    // Status / interrupt outputs
    output wire        history_full,         // predict_history == 8'hFF
    output wire        history_empty,        // predict_history == 8'h00
    output reg         error_flag,           // invalid-address error
    output wire        interrupt_full,       // == history_full
    output wire        interrupt_error       // == error_flag
);

    // Register addresses
    localparam [9:0] ADDR_CONTROL  = 10'h0;
    localparam [9:0] ADDR_TRAIN    = 10'h1;
    localparam [9:0] ADDR_PREDICT  = 10'h2;

    // CSRs
    reg [7:0] control_register; // [0]predict_valid [1]predict_taken [2]train_mispredicted [3]train_taken
    reg [7:0] train_history;    // [6:0] recorded history, [7] reserved
    reg [7:0] predict_history;  // shift register (read-only via APB)

    // ---- Clock gating: latch enable on the low phase of pclk (glitch-free) ----
    reg enable_latch;
    initial enable_latch = 1'b1;
    always @(pclk or clk_gate_en)
        if (!pclk)
            enable_latch = ~clk_gate_en;
    wire gated_clk = pclk & enable_latch;

    // ---- Valid-address decode ----
    wire addr_valid = (paddr == ADDR_CONTROL) ||
                      (paddr == ADDR_TRAIN)   ||
                      (paddr == ADDR_PREDICT);

    // ---- APB combinational response (no wait states) ----
    always @(*) begin
        pready  = 1'b1;
        prdata  = 8'b0;
        pslverr = 1'b0;
        if (pselx && penable) begin
            if (!pwrite) begin
                case (paddr)
                    ADDR_CONTROL: prdata = {4'b0, control_register[3:0]};
                    ADDR_TRAIN:   prdata = {1'b0, train_history[6:0]};
                    ADDR_PREDICT: prdata = predict_history;
                    default:      prdata = 8'b0;
                endcase
            end
            pslverr = ~addr_valid;
        end
    end

    // ---- APB register writes + sticky error flag (gated pclk domain) ----
    always @(posedge gated_clk or negedge presetn) begin
        if (!presetn) begin
            control_register <= 8'b0;
            train_history    <= 8'b0;
            error_flag       <= 1'b0;
        end else if (pselx && penable) begin
            if (pwrite) begin
                case (paddr)
                    ADDR_CONTROL: control_register <= pwdata;
                    ADDR_TRAIN:   train_history    <= pwdata;
                    default:      ; // predict_history is read-only; others invalid
                endcase
            end
            error_flag <= ~addr_valid; // set on invalid address access
        end
    end

    // ---- Prediction history shift register (updated on history_shift_valid) ----
    // Misprediction has highest priority; restores history before the branch.
    always @(posedge history_shift_valid or negedge presetn) begin
        if (!presetn)
            predict_history <= 8'b0;
        else if (control_register[2]) // train_mispredicted
            predict_history <= {train_history[6:0], control_register[3]}; // {history, train_taken}
        else if (control_register[0]) // predict_valid
            predict_history <= {predict_history[6:0], control_register[1]}; // shift in predict_taken
        // else hold
    end

    // ---- Status / interrupts ----
    assign history_full    = (predict_history == 8'hFF);
    assign history_empty   = (predict_history == 8'h00);
    assign interrupt_full  = history_full;
    assign interrupt_error = error_flag;

endmodule

module axi_alu (
    input  wire        axi_clk_in,
    input  wire        fast_clk_in,
    input  wire        reset_in,

    // AXI Interface
    input  wire        axi_awvalid_i,
    input  wire        axi_wvalid_i,
    input  wire        axi_bready_i,
    input  wire        axi_arvalid_i,
    input  wire        axi_rready_i,

    output wire        axi_awready_o,
    output wire        axi_wready_o,
    output wire        axi_bvalid_o,
    output wire        axi_arready_o,
    output wire        axi_rvalid_o,

    input  wire [31:0] axi_awaddr_i,
    input  wire [31:0] axi_wdata_i,
    input  wire [31:0] axi_araddr_i,

    input  wire [3:0]  axi_wstrb_i,
    output wire [31:0] axi_rdata_o,
    output wire [63:0] result_o
);

    wire        clk;
    wire [31:0] operand_a, operand_b, operand_c;
    wire [1:0]  op_select;
    wire        start, clock_control;
    wire [31:0] data_a;
    wire [31:0] data_b;
    wire [31:0] data_c;

    wire [31:0] operand_a_cdc, operand_b_cdc, operand_c_cdc;
    wire [1:0]  op_select_cdc;
    wire        start_cdc;
    wire [31:0] operand_a_sync, operand_b_sync, operand_c_sync;
    wire [1:0]  op_select_sync;
    wire        start_sync;

    // RAM write/read ports driven by the CSR block
    wire        ram_we;
    wire [3:0]  ram_waddr;
    wire [31:0] ram_wdata;
    wire [3:0]  ram_axi_raddr;
    wire [31:0] ram_axi_rdata;

    clock_control u_clock_control (
        .axi_clk_in  (axi_clk_in),
        .fast_clk_in (fast_clk_in),
        .clk_ctrl    (clock_control),
        .clk         (clk)
    );

    axi_csr_block u_axi_csr_block (
        .axi_aclk_i    (axi_clk_in),
        .axi_areset_i  (reset_in),
        .axi_awvalid_i (axi_awvalid_i),
        .axi_awready_o (axi_awready_o),
        .axi_awaddr_i  (axi_awaddr_i),
        .axi_wvalid_i  (axi_wvalid_i),
        .axi_wready_o  (axi_wready_o),
        .axi_wdata_i   (axi_wdata_i),
        .axi_wstrb_i   (axi_wstrb_i),
        .axi_bvalid_o  (axi_bvalid_o),
        .axi_bready_i  (axi_bready_i),
        .axi_arvalid_i (axi_arvalid_i),
        .axi_arready_o (axi_arready_o),
        .axi_araddr_i  (axi_araddr_i),
        .axi_rvalid_o  (axi_rvalid_o),
        .axi_rready_i  (axi_rready_i),
        .axi_rdata_o   (axi_rdata_o),
        .operand_a     (operand_a_cdc),
        .operand_b     (operand_b_cdc),
        .operand_c     (operand_c_cdc),
        .op_select     (op_select_cdc),
        .start         (start_cdc),
        .clock_control (clock_control),
        .ram_we        (ram_we),
        .ram_waddr     (ram_waddr),
        .ram_wdata     (ram_wdata),
        .ram_axi_raddr (ram_axi_raddr),
        .ram_axi_rdata (ram_axi_rdata)
    );

    // CDC synchronizers are USED only when the fast clock is selected
    // (clock_control == 1). When the AXI clock is selected the CSR outputs are
    // used directly (same domain, no synchronization needed).
    assign operand_a = (clock_control) ? operand_a_sync : operand_a_cdc;
    assign operand_b = (clock_control) ? operand_b_sync : operand_b_cdc;
    assign operand_c = (clock_control) ? operand_c_sync : operand_c_cdc;
    assign op_select = (clock_control) ? op_select_sync : op_select_cdc;
    assign start     = (clock_control) ? start_sync     : start_cdc;

    cdc_synchronizer #(.WIDTH(32)) u_cdc_operand_a (.clk_src(axi_clk_in), .clk_dst(clk), .reset_in(reset_in), .data_in(operand_a_cdc), .data_out(operand_a_sync));
    cdc_synchronizer #(.WIDTH(32)) u_cdc_operand_b (.clk_src(axi_clk_in), .clk_dst(clk), .reset_in(reset_in), .data_in(operand_b_cdc), .data_out(operand_b_sync));
    cdc_synchronizer #(.WIDTH(32)) u_cdc_operand_c (.clk_src(axi_clk_in), .clk_dst(clk), .reset_in(reset_in), .data_in(operand_c_cdc), .data_out(operand_c_sync));
    cdc_synchronizer #(.WIDTH(2))  u_cdc_op_select (.clk_src(axi_clk_in), .clk_dst(clk), .reset_in(reset_in), .data_in(op_select_cdc), .data_out(op_select_sync));
    cdc_synchronizer #(.WIDTH(1))  u_cdc_start     (.clk_src(axi_clk_in), .clk_dst(clk), .reset_in(reset_in), .data_in(start_cdc), .data_out(start_sync));

    memory_block u_memory_block (
        .axi_clk    (axi_clk_in),
        .reset_in   (reset_in),
        .we         (ram_we),
        .waddr      (ram_waddr),
        .wdata      (ram_wdata),
        .address_a  (operand_a[3:0]),
        .address_b  (operand_b[3:0]),
        .address_c  (operand_c[3:0]),
        .data_a     (data_a),
        .data_b     (data_b),
        .data_c     (data_c),
        .axi_raddr  (ram_axi_raddr),
        .axi_rdata  (ram_axi_rdata)
    );

    dsp_block u_dsp_block (
        .clk        (clk),
        .reset_in   (reset_in),
        .operand_a  (data_a),
        .operand_b  (data_b),
        .operand_c  (data_c),
        .op_select  (op_select),
        .start      (start),
        .result     (result_o)
    );

endmodule

// ------------------------------------------------------------------
// CDC Synchronizer Module (Double Flop Synchronization)
// ------------------------------------------------------------------
module cdc_synchronizer #(parameter WIDTH = 1) (
    input wire clk_src,
    input wire clk_dst,
    input wire reset_in,
    input wire [WIDTH-1:0] data_in,
    output reg [WIDTH-1:0] data_out
);
    reg [WIDTH-1:0] data_sync_1, data_sync_2;

    always @(posedge clk_dst or posedge reset_in) begin
        if (reset_in) begin
            data_sync_1 <= {WIDTH{1'b0}};
            data_sync_2 <= {WIDTH{1'b0}};
            data_out    <= {WIDTH{1'b0}};
        end else begin
            data_sync_1 <= data_in;
            data_sync_2 <= data_sync_1;
            data_out    <= data_sync_2;
        end
    end
endmodule

// ------------------------------------------------------------------
// Clock Control Module
// ------------------------------------------------------------------
module clock_control (
    input  wire axi_clk_in,
    input  wire fast_clk_in,
    input  wire clk_ctrl,
    output wire clk
);
    assign clk = clk_ctrl ? fast_clk_in : axi_clk_in;
endmodule

// ------------------------------------------------------------------
// AXI-to-CSR Register Block (with INCR burst write + RAM access)
// ------------------------------------------------------------------
module axi_csr_block (
    input  wire        axi_aclk_i,
    input  wire        axi_areset_i,

    input  wire        axi_awvalid_i,
    output reg         axi_awready_o,
    input  wire [31:0] axi_awaddr_i,

    input  wire        axi_wvalid_i,
    output reg         axi_wready_o,
    input  wire [31:0] axi_wdata_i,
    input  wire [3:0]  axi_wstrb_i,

    output reg         axi_bvalid_o,
    input  wire        axi_bready_i,

    input  wire        axi_arvalid_i,
    output reg         axi_arready_o,
    input  wire [31:0] axi_araddr_i,

    output reg         axi_rvalid_o,
    input  wire        axi_rready_i,
    output reg  [31:0] axi_rdata_o,

    // CSR outputs
    output reg  [31:0] operand_a,
    output reg  [31:0] operand_b,
    output reg  [31:0] operand_c,
    output reg  [1:0]  op_select,
    output reg         start,
    output reg         clock_control,

    // RAM interface (memory data registers at 0x20..0x5C -> RAM[0..15])
    output reg         ram_we,
    output reg  [3:0]  ram_waddr,
    output reg  [31:0] ram_wdata,
    output wire [3:0]  ram_axi_raddr,
    input  wire [31:0] ram_axi_rdata
);
    localparam RAM_BASE = 32'h20;

    reg [31:0] csr_reg [0:4];   // 0x00,0x04,0x08,0x0C,0x10
    reg [31:0] wr_ptr;          // running write address (INCR burst)
    reg [31:0] rd_ptr;          // running read address

    // Current write address: a fresh AW provides the base, else continue burst.
    wire [31:0] cur_waddr = axi_awvalid_i ? axi_awaddr_i : wr_ptr;
    // Current read address for the RAM async port.
    wire [31:0] cur_raddr = axi_arvalid_i ? axi_araddr_i : rd_ptr;
    assign ram_axi_raddr  = cur_raddr[5:2] - RAM_BASE[5:2];

    integer i;

    always @(posedge axi_aclk_i or posedge axi_areset_i) begin
        if (axi_areset_i) begin
            operand_a     <= 32'd0;
            operand_b     <= 32'd0;
            operand_c     <= 32'd0;
            op_select     <= 2'd0;
            start         <= 1'b0;
            clock_control <= 1'b0;
            axi_awready_o <= 1'b0;
            axi_wready_o  <= 1'b0;
            axi_bvalid_o  <= 1'b0;
            axi_arready_o <= 1'b0;
            axi_rvalid_o  <= 1'b0;
            axi_rdata_o   <= 32'd0;
            ram_we        <= 1'b0;
            ram_waddr     <= 4'd0;
            ram_wdata     <= 32'd0;
            wr_ptr        <= 32'd0;
            rd_ptr        <= 32'd0;
            for (i = 0; i < 5; i = i + 1) csr_reg[i] <= 32'd0;
        end else begin
            // ---- Write address / data channels (per-beat INCR) ----
            axi_awready_o <= axi_awvalid_i;
            axi_wready_o  <= axi_wvalid_i;
            ram_we        <= 1'b0;

            if (axi_awvalid_i)
                wr_ptr <= axi_awaddr_i;

            if (axi_wvalid_i) begin
                if (cur_waddr < RAM_BASE) begin
                    csr_reg[cur_waddr[4:2]] <= axi_wdata_i;
                end else begin
                    ram_we    <= 1'b1;
                    ram_waddr <= cur_waddr[5:2] - RAM_BASE[5:2];
                    ram_wdata <= axi_wdata_i;
                end
                wr_ptr <= cur_waddr + 32'd4;
            end

            // ---- Write response ----
            if (axi_wvalid_i)
                axi_bvalid_o <= 1'b1;
            else if (axi_bvalid_o && axi_bready_i)
                axi_bvalid_o <= 1'b0;

            // ---- Read channel (per-beat INCR) ----
            axi_arready_o <= axi_arvalid_i;
            if (axi_arvalid_i)
                rd_ptr <= axi_araddr_i;

            if (axi_arvalid_i) begin
                axi_rvalid_o <= 1'b1;
                if (cur_raddr < RAM_BASE)
                    axi_rdata_o <= csr_reg[cur_raddr[4:2]];
                else
                    axi_rdata_o <= ram_axi_rdata;
                rd_ptr <= cur_raddr + 32'd4;
            end else if (axi_rvalid_o && axi_rready_i) begin
                axi_rvalid_o <= 1'b0;
            end

            // ---- CSR register outputs ----
            operand_a     <= csr_reg[0];
            operand_b     <= csr_reg[1];
            operand_c     <= csr_reg[2];
            op_select     <= csr_reg[3][1:0];
            start         <= csr_reg[3][2];
            clock_control <= csr_reg[4][0];
        end
    end
endmodule

// ------------------------------------------------------------------
// Memory Block (RAM : 16 x 32, sync write / async read)
// ------------------------------------------------------------------
module memory_block (
    input  wire        axi_clk,
    input  wire        reset_in,
    input  wire        we,
    input  wire [3:0]  waddr,
    input  wire [31:0] wdata,
    input  wire [3:0]  address_a,
    input  wire [3:0]  address_b,
    input  wire [3:0]  address_c,
    output wire [31:0] data_a,
    output wire [31:0] data_b,
    output wire [31:0] data_c,
    input  wire [3:0]  axi_raddr,
    output wire [31:0] axi_rdata
);
    reg [31:0] ram [0:15];
    integer j;

    always @(posedge axi_clk or posedge reset_in) begin
        if (reset_in) begin
            for (j = 0; j < 16; j = j + 1) ram[j] <= 32'd0;
        end else if (we) begin
            ram[waddr] <= wdata;
        end
    end

    // Asynchronous reads
    assign data_a    = (reset_in) ? 32'd0 : ram[address_a];
    assign data_b    = (reset_in) ? 32'd0 : ram[address_b];
    assign data_c    = (reset_in) ? 32'd0 : ram[address_c];
    assign axi_rdata = ram[axi_raddr];
endmodule

// ------------------------------------------------------------------
// DSP Processing Block
// ------------------------------------------------------------------
module dsp_block (
    input  wire        clk,
    input  wire        reset_in,
    input  wire [31:0] operand_a,
    input  wire [31:0] operand_b,
    input  wire [31:0] operand_c,
    input  wire [1:0]  op_select,
    input  wire        start,
    output reg  [63:0] result
);
    always @(posedge clk or posedge reset_in) begin
        if (reset_in)
            result <= 64'd0;
        else begin
            if (start) begin
                case (op_select)
                    2'b00: result <= (operand_a + operand_b) * operand_c; // MAC
                    2'b01: result <= operand_a * operand_b;               // Multiplication
                    2'b10: result <= operand_a >> operand_b[4:0];         // Shift Right
                    2'b11: result <= operand_b ? operand_a / operand_b : 64'hDEADDEAD; // Division
                endcase
            end
        end
    end
endmodule

module axis_resize (

  input                                           clk,          //Global clock signal: Signals are sampled on the rising edge of clk
  input                                           resetn,       //The global reset signal: resetn is synchronous active-LOW reset.

  input                                           s_valid,      //The s_axis_valid signal indicates that the slave is driving a valid transfer.
  output  reg                                     s_ready,      //The s_axis_ready indicates that the slave can accept a transfer in the current cycle.
  input       [15:0]  s_data,                                   //The s_axis_data is the primary payload data from slave.

  output  reg                                     m_valid,      //The m_axis_valid indicates that the master is driving a valid transfer.
  input                                           m_ready,      //The m_axis_ready indicates that the slave can accept a transfer in the current cycle.
  output  reg [7:0] m_data                                      //The m_axis_data is the primary payload data to master.
);

  // A single 16-bit slave word is emitted as two 8-bit master beats,
  // least-significant byte first.
  localparam IDLE  = 2'd0;  // ready to accept a new slave word
  localparam BEAT0 = 2'd1;  // driving the low byte  s_data[7:0]
  localparam BEAT1 = 2'd2;  // driving the high byte s_data[15:8]

  reg [1:0]  state;
  reg [15:0] data_r;

  always @(posedge clk) begin
    if (!resetn) begin
      state   <= IDLE;
      data_r  <= 16'b0;
      s_ready <= 1'b1;
      m_valid <= 1'b0;
      m_data  <= 8'b0;
    end else begin
      case (state)
        IDLE: begin
          s_ready <= 1'b1;
          m_valid <= 1'b0;
          if (s_valid && s_ready) begin
            data_r  <= s_data;
            m_data  <= s_data[7:0];   // low byte first
            m_valid <= 1'b1;
            s_ready <= 1'b0;
            state   <= BEAT0;
          end
        end
        BEAT0: begin
          m_valid <= 1'b1;
          m_data  <= data_r[7:0];
          s_ready <= 1'b0;
          if (m_valid && m_ready) begin
            m_data <= data_r[15:8]; // high byte
            state  <= BEAT1;
          end
        end
        BEAT1: begin
          m_valid <= 1'b1;
          m_data  <= data_r[15:8];
          s_ready <= 1'b0;
          if (m_valid && m_ready) begin
            m_valid <= 1'b0;
            s_ready <= 1'b1;
            state   <= IDLE;
          end
        end
        default: begin
          state   <= IDLE;
          s_ready <= 1'b1;
          m_valid <= 1'b0;
        end
      endcase
    end
  end

endmodule

module axis_upscale (
  input              clk,            // Global clock signal
  input              resetn,         // Active-low synchronous reset

  input              dfmt_enable,    // Data format enable
  input              dfmt_type,      // 1 = inverted MSB carried forward, 0 = MSB carried forward
  input              dfmt_se,        // 1 = sign-extend the (formatted) 23rd bit, 0 = zero-extend

  input              s_axis_valid,   // Slave valid
  input      [23:0]  s_axis_data,    // 24-bit slave payload
  output             s_axis_ready,   // Slave ready

  output reg         m_axis_valid,   // Master valid
  input              m_axis_ready,   // Master ready
  output reg [31:0]  m_axis_data     // 32-bit master payload
);

  // Single pipeline register stage.  The 24-bit input is widened to 32 bits:
  //   bit[23]    = dfmt_type ^ MSB    (offset-binary <-> two's-complement format)
  //   bits[22:0] = s_axis_data[22:0]  (lower payload, passed through)
  //   bits[31:24]= sign/zero extension selected by dfmt_se
  // When dfmt_enable is low the output is the plain zero-extension of the input.
  wire        fmt_msb = dfmt_type ^ s_axis_data[23];
  wire [31:0] fmt_data = dfmt_enable
                       ? { (dfmt_se ? {8{fmt_msb}} : 8'b0), fmt_msb, s_axis_data[22:0] }
                       : { 8'b0, s_axis_data };

  // Skid-style single register: accept when the stage is empty or being drained.
  assign s_axis_ready = (!m_axis_valid) || m_axis_ready;

  always @(posedge clk) begin
    if (!resetn) begin
      m_axis_valid <= 1'b0;
      m_axis_data  <= 32'b0;
    end else begin
      if (s_axis_ready) begin
        m_axis_valid <= s_axis_valid;
        if (s_axis_valid)
          m_axis_data <= fmt_data;
      end
    end
  end

endmodule

module axi_tap #(
    parameter ADDR_WIDTH = 32, // Width of AXI4-Lite Address
    parameter DATA_WIDTH = 32,  // Width of AXI4-Lite Data
    parameter TIMEOUT_WIDTH = 32 // Width of the timeout timer / threshold
)(
    // Global Ports
    input           clk_i,
    input           rst_i,

    // Master Write Address Channel (AW)
    input           inport_awvalid_i,
    input  [ADDR_WIDTH-1:0]   inport_awaddr_i,
    output          inport_awready_o,
    // Master Write Data Channel (W)
    input           inport_wvalid_i,
    input  [DATA_WIDTH-1:0]   inport_wdata_i,
    input  [3:0]    inport_wstrb_i,
    output          inport_wready_o,
    // Master Write Response Channel (B)
    input           inport_bready_i,
    output          inport_bvalid_o,
    output [1:0]    inport_bresp_o,
    // Master Read Address Channel (AR)
    input           inport_arvalid_i,
    input  [ADDR_WIDTH-1:0]   inport_araddr_i,
    output          inport_arready_o,
    // Master Read Data Channel (R)
    input           inport_rready_i,
    output          inport_rvalid_o,
    output [DATA_WIDTH-1:0]   inport_rdata_o,
    output [1:0]    inport_rresp_o,

    // Default AXI outport
    // Write Address Channel (AW)
    input           outport_awready_i,
    output          outport_awvalid_o,
    output [ADDR_WIDTH-1:0]   outport_awaddr_o,
    // Write Data Channel (W)
    input           outport_wready_i,
    output          outport_wvalid_o,
    output [DATA_WIDTH-1:0]   outport_wdata_o,
    output [3:0]    outport_wstrb_o,
    // Write Response Channel (B)
    input           outport_bvalid_i,
    input  [1:0]    outport_bresp_i,
    output          outport_bready_o,
    // Read Address Channel (AR)
    input           outport_arready_i,
    output          outport_arvalid_o,
    output [ADDR_WIDTH-1:0]   outport_araddr_o,
    // Read Data Channel (R)
    input           outport_rvalid_i,
    input  [DATA_WIDTH-1:0]   outport_rdata_i,
    input  [1:0]    outport_rresp_i,
    output          outport_rready_o,

    // Peripheral 0 interface
    // Write Address Channel (AW)
    input           outport_peripheral0_awready_i,
    output          outport_peripheral0_awvalid_o,
    output [ADDR_WIDTH-1:0]   outport_peripheral0_awaddr_o,
    // Write Data Channel (W)
    input           outport_peripheral0_wready_i,
    output          outport_peripheral0_wvalid_o,
    output [DATA_WIDTH-1:0]   outport_peripheral0_wdata_o,
    output [3:0]    outport_peripheral0_wstrb_o,
    // Write Response Channel (B)
    input  [1:0]    outport_peripheral0_bresp_i,
    input           outport_peripheral0_bvalid_i,
    output          outport_peripheral0_bready_o,
    // Read Address Channel (AR)
    input           outport_peripheral0_arready_i,
    output          outport_peripheral0_arvalid_o,
    output [ADDR_WIDTH-1:0]   outport_peripheral0_araddr_o,
    // Read Data Channel (R)
    input  [1:0]    outport_peripheral0_rresp_i,
    input           outport_peripheral0_rvalid_i,
    input  [DATA_WIDTH-1:0]   outport_peripheral0_rdata_i,
    output          outport_peripheral0_rready_o,

    // Transaction timeout interface (added)
    input  [TIMEOUT_WIDTH-1:0] timeout_threshold, // allowed cycles before timeout
    output reg                 timeout_flag        // asserted on a transaction timeout
);

`define ADDR_SEL_W           1
`define PERIPH0_ADDR         32'h80000000
`define PERIPH0_MASK         32'h80000000

//-----------------------------------------------------------------
// AXI: Read
//-----------------------------------------------------------------
reg [3:0]              read_pending_q;
reg [3:0]              read_pending_r;
reg [`ADDR_SEL_W-1:0]  read_port_q;
reg [`ADDR_SEL_W-1:0]  read_port_r;

always @ *
begin
    read_port_r = `ADDR_SEL_W'b0;
    if ((inport_araddr_i & `PERIPH0_MASK) == `PERIPH0_ADDR) read_port_r = `ADDR_SEL_W'd1;
end

wire read_incr_w = (inport_arvalid_i && inport_arready_o);
wire read_decr_w = (inport_rvalid_o && inport_rready_i);

always @ *
begin
    read_pending_r = read_pending_q;

    if (read_incr_w && !read_decr_w)
        read_pending_r = read_pending_r + 4'd1;
    else if (!read_incr_w && read_decr_w)
        read_pending_r = read_pending_r - 4'd1;
end

always @ (posedge clk_i )
if (rst_i)
begin
    read_pending_q <= 4'b0;
    read_port_q    <= `ADDR_SEL_W'b0;
end
else
begin
    read_pending_q <= read_pending_r;

    // Read command accepted
    if (inport_arvalid_i && inport_arready_o)
    begin
        read_port_q <= read_port_r;
    end
end

wire read_accept_w       = (read_port_q == read_port_r && read_pending_q != 4'hF) || (read_pending_q == 4'h0);

assign outport_arvalid_o = inport_arvalid_i & read_accept_w & (read_port_r == `ADDR_SEL_W'd0);
assign outport_araddr_o  = inport_araddr_i;
assign outport_rready_o  = inport_rready_i;

assign outport_peripheral0_arvalid_o = inport_arvalid_i & read_accept_w & (read_port_r == `ADDR_SEL_W'd1);
assign outport_peripheral0_araddr_o  = inport_araddr_i;
assign outport_peripheral0_rready_o  = inport_rready_i;

reg        outport_rvalid_r;
reg [DATA_WIDTH-1:0] outport_rdata_r;
reg [1:0]  outport_rresp_r;

always @ *
begin
    case (read_port_q)
    `ADDR_SEL_W'd1:
    begin
        outport_rvalid_r = outport_peripheral0_rvalid_i;
        outport_rdata_r  = outport_peripheral0_rdata_i;
        outport_rresp_r  = outport_peripheral0_rresp_i;
    end
    default:
    begin
        outport_rvalid_r = outport_rvalid_i;
        outport_rdata_r  = outport_rdata_i;
        outport_rresp_r  = outport_rresp_i;
    end
    endcase
end

assign inport_rvalid_o  = outport_rvalid_r;
assign inport_rdata_o   = outport_rdata_r;
assign inport_rresp_o   = outport_rresp_r;

reg inport_arready_r;
always @ *
begin
    case (read_port_r)
    `ADDR_SEL_W'd1:
        inport_arready_r = outport_peripheral0_arready_i;
    default:
        inport_arready_r = outport_arready_i;
    endcase
end

assign inport_arready_o = read_accept_w & inport_arready_r;

//-------------------------------------------------------------
// Write Request
//-------------------------------------------------------------
reg awvalid_q;
reg wvalid_q;

wire wr_cmd_accepted_w  = (inport_awvalid_i && inport_awready_o) || awvalid_q;
wire wr_data_accepted_w = (inport_wvalid_i  && inport_wready_o)  || wvalid_q;

always @ (posedge clk_i )
if (rst_i)
    awvalid_q <= 1'b0;
else if (inport_awvalid_i && inport_awready_o && (!wr_data_accepted_w))
    awvalid_q <= 1'b1;
else if (wr_data_accepted_w)
    awvalid_q <= 1'b0;

always @ (posedge clk_i )
if (rst_i)
    wvalid_q <= 1'b0;
else if (inport_wvalid_i && inport_wready_o && !wr_cmd_accepted_w)
    wvalid_q <= 1'b1;
else if (wr_cmd_accepted_w)
    wvalid_q <= 1'b0;

//-----------------------------------------------------------------
// AXI: Write
//-----------------------------------------------------------------
reg [3:0]              write_pending_q;
reg [3:0]              write_pending_r;
reg [`ADDR_SEL_W-1:0]  write_port_q;
reg [`ADDR_SEL_W-1:0]  write_port_r;

always @ *
begin
    if (inport_awvalid_i & ~awvalid_q)
    begin
        write_port_r = `ADDR_SEL_W'b0;
        if ((inport_awaddr_i & `PERIPH0_MASK) == `PERIPH0_ADDR) write_port_r = `ADDR_SEL_W'd1;
    end
    else
        write_port_r = write_port_q;
end

wire write_incr_w = (inport_awvalid_i && inport_awready_o);
wire write_decr_w = (inport_bvalid_o  && inport_bready_i);

always @ *
begin
    write_pending_r = write_pending_q;

    if (write_incr_w && !write_decr_w)
        write_pending_r = write_pending_r + 4'd1;
    else if (!write_incr_w && write_decr_w)
        write_pending_r = write_pending_r - 4'd1;
end

always @ (posedge clk_i )
if (rst_i)
begin
    write_pending_q <= 4'b0;
    write_port_q    <= `ADDR_SEL_W'b0;
end
else
begin
    write_pending_q <= write_pending_r;

    // Write command accepted
    if (inport_awvalid_i && inport_awready_o)
    begin
        write_port_q <= write_port_r;
    end
end

wire write_accept_w      = (write_port_q == write_port_r && write_pending_q != 4'hF) || (write_pending_q == 4'h0);

assign outport_awvalid_o = inport_awvalid_i & ~awvalid_q & write_accept_w & (write_port_r == `ADDR_SEL_W'd0);
assign outport_awaddr_o  = inport_awaddr_i;
assign outport_wvalid_o  = inport_wvalid_i & ~wvalid_q & (inport_awvalid_i || awvalid_q) & (write_port_r == `ADDR_SEL_W'd0);
assign outport_wdata_o   = inport_wdata_i;
assign outport_wstrb_o   = inport_wstrb_i;
assign outport_bready_o  = inport_bready_i;

assign outport_peripheral0_awvalid_o = inport_awvalid_i & ~awvalid_q & write_accept_w & (write_port_r == `ADDR_SEL_W'd1);
assign outport_peripheral0_awaddr_o  = inport_awaddr_i;
assign outport_peripheral0_wvalid_o  = inport_wvalid_i & ~wvalid_q & ((inport_awvalid_i && write_accept_w) || awvalid_q) & (write_port_r == `ADDR_SEL_W'd1);
assign outport_peripheral0_wdata_o   = inport_wdata_i;
assign outport_peripheral0_wstrb_o   = inport_wstrb_i;
assign outport_peripheral0_bready_o  = inport_bready_i;

reg        outport_bvalid_r;
reg [1:0]  outport_bresp_r;

always @ *
begin
    case (write_port_q)
    `ADDR_SEL_W'd1:
    begin
        outport_bvalid_r = outport_peripheral0_bvalid_i;
        outport_bresp_r  = outport_peripheral0_bresp_i;
    end
    default:
    begin
        outport_bvalid_r = outport_bvalid_i;
        outport_bresp_r  = outport_bresp_i;
    end
    endcase
end

assign inport_bvalid_o  = outport_bvalid_r;
assign inport_bresp_o   = outport_bresp_r;

reg inport_awready_r;
reg inport_wready_r;

always @ *
begin
    case (write_port_r)
    `ADDR_SEL_W'd1:
    begin
        inport_awready_r = outport_peripheral0_awready_i;
        inport_wready_r  = outport_peripheral0_wready_i;
    end
    default:
    begin
        inport_awready_r = outport_awready_i;
        inport_wready_r  = outport_wready_i;
    end
    endcase
end

assign inport_awready_o = write_accept_w & ~awvalid_q & inport_awready_r;
assign inport_wready_o  = write_accept_w & ~wvalid_q & inport_wready_r;

//-----------------------------------------------------------------
// Transaction timeout detection (added)
//-----------------------------------------------------------------
// A read transaction is in flight from the cycle AR is valid until the read
// data handshake completes; a write from AW valid until the B handshake.
reg [TIMEOUT_WIDTH-1:0] read_timeout_timer;
reg [TIMEOUT_WIDTH-1:0] write_timeout_timer;

wire read_txn_active  = inport_arvalid_i | (read_pending_q  != 4'h0);
wire write_txn_active = inport_awvalid_i | (write_pending_q != 4'h0);
wire read_txn_done    = inport_rvalid_o & inport_rready_i;
wire write_txn_done   = inport_bvalid_o & inport_bready_i;

// Read timeout timer: counts while a read is outstanding, clears on
// completion or when no read is outstanding.
always @ (posedge clk_i)
if (rst_i)
    read_timeout_timer <= {TIMEOUT_WIDTH{1'b0}};
else if (read_txn_done || !read_txn_active)
    read_timeout_timer <= {TIMEOUT_WIDTH{1'b0}};
else
    read_timeout_timer <= read_timeout_timer + {{(TIMEOUT_WIDTH-1){1'b0}}, 1'b1};

// Write timeout timer.
always @ (posedge clk_i)
if (rst_i)
    write_timeout_timer <= {TIMEOUT_WIDTH{1'b0}};
else if (write_txn_done || !write_txn_active)
    write_timeout_timer <= {TIMEOUT_WIDTH{1'b0}};
else
    write_timeout_timer <= write_timeout_timer + {{(TIMEOUT_WIDTH-1){1'b0}}, 1'b1};

// Timeout flag: asserted when either timer reaches the threshold while its
// transaction is still outstanding. Held high until reset.
always @ (posedge clk_i)
if (rst_i)
    timeout_flag <= 1'b0;
else if ((read_txn_active  && (read_timeout_timer  >= timeout_threshold)) ||
         (write_txn_active && (write_timeout_timer >= timeout_threshold)))
    timeout_flag <= 1'b1;

endmodule

