(
    parameter IMG_WIDTH_IN  = 640,
    parameter IMG_HEIGHT_IN = 480,
    parameter IMG_WIDTH_OUT = 320,
    parameter IMG_HEIGHT_OUT = 240,
    parameter DATA_WIDTH    = 16
)
(
    input  wire                  clk,
    input  wire                  resetn,
    input  wire [DATA_WIDTH-1:0] s_axis_tdata,
    input  wire                  s_axis_tvalid,
    output                       s_axis_tready,
    input  wire                  s_axis_tlast,
    input  wire                  s_axis_tuser,

    output reg [DATA_WIDTH-1:0]  m_axis_tdata,
    output reg                   m_axis_tvalid,
    input  wire                  m_axis_tready,
    output reg                   m_axis_tlast,
    output reg                   m_axis_tuser
);

    // Internal counters for input and output
    reg [15:0] x_count_in, y_count_in;
    reg [15:0] x_count_out, y_count_out;

    // Downsampling factors
    localparam X_SCALE = IMG_WIDTH_IN  / IMG_WIDTH_OUT;
    localparam Y_SCALE = IMG_HEIGHT_IN / IMG_HEIGHT_OUT;

    // The resizer can accept input whenever the downstream border generator
    // is ready to accept the resized pixel stream.
    assign s_axis_tready = m_axis_tready;

    // Control logic for input and output data
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            x_count_in <= 0;
            y_count_in <= 0;
            x_count_out <= 0;
            y_count_out <= 0;
            m_axis_tvalid <= 0;
            m_axis_tlast <= 0;
            m_axis_tuser <= 0;
            m_axis_tdata <= 0;
        end else if (s_axis_tvalid && s_axis_tready) begin
            // Forward only the pixels that fall on the downsampling grid.
            if ((x_count_in % X_SCALE == 0) && (y_count_in % Y_SCALE == 0)) begin
                m_axis_tdata  <= s_axis_tdata;
                m_axis_tvalid <= 1'b1;
                m_axis_tuser  <= s_axis_tuser;
                m_axis_tlast  <= s_axis_tlast;
            end else begin
                m_axis_tvalid <= 1'b0;
                m_axis_tlast  <= 1'b0;
                m_axis_tuser  <= 1'b0;
            end

            // Advance the input pixel counters (row-major).
            if (s_axis_tlast) begin
                x_count_in <= 0;
                if (y_count_in == IMG_HEIGHT_IN - 1)
                    y_count_in <= 0;
                else
                    y_count_in <= y_count_in + 1'b1;
            end else begin
                x_count_in <= x_count_in + 1'b1;
            end
        end else begin
            m_axis_tvalid <= 1'b0;
        end
    end

endmodule"}]}

module binary_search_tree_sort #(
    parameter DATA_WIDTH = 32,
    parameter ARRAY_SIZE = 8
) (
    input clk,
    input reset,
    input reg [ARRAY_SIZE*DATA_WIDTH-1:0] data_in, // Input data to be sorted
    input start,
    output reg [ARRAY_SIZE*DATA_WIDTH-1:0] sorted_out, // Sorted output
    output reg done
);

    // Parameters for top-level FSM states
    parameter IDLE = 2'b00, BUILD_TREE = 2'b01, SORT_TREE = 2'b10;

    // Sub-FSM state encodings
    localparam INIT     = 2'b00,
               B_ROOT   = 2'b01,
               B_CMP    = 2'b10,
               COMPLETE = 2'b11;
    localparam S_INIT   = 2'b00,
               S_LEFT   = 2'b01,
               S_OUTPUT = 2'b10,
               S_RIGHT  = 2'b11;

    // Pointer width (one extra bit so the all-1s value is a NULL pointer)
    localparam WW = $clog2(ARRAY_SIZE) + 1;

    // Registers for FSM states
    reg [1:0] top_state, build_state, sort_state;

    // BST representation
    reg [ARRAY_SIZE*DATA_WIDTH-1:0] keys; // Array to store node keys
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] left_child; // Left child pointers
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] right_child; // Right child pointers
    reg [$clog2(ARRAY_SIZE):0] root; // Root node pointer
    reg [$clog2(ARRAY_SIZE):0] next_free_node; // Pointer to the next free node

    // Stack for in-order traversal
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] stack; // Stack for traversal
    reg [$clog2(ARRAY_SIZE):0] sp; // Stack pointer

    // Working registers
    reg [$clog2(ARRAY_SIZE):0] current_node; // Current node being processed
    reg [$clog2(ARRAY_SIZE):0] input_index; // Index for input data
    reg [$clog2(ARRAY_SIZE):0] output_index; // Index for output data
    reg [DATA_WIDTH-1:0] temp_data; // Temporary data register

    // Initialize all variables
    integer i;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset all states and variables
            top_state <= IDLE;
            build_state <= INIT;
            sort_state <= S_INIT;

            root <= {($clog2(ARRAY_SIZE)+1){1'b1}}; // Null pointer
            next_free_node <= 0;
            sp <= 0;
            input_index <= 0;
            output_index <= 0;
            done <= 0;
            sorted_out <= 0;
            current_node <= 0;
            temp_data <= 0;

            // Clear tree arrays
            for (i = 0; i < ARRAY_SIZE; i = i + 1) begin
                keys[i*DATA_WIDTH +: DATA_WIDTH] <= 0;
                left_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                right_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
            end

        end else begin
            case (top_state)
                IDLE: begin
                    done <= 0;
                    sorted_out <= 0;
                    input_index <= 0;
                    output_index <= 0;
                    root <= {($clog2(ARRAY_SIZE)+1){1'b1}}; // Null pointer
                    next_free_node <= 0;
                    sp <= 0;
                    for (i = 0; i < ARRAY_SIZE+1; i = i + 1) begin
                        if (i < ARRAY_SIZE) begin
                            keys[i*DATA_WIDTH +: DATA_WIDTH] <= 0;
                            left_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                            right_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                            stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        end
                    end
                    if (start) begin
                        // Load input data into input array
                        top_state <= BUILD_TREE;
                        build_state <= INIT;
                    end
                end

                BUILD_TREE: begin
                    case (build_state)
                        // Load the next number to be inserted from the input array
                        INIT: begin
                            if (input_index >= ARRAY_SIZE) begin
                                build_state <= COMPLETE;
                            end else begin
                                temp_data   <= data_in[input_index*DATA_WIDTH +: DATA_WIDTH];
                                build_state <= B_ROOT;
                            end
                        end

                        // Insert the root if the tree is empty, otherwise start
                        // traversal from the root.
                        B_ROOT: begin
                            input_index <= input_index + 1'b1;
                            if (root == {($clog2(ARRAY_SIZE)+1){1'b1}}) begin
                                keys[next_free_node*DATA_WIDTH +: DATA_WIDTH] <= temp_data;
                                root           <= next_free_node;
                                next_free_node <= next_free_node + 1'b1;
                                build_state    <= INIT;
                            end else begin
                                current_node <= root;
                                build_state  <= B_CMP;
                            end
                        end

                        // Compare with current_node and descend / insert.
                        B_CMP: begin
                            if (temp_data > keys[current_node*DATA_WIDTH +: DATA_WIDTH]) begin
                                // go right
                                if (right_child[current_node*WW +: WW] == {WW{1'b1}}) begin
                                    keys[next_free_node*DATA_WIDTH +: DATA_WIDTH] <= temp_data;
                                    right_child[current_node*WW +: WW] <= next_free_node;
                                    next_free_node <= next_free_node + 1'b1;
                                    build_state    <= INIT;
                                end else begin
                                    current_node <= right_child[current_node*WW +: WW];
                                end
                            end else begin
                                // go left
                                if (left_child[current_node*WW +: WW] == {WW{1'b1}}) begin
                                    keys[next_free_node*DATA_WIDTH +: DATA_WIDTH] <= temp_data;
                                    left_child[current_node*WW +: WW] <= next_free_node;
                                    next_free_node <= next_free_node + 1'b1;
                                    build_state    <= INIT;
                                end else begin
                                    current_node <= left_child[current_node*WW +: WW];
                                end
                            end
                        end

                        COMPLETE: begin
                            // Tree construction complete
                            top_state <= SORT_TREE;
                            sort_state <= S_INIT;
                        end

                    endcase
                end

                SORT_TREE: begin
                    case (sort_state)

                        S_INIT: begin
                            if (root == {($clog2(ARRAY_SIZE)+1){1'b1}}) begin
                                // Empty tree, nothing to sort
                                done      <= 1'b1;
                                top_state <= IDLE;
                            end else begin
                                current_node <= root;
                                sort_state   <= S_LEFT;
                            end
                        end

                        // Descend the left spine, pushing nodes on the stack.
                        S_LEFT: begin
                            if (current_node != {WW{1'b1}}) begin
                                stack[sp*WW +: WW] <= current_node;
                                sp <= sp + 1'b1;
                                current_node <= left_child[current_node*WW +: WW];
                            end else begin
                                sort_state <= S_OUTPUT;
                            end
                        end

                        // Pop a node, emit its key, then visit its right child.
                        S_OUTPUT: begin
                            if (sp == 0) begin
                                done      <= 1'b1;
                                top_state <= IDLE;
                            end else begin
                                sp <= sp - 1'b1;
                                sorted_out[output_index*DATA_WIDTH +: DATA_WIDTH] <=
                                    keys[stack[(sp-1)*WW +: WW]*DATA_WIDTH +: DATA_WIDTH];
                                current_node <= stack[(sp-1)*WW +: WW];
                                output_index <= output_index + 1'b1;
                                sort_state   <= S_RIGHT;
                            end
                        end

                        S_RIGHT: begin
                            current_node <= right_child[current_node*WW +: WW];
                            sort_state   <= S_LEFT;
                        end

                    endcase
                end
            endcase
        end
    end
endmodule

module search_binary_search_tree #(
    parameter DATA_WIDTH = 32,         // Width of the data (of a single element)
    parameter ARRAY_SIZE = 15          // Maximum number of elements in the BST
) (

    input clk,                         // Clock signal
    input reset,                       // Reset signal
    input reg start,                   // Start signal to initiate the search
    input reg [DATA_WIDTH-1:0] search_key, // Key to search in the BST
    input reg [$clog2(ARRAY_SIZE):0] root, // Root node of the BST
    input reg [ARRAY_SIZE*DATA_WIDTH-1:0] keys, // Node keys in the BST
    input reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] left_child, // Left child pointers
    input reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] right_child, // Right child pointers
    output reg [$clog2(ARRAY_SIZE):0] key_position, // Position of the found key
    output reg complete_found,         // Signal indicating search completion
    output reg search_invalid          // Signal indicating invalid search
);

    // Parameters for FSM states
    parameter S_IDLE = 3'b000,                 // Idle state
              S_INIT = 3'b001,                 // Initialization state
              S_SEARCH_LEFT = 3'b010,          // Search in left subtree
              S_SEARCH_LEFT_RIGHT = 3'b011,    // Search in both left and right subtrees
              S_COMPLETE_SEARCH = 3'b100;      // Search completion state

    // Pointer width (one extra bit so the all-1s value is a NULL pointer)
    localparam WW = $clog2(ARRAY_SIZE) + 1;

    // Registers to store the current FSM state
    reg [2:0] search_state;

    // Variables to manage traversal
    reg [$clog2(ARRAY_SIZE):0] position;       // Position of the current node
    reg found;                                 // Indicates if the key is found

    reg left_done, right_done;                 // Flags to indicate completion of left and right subtree traversals

    // Stacks for managing traversal of left and right subtrees
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] left_stack;  // Stack for left subtree traversal
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] right_stack; // Stack for right subtree traversal
    reg [$clog2(ARRAY_SIZE):0] sp_left;         // Stack pointer for left subtree
    reg [$clog2(ARRAY_SIZE):0] sp_right;        // Stack pointer for right subtree

    // Pointers for the current nodes in left and right subtrees
    reg [$clog2(ARRAY_SIZE):0] current_left_node;  // Current node in the left subtree
    reg [$clog2(ARRAY_SIZE):0] current_right_node; // Current node in the right subtree

    // Output indices for traversal
    reg [$clog2(ARRAY_SIZE):0] left_output_index;  // Output index for left subtree
    reg [$clog2(ARRAY_SIZE):0] right_output_index; // Output index for right subtree

    // Integer for loop iterations
    integer i;

    // Always block triggered on the rising edge of the clock or reset signal
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset all states and variables
            search_state <= S_IDLE;  // Set state to IDLE
            found <= 0;              // Reset found flag
            position <= {($clog2(ARRAY_SIZE)+1){1'b1}}; // Invalid position
            complete_found <= 0;     // Reset complete_found signal
            key_position <= {($clog2(ARRAY_SIZE)+1){1'b1}}; // Invalid key position
            left_output_index <= 0;  // Reset left output index
            right_output_index <= 0; // Reset right output index
            sp_left <= 0;            // Reset left stack pointer
            sp_right <= 0;           // Reset right stack pointer
            left_done <= 0;          // Reset left_done flag
            right_done <= 0;         // Reset right_done flag
            search_invalid <= 0;        // Set invalid_key to 0
            current_left_node <= 0;
            current_right_node <= 0;

            // Clear the stacks
            for (i = 0; i < ARRAY_SIZE; i = i + 1) begin
                left_stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                right_stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
            end

        end else begin
            // Main FSM logic
            case (search_state)
                S_IDLE: begin
                    // Reset intermediate variables
                    for (i = 0; i < ARRAY_SIZE+1; i = i + 1) begin
                        if (i < ARRAY_SIZE) begin
                            left_stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                            right_stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        end
                    end
                    complete_found <= 0;
                    search_invalid <= 0;

                    if (start) begin
                        // Start the search
                        left_output_index <= 0;
                        right_output_index <= 0;
                        sp_left <= 0;
                        sp_right <= 0;
                        left_done <= 0;
                        right_done <= 0;
                        found <= 0;
                        position <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        key_position <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        search_state <= S_INIT; // Move to INIT state
                    end
                end

                S_INIT: begin
                    // Detect an empty tree (root has zero key and no children),
                    // otherwise begin the in-order traversal from the root.
                    if ((keys[root*DATA_WIDTH +: DATA_WIDTH] == {DATA_WIDTH{1'b0}}) &&
                        (left_child[root*WW +: WW]  == {WW{1'b1}}) &&
                        (right_child[root*WW +: WW] == {WW{1'b1}})) begin
                        found        <= 1'b0;
                        search_state <= S_COMPLETE_SEARCH;
                    end else begin
                        current_left_node <= root;
                        search_state      <= S_SEARCH_LEFT;
                    end
                end

                S_SEARCH_LEFT: begin
                    // Descend the left spine, pushing nodes on the stack.
                    if (current_left_node != {WW{1'b1}}) begin
                        left_stack[sp_left*WW +: WW] <= current_left_node;
                        sp_left <= sp_left + 1'b1;
                        current_left_node <= left_child[current_left_node*WW +: WW];
                    end else begin
                        search_state <= S_SEARCH_LEFT_RIGHT;
                    end
                end

                S_SEARCH_LEFT_RIGHT: begin
                    // Pop a node (visited in sorted order). If it matches the
                    // search key, record its in-order position; otherwise move
                    // on to its right child and keep traversing.
                    if (sp_left == 0) begin
                        // Whole tree traversed, key not present
                        found        <= 1'b0;
                        search_state <= S_COMPLETE_SEARCH;
                    end else begin
                        sp_left <= sp_left - 1'b1;
                        if (keys[left_stack[(sp_left-1)*WW +: WW]*DATA_WIDTH +: DATA_WIDTH] == search_key) begin
                            found        <= 1'b1;
                            position     <= left_output_index;
                            search_state <= S_COMPLETE_SEARCH;
                        end else begin
                            left_output_index <= left_output_index + 1'b1;
                            current_left_node <= right_child[left_stack[(sp_left-1)*WW +: WW]*WW +: WW];
                            search_state      <= S_SEARCH_LEFT;
                        end
                    end
                end

                S_COMPLETE_SEARCH: begin
                    // Drive the result outputs for a single cycle.
                    if (found) begin
                        complete_found <= 1'b1;
                        key_position   <= position;
                        search_invalid <= 1'b0;
                    end else begin
                        complete_found <= 1'b0;
                        key_position   <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        search_invalid <= 1'b1;
                    end
                    search_state <= S_IDLE;
                end

                default: begin
                    search_state <= S_IDLE; // Default to IDLE state
                end
            endcase
        end
    end

endmodule

module cvdp_copilot_bus_arbiter (
    input wire reset,
    input wire clk,
    input wire req1,
    input wire req2,
    output reg grant1,
    output reg grant2
);
    // State encoding using localparam
    localparam IDLE    = 3'b000,
               GRANT_1 = 3'b001,
               GRANT_2 = 3'b010,
               CLEAR   = 3'b011;

    // State registers
    reg [2:0] state;
    reg [2:0] next_state;

    // Sequential logic for state transition
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Combinational logic for next state
    always @(*) begin
        // Default assignments
        next_state = state;

        case (state)
            IDLE: begin
                // req2 prioritized when both are active
                if (req2)
                    next_state = GRANT_2;
                else if (req1)
                    next_state = GRANT_1;
                else
                    next_state = IDLE;
            end

            GRANT_1: begin
                // req2 preempts req1 (req2 has priority)
                if (req2)
                    next_state = GRANT_2;
                else if (!req1)
                    next_state = CLEAR;   // req1 deasserted -> clear
                else
                    next_state = GRANT_1;
            end

            GRANT_2: begin
                if (!req2)
                    next_state = CLEAR;   // req2 deasserted -> clear
                else
                    next_state = GRANT_2;
            end

            CLEAR: begin
                // Return to IDLE OR serve another pending request
                if (req2)
                    next_state = GRANT_2;
                else if (req1)
                    next_state = GRANT_1;
                else
                    next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

    // Output logic (driven by the next state of the FSM)
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            grant1 <= 1'b0;
            grant2 <= 1'b0;
        end else begin
            case (next_state)
                GRANT_1: begin
                    grant1 <= 1'b1;
                    grant2 <= 1'b0;
                end
                GRANT_2: begin
                    grant1 <= 1'b0;
                    grant2 <= 1'b1;
                end
                default: begin
                    grant1 <= 1'b0;
                    grant2 <= 1'b0;
                end
            endcase
        end
    end

endmodule

module pseudo_lru_nmru_policy #(
    parameter NWAYS = 4,
    parameter NINDEXES = 32
) (
    input clock,
    input reset,
    input [$clog2(NINDEXES)-1:0] index,
    input [$clog2(NWAYS)-1:0] way_select,
    input access,
    input hit,
    output [$clog2(NWAYS)-1:0] way_replace
);

reg [NWAYS-1:0] recency [NINDEXES-1:0];

// ----------------------------------------------------------------------
// Replacement selection: a way is a candidate for replacement when its
// recency bit is 0. When several bits are 0 (NMRU) the smallest index is
// pointed first; when only one bit is 0 it is the LRU way.
// ----------------------------------------------------------------------
reg [$clog2(NWAYS)-1:0] way_replace_r;
integer k;
always @(*) begin
    way_replace_r = {$clog2(NWAYS){1'b0}};
    // scan from high index to low so the lowest zero index wins
    for (k = NWAYS-1; k >= 0; k = k - 1) begin
        if (recency[index][k] == 1'b0)
            way_replace_r = k[$clog2(NWAYS)-1:0];
    end
end
assign way_replace = way_replace_r;

// ----------------------------------------------------------------------
// Recency update: combinational next value for the accessed set.
//   - On a hit the accessed way's recency bit is set to 1.
//   - If setting it makes every bit 1 (it was the last 0 -> LRU case),
//     collapse: keep only the accessed way at 1, reset all others to 0.
// ----------------------------------------------------------------------
reg [NWAYS-1:0] recency_next;
always @(*) begin
    recency_next = recency[index];
    recency_next[way_select] = 1'b1;
    if (&recency_next) begin
        recency_next = {NWAYS{1'b0}};
        recency_next[way_select] = 1'b1;
    end
end

integer reset_counter;
always_ff @ (posedge clock or posedge reset) begin
    if (reset) begin
        for (reset_counter = 0; reset_counter < NINDEXES; reset_counter = reset_counter + 1) begin
            recency[reset_counter] <= {NWAYS{1'b0}};
        end
    end else begin
        if (access && hit) begin
            recency[index] <= recency_next;
        end
    end
end

endmodule : pseudo_lru_nmru_policy

module pseudo_lru_tree_policy #(
    parameter NWAYS = 4,
    parameter NINDEXES = 32
)(
    input clock,
    input reset,
    input [$clog2(NINDEXES)-1:0] index,
    input [$clog2(NWAYS)-1:0] way_select,
    input access,
    input hit,
    output [$clog2(NWAYS)-1:0] way_replace
);

    localparam int unsigned NBITS_TREE = NWAYS - 1;

    // Recency array to track next way to be replaced
    reg [NBITS_TREE-1:0] recency [NINDEXES-1:0];

    wire [NBITS_TREE-1:0] recency_updated;
    wire [$clog2(NWAYS)-1:0] pseudo_lru_slot;

    integer i;

    // Sequential logic for reset and recency updates
    always_ff @ (posedge clock or posedge reset) begin
        if (reset) begin
            for (i = 0; i < NINDEXES; i++) begin
                recency[i] <= {NBITS_TREE{1'b0}};
            end
        end else begin
            if (access) begin
                recency[index] <= recency_updated;
            end
        end
    end

    // On a hit the accessed way (way_select) becomes MRU; on a miss the
    // replaced way (the current LRU slot) becomes MRU. In both cases mark
    // the tree to point AWAY from that way along its root-to-leaf path.
    wire [$clog2(NWAYS)-1:0] target_way = hit ? way_select : pseudo_lru_slot;

    function automatic [NBITS_TREE-1:0] mark_mru
        (input [NBITS_TREE-1:0] cur, input [$clog2(NWAYS)-1:0] way);
        integer d;
        reg [$clog2(NWAYS)-1:0] pos;
        reg pbit;
        begin
            mark_mru = cur;
            pos = {$clog2(NWAYS){1'b0}};
            for (d = 0; d < $clog2(NWAYS); d = d + 1) begin
                // path bit at depth d, MSB-first toward the accessed leaf
                pbit = way[$clog2(NWAYS)-1 - d];
                // node bit points to the opposite (non-accessed) subtree
                mark_mru[(2**d - 1) + pos] = ~pbit;
                pos = (pos << 1) | pbit;
            end
        end
    endfunction

    // Update recency tree for the accessed/replaced way (mark it MRU)
    assign recency_updated = mark_mru(recency[index], target_way);

    // Select the Pseudo LRU slot
    slot_select_pseudo_lru_tree #(
        .NWAYS (NWAYS)
    ) slot_select_unit (
        .array (recency[index]),
        .index (pseudo_lru_slot)
    );

    assign way_replace = pseudo_lru_slot;

endmodule : pseudo_lru_tree_policy

module slot_select_pseudo_lru_tree #(
    parameter NWAYS = 4
)(
    input [NWAYS-2:0] array,
    output logic [$clog2(NWAYS)-1:0] index
);

    localparam int unsigned MAX_DEPTH = $clog2(NWAYS);

    integer depth;
    logic [$clog2(NWAYS)-1:0] step;
    logic direction;

    always_comb begin
        // Find the Pseudo LRU way index by descending the tree: at each node
        // the bit indicates which subtree holds the LRU way (0 -> left).
        step = {$clog2(NWAYS){1'b0}};
        direction = 1'b0;
        for (depth = 0; depth < MAX_DEPTH; depth = depth + 1) begin
            direction = array[(2**depth - 1) + step];
            step = (step << 1) | direction;
        end
        index = step;
    end

endmodule : slot_select_pseudo_lru_tree

module clock_jitter_detection_module #(
    parameter JITTER_THRESHOLD = 5    // Threshold (in clock cycles) for detecting jitter
)(
    input logic clk,               // Input clock
    input logic system_clk,        // Input system clock
    input logic rst,               // Active high reset
    output logic jitter_detected   // Output flag indicating jitter detection
);

    // Internal signals
    logic [31:0] edge_count, edge_count_r;   // Counters to measure time between rising edges
    logic prev_system_clk;                   // To store the previous clock state (rising edge detection)
    logic edge_detected;                     // Flag for detecting rising edges
    logic start_counter;

    // Rising edge detection logic (detects when clock transitions from 0 to 1)
    always @(posedge clk) begin
        if (rst) begin
            // Initialize counters, edge detection, and jitter detection on reset
            edge_count      <= 32'd0;
            edge_count_r    <= 32'd0;
            prev_system_clk <= 1'b0;
            edge_detected   <= 1'b0;
            start_counter   <= 1'b0;
            jitter_detected <= 1'b0;
        end else begin
            prev_system_clk <= system_clk;

            // Detect rising edge transition of system_clk
            edge_detected <= (system_clk & ~prev_system_clk);

            if (system_clk & ~prev_system_clk) begin
                // New rising edge: latch the measured interval, restart the counter
                edge_count_r  <= edge_count;
                edge_count    <= 32'd0;
                start_counter <= 1'b1;

                // Compare measured interval against the threshold. Jitter is
                // flagged when it deviates from JITTER_THRESHOLD by more than
                // one clock cycle. Asserted for a single clk cycle.
                if ((edge_count > (JITTER_THRESHOLD + 1)) ||
                    ((edge_count + 1) < JITTER_THRESHOLD))
                    jitter_detected <= 1'b1;
                else
                    jitter_detected <= 1'b0;
            end else begin
                // No edge this cycle: keep counting clk cycles until next edge
                if (start_counter)
                    edge_count <= edge_count + 32'd1;
                jitter_detected <= 1'b0;
            end
        end
    end

endmodule

module coffee_machine #(
    parameter NBW_DLY    = 'd5,
    parameter NBW_BEANS  = 'd2,
    parameter NS_BEANS   = 'd4,
    parameter NS_OP      = 'd3, // Fixed
    parameter NS_SENSOR  = 'd4  // Fixed
) (
    input  logic                 clk,
    input  logic                 rst_async_n,
    input  logic [NBW_DLY-1:0]   i_grind_delay,
    input  logic [NBW_DLY-1:0]   i_heat_delay,
    input  logic [NBW_DLY-1:0]   i_pour_delay,
    input  logic [NBW_BEANS-1:0] i_bean_sel,
    input  logic [NS_OP-1:0]     i_operation_sel,
    input  logic                 i_start,
    input  logic [NS_SENSOR-1:0] i_sensor,
    output logic [NS_BEANS-1:0]  o_bean_sel,
    output logic                 o_grind_beans,
    output logic                 o_use_powder,
    output logic                 o_heat_water,
    output logic                 o_pour_coffee,
    output logic                 o_error
);

// Fixed delays (bean selection and powder usage)
localparam SEL_CYCLES    = 'd3;
localparam POWDER_CYCLES = 'd2;

typedef enum logic [2:0] {
    IDLE     = 3'b000,
    BEAN_SEL = 3'b001,
    GRIND    = 3'b011,
    POWDER   = 3'b111,
    HEAT     = 3'b110,
    POUR     = 3'b100
} state_t;

// ----------------------------------------
// - Wires/Registers creation
// ----------------------------------------
state_t state_ff, state_nx;
logic [NBW_DLY:0]     counter_ff, counter_nx;
logic [NBW_DLY-1:0]   grind_delay_ff, heat_delay_ff, pour_delay_ff;
logic [NS_OP-1:0]     operation_sel_ff;
logic [NBW_BEANS-1:0] bean_sel_in_ff;
logic                 start_ff;

// Output assignment (error conditions)
always_comb begin : error_logic
    if(state_ff == IDLE) begin
        o_error = (i_sensor[0] | i_sensor[3]) | (&i_operation_sel[2:1]) | (i_operation_sel[1] & i_sensor[1]) | ((i_operation_sel[2] || i_operation_sel[0]) & i_sensor[2]);
    end else begin
        o_error = i_sensor[3];
    end
end

// ----------------------------------------
// - Registers
// ----------------------------------------
always_ff @(posedge clk) begin : data_regs
    // The operation may only start when there is no error: no water / generic
    // error, the operation is not the illegal 3'b11x, the bean sensor is not
    // tripped for a bean-using operation, and the powder sensor is not tripped
    // for a powder-without-beans operation.
    start_ff <= i_start
                & ~(i_sensor[0] | i_sensor[3])
                & ~(&i_operation_sel[2:1])
                & ~(i_operation_sel[1] & i_sensor[1])
                & ~((i_operation_sel == 3'b100 || i_operation_sel == 3'b001) & i_sensor[2]);

    if(i_start && state_ff == IDLE) begin
        operation_sel_ff <= i_operation_sel;
        grind_delay_ff   <= i_grind_delay;
        heat_delay_ff    <= i_heat_delay;
        pour_delay_ff    <= i_pour_delay;
        bean_sel_in_ff   <= i_bean_sel;
    end

    counter_ff      <= counter_nx;
end

always_ff @(posedge clk or negedge rst_async_n) begin : reset_regs
    if(~rst_async_n) begin
        state_ff <= IDLE;
    end else begin
        state_ff <= state_nx;
    end
end

// ----------------------------------------
// - FSM update
// ----------------------------------------
always_comb begin
    case(state_ff)
        IDLE: begin
            counter_nx = 0;

            if(start_ff) begin
                if(~(|i_operation_sel[2:1])) begin
                    state_nx = HEAT;
                end else if(i_operation_sel[1]) begin
                    state_nx = BEAN_SEL;
                end else if(i_operation_sel[0]) begin
                    state_nx = POUR;
                end else begin
                    state_nx = POWDER;
                end
            end else begin
                state_nx = IDLE;
            end
        end
        BEAN_SEL: begin
            if(counter_ff >= SEL_CYCLES - 1) begin
                counter_nx = 0;
                state_nx   = GRIND;
            end else begin
                counter_nx = counter_ff + 1'b1;
                state_nx   = BEAN_SEL;
            end
        end
        GRIND: begin
            if(counter_ff >= grind_delay_ff - 1) begin
                counter_nx = 0;
                if(operation_sel_ff[0]) begin
                    state_nx = POWDER;
                end else begin
                    state_nx = HEAT;
                end
            end else begin
                counter_nx = counter_ff + 1'b1;
                state_nx   = GRIND;
            end
        end
        POWDER: begin
            if(counter_ff >= POWDER_CYCLES - 1) begin
                counter_nx = 0;
                state_nx   = POUR;
            end else begin
                counter_nx = counter_ff + 1'b1;
                state_nx   = POWDER;
            end
        end
        HEAT: begin
            if(counter_ff >= heat_delay_ff - 1) begin
                counter_nx = 0;
                if(|operation_sel_ff[1:0]) begin
                    state_nx = POWDER;
                end else begin
                    state_nx = POUR;
                end
            end else begin
                counter_nx = counter_ff + 1'b1;
                state_nx   = HEAT;
            end
        end
        POUR: begin
            if(counter_ff >= pour_delay_ff - 1) begin
                counter_nx = 0;
                state_nx   = IDLE;
            end else begin
                counter_nx = counter_ff + 1'b1;
                state_nx   = POUR;
            end
        end
        default: begin
            counter_nx = 0;
            state_nx   = IDLE;
        end
    endcase
end

// ----------------------------------------
// - Controller outputs
// ----------------------------------------
always_comb begin
    case(state_ff)
        IDLE: begin
            o_bean_sel      = {NS_BEANS{1'b0}};
            o_use_powder    = 1'b0;
            o_grind_beans   = 1'b0;
            o_heat_water    = 1'b0;
            o_pour_coffee   = 1'b0;
        end
        BEAN_SEL: begin
            o_bean_sel                      = 1'b0; // Set all bits to 0
            o_bean_sel[bean_sel_in_ff]      = 1'b1; // Only the position of bean_sel_ff should be 1
            o_grind_beans                   = 1'b0;
            o_use_powder                    = 1'b0;
            o_heat_water                    = 1'b0;
            o_pour_coffee                   = 1'b0;
        end
        GRIND: begin
            o_bean_sel      = {NS_BEANS{1'b0}};
            o_grind_beans   = 1'b1;
            o_use_powder    = 1'b0;
            o_heat_water    = 1'b0;
            o_pour_coffee   = 1'b0;
        end
        POWDER: begin
            o_bean_sel      = {NS_BEANS{1'b0}};
            o_grind_beans   = 1'b0;
            o_use_powder    = 1'b1;
            o_heat_water    = 1'b0;
            o_pour_coffee   = 1'b0;
        end
        HEAT: begin
            o_bean_sel      = {NS_BEANS{1'b0}};
            o_grind_beans   = 1'b0;
            o_use_powder    = 1'b0;
            o_heat_water    = 1'b1;
            o_pour_coffee   = 1'b0;
        end
        POUR: begin
            o_bean_sel      = {NS_BEANS{1'b0}};
            o_grind_beans   = 1'b0;
            o_use_powder    = 1'b0;
            o_heat_water    = 1'b0;
            o_pour_coffee   = 1'b1;
        end
        default: begin
            o_bean_sel      = {NS_BEANS{1'b0}};
            o_grind_beans   = 1'b0;
            o_use_powder    = 1'b0;
            o_heat_water    = 1'b0;
            o_pour_coffee   = 1'b0;
        end
    endcase
end

endmodule : coffee_machine

module enhanced_fsm_signal_processor (
    input  wire        i_clk,
    input  wire        i_rst_n,
    input  wire        i_enable,
    input  wire        i_clear,
    input  wire        i_ack,
    input  wire        i_fault,
    input  wire [4:0]  i_vector_1,
    input  wire [4:0]  i_vector_2,
    input  wire [4:0]  i_vector_3,
    input  wire [4:0]  i_vector_4,
    input  wire [4:0]  i_vector_5,
    input  wire [4:0]  i_vector_6,
    output reg         o_ready,
    output reg         o_error,
    output reg [1:0]   o_fsm_status,
    output reg [7:0]   o_vector_1,
    output reg [7:0]   o_vector_2,
    output reg [7:0]   o_vector_3,
    output reg [7:0]   o_vector_4
);

    // FSM state encoding
    localparam [1:0] IDLE    = 2'b00,
                     PROCESS = 2'b01,
                     READY   = 2'b10,
                     FAULT   = 2'b11;

    reg [1:0] state;

    // 30-bit concatenation of the six 5-bit vectors (i_vector_1 = MSB),
    // with two '1' bits appended at the LSB -> 32-bit bus.
    wire [31:0] concat_bus = {i_vector_1, i_vector_2, i_vector_3,
                              i_vector_4, i_vector_5, i_vector_6, 2'b11};

    always @(posedge i_clk or negedge i_rst_n) begin
        if (!i_rst_n) begin
            state        <= IDLE;
            o_ready      <= 1'b0;
            o_error      <= 1'b0;
            o_fsm_status <= IDLE;
            o_vector_1   <= 8'd0;
            o_vector_2   <= 8'd0;
            o_vector_3   <= 8'd0;
            o_vector_4   <= 8'd0;
        end else begin
            // Default pulse deassertions
            o_ready <= 1'b0;
            o_error <= 1'b0;

            // i_fault takes precedence over every other input (except clk/rst).
            if (i_fault && state != FAULT) begin
                state        <= FAULT;
                o_fsm_status <= FAULT;
                o_error      <= 1'b1;
                o_vector_1   <= 8'd0;
                o_vector_2   <= 8'd0;
                o_vector_3   <= 8'd0;
                o_vector_4   <= 8'd0;
            end else begin
                case (state)
                    IDLE: begin
                        o_fsm_status <= IDLE;
                        if (i_enable) begin
                            state        <= PROCESS;
                            o_fsm_status <= PROCESS;
                        end
                    end

                    PROCESS: begin
                        // Split the 32-bit bus into four 8-bit vectors
                        // (o_vector_1 = MSB .. o_vector_4 = LSB).
                        o_vector_1   <= concat_bus[31:24];
                        o_vector_2   <= concat_bus[23:16];
                        o_vector_3   <= concat_bus[15:8];
                        o_vector_4   <= concat_bus[7:0];
                        o_ready      <= 1'b1;        // valid alongside READY
                        state        <= READY;
                        o_fsm_status <= READY;
                    end

                    READY: begin
                        o_ready      <= 1'b1;        // hold until acknowledged
                        o_fsm_status <= READY;
                        if (i_ack) begin
                            o_ready      <= 1'b0;
                            state        <= IDLE;
                            o_fsm_status <= IDLE;
                        end
                    end

                    FAULT: begin
                        o_error      <= 1'b1;
                        o_fsm_status <= FAULT;
                        o_vector_1   <= 8'd0;
                        o_vector_2   <= 8'd0;
                        o_vector_3   <= 8'd0;
                        o_vector_4   <= 8'd0;
                        // Leave FAULT only when cleared and the fault is gone
                        if (i_clear && !i_fault) begin
                            o_error      <= 1'b0;
                            state        <= IDLE;
                            o_fsm_status <= IDLE;
                        end
                    end

                    default: begin
                        state        <= IDLE;
                        o_fsm_status <= IDLE;
                    end
                endcase
            end
        end
    end

endmodule

module advanced_decimator_with_adaptive_peak_detection #(
    parameter N          = 8,
    parameter DATA_WIDTH = 16,
    parameter DEC_FACTOR = 4
)(
    input  wire                                  clk,
    input  wire                                  reset,      // async, active high
    input  wire                                  valid_in,
    input  wire [DATA_WIDTH*N-1:0]               data_in,    // N packed signed samples
    output reg                                   valid_out,
    output wire [DATA_WIDTH*(N/DEC_FACTOR)-1:0]  data_out,
    output wire [DATA_WIDTH-1:0]                 peak_value
);
    localparam M = N / DEC_FACTOR;   // number of decimated samples

    integer i, j;

    // ---------------------------------------------------------------
    // 1. Input data registering (cleared on reset)
    // ---------------------------------------------------------------
    reg [DATA_WIDTH*N-1:0] data_in_reg;
    always @(posedge clk or posedge reset) begin
        if (reset)
            data_in_reg <= {(DATA_WIDTH*N){1'b0}};
        else
            data_in_reg <= data_in;
    end

    // ---------------------------------------------------------------
    // 2-5. Combinational unpack -> decimate -> peak -> pack
    //   Packed bus is MSB-first: the first element of the {a,b,c,...}
    //   concatenation occupies the most-significant slice.
    // ---------------------------------------------------------------
    reg signed [DATA_WIDTH-1:0] samples [0:N-1];
    reg signed [DATA_WIDTH-1:0] decimated [0:M-1];
    reg signed [DATA_WIDTH-1:0] peak_comb;
    reg        [DATA_WIDTH*M-1:0] data_out_comb;

    always @(*) begin
        // unpack
        for (i = 0; i < N; i = i + 1)
            samples[i] = data_in_reg[DATA_WIDTH*(N-1-i) +: DATA_WIDTH];

        // decimate: take one sample every DEC_FACTOR positions
        for (j = 0; j < M; j = j + 1)
            decimated[j] = samples[j*DEC_FACTOR];

        // peak detection (signed max over the decimated set)
        peak_comb = decimated[0];
        for (j = 1; j < M; j = j + 1)
            if (decimated[j] > peak_comb)
                peak_comb = decimated[j];

        // pack the decimated samples back, MSB-first
        for (j = 0; j < M; j = j + 1)
            data_out_comb[DATA_WIDTH*(M-1-j) +: DATA_WIDTH] = decimated[j];
    end

    assign data_out   = data_out_comb;
    assign peak_value = peak_comb;

    // ---------------------------------------------------------------
    // 6. Validation control (registered) -> fixed 1-cycle latency
    // ---------------------------------------------------------------
    always @(posedge clk or posedge reset) begin
        if (reset)
            valid_out <= 1'b0;
        else
            valid_out <= valid_in;
    end

endmodule

module sgd_linear_regression #(
    parameter DATA_WIDTH = 16,
    parameter LEARNING_RATE = 3'd1
) (
    input  logic clk,                               // Clock
    input  logic reset,                             // Asynchronous reset
    input  logic signed [DATA_WIDTH-1:0] x_in,      // Input data (x)
    input  logic signed [DATA_WIDTH-1:0] y_true,    // True output (target)
    output logic signed [DATA_WIDTH-1:0] w,     // Trained weight
    output logic signed [DATA_WIDTH-1:0] b      // Trained bias
);
    localparam NBW_PRED  = 2*DATA_WIDTH + 1;
    localparam NBW_ERROR = NBW_PRED + 1;
    localparam NBW_DELTA = 3 + NBW_ERROR + DATA_WIDTH;

    // Intermediate values
    logic signed [NBW_PRED-1:0] y_pred;
    logic signed [NBW_ERROR-1:0] error;
    logic signed [NBW_DELTA-1:0] delta_w;
    logic signed [NBW_DELTA-1:0] delta_b;

    // Predicted output caculation
    always_comb begin
      y_pred = (w * x_in) + b;
    end

    // Error calculation (combinational): error = y_true - y_pred
    always_comb begin
      error = y_true - y_pred;
    end

    // Weight and bias update terms (combinational).
    // LEARNING_RATE is a small non-negative constant (0,1,2); make it signed so
    // the multiplication keeps `error`/`x_in` signed (a bare unsigned parameter
    // operand would force an unsigned product and corrupt negative operands).
    always_comb begin
      delta_w = ($signed(LEARNING_RATE) * error) * x_in;
      delta_b =  $signed(LEARNING_RATE) * error;
    end

    // Sequential weight/bias adjustment; w/b keep the DATA_WIDTH LSBs of the sum.
    always_ff @(posedge clk or posedge reset) begin
      if (reset) begin
        w <= '0;
        b <= '0;
      end else begin
        w <= w + delta_w;
        b <= b + delta_b;
      end
    end

endmodule

module cont_adder #(
  parameter DATA_WIDTH = 32,
  parameter signed THRESHOLD_VALUE_1 = 50,
  parameter signed THRESHOLD_VALUE_2 = 100,
  parameter signed THRESHOLD_VALUE_3 = 150,
  parameter ACCUM_MODE = 0,
  parameter WEIGHT = 1,
  parameter signed SAT_MAX = (2**(DATA_WIDTH-1))-1,
  parameter signed SAT_MIN = -(2**(DATA_WIDTH-1))
) (
  input  logic                         clk,
  input  logic                         reset,
  input  logic                         accum_clear,
  input  logic                         enable,
  input  logic signed [DATA_WIDTH-1:0] data_in,
  input  logic                         data_valid,
  input  logic [15:0]                  window_size,
  output logic signed [DATA_WIDTH-1:0] sum_out,
  output logic signed [DATA_WIDTH-1:0] avg_out,
  output logic                         threshold_1,
  output logic                         threshold_2,
  output logic                         threshold_3,
  output logic                         sum_ready,
  output logic                         busy
);

  typedef enum logic [1:0] {IDLE, ACCUM, DONE} state_t;
  state_t state;
  logic signed [DATA_WIDTH-1:0] sum_accum;
  logic [15:0] sample_count;
  logic signed [DATA_WIDTH-1:0] weighted_in_reg;
  logic signed [DATA_WIDTH-1:0] sat_sum;

  // The smallest threshold magnitude: an OR of |x|>=T_i collapses to |x|>=min(T_i).
  localparam signed THRESHOLD_MIN =
      (THRESHOLD_VALUE_1 <= THRESHOLD_VALUE_2)
        ? ((THRESHOLD_VALUE_1 <= THRESHOLD_VALUE_3) ? THRESHOLD_VALUE_1
                                                    : THRESHOLD_VALUE_3)
        : ((THRESHOLD_VALUE_2 <= THRESHOLD_VALUE_3) ? THRESHOLD_VALUE_2
                                                    : THRESHOLD_VALUE_3);

  always_ff @(posedge clk or posedge reset) begin
    if (reset)
      weighted_in_reg <= 0;
    else if (enable && data_valid) begin
      if (WEIGHT == 1)
        weighted_in_reg <= data_in;
      else
        weighted_in_reg <= data_in * WEIGHT;
    end else
      weighted_in_reg <= weighted_in_reg;
  end

  // The running sum stage with overflow saturation (kept bit-identical to the
  // original; only the dead `new_sum` register/adder was removed).
  always_ff @(posedge clk or posedge reset) begin
    if (reset)
      sat_sum <= 0;
    else if (enable && data_valid) begin
      if ((sum_accum + weighted_in_reg) > SAT_MAX)
        sat_sum <= SAT_MAX;
      else if ((sum_accum + weighted_in_reg) < SAT_MIN)
        sat_sum <= SAT_MIN;
      else
        sat_sum <= sum_accum + weighted_in_reg;
    end
  end

  always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
      sum_accum <= 0;
      sample_count <= 0;
    end else if (accum_clear) begin
      state <= IDLE;
      sum_accum <= 0;
      sample_count <= 0;
    end else if (enable && data_valid) begin
      case (state)
        IDLE: begin
          state <= ACCUM;
          sum_accum <= sat_sum;
          sample_count <= 1;
        end
        ACCUM: begin
          sum_accum <= sat_sum;
          sample_count <= sample_count + 1;
          if (ACCUM_MODE == 1) begin
            if ((sample_count + 1) >= window_size)
              state <= DONE;
          end else begin
            // OR of the three magnitude thresholds == |sat_sum| >= THRESHOLD_MIN.
            if ((sat_sum >= THRESHOLD_MIN) || (sat_sum <= -THRESHOLD_MIN))
              state <= DONE;
          end
        end
        DONE: begin
          state <= IDLE;
          sum_accum <= 0;
          sample_count <= 0;
        end
        default: state <= IDLE;
      endcase
    end
  end

  // Shared magnitude (one's-complement) comparison for the three thresholds:
  //   (s >= T) || (s <= -T)  ==  mag >= (s<0 ? T-1 : T)   for T > 0,
  // with mag = s ^ {W{s[W-1]}} compared unsigned.  One magnitude network is
  // shared across all three thresholds instead of six signed comparators.
  wire                  sa_neg = sum_accum[DATA_WIDTH-1];
  wire [DATA_WIDTH-1:0] sa_mag = sum_accum ^ {DATA_WIDTH{sa_neg}};
  wire [DATA_WIDTH-1:0] t1_adj = sa_neg ? (THRESHOLD_VALUE_1 - 1) : THRESHOLD_VALUE_1;
  wire [DATA_WIDTH-1:0] t2_adj = sa_neg ? (THRESHOLD_VALUE_2 - 1) : THRESHOLD_VALUE_2;
  wire [DATA_WIDTH-1:0] t3_adj = sa_neg ? (THRESHOLD_VALUE_3 - 1) : THRESHOLD_VALUE_3;
  wire th1_hit = (sa_mag >= t1_adj);
  wire th2_hit = (sa_mag >= t2_adj);
  wire th3_hit = (sa_mag >= t3_adj);

  always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
      sum_out <= 0;
      avg_out <= 0;
      sum_ready <= 0;
      threshold_1 <= 0;
      threshold_2 <= 0;
      threshold_3 <= 0;
      busy <= 0;
    end else begin
      busy <= (state == ACCUM);
      if (state == DONE) begin
        sum_out <= sum_accum;
        avg_out <= (ACCUM_MODE == 1) ? (sum_accum / sample_count) : 0;
        sum_ready <= 1;
        threshold_1 <= th1_hit;
        threshold_2 <= th2_hit;
        threshold_3 <= th3_hit;
      end else begin
        sum_out <= 0;
        avg_out <= 0;
        sum_ready <= 0;
        threshold_1 <= 0;
        threshold_2 <= 0;
        threshold_3 <= 0;
      end
    end
  end

endmodule

// Data bus controller: two ready/valid masters (m0, m1) arbitrated onto a
// single ready/valid slave.  AFINITY selects the winner on a same-cycle clash
// (0 -> m0 wins, 1 -> m1 wins).  Slave readiness is passed back to the selected
// master; the slave datapath is registered for a one-cycle latency.
//
// Interface note: the descriptive signal tables name the master/slave readiness
// ports m0_ready / m1_ready / s_ready (the semantic, testbench-facing names),
// which are used here rather than the abbreviated stub spelling.
module data_bus_controller #(
  parameter AFINITY = 0
)(
  input         clk      ,
  input         rst_n    ,   // asynchronous, active low

  output        m0_ready ,
  input         m0_valid ,
  input  [31:0] m0_data  ,

  output        m1_ready ,
  input         m1_valid ,
  input  [31:0] m1_data  ,

  input         s_ready  ,
  output        s_valid  ,
  output [31:0] s_data
);

  // ---------------------------------------------------------------
  // Combinational arbitration (procedural priority so an undriven/idle
  // valid evaluating X never corrupts the select).  AFINITY fixes the
  // priority order, which both resolves a same-cycle clash and degrades
  // to first-come / single-master when only one valid is asserted.
  // ---------------------------------------------------------------
  reg sel_m0, sel_m1;
  always @(*) begin
    sel_m0 = 1'b0;
    sel_m1 = 1'b0;
    if (AFINITY == 0) begin
      if (m0_valid)      sel_m0 = 1'b1;
      else if (m1_valid) sel_m1 = 1'b1;
    end else begin
      if (m1_valid)      sel_m1 = 1'b1;
      else if (m0_valid) sel_m0 = 1'b1;
    end
  end

  // Slave readiness flows back only to the master that was selected.
  assign m0_ready = sel_m0 & s_ready;
  assign m1_ready = sel_m1 & s_ready;

  // ---------------------------------------------------------------
  // Registered slave datapath (one-cycle latency).
  // ---------------------------------------------------------------
  reg        s_valid_r;
  reg [31:0] s_data_r;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      s_valid_r <= 1'b0;
      s_data_r  <= 32'b0;
    end else begin
      s_valid_r <= sel_m0 | sel_m1;
      s_data_r  <= sel_m0 ? m0_data : (sel_m1 ? m1_data : 32'b0);
    end
  end

  assign s_valid = s_valid_r;
  assign s_data  = s_data_r;

endmodule

// Countdown timer (HH:MM:SS).  Loads a custom start time and counts down to
// 00:00:00 where it holds.  Derived from the original count-up dig_stopwatch:
// same name, original ports retained, four load ports added.  `hour` is widened
// to hold the 0..23 range the load range requires.
module dig_stopwatch #(
    parameter CLK_FREQ = 50000000  // clock frequency (Hz)
)(
    input  wire        clk,
    input  wire        reset,        // async, active high -> 00:00:00
    input  wire        start_stop,   // run when high, pause when low
    input  wire        load,         // load preset values
    input  wire [4:0]  load_hours,   // 0..23
    input  wire [5:0]  load_minutes, // 0..59
    input  wire [5:0]  load_seconds, // 0..59
    output reg  [5:0]  seconds,
    output reg  [5:0]  minutes,
    output reg  [4:0]  hour
);

    localparam COUNTER_MAX = CLK_FREQ - 1;
    reg [$clog2(COUNTER_MAX):0] counter;   // 1 Hz clock divider

    // Range-clamp the load inputs (out-of-range -> maximum valid value).
    wire [4:0] h_load = (load_hours   > 5'd23) ? 5'd23 : load_hours;
    wire [5:0] m_load = (load_minutes > 6'd59) ? 6'd59 : load_minutes;
    wire [5:0] s_load = (load_seconds > 6'd59) ? 6'd59 : load_seconds;

    wire timer_zero = (hour == 5'd0) && (minutes == 6'd0) && (seconds == 6'd0);

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset always wins, regardless of start_stop / load.
            seconds <= 6'd0;
            minutes <= 6'd0;
            hour    <= 5'd0;
            counter <= 0;
        end else if (load) begin
            // Load preset values (clamped) and restart the divider.
            seconds <= s_load;
            minutes <= m_load;
            hour    <= h_load;
            counter <= 0;
        end else if (start_stop && !timer_zero) begin
            // Running: divide the clock, decrement one second per tick.
            if (counter == COUNTER_MAX) begin
                counter <= 0;
                if (seconds != 6'd0) begin
                    seconds <= seconds - 6'd1;
                end else begin
                    seconds <= 6'd59;
                    if (minutes != 6'd0) begin
                        minutes <= minutes - 6'd1;
                    end else begin
                        minutes <= 6'd59;
                        hour    <= hour - 5'd1;   // timer_zero guards hour==0 here
                    end
                end
            end else begin
                counter <= counter + 1;
            end
        end
        // start_stop low (or already at zero): hold values and divider progress.
    end

endmodule

// Dot-product engine supporting real-only, complex-only and mixed modes.
// Each 32-bit vector word is {Imaginary[31:16], Real[15:0]} (signed fields).
// Real-only result is a full 32-bit real accumulation; complex/mixed results
// are packed {acc_im[15:0], acc_re[15:0]}.  Inputs are registered; output
// latency is three clock cycles.  An error is flagged if a valid drops while a
// computation is in flight.
module dot_product (
    input               clk_in,
    input               reset_in,                   // async reset, active high
    input               start_in,                   // start (1 cycle)
    input       [7:0]   dot_length_in,              // vector length (up to 256)
    input       [31:0]  vector_a_in,                // {Im[31:16], Re[15:0]}
    input               vector_a_valid_in,
    input       [31:0]  vector_b_in,                // {Im[31:16], Re[15:0]}
    input               vector_b_valid_in,
    input               a_complex_in,               // 1 = vector A is complex
    input               b_complex_in,               // 1 = vector B is complex
    output reg  [31:0]  dot_product_out,
    output reg          dot_product_valid_out,
    output reg          dot_product_error_out
);

    typedef enum logic [1:0] {
        IDLE    = 2'b00,
        COMPUTE = 2'b01,
        OUTPUT  = 2'b10,
        ERROR   = 2'b11
    } state_t;

    state_t state;

    // ---------------- registered inputs ----------------
    reg [31:0] a_reg, b_reg;
    reg        a_v, b_v;
    reg        a_cplx, b_cplx;
    reg [7:0]  dot_length_reg;

    reg signed [31:0] acc_re, acc_im;
    reg        [7:0]  cnt;
    reg               mode_real;     // latched real-only flag for output format

    // sign-extended field views of the registered operands
    wire signed [15:0] A_re = a_reg[15:0];
    wire signed [15:0] A_im = a_reg[31:16];
    wire signed [15:0] B_re = b_reg[15:0];
    wire signed [15:0] B_im = b_reg[31:16];

    // per-element real/imaginary products for the current mode
    reg signed [31:0] prod_re, prod_im;
    always @(*) begin
        // default real-only
        prod_re = A_re * B_re;
        prod_im = 32'sd0;
        if (a_cplx && b_cplx) begin
            prod_re = (A_re * B_re) - (A_im * B_im);
            prod_im = (A_re * B_im) + (A_im * B_re);
        end else if (a_cplx && !b_cplx) begin
            prod_re = A_re * B_re;
            prod_im = A_im * B_re;
        end else if (!a_cplx && b_cplx) begin
            prod_re = A_re * B_re;
            prod_im = A_re * B_im;
        end
    end

    always @(posedge clk_in or posedge reset_in) begin
        if (reset_in) begin
            state                 <= IDLE;
            a_reg                 <= 32'd0;
            b_reg                 <= 32'd0;
            a_v                   <= 1'b0;
            b_v                   <= 1'b0;
            a_cplx                <= 1'b0;
            b_cplx                <= 1'b0;
            dot_length_reg        <= 8'd0;
            acc_re                <= 32'sd0;
            acc_im                <= 32'sd0;
            cnt                   <= 8'd0;
            mode_real             <= 1'b0;
            dot_product_out       <= 32'd0;
            dot_product_valid_out <= 1'b0;
            dot_product_error_out <= 1'b0;
        end else begin
            // register the inputs every cycle
            a_reg  <= vector_a_in;
            b_reg  <= vector_b_in;
            a_v    <= vector_a_valid_in;
            b_v    <= vector_b_valid_in;
            a_cplx <= a_complex_in;
            b_cplx <= b_complex_in;

            case (state)
                IDLE: begin
                    dot_product_valid_out <= 1'b0;
                    dot_product_error_out <= 1'b0;
                    dot_length_reg        <= dot_length_in;
                    if (start_in) begin
                        state     <= COMPUTE;
                        acc_re    <= 32'sd0;
                        acc_im    <= 32'sd0;
                        cnt       <= 8'd0;
                        mode_real <= ~(a_complex_in | b_complex_in);
                    end
                end

                COMPUTE: begin
                    if (a_v && b_v) begin
                        acc_re <= acc_re + prod_re;
                        acc_im <= acc_im + prod_im;
                        cnt    <= cnt + 8'd1;
                        if (cnt == dot_length_reg - 8'd1)
                            state <= OUTPUT;
                    end else begin
                        // a valid dropped mid-computation -> error
                        state <= ERROR;
                    end
                end

                OUTPUT: begin
                    dot_product_out <= mode_real
                                       ? acc_re
                                       : {acc_im[15:0], acc_re[15:0]};
                    dot_product_valid_out <= 1'b1;
                    dot_product_error_out <= 1'b0;
                    state                 <= IDLE;
                end

                ERROR: begin
                    dot_product_out       <= 32'd0;
                    dot_product_valid_out <= 1'b0;
                    dot_product_error_out <= 1'b1;
                    state                 <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

/*
 * Elevator Control System (with Overloading Warning)
 *
 * FSM-based elevator: Idle, Moving Up, Moving Down, Emergency Halt, Door Open,
 * plus a new Overload Halt.  An asserted overload_detected forces OVERLOAD_HALT
 * from any state and asserts overload_warning; clearing it returns to IDLE.
*/
module elevator_control_system #(
    parameter N = 8, //Number of floors
    parameter DOOR_OPEN_TIME_MS = 500 // Door open time in milliseconds
) (
    input wire clk,                   // 100MHz clock input
    input wire reset,                 // Active-high reset signal
    input wire [N-1:0] call_requests, // External Floor call requests
    input wire emergency_stop,        // Emergency stop signal
    input wire overload_detected,     // Overload condition (active high)
    output wire [$clog2(N)-1:0] current_floor, // Current floor of the elevator
    output reg direction,             // Elevator direction: 1 = up, 0 = down
    output reg door_open,             // Door open signal
    output reg [2:0] system_status,    // Elevator system state indicator
    output wire overload_warning,      // Asserted while in the overload condition
    output wire [6:0] seven_seg_out    // Seven-segment display output for current floor visualization
);

// State Encoding
localparam IDLE = 3'b000;          // Elevator is idle
localparam MOVING_UP = 3'b001;     // Elevator moving up
localparam MOVING_DOWN = 3'b010;   // Elevator moving down
localparam EMERGENCY_HALT = 3'b011;// Emergency halt state
localparam DOOR_OPEN = 3'b100;     // Door open state
localparam OVERLOAD_HALT = 3'b101; // Overload halt state

// Internal registers
reg [N-1:0] call_requests_internal;   // Internal copy of call requests
reg [2:0] present_state, next_state; // FSM current and next states
reg [$clog2(N)-1:0] max_request;     // Highest requested floor
reg [$clog2(N)-1:0] min_request;    // Lowest requested floor

// Door open time configuration
`ifdef SIMULATION
    localparam CLK_FREQ_MHZ = 100;  // Clock frequency in MHz
    localparam SIM_DOOR_OPEN_TIME_MS = 0.05; // Shorter door open time for simulation
    localparam DOOR_OPEN_CYCLES = (SIM_DOOR_OPEN_TIME_MS * CLK_FREQ_MHZ * 1000); // Door open cycles for simulation
`else
    // Calculating door open cycles based on time and clock frequency
    localparam CLK_FREQ_MHZ = 100;  // Clock frequency in MHz
    localparam DOOR_OPEN_CYCLES = (DOOR_OPEN_TIME_MS * CLK_FREQ_MHZ * 1000);   // Door open cycles for real implementation
`endif


reg [$clog2(DOOR_OPEN_CYCLES)-1:0] door_open_counter;   // Counter for door open duration

reg [$clog2(N)-1:0] current_floor_reg, current_floor_next=0;

assign current_floor = current_floor_reg;

// Overload warning reflects the overload-halt state.
assign overload_warning = (present_state == OVERLOAD_HALT);

// FSM state transition
always@(posedge clk or posedge reset) begin
    if(reset)begin
        present_state <= IDLE;
        system_status <= IDLE;
        current_floor_reg <= 0;
        max_request <= 0;
        min_request <= N-1;
    end else begin
        present_state <= next_state;
        system_status <= next_state;
        current_floor_reg <= current_floor_next;

        // Calculate max_request and min_request based on active requests
        max_request = 0;
        min_request = N-1;
        for (integer i = 0; i < N; i = i + 1) begin
            if (call_requests_internal[i]) begin
                if (i > max_request) max_request = i;
                if (i < min_request) min_request = i;
            end
        end
    end
end

always@(*)begin
    next_state = present_state;
    current_floor_next = current_floor_reg;

    case(present_state)
        IDLE:begin
            if(emergency_stop)begin
                next_state = EMERGENCY_HALT;
            end else if(call_requests_internal != 0)begin
                if(max_request > current_floor_reg)begin
                    next_state = MOVING_UP;
                end else if(min_request < current_floor_reg) begin
                    next_state = MOVING_DOWN;
                end
            end
        end

        MOVING_UP: begin
            if(emergency_stop)begin
                next_state = EMERGENCY_HALT;
            end else if(call_requests_internal[current_floor_reg+1]) begin
                current_floor_next = current_floor_reg + 1;
                next_state = DOOR_OPEN;
            end else if(current_floor_reg >= max_request) begin
                // If we reach the highest request, go idle
                next_state = IDLE;
            end else begin
                current_floor_next = current_floor_reg + 1;
                next_state = MOVING_UP;
            end
        end

        MOVING_DOWN: begin
            if(emergency_stop)begin
                next_state = EMERGENCY_HALT;
            end else if(call_requests_internal[current_floor_reg-1]) begin
                current_floor_next = current_floor_reg - 1;
                next_state = DOOR_OPEN;
            end else if(current_floor_reg <= min_request) begin
                // If we reach the lowest request, go idle
                next_state = IDLE;
            end else begin
                current_floor_next = current_floor_reg - 1;
                next_state = MOVING_DOWN;
            end
        end

        EMERGENCY_HALT: begin
            if (!emergency_stop) begin
                next_state = IDLE;
                current_floor_next = 0; // Optionally reset to ground floor
            end
        end

        DOOR_OPEN: begin
            if (door_open_counter == 0) begin
                next_state = IDLE;
            end else begin
                next_state = DOOR_OPEN;
            end
        end

        OVERLOAD_HALT: begin
            // Recover to IDLE once the overload condition clears.
            if (!overload_detected) begin
                next_state = IDLE;
            end else begin
                next_state = OVERLOAD_HALT;
            end
        end
    endcase

    // Overload halts the elevator from ANY state, regardless of the case above.
    if (overload_detected) begin
        next_state = OVERLOAD_HALT;
        current_floor_next = current_floor_reg; // hold position, no movement
    end
end


// Door open control logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        door_open_counter <= 0;
        door_open <= 0;
    end else begin
        if (present_state == DOOR_OPEN) begin
            if (door_open_counter > 0) begin
                door_open <= 1;
                door_open_counter <= door_open_counter - 1;
            end else begin
                door_open <= 0;
                next_state = IDLE;
            end
        end else begin
            door_open <= 0;
            door_open_counter <= DOOR_OPEN_CYCLES; // Reset door open counter
        end
    end
end

// Call request management
always@(*)begin
    if(reset) begin
        call_requests_internal = 0;
    end else begin
        if(call_requests_internal[current_floor_reg])begin
            call_requests_internal[current_floor_reg] = 0;      // Clear served request
        end
        call_requests_internal = call_requests_internal | call_requests;    // Update requests
    end
end

// Direction control logic
always@(*)begin
    if(reset) begin
        direction = 1;
    end else begin
        if(present_state == MOVING_UP)begin
            direction = 1;
        end else if (present_state == MOVING_DOWN) begin
            direction = 0;
        end else begin
            direction = 1;
        end
    end
end


// Seven-segment display converter instantiation
floor_to_seven_segment #(.N(8)) floor_display_converter (
    .floor_display(current_floor_reg),
    .seven_seg_out(seven_seg_out)
);

endmodule

module fan_controller (
    input wire clk,                 // System clock
    input wire reset,               // Reset signal
    output reg fan_pwm_out,         // PWM output for fan control

    //APB signals
    input  wire         psel,       // Slave select
    input  wire         penable,    // Enable signal
    input  wire         pwrite,     // Write control
    input  wire [7:0]   paddr,      // Address bus
    input  wire [7:0]   pwdata,     // Write data bus
    output reg  [7:0]   prdata,     // Read data bus
    output reg          pready,      // Ready signal
    output reg          pslverr     // Slave error
);

    // Parameters for temperature thresholds
    reg [7:0] TEMP_LOW ;      // Low temperature threshold
    reg [7:0] TEMP_MED ;      // Medium temperature threshold
    reg [7:0] TEMP_HIGH;      // High temperature threshold
    reg [7:0]  temp_adc_in;   // Temperature sensor input (0-255)

    reg setup;
    // APB Protocol States
    always @(posedge clk or posedge reset)
	begin
        if (reset)
        begin
            prdata   <= 8'b0;
            pready   <= 1'b0;
            pslverr  <= 1'b0;
            TEMP_LOW <= 8'd30;
            TEMP_MED <= 8'd60;
            TEMP_HIGH <=8'd90;
            setup  <= 1'b0;
        end
        else
        begin
            if (psel && !penable && !setup)
            begin
                // Setup phase: Indicate the slave is not yet ready
                pready <= 1'b0;
                setup  <= 1'b1;

            end
            else if (psel && penable && setup)
            begin
                // Access phase: Perform read/write operation and indicate ready
                pready <= 1'b1; // Slave is ready for the current operation
                setup  <= 1'b0;
                if (pwrite)
                 begin
                    // Write Operation
                    case(paddr)
                          8'h0a: begin
                                  TEMP_LOW    <= pwdata;
                                  pslverr     <= 1'b0;
                                  end
                          8'h0b: begin
                                  TEMP_MED    <= pwdata;
                                  pslverr     <= 1'b0;
                                  end
                          8'h0c: begin
                                  TEMP_HIGH   <= pwdata;
                                  pslverr     <= 1'b0;
                                  end
                          8'h0f: begin
                                  temp_adc_in <= pwdata;
                                  pslverr     <= 1'b0;
                                  end
                          default:pslverr     <= 1'b1;
                    endcase
                end
                else
                begin
                    // Read Operation
                    case(paddr)
                          8'h0a: begin
                                  prdata   <= TEMP_LOW ;
                                  pslverr  <= 1'b0;
                                  end
                          8'h0b: begin
                                  prdata   <= TEMP_MED ;
                                  pslverr  <= 1'b0;
                                  end
                          8'h0c: begin
                                  prdata   <= TEMP_HIGH;
                                  pslverr  <= 1'b0;
                                  end
                          8'h0f: begin
                                  prdata   <= temp_adc_in;
                                  pslverr  <= 1'b0;
                                  end
                          default:pslverr  <= 1'b1;
                    endcase
                end
            end
            else
            begin
                // Default case: Clear ready signal when not selected
                pready <= 1'b0;
                setup  <= 1'b0;
            end
        end
    end

    // PWM control
    reg [7:0] pwm_duty_cycle;    // Duty cycle (0-255)
    reg [7:0] pwm_counter;       // Counter for PWM generation

    // Fan speed adjustment logic.  The intermediate 3-bit speed_control encoding
    // and its decode case are folded into one direct combinational duty-cycle
    // mux over the same temperature comparisons (functionally identical, fewer
    // cells/wires).
    always @(posedge clk or posedge reset) begin
        if (reset)
        begin
            pwm_duty_cycle <= 8'd0;  // Fan off by default
        end
        else
        begin
            // if/else chain (not a ternary) so an undriven/X temperature falls
            // through to the final else (8'd255) exactly like the original
            // case-statement default did.
            if      (temp_adc_in < TEMP_LOW)  pwm_duty_cycle <= 8'd64;  // 25%
            else if (temp_adc_in < TEMP_MED)  pwm_duty_cycle <= 8'd128; // 50%
            else if (temp_adc_in < TEMP_HIGH) pwm_duty_cycle <= 8'd192; // 75%
            else                              pwm_duty_cycle <= 8'd255; // 100%
        end
    end

    // PWM generation logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            pwm_counter <= 8'd0;
            fan_pwm_out <= 1'b0;
        end else begin
            pwm_counter <= pwm_counter + 1;
            fan_pwm_out <= (pwm_counter < pwm_duty_cycle) ? 1'b1 : 1'b0;
        end
    end

endmodule

// Asynchronous FIFO with configurable depth and data width.
// Gray-coded read/write pointers with one extra (wrap) bit, cross-domain 2-FF
// synchronizers, full/empty derived from the synchronized pointers.
//   empty : read pointer equals the synchronized write pointer.
//   full  : write pointer equals the synchronized read pointer with the top two
//           Gray bits inverted (the Gray-code form of "a full wrap ahead").
module fifo_async #(
    parameter DATA_WIDTH = 8,
    parameter DEPTH      = 16
)(
    input  wire                  w_clk,
    input  wire                  w_rst,
    input  wire                  w_inc,
    input  wire [DATA_WIDTH-1:0] w_data,
    input  wire                  r_clk,
    input  wire                  r_rst,
    input  wire                  r_inc,
    output wire                  w_full,
    output wire                  r_empty,
    output wire [DATA_WIDTH-1:0] r_data
);

    localparam ADDR = $clog2(DEPTH);   // address width

    // Storage
    reg [DATA_WIDTH-1:0] mem [0:DEPTH-1];

    // ---------------- write clock domain ----------------
    reg  [ADDR:0] w_bin, w_gray;
    reg  [ADDR:0] r_gray_s1, r_gray_s2;   // read pointer synced into write domain

    wire [ADDR:0] w_bin_next  = w_bin + (w_inc & ~w_full);
    wire [ADDR:0] w_gray_next = (w_bin_next >> 1) ^ w_bin_next;

    always @(posedge w_clk or posedge w_rst) begin
        if (w_rst) begin
            w_bin  <= {(ADDR+1){1'b0}};
            w_gray <= {(ADDR+1){1'b0}};
        end else begin
            w_bin  <= w_bin_next;
            w_gray <= w_gray_next;
        end
    end

    // memory write
    always @(posedge w_clk) begin
        if (w_inc && !w_full)
            mem[w_bin[ADDR-1:0]] <= w_data;
    end

    // synchronize read Gray pointer into the write domain
    always @(posedge w_clk or posedge w_rst) begin
        if (w_rst) begin
            r_gray_s1 <= {(ADDR+1){1'b0}};
            r_gray_s2 <= {(ADDR+1){1'b0}};
        end else begin
            r_gray_s1 <= r_gray;
            r_gray_s2 <= r_gray_s1;
        end
    end

    assign w_full = (w_gray_next ==
                     {~r_gray_s2[ADDR:ADDR-1], r_gray_s2[ADDR-2:0]});

    // ---------------- read clock domain ----------------
    reg  [ADDR:0] r_bin, r_gray;
    reg  [ADDR:0] w_gray_s1, w_gray_s2;   // write pointer synced into read domain

    wire [ADDR:0] r_bin_next  = r_bin + (r_inc & ~r_empty);
    wire [ADDR:0] r_gray_next = (r_bin_next >> 1) ^ r_bin_next;

    always @(posedge r_clk or posedge r_rst) begin
        if (r_rst) begin
            r_bin  <= {(ADDR+1){1'b0}};
            r_gray <= {(ADDR+1){1'b0}};
        end else begin
            r_bin  <= r_bin_next;
            r_gray <= r_gray_next;
        end
    end

    // synchronize write Gray pointer into the read domain
    always @(posedge r_clk or posedge r_rst) begin
        if (r_rst) begin
            w_gray_s1 <= {(ADDR+1){1'b0}};
            w_gray_s2 <= {(ADDR+1){1'b0}};
        end else begin
            w_gray_s1 <= w_gray;
            w_gray_s2 <= w_gray_s1;
        end
    end

    assign r_empty = (r_gray_next == w_gray_s2);
    assign r_data  = mem[r_bin[ADDR-1:0]];

endmodule

module ping_pong_fifo_2_axi_stream #(
  parameter int                                DATA_WIDTH          = 24,
  parameter int                                STROBE_WIDTH        = DATA_WIDTH / 8,
  parameter int                                USE_KEEP            = 0,
  parameter int                                USER_IN_DATA        = 1
)(
  input  logic                                 rst,

  // Ping Pong FIFO Read Interface
  input  logic                                 i_block_fifo_rdy,
  output logic                                 o_block_fifo_act,
  input  logic [23:0]                          i_block_fifo_size,
  input  logic [(DATA_WIDTH + 1) - 1:0]        i_block_fifo_data,
  output logic                                 o_block_fifo_stb,
  input  logic [3:0]                           i_axi_user,

  // AXI Stream Output
  input  logic                                 i_axi_clk,
  output logic [3:0]                           o_axi_user,
  input  logic                                 i_axi_ready,
  output logic [DATA_WIDTH - 1:0]              o_axi_data,
  output logic                                 o_axi_last,
  output logic                                 o_axi_valid
);

// Internal signals
logic [DATA_WIDTH - 1:0] fifo_data_buffer;
logic fifo_valid_buffer;
logic fifo_last_buffer;

// Pass-through outputs (driven combinationally so the given reset block is kept
// intact).  A read strobe is issued when a block is active, the FIFO has data
// ready, and the AXI sink can accept it.
assign o_axi_data       = fifo_data_buffer;
assign o_axi_last       = fifo_last_buffer;
assign o_axi_user       = i_axi_user;
assign o_block_fifo_stb = o_block_fifo_act & i_block_fifo_rdy & i_axi_ready;

// Reset Condition
always_ff @(posedge i_axi_clk or posedge rst) begin
  if (rst) begin
    o_block_fifo_act   <= 1'b0;
    o_axi_valid        <= 1'b0;
    fifo_data_buffer   <= {DATA_WIDTH{1'b0}};
    fifo_valid_buffer  <= 1'b0;
    fifo_last_buffer   <= 1'b0;
  end else begin
    // Acquire / hold a block while the FIFO has data available.
    if (i_block_fifo_rdy)
      o_block_fifo_act <= 1'b1;
    else
      o_block_fifo_act <= 1'b0;

    // Move one word per accepted beat; stall (hold data) when the sink is not
    // ready or no data is available.
    if (o_block_fifo_stb) begin
      fifo_data_buffer  <= i_block_fifo_data[DATA_WIDTH-1:0];
      fifo_last_buffer  <= i_block_fifo_data[DATA_WIDTH];
      fifo_valid_buffer <= 1'b1;
      o_axi_valid       <= 1'b1;
    end else if (i_axi_ready) begin
      // Accepted (or nothing to send): drop valid until the next word.
      o_axi_valid       <= 1'b0;
      fifo_valid_buffer <= 1'b0;
    end
  end
end

endmodule

module divider #
(
    parameter WIDTH = 32
)
(
    input  wire                  clk,
    input  wire                  rst_n,      // Active-low asynchronous reset
    input  wire                  start,      // Start signal for new operation
    input  wire [WIDTH-1 : 0]    dividend,   // Dividend (numerator)
    input  wire [WIDTH-1 : 0]    divisor,    // Divisor (denominator)
    output wire [WIDTH-1 : 0]    quotient,   // Result of the division
    output wire [WIDTH-1 : 0]    remainder,  // Remainder after division
    output wire                  valid       // Indicates output is valid
);

    localparam AW = WIDTH + 1;
    // Simple 3-state FSM
    localparam IDLE = 2'b00;
    localparam BUSY = 2'b01;
    localparam DONE = 2'b10;

    reg [1:0] state_reg, state_next;

    // A+Q combined into one WIDTH + 1 + WIDTH register:
    reg [AW+WIDTH-1 : 0] aq_reg,   aq_next;

    // Divisor register
    reg [AW-1 : 0]       m_reg,    m_next;

    // Iterate exactly WIDTH times
    reg [$clog2(WIDTH)-1:0] n_reg, n_next;

    // Final outputs
    reg [WIDTH-1:0] quotient_reg, quotient_next;
    reg [WIDTH-1:0] remainder_reg, remainder_next;
    reg valid_reg, valid_next;

    // Assign the top-level outputs
    assign quotient  = quotient_reg;
    assign remainder = remainder_reg;
    assign valid     = valid_reg;

    // Combinational temporaries for one non-restoring iteration
    reg [AW+WIDTH-1 : 0] aq_sl;     // AQ shifted left by 1
    reg [AW-1 : 0]       a_s;       // accumulator field after shift
    reg [AW-1 : 0]       a_op;      // accumulator after add/sub of M
    reg                  q0;        // new Q[0]
    reg [AW+WIDTH-1 : 0] aq_iter;   // AQ after this iteration
    reg [AW-1 : 0]       a_final;   // accumulator after final adjustment

    always_comb begin
        // Defaults: hold
        state_next     = state_reg;
        aq_next        = aq_reg;
        m_next         = m_reg;
        n_next         = n_reg;
        quotient_next  = quotient_reg;
        remainder_next = remainder_reg;
        valid_next     = valid_reg;

        // One non-restoring iteration (computed from current AQ / M)
        aq_sl   = aq_reg << 1;
        a_s     = aq_sl[AW+WIDTH-1 : WIDTH];
        if (aq_reg[AW+WIDTH-1])               // sign bit of accumulator A == 1
            a_op = a_s + m_reg;               // A = A + M
        else
            a_op = a_s - m_reg;               // A = A - M (add 2's complement)
        q0      = ~a_op[AW-1];                // sign(A_new)==0 -> Q[0]=1 else 0
        aq_iter = {a_op, aq_sl[WIDTH-1:1], q0};

        // Final adjustment: if sign(A) is 1 after the last iteration, A = A + M
        a_final = aq_iter[AW+WIDTH-1 : WIDTH];
        if (a_final[AW-1])
            a_final = a_final + m_reg;

        case (state_reg)
            IDLE: begin
                valid_next = 1'b0;
                if (start) begin
                    // Load: A = 0, Q = dividend, M = divisor, N = WIDTH
                    aq_next    = {{AW{1'b0}}, dividend};
                    m_next     = {1'b0, divisor};
                    n_next     = WIDTH - 1;          // count WIDTH iterations
                    state_next = BUSY;
                end
            end

            BUSY: begin
                aq_next = aq_iter;
                if (n_reg == 0) begin
                    // Last iteration: register results, assert valid in DONE
                    state_next     = DONE;
                    valid_next     = 1'b1;
                    quotient_next  = aq_iter[WIDTH-1:0];
                    remainder_next = a_final[WIDTH-1:0];
                end else begin
                    n_next = n_reg - 1'b1;
                end
            end

            DONE: begin
                // Hold outputs and valid until start is de-asserted
                valid_next = 1'b1;
                if (!start) begin
                    valid_next = 1'b0;
                    state_next = IDLE;
                end
            end

            default: state_next = IDLE;
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_reg     <= IDLE;
            aq_reg        <= '0;
            m_reg         <= '0;
            n_reg         <= '0;
            quotient_reg  <= '0;
            remainder_reg <= '0;
            valid_reg     <= 1'b0;
        end else begin
            state_reg     <= state_next;
            aq_reg        <= aq_next;
            m_reg         <= m_next;
            n_reg         <= n_next;
            quotient_reg  <= quotient_next;
            remainder_reg <= remainder_next;
            valid_reg     <= valid_next;
        end
    end

endmodule

module hebb_gates(
   input  logic               clk,
   input  logic               rst,                // Asynchronous negedge reset
   input  logic               start,              // To start the Training FSM
   input  logic  signed [3:0] a,                  // First Input
   input  logic  signed [3:0] b,                  // Second Input
   input  logic         [1:0] gate_select,        // Gate target selector
   output logic  signed [3:0] w1,                 // Weight 1 obtained by training
   output logic  signed [3:0] w2,                 // Weight 2 obtained by training
   output logic  signed [3:0] bias,               // Bias obtained by training
   output logic         [3:0] present_state,      // Present State of the Training FSM
   output logic         [3:0] next_state,         // Next State of the Training FSM
   output logic               done,               // Training complete flag
   output logic         [3:0] test_present_state, // Present state of the Testing FSM
   output logic         [3:0] test_output,        // Calculated output during testing
   output logic         [3:0] test_result,        // Count of correct matches
   output logic               test_done           // Active high: testing complete
);

   // ---------------------------------------------------------------
   // Target gate submodule (hardcoded control)
   // ---------------------------------------------------------------
   logic signed [3:0] t1, t2, t3, t4;

   gate_target dut(
       .gate_select(gate_select),
       .o_1        (t1),
       .o_2        (t2),
       .o_3        (t3),
       .o_4        (t4)
   );

   // ===============================================================
   // Training FSM (hardcoded control unit) - 11 states S0..S10
   // ===============================================================
   localparam [3:0] S0=4'd0,S1=4'd1,S2=4'd2,S3=4'd3,S4=4'd4,S5=4'd5,
                    S6=4'd6,S7=4'd7,S8=4'd8,S9=4'd9,S10=4'd10;

   logic [2:0]        iteration;
   logic signed [3:0] x1, x2;
   logic signed [3:0] target;
   logic signed [3:0] w1_reg, w2_reg, bias_reg;

   always_ff @(posedge clk or negedge rst) begin
      if (!rst) present_state <= S0;
      else      present_state <= next_state;
   end

   always_comb begin
      next_state = present_state;
      case (present_state)
         S0 : next_state = start ? S1 : S0;
         S1 : next_state = S2;
         S2 : next_state = (iteration==0)?S3:(iteration==1)?S4:(iteration==2)?S5:S6;
         S3 : next_state = S7;
         S4 : next_state = S7;
         S5 : next_state = S7;
         S6 : next_state = S7;
         S7 : next_state = S8;
         S8 : next_state = S9;
         S9 : next_state = (iteration < 4) ? S1 : S10;
         S10: next_state = S0;
         default : next_state = S0;
      endcase
   end

   always_ff @(posedge clk or negedge rst) begin
      if (!rst) begin
         x1<='0; x2<='0; target<='0; iteration<='0;
         w1_reg<='0; w2_reg<='0; bias_reg<='0; done<=1'b0;
      end else begin
         case (present_state)
            S0 : begin w1_reg<='0; w2_reg<='0; bias_reg<='0; iteration<='0; end
            S1 : begin x1<=a; x2<=b; end
            S3 : target <= t1;
            S4 : target <= t2;
            S5 : target <= t3;
            S6 : target <= t4;
            S8 : begin
               w1_reg    <= w1_reg   + (x1 * target);
               w2_reg    <= w2_reg   + (x2 * target);
               bias_reg  <= bias_reg + target;
               iteration <= iteration + 1'b1;
            end
            S10: done <= 1'b1;   // training complete: latch the flag for Testing FSM
            default : ; // hold (trained weights are HELD for the Testing FSM)
         endcase
      end
   end

   assign w1   = w1_reg;
   assign w2   = w2_reg;
   assign bias = bias_reg;

   // ===============================================================
   // Predefined Testing Vectors (depth 16, 4-bit each)
   //   4 input combinations per gate; expected = gate truth table.
   // ===============================================================
   logic signed [3:0] test_inputs_x1        [0:15];
   logic signed [3:0] test_inputs_x2        [0:15];
   logic signed [3:0] test_expected_outputs [0:15];

   initial begin
      // x1 pattern (bipolar) for every gate window
      test_inputs_x1[0]= 1; test_inputs_x1[1]= 1; test_inputs_x1[2]=-1; test_inputs_x1[3]=-1;
      test_inputs_x1[4]= 1; test_inputs_x1[5]= 1; test_inputs_x1[6]=-1; test_inputs_x1[7]=-1;
      test_inputs_x1[8]= 1; test_inputs_x1[9]= 1; test_inputs_x1[10]=-1;test_inputs_x1[11]=-1;
      test_inputs_x1[12]=1; test_inputs_x1[13]=1; test_inputs_x1[14]=-1;test_inputs_x1[15]=-1;
      // x2 pattern (bipolar)
      test_inputs_x2[0]= 1; test_inputs_x2[1]=-1; test_inputs_x2[2]= 1; test_inputs_x2[3]=-1;
      test_inputs_x2[4]= 1; test_inputs_x2[5]=-1; test_inputs_x2[6]= 1; test_inputs_x2[7]=-1;
      test_inputs_x2[8]= 1; test_inputs_x2[9]=-1; test_inputs_x2[10]=1; test_inputs_x2[11]=-1;
      test_inputs_x2[12]=1; test_inputs_x2[13]=-1;test_inputs_x2[14]=1; test_inputs_x2[15]=-1;
      // expected outputs per gate window: 00=AND,01=OR,10=NAND,11=NOR (match gate_target)
      test_expected_outputs[0]= 1; test_expected_outputs[1]=-1; test_expected_outputs[2]=-1; test_expected_outputs[3]=-1;
      test_expected_outputs[4]= 1; test_expected_outputs[5]= 1; test_expected_outputs[6]= 1; test_expected_outputs[7]=-1;
      test_expected_outputs[8]= 1; test_expected_outputs[9]= 1; test_expected_outputs[10]=1; test_expected_outputs[11]=-1;
      test_expected_outputs[12]=1; test_expected_outputs[13]=-1;test_expected_outputs[14]=-1;test_expected_outputs[15]=-1;
   end

   // ===============================================================
   // Testing FSM (microcode control unit) - 5 ROM locations
   // ===============================================================
   localparam [3:0] T0=4'd0,T1=4'd1,T2=4'd2,T3=4'd3,T4=4'd4;
   localparam [3:0] ACT_NOP=4'd0, ACT_INIT=4'd1, ACT_FETCH=4'd2,
                    ACT_CALC=4'd3, ACT_VERIFY=4'd4;

   // Microcode ROM: {test_next_state[15:12], test_action[11:8], 8'h00}
   logic [15:0] microcode_rom [0:4];
   initial begin
      microcode_rom[T0] = {T1, ACT_INIT,   8'h00};
      microcode_rom[T1] = {T2, ACT_FETCH,  8'h00};
      microcode_rom[T2] = {T3, ACT_CALC,   8'h00};
      microcode_rom[T3] = {T1, ACT_VERIFY, 8'h00};
      microcode_rom[T4] = {T4, ACT_NOP,    8'h00};
   end

   wire [3:0] cur_next   = microcode_rom[test_present_state][15:12];
   wire [3:0] cur_action = microcode_rom[test_present_state][11:8];

   logic signed [3:0]  test_x1, test_x2, expected_output;
   logic signed [15:0] test_calc;
   logic [3:0]         test_index;

   wire [3:0] start_index = (gate_select==2'b00) ? 4'd0  :
                            (gate_select==2'b01) ? 4'd4  :
                            (gate_select==2'b10) ? 4'd8  : 4'd12;
   wire [3:0] terminal    = start_index + 4'd3;

   wire signed [15:0] calc_comb = (w1_reg * test_x1) + (w2_reg * test_x2) + bias_reg;

   always_ff @(posedge clk or negedge rst) begin
      if (!rst) begin
         test_present_state <= T0;
         test_index         <= '0;
         test_x1            <= '0;
         test_x2            <= '0;
         expected_output    <= '0;
         test_calc          <= '0;
         test_output        <= '0;
         test_result        <= '0;
         test_done          <= 1'b0;
      end else if (done) begin
         // advance the microcode sequencer once training is complete
         case (cur_action)
            ACT_INIT : begin
               test_done   <= 1'b0;
               test_result <= '0;
               test_output <= '0;
               test_index  <= start_index;
            end
            ACT_FETCH : begin
               test_x1         <= test_inputs_x1[test_index];
               test_x2         <= test_inputs_x2[test_index];
               expected_output <= test_expected_outputs[test_index];
            end
            ACT_CALC : begin
               test_calc   <= calc_comb;
               test_output <= (calc_comb > 0) ? 4'sd1 : -4'sd1;
            end
            ACT_VERIFY : begin
               if (test_output == expected_output)
                  test_result <= test_result + 1'b1;
            end
            default : ; // NOP
         endcase

         // next-state: ROM default, with the VERIFY terminal-branch override
         if (cur_action == ACT_VERIFY) begin
            if (test_index == terminal) begin
               test_done          <= 1'b1;
               test_present_state <= T4;
            end else begin
               test_index         <= test_index + 1'b1;
               test_present_state <= cur_next;   // back to FETCH
            end
         end else begin
            test_present_state <= cur_next;
         end
      end
   end

endmodule

module gate_target(
   input  logic        [1:0] gate_select,
   output logic signed [3:0] o_1,
   output logic signed [3:0] o_2,
   output logic signed [3:0] o_3,
   output logic signed [3:0] o_4
);
   always_comb begin
      case (gate_select)
         2'b00 : begin o_1= 1; o_2=-1; o_3=-1; o_4=-1; end
         2'b01 : begin o_1= 1; o_2= 1; o_3= 1; o_4=-1; end
         2'b10 : begin o_1= 1; o_2= 1; o_3= 1; o_4=-1; end
         2'b11 : begin o_1= 1; o_2=-1; o_3=-1; o_4=-1; end
         default : begin o_1=0; o_2=0; o_3=0; o_4=0; end
      endcase
   end
endmodule

module hebb_gates(
   input  logic               clk,
   input  logic               rst,          // Asynchronous negedge reset
   input  logic               start,        // To start the FSM
   input  logic  signed [3:0] a,            // First input  (bipolar -1/1)
   input  logic  signed [3:0] b,            // Second input (bipolar -1/1)
   input  logic         [1:0] gate_select,  // Target gate selector
   output logic  signed [3:0] w1,           // Trained weight 1
   output logic  signed [3:0] w2,           // Trained weight 2
   output logic  signed [3:0] bias,         // Trained bias
   output logic         [3:0] present_state,// Present state of the Training FSM
   output logic         [3:0] next_state    // Next state of the Training FSM
);

   localparam [3:0] S0 = 4'd0;
   localparam [3:0] S1 = 4'd1;
   localparam [3:0] S2 = 4'd2;
   localparam [3:0] S3 = 4'd3;
   localparam [3:0] S4 = 4'd4;
   localparam [3:0] S5 = 4'd5;
   localparam [3:0] S6 = 4'd6;
   localparam [3:0] S7 = 4'd7;
   localparam [3:0] S8 = 4'd8;
   localparam [3:0] S9 = 4'd9;
   localparam [3:0] S10 = 4'd10;

   logic signed [3:0] t1, t2, t3, t4;

   gate_target dut(
       .gate_select(gate_select),
       .o_1        (t1),
       .o_2        (t2),
       .o_3        (t3),
       .o_4        (t4)
   );

   logic [2:0]        iteration;
   logic signed [3:0] x1, x2;
   logic signed [3:0] target;
   logic signed [3:0] w1_reg, w2_reg, bias_reg;

   // ---------------- State register ----------------
   always_ff @(posedge clk or negedge rst) begin
      if (!rst)
         present_state <= S0;
      else
         present_state <= next_state;
   end

   // ---------------- Next-state (Moore) ----------------
   always_comb begin
      next_state = present_state;
      case (present_state)
         S0 : next_state = start ? S1 : S0;
         S1 : next_state = S2;
         S2 : begin
            if      (iteration == 0) next_state = S3;
            else if (iteration == 1) next_state = S4;
            else if (iteration == 2) next_state = S5;
            else                     next_state = S6;
         end
         S3 : next_state = S7;
         S4 : next_state = S7;
         S5 : next_state = S7;
         S6 : next_state = S7;
         S7 : next_state = S8;
         S8 : next_state = S9;
         S9 : next_state = (iteration < 4) ? S1 : S10;
         S10: next_state = S0;
         default : next_state = S0;
      endcase
   end

   // ---------------- Datapath (registered, decoded from state) ----------------
   always_ff @(posedge clk or negedge rst) begin
      if (!rst) begin
         x1        <= '0;
         x2        <= '0;
         target    <= '0;
         iteration <= '0;
         w1_reg    <= '0;
         w2_reg    <= '0;
         bias_reg  <= '0;
      end else begin
         case (present_state)
            S0 : begin
               // Initialize weights/bias and iteration counter
               w1_reg    <= '0;
               w2_reg    <= '0;
               bias_reg  <= '0;
               iteration <= '0;
            end
            S1 : begin
               // Capture activations
               x1 <= a;
               x2 <= b;
            end
            S3 : target <= t1;
            S4 : target <= t2;
            S5 : target <= t3;
            S6 : target <= t4;
            S8 : begin
               // Hebbian update: w(new) = w(old) + x*target, bias += target
               w1_reg    <= w1_reg   + (x1 * target);
               w2_reg    <= w2_reg   + (x2 * target);
               bias_reg  <= bias_reg + target;
               iteration <= iteration + 1'b1;
            end
            default : ; // hold
         endcase
      end
   end

   assign w1   = w1_reg;
   assign w2   = w2_reg;
   assign bias = bias_reg;

endmodule

module gate_target(
   input  logic        [1:0] gate_select,
   output logic signed [3:0] o_1,
   output logic signed [3:0] o_2,
   output logic signed [3:0] o_3,
   output logic signed [3:0] o_4
);
   always_comb begin
      case (gate_select)
         2'b00 : begin o_1 =  1; o_2 = -1; o_3 = -1; o_4 = -1; end // AND
         2'b01 : begin o_1 =  1; o_2 =  1; o_3 =  1; o_4 = -1; end // OR
         2'b10 : begin o_1 =  1; o_2 =  1; o_3 =  1; o_4 = -1; end // NAND
         2'b11 : begin o_1 =  1; o_2 = -1; o_3 = -1; o_4 = -1; end // NOR
         default : begin o_1 = 0; o_2 = 0; o_3 = 0; o_4 = 0; end
      endcase
   end
endmodule

module hmac_reg_interface #(
    parameter DATA_WIDTH = 8,
    parameter ADDR_WIDTH = 8
) (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic                  write_en,
    input  logic                  read_en,
    input  logic [ADDR_WIDTH-1:0] addr,
    input  logic [DATA_WIDTH-1:0] wdata,
    input  logic                  i_wait_en,
    output logic [DATA_WIDTH-1:0] rdata,
    output logic                  hmac_valid,
    output logic                  hmac_key_error
);

    // Number of registers
    localparam NUM_REGS = 1 << ADDR_WIDTH;
    localparam [DATA_WIDTH-1:0] XOR = {(DATA_WIDTH/2){2'b01}};

    // FSM States
    typedef enum logic [2:0] {
        IDLE     = 3'b000,
        ANALYZE  = 3'b001,
        XOR_DATA = 3'b010,
        WRITE    = 3'b011,
        LOST     = 3'b100,
        CHECK_KEY= 3'b101,
        TRIG_WAIT= 3'b110
    } state_t;

    state_t current_state, next_state;

    // Registers
    logic [DATA_WIDTH-1:0] registers [NUM_REGS-1:0];

    // HMAC data
    logic [DATA_WIDTH-1:0] hmac_key;
    logic [DATA_WIDTH-1:0] hmac_data;

    logic [DATA_WIDTH-1:0] xor_data;

    // Captured transaction context + outputs
    logic [DATA_WIDTH-1:0] wdata_q;
    logic [ADDR_WIDTH-1:0] addr_q;
    logic                  xor_path;
    logic [DATA_WIDTH-1:0] rdata_q;
    logic                  hmac_valid_q;
    logic                  key_valid;
    logic [DATA_WIDTH-1:0] write_payload;

    // ---------------- XOR logic and key analysis (combinational) ----------------
    // XOR every 2 bits of the captured wdata with 2'b01
    assign xor_data      = wdata_q ^ XOR;
    assign write_payload = xor_path ? xor_data : wdata_q;

    // Key valid when the 2 MSB and the 2 LSB are zero; error flag otherwise.
    assign key_valid      = (hmac_key[DATA_WIDTH-1 -: 2] == 2'b00) &&
                            (hmac_key[1:0] == 2'b00);
    assign hmac_key_error = ~key_valid;

    assign rdata      = rdata_q;
    assign hmac_valid = hmac_valid_q;

    // ---------------- FSM next-state (combinational) ----------------
    always_comb begin
        next_state = current_state;
        case (current_state)
            IDLE     : if (write_en) next_state = ANALYZE;
            ANALYZE  : if (wdata_q[DATA_WIDTH-1]) next_state = XOR_DATA;
                       else                       next_state = WRITE;
            XOR_DATA : next_state = WRITE;
            WRITE    : if (write_en) next_state = IDLE;
                       else          next_state = LOST;
            LOST     : if (read_en) next_state = CHECK_KEY;
                       else         next_state = LOST;
            CHECK_KEY: if (key_valid) next_state = TRIG_WAIT;
                       else           next_state = WRITE;
            TRIG_WAIT: begin
                if (i_wait_en)
                    next_state = TRIG_WAIT;
                else if ((hmac_data != '0) && (hmac_key != '0))
                    next_state = IDLE;
                else
                    next_state = WRITE;
            end
            default  : next_state = IDLE;
        endcase
    end

    // ---------------- Sequential write / read / capture ----------------
    integer i;
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= IDLE;
            hmac_key      <= '0;
            hmac_data     <= '0;
            rdata_q       <= '0;
            hmac_valid_q  <= 1'b0;
            wdata_q       <= '0;
            addr_q        <= '0;
            xor_path      <= 1'b0;
            for (i = 0; i < NUM_REGS; i = i + 1)
                registers[i] <= '0;
        end else begin
            current_state <= next_state;

            // hmac_valid is asserted only during the WRITE state
            hmac_valid_q <= (next_state == WRITE);

            // Capture the transaction at the start of a write sequence
            if (current_state == IDLE && write_en) begin
                wdata_q <= wdata;
                addr_q  <= addr;
            end

            // Latch which path processes the data (XOR vs straight)
            if (current_state == ANALYZE)
                xor_path <= wdata_q[DATA_WIDTH-1];

            // Sequential write: store the processed data during WRITE state.
            if (current_state == WRITE) begin
                registers[addr_q] <= write_payload;
                if (addr_q == 0) hmac_key  <= write_payload;
                if (addr_q == 1) hmac_data <= write_payload;
            end

            // Sequential read: 1-cycle latency, only when not writing.
            if (read_en && (current_state != WRITE)) begin
                if (addr == 0)
                    rdata_q <= hmac_key;
                else if (addr == 1)
                    rdata_q <= hmac_data;
                else
                    rdata_q <= registers[addr];
            end
        end
    end

endmodule

module image_rotate #(
  parameter IN_ROW     = 4                                  , // Number of rows in input matrix
  parameter IN_COL     = 4                                  , // Number of columns in input matrix
  parameter OUT_ROW    = (IN_ROW > IN_COL) ? IN_ROW : IN_COL, // Output rows after padding
  parameter OUT_COL    = (IN_ROW > IN_COL) ? IN_ROW : IN_COL, // Output columns after padding
  parameter DATA_WIDTH = 8                                    // Bit-width of data
) (
  input  logic [                             1:0] rotation_angle, // Rotation angle (00: 90, 01: 180, 10: 270, 11: No Rotation)
  input  logic [  (IN_ROW*IN_COL*DATA_WIDTH)-1:0] image_in      , // Flattened input image
  output logic [(OUT_ROW*OUT_COL*DATA_WIDTH)-1:0] image_out       // Flattened output image
);

  logic [(OUT_ROW*OUT_COL*DATA_WIDTH)-1:0] padded_image    ; // Padded square image
  logic [(OUT_ROW*OUT_COL*DATA_WIDTH)-1:0] transposed_image; // Transposed square image

  genvar pad_row, pad_col, trans_row, trans_col, rot_row, rot_col;

  // ----------------------------------------------------------------
  // Padding: copy image_in into the BOTTOM-RIGHT of the square matrix,
  // filling the top rows and the left columns with zeros.
  // ----------------------------------------------------------------
  generate
    for (pad_row = 0; pad_row < OUT_ROW; pad_row++) begin: pad_row_block
      for (pad_col = 0; pad_col < OUT_COL; pad_col++) begin: pad_col_block
        if ((pad_row >= (OUT_ROW - IN_ROW)) && (pad_col >= (OUT_COL - IN_COL))) begin: g_copy
          assign padded_image[(pad_row*OUT_COL + pad_col)*DATA_WIDTH +: DATA_WIDTH] =
                 image_in[(((pad_row-(OUT_ROW-IN_ROW))*IN_COL) +
                            (pad_col-(OUT_COL-IN_COL)))*DATA_WIDTH +: DATA_WIDTH];
        end else begin: g_zero
          assign padded_image[(pad_row*OUT_COL + pad_col)*DATA_WIDTH +: DATA_WIDTH] = {DATA_WIDTH{1'b0}};
        end
      end
    end
  endgenerate

  // ----------------------------------------------------------------
  // Transpose: transposed[r][c] = padded[c][r]
  // ----------------------------------------------------------------
  generate
    for (trans_row = 0; trans_row < OUT_ROW; trans_row++) begin: trans_row_block
      for (trans_col = 0; trans_col < OUT_COL; trans_col++) begin: trans_col_block
        assign transposed_image[(trans_row*OUT_COL + trans_col)*DATA_WIDTH +: DATA_WIDTH] =
               padded_image[(trans_col*OUT_COL + trans_row)*DATA_WIDTH +: DATA_WIDTH];
      end
    end
  endgenerate

  // ----------------------------------------------------------------
  // Output rotation (clockwise). All rotations square OUT_ROW==OUT_COL.
  //   00 (90):  transposed with each row reversed  -> transposed[i][N-1-j]
  //   01 (180): padded with rows and columns reversed -> padded[N-1-i][N-1-j]
  //   10 (270): transposed with each column reversed -> transposed[N-1-i][j]
  //   11 (none): padded[i][j]
  // ----------------------------------------------------------------
  generate
    for (rot_row = 0; rot_row < OUT_ROW; rot_row++) begin: rot_row_block
      for (rot_col = 0; rot_col < OUT_COL; rot_col++) begin: rot_col_block
        assign image_out[(rot_row*OUT_COL + rot_col)*DATA_WIDTH +: DATA_WIDTH] =
          (rotation_angle == 2'b00) ?
              transposed_image[(rot_row*OUT_COL + (OUT_COL-1-rot_col))*DATA_WIDTH +: DATA_WIDTH] :
          (rotation_angle == 2'b01) ?
              padded_image[((OUT_ROW-1-rot_row)*OUT_COL + (OUT_COL-1-rot_col))*DATA_WIDTH +: DATA_WIDTH] :
          (rotation_angle == 2'b10) ?
              transposed_image[((OUT_ROW-1-rot_row)*OUT_COL + rot_col)*DATA_WIDTH +: DATA_WIDTH] :
              padded_image[(rot_row*OUT_COL + rot_col)*DATA_WIDTH +: DATA_WIDTH];
      end
    end
  endgenerate

endmodule

module interrupt_controller
#(
    parameter NUM_INTERRUPTS = 4,
    parameter ADDR_WIDTH = 8)
(
    input  logic                      clk,
    input  logic                      rst_n,
    input  logic [NUM_INTERRUPTS-1:0] interrupt_requests,
    output logic [NUM_INTERRUPTS-1:0] interrupt_service,
    output logic                      cpu_interrupt,
    input  logic                      cpu_ack,
    output logic [$clog2(NUM_INTERRUPTS)-1:0] interrupt_idx,
    output logic [ADDR_WIDTH-1:0]     interrupt_vector,
    input  logic [NUM_INTERRUPTS-1:0] priority_map_value [NUM_INTERRUPTS-1:0],
    input  logic                      priority_map_update,
    input  logic [ADDR_WIDTH-1:0]     vector_table_value [NUM_INTERRUPTS-1:0],
    input  logic                      vector_table_update,
    input  logic [NUM_INTERRUPTS-1:0] interrupt_mask_value,
    input  logic                      interrupt_mask_update
);

    localparam IDXW = $clog2(NUM_INTERRUPTS);

    logic [NUM_INTERRUPTS-1:0] priority_mask;
    logic [NUM_INTERRUPTS-1:0] pending_interrupts;
    logic [NUM_INTERRUPTS-1:0] interrupt_mask;

    // Internal configuration / state
    logic [NUM_INTERRUPTS-1:0] priority_map [NUM_INTERRUPTS-1:0];
    logic [ADDR_WIDTH-1:0]     vector_table [NUM_INTERRUPTS-1:0];
    logic [NUM_INTERRUPTS-1:0] req_sync;       // synchronized requests
    logic                      servicing;

    integer i;

    // ------------------------------------------------------------------
    // Pending evaluation: a request that is not masked is pending.
    // ------------------------------------------------------------------
    assign pending_interrupts = req_sync & ~interrupt_mask;

    // ------------------------------------------------------------------
    // Combinational priority selection: lowest priority_map value wins.
    // Procedural priority avoids X-propagation from undriven requests.
    // ------------------------------------------------------------------
    logic [IDXW-1:0]           sel_idx;
    logic                      sel_valid;
    logic [NUM_INTERRUPTS-1:0] best_pri;

    always_comb begin
        sel_idx   = '0;
        sel_valid = 1'b0;
        best_pri  = '1;
        for (i = 0; i < NUM_INTERRUPTS; i = i + 1) begin
            if (pending_interrupts[i]) begin
                if (!sel_valid || (priority_map[i] < best_pri)) begin
                    best_pri  = priority_map[i];
                    sel_idx   = i[IDXW-1:0];
                    sel_valid = 1'b1;
                end
            end
        end
    end

    assign priority_mask = pending_interrupts;

    // ------------------------------------------------------------------
    // Sequential control
    // ------------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < NUM_INTERRUPTS; i = i + 1) begin
                priority_map[i] <= i[NUM_INTERRUPTS-1:0];        // sequential priorities
                vector_table[i] <= (i * 4);                      // vectors = multiples of 4
            end
            interrupt_mask    <= '0;
            req_sync          <= '0;
            interrupt_service <= '0;
            cpu_interrupt     <= 1'b0;
            interrupt_idx     <= '0;
            interrupt_vector  <= '0;
            servicing         <= 1'b0;
        end else begin
            // Synchronize the request lines
            req_sync <= interrupt_requests;

            // Dynamic configuration updates
            if (priority_map_update)
                for (i = 0; i < NUM_INTERRUPTS; i = i + 1)
                    priority_map[i] <= priority_map_value[i];
            if (vector_table_update)
                for (i = 0; i < NUM_INTERRUPTS; i = i + 1)
                    vector_table[i] <= vector_table_value[i];
            if (interrupt_mask_update)
                interrupt_mask <= interrupt_mask_value;

            // Service / acknowledge handling
            if (cpu_ack) begin
                // CPU finished servicing: clear and prepare for next
                interrupt_service <= '0;
                cpu_interrupt     <= 1'b0;
                servicing         <= 1'b0;
            end else if (!servicing && sel_valid) begin
                // Start servicing the highest-priority unmasked interrupt
                interrupt_service <= '0;
                interrupt_service[sel_idx] <= 1'b1;
                interrupt_idx     <= sel_idx;
                interrupt_vector  <= vector_table[sel_idx];
                cpu_interrupt     <= 1'b1;
                servicing         <= 1'b1;
            end
        end
    end

endmodule

module interrupt_controller (
    input wire clk,
    input wire rst_n,
    input wire reset_interrupts,
    input wire [9:0] interrupt_requests,
    input wire interrupt_ack,
  	input wire interrupt_trig,
    input wire [9:0] interrupt_mask,
    input wire [3:0] priority_override,
    input wire [3:0] override_interrupt_id,
    input wire priority_override_en,
    output reg [3:0] interrupt_id,
    output reg interrupt_valid,
    output reg [9:0] interrupt_status,
    output reg [9:0] missed_interrupts,
    output reg starvation_detected
);

    parameter STARVATION_THRESHOLD = 5;

    localparam [2:0]
        IDLE = 3'b000,
        PRIORITY_CALC = 3'b001,
        SERVICE_PREP = 3'b010,
        SERVICING = 3'b011,
        COMPLETION = 3'b100,
        ERROR = 3'b111;

    reg [2:0] current_state, next_state;
    reg [9:0] pending_interrupts;
    reg [3:0] wait_counters [0:9];
    reg [4:0] effective_priority [0:9];
    reg [9:0] active_mask;
    reg [3:0] service_timer;
    reg timeout_error;
    reg [3:0] next_interrupt_id;
    reg [4:0] max_priority;

    integer i;

    // ------------------------------------------------------------------
    // Combinational arbitration: pick the (enabled) pending interrupt with
    // the smallest effective_priority value; ties resolve to the lower id.
    // ------------------------------------------------------------------
    reg [3:0] sel_id;
    reg       sel_valid;
    reg [4:0] sel_pri;
    always @(*) begin
        sel_id    = 4'd0;
        sel_valid = 1'b0;
        sel_pri   = 5'h1f;
        for (i = 0; i < 10; i = i + 1) begin
            if (pending_interrupts[i] && interrupt_mask[i]) begin
                if (!sel_valid || (effective_priority[i] < sel_pri)) begin
                    sel_pri   = effective_priority[i];
                    sel_id    = i[3:0];
                    sel_valid = 1'b1;
                end
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state       <= IDLE;
            pending_interrupts  <= 10'b0;
            interrupt_status    <= 10'b0;
            missed_interrupts   <= 10'b0;
            interrupt_valid     <= 1'b0;
            interrupt_id        <= 4'b0;
            starvation_detected <= 1'b0;
            service_timer       <= 4'b0;
            timeout_error       <= 1'b0;
            active_mask         <= 10'b0;
            next_interrupt_id   <= 4'b0;
            max_priority        <= 5'b0;
            for (i = 0; i < 10; i = i + 1) begin
                wait_counters[i]      <= 4'b0;
                effective_priority[i] <= 5'b0;
            end
        end else if (reset_interrupts) begin
            // Reset all pending and serviced interrupts
            pending_interrupts  <= 10'b0;
            interrupt_status    <= 10'b0;
            missed_interrupts   <= 10'b0;
            interrupt_valid     <= 1'b0;
            starvation_detected <= 1'b0;
            current_state       <= IDLE;
            for (i = 0; i < 10; i = i + 1)
                wait_counters[i] <= 4'b0;
        end else begin
            // Capture new interrupt set on a trigger
            if (interrupt_trig) begin
                pending_interrupts <= pending_interrupts | (interrupt_requests & interrupt_mask);
                missed_interrupts  <= missed_interrupts  | (interrupt_requests & ~interrupt_mask);
                active_mask        <= interrupt_mask;
            end

            // Aging / starvation monitoring
            starvation_detected <= 1'b0;
            for (i = 0; i < 10; i = i + 1) begin
                if (pending_interrupts[i]) begin
                    if (wait_counters[i] < 4'hf)
                        wait_counters[i] <= wait_counters[i] + 4'b1;
                    if (wait_counters[i] >= STARVATION_THRESHOLD)
                        starvation_detected <= 1'b1;
                end
            end

            case (current_state)
                IDLE: begin
                    interrupt_valid <= 1'b0;
                    if (|pending_interrupts)
                        current_state <= PRIORITY_CALC;
                end

                PRIORITY_CALC: begin
                    // Effective priority: starving interrupts are boosted to 0
                    // (highest); an override pins a specific value.
                    for (i = 0; i < 10; i = i + 1) begin
                        if (priority_override_en && (i[3:0] == override_interrupt_id))
                            effective_priority[i] <= {1'b0, priority_override};
                        else if (wait_counters[i] >= STARVATION_THRESHOLD)
                            effective_priority[i] <= 5'd0;
                        else
                            effective_priority[i] <= i[4:0];
                    end
                    current_state <= SERVICE_PREP;
                end

                SERVICE_PREP: begin
                    next_interrupt_id <= sel_id;
                    max_priority      <= sel_pri;
                    if (sel_valid) begin
                        interrupt_id  <= sel_id;
                        service_timer <= 4'b0;
                        current_state <= SERVICING;
                    end else begin
                        current_state <= IDLE;
                    end
                end

                SERVICING: begin
                    interrupt_valid             <= 1'b1;
                    interrupt_status[interrupt_id] <= 1'b1;
                    service_timer               <= service_timer + 4'b1;
                    if (interrupt_ack) begin
                        current_state <= COMPLETION;
                    end else if (service_timer >= 4'hf) begin
                        timeout_error <= 1'b1;
                        current_state <= ERROR;
                    end
                end

                COMPLETION: begin
                    interrupt_valid                 <= 1'b0;
                    pending_interrupts[interrupt_id]<= 1'b0;
                    interrupt_status[interrupt_id]  <= 1'b0;
                    wait_counters[interrupt_id]     <= 4'b0;
                    current_state                   <= IDLE;
                end

                ERROR: begin
                    interrupt_valid                 <= 1'b0;
                    timeout_error                   <= 1'b0;
                    pending_interrupts[interrupt_id]<= 1'b0;
                    interrupt_status[interrupt_id]  <= 1'b0;
                    wait_counters[interrupt_id]     <= 4'b0;
                    current_state                   <= IDLE;
                end

                default: current_state <= IDLE;
            endcase
        end
    end

endmodule

// SystemVerilog RTL for a Priority-Based Interrupt Controller with APB Interface

module interrupt_controller_apb #(
    parameter NUM_INTERRUPTS = 4,
    parameter ADDR_WIDTH = 8
    )
    (
    input  logic                      clk,
    input  logic                      rst_n,
    input  logic [NUM_INTERRUPTS-1:0] interrupt_requests,
    output logic [NUM_INTERRUPTS-1:0] interrupt_service,
    output logic                      cpu_interrupt,
    input  logic                      cpu_ack,
    output  logic [$clog2(NUM_INTERRUPTS)-1:0] interrupt_idx,
    output logic [ADDR_WIDTH-1:0]     interrupt_vector,

    // APB Interface Signals
    input  logic                      pclk,
    input  logic                      presetn,
    input  logic                      psel,
    input  logic                      penable,
    input  logic                      pwrite,
    input  logic [ADDR_WIDTH-1:0]     paddr,
    input  logic [31:0]               pwdata,
    output logic [31:0]               prdata,
    output logic                      pready
);

    localparam IDXW = $clog2(NUM_INTERRUPTS);

    // Register addresses
    localparam [ADDR_WIDTH-1:0] REG_PRIORITY_MAP   = 'h0;
    localparam [ADDR_WIDTH-1:0] REG_INTERRUPT_MASK = 'h1;
    localparam [ADDR_WIDTH-1:0] REG_VECTOR_TABLE   = 'h2;
    localparam [ADDR_WIDTH-1:0] REG_PENDING        = 'h3;
    localparam [ADDR_WIDTH-1:0] REG_CURRENT_INT    = 'h4;

    logic [NUM_INTERRUPTS-1:0] interrupt_mask;
    logic servicing;
    logic [NUM_INTERRUPTS-1:0] pending_interrupts;

    // Configurable state
    logic [23:0]            priority_map [NUM_INTERRUPTS-1:0];
    logic [ADDR_WIDTH-1:0]  vector_table [NUM_INTERRUPTS-1:0];
    logic [NUM_INTERRUPTS-1:0] req_sync;
    logic [IDXW-1:0]        current_int;

    integer i;

    // ==================================================================
    // APB interface (pclk domain) — single-cycle access, no wait states.
    // ==================================================================
    assign pready = psel & penable;

    always_ff @(posedge pclk or negedge presetn) begin
        if (!presetn) begin
            for (i = 0; i < NUM_INTERRUPTS; i = i + 1) begin
                priority_map[i] <= i[23:0];          // sequential priorities
                vector_table[i] <= (i * 4);          // consecutive addresses
            end
            interrupt_mask <= {NUM_INTERRUPTS{1'b1}}; // all interrupts enabled
        end else begin
            if (psel && penable && pwrite) begin
                case (paddr)
                    REG_PRIORITY_MAP : priority_map[pwdata[7:0]] <= pwdata[31:8];
                    REG_INTERRUPT_MASK: interrupt_mask <= pwdata[NUM_INTERRUPTS-1:0];
                    REG_VECTOR_TABLE : vector_table[pwdata[7:0]] <= pwdata[8 +: ADDR_WIDTH];
                    default: ; // read-only / unmapped: ignore
                endcase
            end
        end
    end

    // Combinational read data (available in the access phase)
    always_comb begin
        prdata = 32'b0;
        case (paddr)
            REG_INTERRUPT_MASK: prdata = {{(32-NUM_INTERRUPTS){1'b0}}, interrupt_mask};
            REG_PENDING       : prdata = {{(32-NUM_INTERRUPTS){1'b0}}, pending_interrupts};
            REG_CURRENT_INT   : prdata = servicing ? {{(32-IDXW){1'b0}}, current_int}
                                                   : 32'hFFFFFFFF; // invalid index (-1)
            default           : prdata = 32'b0;
        endcase
    end

    // ==================================================================
    // Interrupt controller core (clk domain)
    // ==================================================================
    assign pending_interrupts = req_sync & interrupt_mask; // mask bit 1 = enabled

    // Combinational priority arbitration: lowest priority value wins.
    logic [IDXW-1:0] sel_idx;
    logic            sel_valid;
    logic [23:0]     best_pri;
    always_comb begin
        sel_idx   = '0;
        sel_valid = 1'b0;
        best_pri  = '1;
        for (i = 0; i < NUM_INTERRUPTS; i = i + 1) begin
            if (pending_interrupts[i]) begin
                if (!sel_valid || (priority_map[i] < best_pri)) begin
                    best_pri  = priority_map[i];
                    sel_idx   = i[IDXW-1:0];
                    sel_valid = 1'b1;
                end
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            req_sync          <= '0;
            interrupt_service <= '0;
            cpu_interrupt     <= 1'b0;
            interrupt_idx     <= '0;
            interrupt_vector  <= '0;
            servicing         <= 1'b0;
            current_int       <= {IDXW{1'b1}};   // invalid index
        end else begin
            req_sync <= interrupt_requests;       // synchronize requests

            if (cpu_ack) begin
                interrupt_service <= '0;
                cpu_interrupt     <= 1'b0;
                servicing         <= 1'b0;
                current_int       <= {IDXW{1'b1}};
            end else if (!servicing && sel_valid) begin
                interrupt_service          <= '0;
                interrupt_service[sel_idx] <= 1'b1;
                interrupt_idx              <= sel_idx;
                interrupt_vector           <= vector_table[sel_idx];
                cpu_interrupt              <= 1'b1;
                servicing                  <= 1'b1;
                current_int                <= sel_idx;
            end
        end
    end

endmodule

module line_buffer #(
    parameter NBW_DATA  = 'd8,  // Bit width of grayscale input/output data
    parameter NS_ROW    = 'd10, // Number of rows
    parameter NS_COLUMN = 'd8,  // Number of columns
    parameter NBW_ROW   = 'd4,  // log2(NS_ROW). Bit width of i_image_row_start
    parameter NBW_COL   = 'd3,  // log2(NS_COLUMN). Bit width of i_image_col_start
    parameter NBW_MODE  = 'd3,  // Bit width of mode input
    parameter NS_R_OUT  = 'd4,  // Number of rows of the output window
    parameter NS_C_OUT  = 'd3,  // Number of columns of the output window
    parameter CONSTANT  = 'd255 // Constant value to use in PAD_CONSTANT mode
) (
    input  logic                                  clk,
    input  logic                                  rst_async_n,
    input  logic [NBW_MODE-1:0]                   i_mode,
    input  logic                                  i_valid,
    input  logic                                  i_update_window,
    input  logic [NBW_DATA*NS_COLUMN-1:0]         i_row_image,
    input  logic [NBW_ROW-1:0]                    i_image_row_start,
    input  logic [NBW_COL-1:0]                    i_image_col_start,
    output logic [NBW_DATA*NS_R_OUT*NS_C_OUT-1:0] o_image_window
);

// ----------------------------------------
// - Wires/Registers creation
// ----------------------------------------
logic [NBW_DATA-1:0] image_buffer_ff [NS_ROW][NS_COLUMN];
logic [NBW_DATA-1:0] row_image [NS_COLUMN];
logic [NBW_DATA-1:0] window [NS_R_OUT][NS_C_OUT];
logic [NBW_DATA*NS_R_OUT*NS_C_OUT-1:0] image_window_ff;

// ----------------------------------------
// - Output generation
// ----------------------------------------
// The window is read with a STRAIGHT index mapping: window[row][col] selects the
// internal buffer at (i_image_row_start + row, i_image_col_start + col).  Each
// axis applies its own boundary policy independently so the both-out-of-range
// corner is correct (reflect uses 2*N-1-i, wrap uses i-N, extend clamps to N-1).
always_comb begin : window_assignment
    int rr, cc, rr_eff, cc_eff;
    for (int row = 0; row < NS_R_OUT; row++) begin
        for (int col = 0; col < NS_C_OUT; col++) begin
            rr = i_image_row_start + row;
            cc = i_image_col_start + col;
            case (i_mode)
                3'd0: begin // NO_BOUND_PROCESS
                    if (rr >= NS_ROW)         window[row][col] = 0;
                    else if (cc >= NS_COLUMN) window[row][col] = 0;
                    else                      window[row][col] = image_buffer_ff[rr][cc];
                end
                3'd1: begin // PAD_CONSTANT
                    if (rr >= NS_ROW)         window[row][col] = CONSTANT;
                    else if (cc >= NS_COLUMN) window[row][col] = CONSTANT;
                    else                      window[row][col] = image_buffer_ff[rr][cc];
                end
                3'd2: begin // EXTEND_NEAR (clamp each axis to nearest valid index)
                    rr_eff = (rr >= NS_ROW)    ? NS_ROW-1    : rr;
                    cc_eff = (cc >= NS_COLUMN) ? NS_COLUMN-1 : cc;
                    window[row][col] = image_buffer_ff[rr_eff][cc_eff];
                end
                3'd3: begin // MIRROR_BOUND (reflect each axis: 2*N-1-i)
                    rr_eff = (rr >= NS_ROW)    ? (2*NS_ROW-1-rr)    : rr;
                    cc_eff = (cc >= NS_COLUMN) ? (2*NS_COLUMN-1-cc) : cc;
                    window[row][col] = image_buffer_ff[rr_eff][cc_eff];
                end
                3'd4: begin // WRAP_AROUND (each axis: i-N)
                    rr_eff = (rr >= NS_ROW)    ? (rr-NS_ROW)    : rr;
                    cc_eff = (cc >= NS_COLUMN) ? (cc-NS_COLUMN) : cc;
                    window[row][col] = image_buffer_ff[rr_eff][cc_eff];
                end
                default: begin
                    window[row][col] = 0;
                end
            endcase
        end
    end
end

// ----------------------------------------
// - Input control
// ----------------------------------------
generate
    for (genvar col = 0; col < NS_COLUMN; col++) begin : unpack_row_image
        assign row_image[NS_COLUMN-col-1] = i_row_image[(col+1)*NBW_DATA-1-:NBW_DATA];
    end
endgenerate

always_ff @(posedge clk or negedge rst_async_n) begin : ctrl_regs
    if(~rst_async_n) begin
        image_window_ff <= 0;
        for (int row = 0; row < NS_ROW; row++) begin
            for (int col = 0; col < NS_COLUMN; col++) begin
                image_buffer_ff[row][col] <= 0;
            end
        end
    end else begin
        if(i_valid) begin
            for (int col = 0; col < NS_COLUMN; col++) begin
                image_buffer_ff[0][col] <= row_image[col];
            end

            for (int row = 1; row < NS_ROW; row++) begin
                for (int col = 0; col < NS_COLUMN; col++) begin
                    image_buffer_ff[row][col] <= image_buffer_ff[row-1][col];
                end
            end
        end

        if(i_update_window) begin
            image_window_ff <= o_image_window;
        end
    end
end

// ----------------------------------------
// - Output packing
// ----------------------------------------
generate
    for(genvar row = 0; row < NS_R_OUT; row++) begin : out_row
        for(genvar col = 0; col < NS_C_OUT; col++) begin : out_col
            always_comb begin
                if(i_update_window) begin
                    o_image_window[(row*NS_C_OUT+col+1)*NBW_DATA-1-:NBW_DATA] = window[row][col];
                end else begin
                    o_image_window[(row*NS_C_OUT+col+1)*NBW_DATA-1-:NBW_DATA] = image_window_ff[(row*NS_C_OUT+col+1)*NBW_DATA-1-:NBW_DATA];
                end
            end
        end
    end
endgenerate

endmodule : line_buffer

module load_store_unit (
    input  logic                 clk,
    input  logic                 rst_n,

    // EX stage interface
    input  logic                 ex_if_req_i,           // LSU request
    input  logic                 ex_if_we_i,            // Write enable: 0 (load), 1 (store)
    input  logic     [ 1:0]      ex_if_type_i,          // Data type: 0x2 (word), 0x1 (halfword), 0x0 (byte)
    input  logic     [31:0]      ex_if_wdata_i,         // Data to write to memory
    input  logic     [31:0]      ex_if_addr_base_i,     // Base address
    input  logic     [31:0]      ex_if_addr_offset_i,   // Offset address
    input  logic                 ex_if_extend_mode_i,
    output logic                 ex_if_ready_o    ,


    // Writeback stage interface
    output logic     [31:0]      wb_if_rdata_o,         // Requested data
    output logic                 wb_if_rvalid_o,        // Requested data valid

    // Data memory (DMEM) interface
    output logic                 dmem_req_o,
    input  logic                 dmem_gnt_i,
    output logic     [31:0]      dmem_req_addr_o,
    output logic                 dmem_req_we_o,
    output logic     [ 3:0]      dmem_req_be_o,
    output logic     [31:0]      dmem_req_wdata_o,
    input  logic     [31:0]      dmem_rsp_rdata_i,
    input  logic                 dmem_rvalid_i
    );

  // FSM states
  typedef enum logic [3:0] {
    IDLE                = 4'd0,
    ALIGNED_WR          = 4'd1,
    ALIGNED_RD          = 4'd2,
    ALIGNED_RD_GNT      = 4'd3,
    MISALIGNED_WR       = 4'd4,
    MISALIGNED_WR_1     = 4'd5,
    MISALIGNED_RD       = 4'd6,
    MISALIGNED_RD_GNT   = 4'd7,
    MISALIGNED_RD_1     = 4'd8,
    MISALIGNED_RD_GNT_1 = 4'd9
  } state_t;

  state_t state, next_state;

  // Effective address
  logic [31:0] data_addr_int;
  logic [1:0]  off_c;

  // Combinational byte-enable / alignment decode for the incoming request
  logic [3:0] be_lo_c, be_hi_c;
  logic       mis_c;

  // Captured transaction context
  logic [31:0] addr_lo, addr_hi, wdata_q;
  logic [3:0]  be_lo, be_hi;
  logic        we_q;
  logic [1:0]  type_q, off_q;
  logic        sign_q;
  logic        mis_q;

  // Read extension datapath
  logic [31:0] rdata_w_ext, rdata_h_ext, rdata_b_ext, data_rdata_ext;
  logic [31:0] wb_if_rdata_q;
  logic        wb_if_rvalid_q;

  assign data_addr_int = ex_if_addr_base_i + ex_if_addr_offset_i;
  assign off_c         = data_addr_int[1:0];
  assign ex_if_ready_o = (state == IDLE);

  // ------------------------------------------------------------------
  // Byte-enable / alignment decode (combinational, from current request)
  //   misaligned (two transactions) when a word is not 4-byte aligned, or
  //   a halfword crosses a word boundary (offset == 2'b11).
  // ------------------------------------------------------------------
  always_comb begin
    be_lo_c = 4'b0000;
    be_hi_c = 4'b0000;
    mis_c   = 1'b0;
    case (ex_if_type_i)
      2'b00: begin // byte (always single transaction)
        be_lo_c = (4'b0001 << off_c);
      end
      2'b01: begin // halfword
        case (off_c)
          2'b00: be_lo_c = 4'b0011;
          2'b01: be_lo_c = 4'b0110;
          2'b10: be_lo_c = 4'b1100;
          2'b11: begin // crosses word boundary -> two transactions
            be_lo_c = 4'b1000;
            be_hi_c = 4'b0001;
            mis_c   = 1'b1;
          end
          default: be_lo_c = 4'b0000;
        endcase
      end
      2'b10: begin // word
        if (off_c == 2'b00) begin
          be_lo_c = 4'b1111;
        end else begin // misaligned -> two transactions
          be_lo_c = (4'b1111 << off_c);
          be_hi_c = (4'b1111 >> (3'd4 - {1'b0, off_c}));
          mis_c   = 1'b1;
        end
      end
      default: be_lo_c = 4'b0000;
    endcase
  end

  // ------------------------------------------------------------------
  // Next-state logic
  // ------------------------------------------------------------------
  always_comb begin
    next_state = state;
    case (state)
      IDLE: begin
        if (ex_if_req_i) begin
          if (ex_if_we_i) begin
            if (mis_c) next_state = MISALIGNED_WR;
            else       next_state = ALIGNED_WR;
          end else begin
            if (mis_c) next_state = MISALIGNED_RD;
            else       next_state = ALIGNED_RD;
          end
        end
      end
      ALIGNED_WR         : if (dmem_gnt_i)    next_state = IDLE;
      ALIGNED_RD         : if (dmem_gnt_i)    next_state = ALIGNED_RD_GNT;
      ALIGNED_RD_GNT     : if (dmem_rvalid_i) next_state = IDLE;
      MISALIGNED_WR      : if (dmem_gnt_i)    next_state = MISALIGNED_WR_1;
      MISALIGNED_WR_1    : if (dmem_gnt_i)    next_state = IDLE;
      MISALIGNED_RD      : if (dmem_gnt_i)    next_state = MISALIGNED_RD_GNT;
      MISALIGNED_RD_GNT  : if (dmem_rvalid_i) next_state = MISALIGNED_RD_1;
      MISALIGNED_RD_1    : if (dmem_gnt_i)    next_state = MISALIGNED_RD_GNT_1;
      MISALIGNED_RD_GNT_1: if (dmem_rvalid_i) next_state = IDLE;
      default            : next_state = IDLE;
    endcase
  end

  // ------------------------------------------------------------------
  // State register + transaction context capture
  // ------------------------------------------------------------------
  always_ff @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
      state   <= IDLE;
      addr_lo <= '0;
      addr_hi <= '0;
      wdata_q <= '0;
      be_lo   <= '0;
      be_hi   <= '0;
      we_q    <= '0;
      type_q  <= '0;
      off_q   <= '0;
      sign_q  <= '0;
      mis_q   <= '0;
    end else begin
      state <= next_state;
      if (state == IDLE && ex_if_req_i) begin
        addr_lo <= data_addr_int;                         // word containing the start
        addr_hi <= {data_addr_int[31:2], 2'b00} + 32'd4;  // next word
        wdata_q <= ex_if_wdata_i;
        be_lo   <= be_lo_c;
        be_hi   <= be_hi_c;
        we_q    <= ex_if_we_i;
        type_q  <= ex_if_type_i;
        off_q   <= off_c;
        sign_q  <= ex_if_extend_mode_i;
        mis_q   <= mis_c;
      end
    end
  end

  // ------------------------------------------------------------------
  // DMEM request drive — all bus signals are zeroed whenever dmem_req_o
  // is deasserted (i.e. outside a request-issuing state).
  // ------------------------------------------------------------------
  always_comb begin
    dmem_req_o       = 1'b0;
    dmem_req_addr_o  = 32'b0;
    dmem_req_we_o    = 1'b0;
    dmem_req_be_o    = 4'b0;
    dmem_req_wdata_o = 32'b0;
    case (state)
      ALIGNED_WR, MISALIGNED_WR: begin
        dmem_req_o       = 1'b1;
        dmem_req_addr_o  = addr_lo;
        dmem_req_we_o    = 1'b1;
        dmem_req_be_o    = be_lo;
        dmem_req_wdata_o = wdata_q;
      end
      MISALIGNED_WR_1: begin
        dmem_req_o       = 1'b1;
        dmem_req_addr_o  = addr_hi;
        dmem_req_we_o    = 1'b1;
        dmem_req_be_o    = be_hi;
        dmem_req_wdata_o = wdata_q;
      end
      ALIGNED_RD, MISALIGNED_RD: begin
        dmem_req_o      = 1'b1;
        dmem_req_addr_o = addr_lo;
        dmem_req_we_o   = 1'b0;
        dmem_req_be_o   = be_lo;
      end
      MISALIGNED_RD_1: begin
        dmem_req_o      = 1'b1;
        dmem_req_addr_o = addr_hi;
        dmem_req_we_o   = 1'b0;
        dmem_req_be_o   = be_hi;
      end
      default: ; // GNT / IDLE states: bus held at zero
    endcase
  end

  // ------------------------------------------------------------------
  // Read-data extension (only used for naturally-aligned loads)
  // ------------------------------------------------------------------
  always_comb begin
    case (off_q)
      2'b00:   rdata_w_ext = dmem_rsp_rdata_i[31:0];
      default: rdata_w_ext = '0;
    endcase
  end

  always_comb begin
    case (off_q)
      2'b00: begin
        if (sign_q) rdata_h_ext = {{16{dmem_rsp_rdata_i[15]}}, dmem_rsp_rdata_i[15:0]};
        else        rdata_h_ext = {16'h0000, dmem_rsp_rdata_i[15:0]};
      end
      2'b10: begin
        if (sign_q) rdata_h_ext = {{16{dmem_rsp_rdata_i[31]}}, dmem_rsp_rdata_i[31:16]};
        else        rdata_h_ext = {16'h0000, dmem_rsp_rdata_i[31:16]};
      end
      default: rdata_h_ext = '0;
    endcase
  end

  always_comb begin
    case (off_q)
      2'b00: begin
        if (sign_q) rdata_b_ext = {{24{dmem_rsp_rdata_i[7]}},  dmem_rsp_rdata_i[7:0]};
        else        rdata_b_ext = {24'h00_0000, dmem_rsp_rdata_i[7:0]};
      end
      2'b01: begin
        if (sign_q) rdata_b_ext = {{24{dmem_rsp_rdata_i[15]}}, dmem_rsp_rdata_i[15:8]};
        else        rdata_b_ext = {24'h00_0000, dmem_rsp_rdata_i[15:8]};
      end
      2'b10: begin
        if (sign_q) rdata_b_ext = {{24{dmem_rsp_rdata_i[23]}}, dmem_rsp_rdata_i[23:16]};
        else        rdata_b_ext = {24'h00_0000, dmem_rsp_rdata_i[23:16]};
      end
      2'b11: begin
        if (sign_q) rdata_b_ext = {{24{dmem_rsp_rdata_i[31]}}, dmem_rsp_rdata_i[31:24]};
        else        rdata_b_ext = {24'h00_0000, dmem_rsp_rdata_i[31:24]};
      end
      default: rdata_b_ext = '0;
    endcase
  end

  always_comb begin
    case (type_q)
      2'b00:   data_rdata_ext = rdata_b_ext;
      2'b01:   data_rdata_ext = rdata_h_ext;
      2'b10:   data_rdata_ext = rdata_w_ext;
      default: data_rdata_ext = 32'b0;
    endcase
  end

  // ------------------------------------------------------------------
  // Writeback: aligned loads are extended; misaligned loads forward the
  // raw memory response per transaction.
  // ------------------------------------------------------------------
  always_ff @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
      wb_if_rdata_q  <= 32'b0;
      wb_if_rvalid_q <= 1'b0;
    end else begin
      wb_if_rvalid_q <= 1'b0;
      if (dmem_rvalid_i && (state == ALIGNED_RD_GNT)) begin
        wb_if_rdata_q  <= data_rdata_ext;
        wb_if_rvalid_q <= 1'b1;
      end else if (dmem_rvalid_i &&
                   ((state == MISALIGNED_RD_GNT) || (state == MISALIGNED_RD_GNT_1))) begin
        wb_if_rdata_q  <= dmem_rsp_rdata_i;   // raw data per transaction
        wb_if_rvalid_q <= 1'b1;
      end
    end
  end

  assign wb_if_rdata_o  = wb_if_rdata_q;
  assign wb_if_rvalid_o = wb_if_rvalid_q;

endmodule

// microcode_sequencer — a microcoded bit-slice sequencer with a LIFO stack,
// program counter, ripple-carry arithmetic unit, instruction decoder and a
// result register, wired per the design specification.
module microcode_sequencer (
    input              clk,
    input              c_n_in,     // carry-in for the ripple carry adder
    input              c_inc_in,   // carry-in for the PC incrementer
    input              r_en,       // ACTIVE LOW auxiliary register enable
    input              cc,         // ACTIVE LOW condition code
    input              ien,        // ACTIVE LOW instruction enable
    input      [3:0]   d_in,       // 4-bit data input bus
    input      [4:0]   instr_in,   // 5-bit opcode
    input              oen,        // ACTIVE LOW output enable
    output     [3:0]   d_out,      // 4-bit address output bus
    output             c_n_out,    // carry-out of the ripple carry adder
    output             c_inc_out,  // carry-out of the PC incrementer
    output             full,       // ACTIVE HIGH stack full
    output             empty       // ACTIVE HIGH stack empty
);

    // -------- decoded control signals --------
    wire        dec_cen, dec_rst, dec_oen, dec_inc, dec_rsel, dec_rce, dec_pc_mux_sel;
    wire [1:0]  dec_a_mux_sel, dec_b_mux_sel;
    wire        dec_push, dec_pop, dec_src_sel, dec_stack_we, dec_stack_re, dec_out_ce;

    // -------- datapath nets --------
    wire [3:0]  arith_d_out;
    wire        arith_cout;
    wire [3:0]  pc_out;
    wire        pc_c_out;
    wire [3:0]  stack_data_out;
    wire        stack_full, stack_empty;

    instruction_decoder u_dec (
        .instr_in   (instr_in),
        .cc_in      (cc),
        .instr_en   (ien),
        .cen        (dec_cen),
        .rst        (dec_rst),
        .oen        (dec_oen),
        .inc        (dec_inc),
        .rsel       (dec_rsel),
        .rce        (dec_rce),
        .pc_mux_sel (dec_pc_mux_sel),
        .a_mux_sel  (dec_a_mux_sel),
        .b_mux_sel  (dec_b_mux_sel),
        .push       (dec_push),
        .pop        (dec_pop),
        .src_sel    (dec_src_sel),
        .stack_we   (dec_stack_we),
        .stack_re   (dec_stack_re),
        .out_ce     (dec_out_ce)
    );

    lifo_stack u_stack (
        .clk            (clk),
        .stack_data1_in (d_in),
        .stack_data2_in (pc_out),
        .stack_reset    (dec_rst),
        .stack_push     (dec_push),
        .stack_pop      (dec_pop),
        .stack_mux_sel  (dec_src_sel),
        .stack_we       (dec_stack_we),
        .stack_re       (dec_stack_re),
        .stack_data_out (stack_data_out),
        .full_o         (stack_full),
        .empty_o        (stack_empty)
    );

    program_counter u_pc (
        .clk                (clk),
        .full_adder_data_i  (arith_d_out),
        .pc_c_in            (c_inc_in),
        .inc                (dec_inc),
        .pc_mux_sel         (dec_pc_mux_sel),
        .pc_out             (pc_out),
        .pc_c_out           (pc_c_out)
    );

    microcode_arithmetic u_arith (
        .clk           (clk),
        .fa_in         (arith_d_out),
        .d_in          (d_in),
        .stack_data_in (stack_data_out),
        .pc_data_in    (pc_out),
        .reg_en        (r_en),
        .oen           (oen),
        .rce           (dec_rce),
        .cen           (dec_cen),
        .a_mux_sel     (dec_a_mux_sel),
        .b_mux_sel     (dec_b_mux_sel),
        .arith_cin     (c_n_in),
        .oe            (dec_oen),
        .rsel          (dec_rsel),
        .arith_cout    (arith_cout),
        .d_out         (arith_d_out)
    );

    // PRST forces the D output to zero; otherwise the full-adder result drives
    // it. The output bus is enabled only when oen is LOW (active-low).
    wire [3:0] d_out_int = dec_rst ? 4'b0000 : arith_d_out;
    assign d_out     = (~oen) ? d_out_int : 4'b0000;
    assign c_n_out   = arith_cout;
    assign c_inc_out = pc_c_out;
    assign full      = stack_full;
    assign empty     = stack_empty;

endmodule


// ---------------- Instruction Decoder ----------------
module instruction_decoder (
    input      [4:0] instr_in,
    input            cc_in,
    input            instr_en,   // ACTIVE LOW
    output reg       cen,
    output reg       rst,
    output reg       oen,
    output reg       inc,
    output reg       rsel,
    output reg       rce,
    output reg       pc_mux_sel,
    output reg [1:0] a_mux_sel,
    output reg [1:0] b_mux_sel,
    output reg       push,
    output reg       pop,
    output reg       src_sel,
    output reg       stack_we,
    output reg       stack_re,
    output reg       out_ce
);
    always @(*) begin
        // safe defaults
        cen        = 1'b0;
        rst        = 1'b0;
        oen        = 1'b0;
        inc        = 1'b0;
        rsel       = 1'b0;
        rce        = 1'b0;
        pc_mux_sel = 1'b0;
        a_mux_sel  = 2'b10;   // 4'b0000
        b_mux_sel  = 2'b10;   // 4'b0000
        push       = 1'b0;
        pop        = 1'b0;
        src_sel    = 1'b0;
        stack_we   = 1'b0;
        stack_re   = 1'b0;
        out_ce     = 1'b0;
        if (!instr_en) begin
            case (instr_in)
                5'b00000: begin                 // PRST
                    rst = 1'b1; oen = 1'b1; inc = 1'b1;
                end
                5'b00001: begin                 // Fetch PC
                    oen = 1'b1; a_mux_sel = 2'b10; b_mux_sel = 2'b00; out_ce = 1'b1;
                end
                5'b00010: begin                 // Fetch R
                    oen = 1'b1; a_mux_sel = 2'b01; b_mux_sel = 2'b10; out_ce = 1'b1;
                end
                5'b00011: begin                 // Fetch D
                    oen = 1'b1; a_mux_sel = 2'b00; b_mux_sel = 2'b10; out_ce = 1'b1;
                end
                5'b00100: begin                 // Fetch R + D
                    oen = 1'b1; a_mux_sel = 2'b00; b_mux_sel = 2'b11; out_ce = 1'b1;
                end
                5'b01011: begin                 // Push PC
                    push = 1'b1; stack_we = 1'b1; src_sel = 1'b0;
                end
                5'b01110: begin                 // Pop PC
                    pop = 1'b1; stack_re = 1'b1; oen = 1'b1;
                    a_mux_sel = 2'b10; b_mux_sel = 2'b01; out_ce = 1'b1;
                end
                default: ;
            endcase
        end
    end
endmodule


// ---------------- LIFO Stack ----------------
module stack_pointer (
    input            clk,
    input            rst,
    input            push,
    input            pop,
    output reg [4:0] stack_addr,
    output           full,
    output           empty
);
    assign full  = (stack_addr == 5'd16);
    assign empty = (stack_addr == 5'd0);
    always @(posedge clk) begin
        if (rst)
            stack_addr <= 5'd0;
        else if (push && !full)
            stack_addr <= stack_addr + 5'd1;
        else if (pop && !empty)
            stack_addr <= stack_addr - 5'd1;
    end
endmodule

module stack_ram (
    input            clk,
    input      [4:0] stack_addr,
    input      [3:0] stack_data_in,
    input            stack_we,
    input            stack_re,
    output     [3:0] stack_data_out
);
    reg [3:0] mem [0:16];
    always @(posedge clk) begin
        if (stack_we)
            mem[stack_addr] <= stack_data_in;
    end
    assign stack_data_out = mem[stack_addr];
endmodule

module stack_data_mux (
    input      [3:0] data_in,
    input      [3:0] pc_in,
    input            stack_mux_sel,
    output     [3:0] stack_mux_out
);
    assign stack_mux_out = stack_mux_sel ? data_in : pc_in;
endmodule

module lifo_stack (
    input            clk,
    input      [3:0] stack_data1_in,
    input      [3:0] stack_data2_in,
    input            stack_reset,
    input            stack_push,
    input            stack_pop,
    input            stack_mux_sel,
    input            stack_we,
    input            stack_re,
    output     [3:0] stack_data_out,
    output           full_o,
    output           empty_o
);
    wire [4:0] sp_addr;
    wire [3:0] mux_out;
    stack_pointer u_sp (
        .clk        (clk),
        .rst        (stack_reset),
        .push       (stack_push),
        .pop        (stack_pop),
        .stack_addr (sp_addr),
        .full       (full_o),
        .empty      (empty_o)
    );
    stack_data_mux u_mux (
        .data_in       (stack_data1_in),
        .pc_in         (stack_data2_in),
        .stack_mux_sel (stack_mux_sel),
        .stack_mux_out (mux_out)
    );
    stack_ram u_ram (
        .clk           (clk),
        .stack_addr    (sp_addr),
        .stack_data_in (mux_out),
        .stack_we      (stack_we),
        .stack_re      (stack_re),
        .stack_data_out(stack_data_out)
    );
endmodule


// ---------------- Program Counter ----------------
module pc_mux (
    input      [3:0] full_adder_data,
    input      [3:0] pc_data,
    input            pc_mux_sel,
    output     [3:0] pc_mux_out
);
    assign pc_mux_out = pc_mux_sel ? full_adder_data : pc_data;
endmodule

module pc_incrementer (
    input            pc_c_in,
    input            inc,
    input      [3:0] pc_data_in,
    output     [3:0] pc_inc_out,
    output           pc_c_out
);
    wire [4:0] sum = inc ? ({1'b0, pc_data_in} + {4'b0, pc_c_in})
                         : {1'b0, pc_data_in};
    assign pc_inc_out = sum[3:0];
    assign pc_c_out   = sum[4];
endmodule

module pc_reg (
    input            clk,
    input      [3:0] pc_data_in,
    output reg [3:0] pc_data_out
);
    always @(posedge clk)
        pc_data_out <= pc_data_in;
endmodule

module program_counter (
    input            clk,
    input      [3:0] full_adder_data_i,
    input            pc_c_in,
    input            inc,
    input            pc_mux_sel,
    output     [3:0] pc_out,
    output           pc_c_out
);
    wire [3:0] mux_out, inc_out, reg_out;
    pc_mux u_pcmux (
        .full_adder_data (full_adder_data_i),
        .pc_data         (reg_out),
        .pc_mux_sel      (pc_mux_sel),
        .pc_mux_out      (mux_out)
    );
    pc_incrementer u_inc (
        .pc_c_in    (pc_c_in),
        .inc        (inc),
        .pc_data_in (mux_out),
        .pc_inc_out (inc_out),
        .pc_c_out   (pc_c_out)
    );
    pc_reg u_reg (
        .clk         (clk),
        .pc_data_in  (inc_out),
        .pc_data_out (reg_out)
    );
    assign pc_out = reg_out;
endmodule


// ---------------- Microcode Arithmetic ----------------
module aux_reg_mux (
    input      [3:0] reg1_in,
    input      [3:0] reg2_in,
    input            rsel,
    input            re,        // ACTIVE LOW
    output     [3:0] reg_mux_out
);
    wire sel = rsel & ~re;
    assign reg_mux_out = sel ? reg1_in : reg2_in;
endmodule

module aux_reg (
    input            clk,
    input      [3:0] reg_in,
    input            rce,
    input            re,        // ACTIVE LOW
    output reg [3:0] reg_out
);
    wire en = rce | ~re;
    always @(posedge clk)
        if (en) reg_out <= reg_in;
endmodule

module a_mux (
    input      [3:0] register_data,
    input      [3:0] data_in,
    input      [1:0] a_mux_sel,
    output reg [3:0] a_mux_out
);
    always @(*) begin
        case (a_mux_sel)
            2'b00:   a_mux_out = data_in;
            2'b01:   a_mux_out = register_data;
            2'b10:   a_mux_out = 4'b0000;
            default: a_mux_out = 4'b0000;
        endcase
    end
endmodule

module b_mux (
    input      [3:0] register_data,
    input      [3:0] stack_data,
    input      [3:0] pc_data,
    input      [1:0] b_mux_sel,
    output reg [3:0] b_mux_out
);
    always @(*) begin
        case (b_mux_sel)
            2'b00:   b_mux_out = pc_data;
            2'b01:   b_mux_out = stack_data;
            2'b10:   b_mux_out = 4'b0000;
            2'b11:   b_mux_out = register_data;
            default: b_mux_out = 4'b0000;
        endcase
    end
endmodule

module full_adder (
    input      [3:0] a_in,
    input      [3:0] b_in,
    input            c_in,
    input            cen,       // ACTIVE HIGH: allow c_in
    output     [3:0] c_out,
    output           cout
);
    wire [4:0] sum = {1'b0, a_in} + {1'b0, b_in} + {4'b0, (cen ? c_in : 1'b0)};
    assign c_out = sum[3:0];
    assign cout  = sum[4];
endmodule

module microcode_arithmetic (
    input            clk,
    input      [3:0] fa_in,
    input      [3:0] d_in,
    input      [3:0] stack_data_in,
    input      [3:0] pc_data_in,
    input            reg_en,    // r_en, ACTIVE LOW
    input            oen,
    input            rce,
    input            cen,
    input      [1:0] a_mux_sel,
    input      [1:0] b_mux_sel,
    input            arith_cin,
    input            oe,
    input            rsel,
    output           arith_cout,
    output     [3:0] d_out
);
    wire [3:0] reg_mux_out, reg_out, a_out, b_out, sum;

    aux_reg_mux u_arm (
        .reg1_in     (fa_in),
        .reg2_in     (d_in),
        .rsel        (rsel),
        .re          (reg_en),
        .reg_mux_out (reg_mux_out)
    );
    aux_reg u_ar (
        .clk     (clk),
        .reg_in  (reg_mux_out),
        .rce     (rce),
        .re      (reg_en),
        .reg_out (reg_out)
    );
    a_mux u_am (
        .register_data (reg_out),
        .data_in       (d_in),
        .a_mux_sel     (a_mux_sel),
        .a_mux_out     (a_out)
    );
    b_mux u_bm (
        .register_data (reg_out),
        .stack_data    (stack_data_in),
        .pc_data       (pc_data_in),
        .b_mux_sel     (b_mux_sel),
        .b_mux_out     (b_out)
    );
    full_adder u_fa (
        .a_in  (a_out),
        .b_in  (b_out),
        .c_in  (arith_cin),
        .cen   (cen),
        .c_out (sum),
        .cout  (arith_cout)
    );
    assign d_out = sum;
endmodule


// ---------------- Result Register ----------------
module result_register (
    input            clk,
    input      [3:0] data_in,
    input            out_ce,
    output reg [3:0] data_out
);
    always @(posedge clk)
        if (out_ce) data_out <= data_in;

  // power-up determinism (rtl_hygiene_lint --fix): reset-less registered
  // outputs default to 0 so they are not X at t=0.
  initial begin
    data_out = 0;
  end

endmodule

module mux_synch (

input [7:0] data_in,   			//asynchronous data input
input req,                  		//indicating that data is available at the data_in input
input dst_clk,                 		//destination clock
input src_clk,                 		//source clock
input nrst,                    		//asynchronous reset
output reg [7:0] data_out,              //synchronized version of data_in to the destination clock domain
output ack_out );


wire syncd_req,anded_req,syncd_ack;
reg syncd_req_1,ack;


nff  req_synch_0 (.d_in(req),.dst_clk(dst_clk),.rst(nrst),.syncd(syncd_req)) ;		//2-flop synchronizer for the enable input


always_ff @(posedge dst_clk)                     					//one clock cycle delayed synced_enable
begin
    syncd_req_1 <= syncd_req;
end

assign anded_req = (!syncd_req_1 && syncd_req);    					//posedge detector


always_ff @(posedge dst_clk or negedge nrst)
begin
	if(!nrst)
		data_out <= 1'b0;               					//forcing the output data_in to zero when an active-low asynchronous reset is detected.

	else if (anded_req==1'b1)
		data_out <= data_in;                    				//latching data_in to data_out when the enable signal is available.

	else
		data_out <= data_out;                   				//holds the data till next req comes.
end


// acknowledgment signal generation
// BUG FIX: a one-cycle dst_clk pulse on `ack` can fall entirely between two
// active edges of the slower src_clk and be lost by the 2-flop synchronizer.
// Carry the event across the clock domain as a HELD LEVEL, not a 1-cycle
// pulse: assert ack when the data is sampled and hold it until the source
// withdraws its request (syncd_req falls), so the src-domain synchronizer is
// guaranteed to capture it regardless of the clock-frequency ratio.
always_ff@(posedge dst_clk or negedge nrst)
begin
	if(!nrst)
		ack <= 1'b0;

	else if (anded_req==1'b1)
		ack <= 1'b1;

	else if (!syncd_req)
		ack <= 1'b0;
	else
		ack <= ack;
end

//changing the clock domain of the ack signal
nff  enable_synch_1 (.d_in(ack),.dst_clk(src_clk),.rst(nrst),.syncd(syncd_ack)) ;

//edge detector circuit
assign ack_out = syncd_ack;


endmodule

module nff  (

	input d_in,   									//input data that needs to be synchronized to the dst_clk domain.
	input dst_clk,     								//destination domain clock.
	input rst,         								//asynchronous active-low reset
	output reg  syncd 								//synced output, which is a 2-clock-cycle delayed version of d_in.
	                   );

reg   dmeta;             								//register to hold output.



always@(posedge dst_clk or negedge rst)
begin
	if(!rst)              								//active-low asynchronous reset
  begin
    syncd <= 1'b0;      								//resetting the synced register to 0
    dmeta <= 1'b0;      								//resetting dmeta register to 0
  end
  else
  begin
    dmeta <= d_in;      								//passing d_in to dmeta
    syncd <= dmeta;     								//passing dmeta to syncd
  end
end

endmodule

module neuromorphic_array #(
    parameter NEURONS = 8,       // Number of neurons
    parameter INPUTS = 8,        // Number of inputs
    parameter OUTPUTS = 8         // Number of outputs
) (
    input  logic [7:0] ui_in,       // Control input
    input logic [7:0] uio_in,      // Input data
    output logic [7:0] uo_out,     // Output data
    input logic clk,                // Clock
    input logic rst_n               // Reset
);
    // Internal wires for neuron outputs
    logic [7:0] neuron_outputs [0:NEURONS-1];

    // Instantiate the neurons.
    // Each neuron updates its state from the SHARED module input data (uio_in)
    // when the control bit is high — a parallel broadcast, not a serial shift
    // chain (latency is independent of NEURONS, the last neuron's stored value
    // appears the cycle after a control-high update).
    genvar i;
    generate
        for (i = 0; i < NEURONS; i = i + 1) begin : neuron_inst
            single_neuron_dut neuron (
                .clk     (clk),
                .rst_n   (rst_n),
                .control (ui_in[0]),
                .seq_in  (uio_in),
                .seq_out (neuron_outputs[i])
            );
        end
    endgenerate

    // Combine outputs from the last neuron
    assign uo_out = neuron_outputs[NEURONS-1]; // Output from the last neuron

endmodule

module single_neuron_dut (
    input logic clk,
    input logic rst_n,
    input logic control,        // Control signal
    input logic [7:0] seq_in,   // Input sequence
    output logic [7:0] seq_out   // Output sequence
);
    // 8-bit internal state, updated with seq_in when control is high,
    // cleared on active-low reset; seq_out reflects the stored state.
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            seq_out <= 8'b0;
        else if (control)
            seq_out <= seq_in;
    end
endmodule

module perceptron_gates (
   input  logic clk,// Posedge clock
   input  logic rst_n,// Negedge reset
   input  logic signed [3:0] x1, // First Input of the Perceptron
   input  logic signed [3:0] x2, // Second Input of the Perceptron
   input  logic learning_rate, // Learning rate (alpha)
   input  logic signed [3:0] threshold, // Threshold value
   input  logic [1:0] gate_select, // Gate selection for target values
   output logic signed [3:0] percep_w1, // Trained Weight 1
   output logic signed [3:0] percep_w2, // Trained Weight 2
   output logic signed [3:0] percep_bias, // Trained Bias
   output logic [3:0] present_addr, // Current address in microcode ROM
   output logic stop, // Condition to indicate no learning has occurred(i.e. no weight change between iterations)
   output logic [2:0] input_index,// Vector to track the selection of target for a given input combination for a gate
   output logic signed [3:0] y_in, // Calculated Response
   output logic signed [3:0] y, // Calculated Response obtained by comparing y_in against a threshold value
   output logic signed [3:0] prev_percep_wt_1,//Value of Weight 1 during a previous iteration
   output logic signed [3:0] prev_percep_wt_2,//Value of Weight 2 during a previous iteration
   output logic signed [3:0] prev_percep_bias, // Value of Bias during a previous iteration
   // ---- Testing control unit outputs ----
   output logic [3:0]        test_percep_present_state, // present state of Testing microcode
   output logic signed [3:0] expected_percep_output,    // expected output from predefined vector
   output logic signed [3:0] test_percep_output,        // actual output of Testing unit
   output logic signed [3:0] test_percep_result,        // number of matches
   output logic signed [3:0] test_percep_done,          // Testing complete
   output logic signed [3:0] test_percep_x1,            // input from predefined vector
   output logic signed [3:0] test_percep_x2             // input from predefined vector
);

   logic [15:0] microcode_rom [0:5];
   logic [3:0]  next_addr;
   logic [3:0]  train_action;
   logic [3:0]  microcode_addr;
   logic [15:0] microinstruction;
   logic signed [3:0] t1, t2, t3, t4;

   gate_target dut (
       .gate_select(gate_select),
       .o_1(t1),
       .o_2(t2),
       .o_3(t3),
       .o_4(t4)
   );

   logic signed [3:0] percep_wt_1_reg;
   logic signed [3:0] percep_wt_2_reg;
   logic signed [3:0] percep_bias_reg;


   logic signed [3:0] target;
   logic signed [3:0] prev_wt1_update;
   logic signed [3:0] prev_wt2_update;
   logic signed [3:0] prev_bias_update;

   logic signed [3:0] wt1_update;
   logic signed [3:0] wt2_update;
   logic signed [3:0] bias_update;
   logic [7:0] epoch_counter;

   assign  prev_percep_wt_1 = prev_wt1_update;
   assign  prev_percep_wt_2 = prev_wt2_update;
   assign  prev_percep_bias = prev_bias_update;

   initial begin
      microcode_rom[0] = 16'b0001_0000_0000_0000;
      microcode_rom[1] = 16'b0010_0001_0000_0000;
      microcode_rom[2] = 16'b0011_0010_0000_0000;
      microcode_rom[3] = 16'b0100_0011_0000_0000;
      microcode_rom[4] = 16'b0101_0100_0000_0000;
      microcode_rom[5] = 16'b0000_0101_0000_0000;
   end

   always@(*) begin
      microinstruction = microcode_rom[microcode_addr];
      next_addr        = microinstruction[15:12];
      train_action     = microinstruction[11:8];
   end

   always_ff @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
         present_addr    <= 4'd0;
         microcode_addr  <= 4'd0;
         percep_wt_1_reg <= 4'd0;
         percep_wt_2_reg <= 4'd0;
         percep_bias_reg <= 4'd0;
         input_index     <= 2'd0;
         stop            <= 1'b0;
      end else begin
         present_addr    <= next_addr;
         microcode_addr  <= present_addr;
      end
   end

   always_comb begin
      case (train_action)
         4'd0:  begin
                   percep_wt_1_reg = 4'd0;
                   percep_wt_2_reg = 4'd0;
                   percep_bias_reg = 4'd0;
                   stop = 1'b0;
                   next_addr = next_addr + 4'd0;
                   y_in = 4'd0;
                   y    = 4'd0;
                   prev_wt1_update = 4'd0;
                   prev_wt2_update = 4'd0;
                   prev_bias_update = 4'd0;
                   input_index = 0;
                   target = 0;
                   wt1_update = 0;
                   wt2_update = 0;
                   bias_update = 0;
                   epoch_counter = 0;
                end
         4'd1 : begin
                   y_in = percep_bias_reg + (x1 * percep_wt_1_reg) + (x2 * percep_wt_2_reg);
                   if (y_in > threshold)
                      y = 4'd1;
                   else if (y_in >= -threshold && y_in <= threshold)
                      y = 4'd0;
                   else
                      y = -4'd1;

                   percep_wt_1_reg  = percep_wt_1_reg  + 4'd0;
                   percep_wt_2_reg  = percep_wt_2_reg  + 4'd0;
                   percep_bias_reg  = percep_bias_reg  + 4'd0;
                   prev_wt1_update  = prev_wt1_update  + 4'd0;
                   prev_wt2_update  = prev_wt2_update  + 4'd0;
                   prev_bias_update = prev_bias_update + 4'd0;
                   input_index = input_index + 0;
                   next_addr = next_addr + 4'd0;
                   stop = stop + 1'b0;
                   target = target + 4'd0;
                   wt1_update = wt1_update + 4'd0 ;
                   wt2_update = wt2_update + 4'd0 ;
                   bias_update = bias_update + 4'd0 ;
                   epoch_counter = epoch_counter + 0;
                end
         4'd2 : begin
                   if(input_index == 0)
                        target = t1;
                   else if(input_index == 1)
                        target = t2;
                   else if(input_index == 2)
                        target = t3;
                   else if(input_index == 3)
                        target = t4;
                   else begin
                        input_index = 0;
                        target = 0;
                   end
                   stop = stop + 1'b0;
                   input_index = input_index + 0;
                   next_addr = next_addr + 4'd0;
                   target = target + 4'd0;
                   prev_wt1_update  = prev_wt1_update  + 4'd0;
                   prev_wt2_update  = prev_wt2_update  + 4'd0;
                   prev_bias_update = prev_bias_update + 4'd0;

                   percep_wt_1_reg = percep_wt_1_reg + 4'd0;
                   percep_wt_2_reg = percep_wt_2_reg + 4'd0;
                   percep_bias_reg = percep_bias_reg + 4'd0;
                   y_in = y_in + 4'd0;
                   y = y + 4'd0;
                   wt1_update = wt1_update + 4'd0 ;
                   wt2_update = wt2_update + 4'd0 ;
                   bias_update = bias_update + 4'd0 ;
                   epoch_counter = epoch_counter + 0;
                end
         4'd3 : begin
                   if (y != target) begin
                        wt1_update = learning_rate * x1 * target ;
                        wt2_update = learning_rate * x2 * target ;
                        bias_update = learning_rate * target ;
                    end else begin
                        wt1_update = 0 ;
                        wt2_update = 0 ;
                        bias_update = 0 ;
                    end
                    percep_wt_1_reg = percep_wt_1_reg + wt1_update;
                    percep_wt_2_reg = percep_wt_2_reg + wt2_update;
                    percep_bias_reg = percep_bias_reg + bias_update;
                    prev_wt1_update  = prev_wt1_update  + 4'd0;
                    prev_wt2_update  = prev_wt2_update  + 4'd0;
                    prev_bias_update = prev_bias_update + 4'd0;
                    y_in = y_in + 4'd0;
                    y = y + 4'd0;
                    stop = stop + 1'b0;
                    input_index = input_index + 0;
                    next_addr = next_addr + 4'd0;
                    target = target + 4'd0;
                    epoch_counter = epoch_counter + 0;
                end
         4'd4 : begin
                  if ((prev_wt1_update == wt1_update) & (prev_wt2_update == wt2_update) & (input_index == 4'd3)) begin
                          // CONVERGED: hold the trained weights/bias so the
                          // Testing control unit can read them (do NOT zero
                          // them as the original did), park in this state, and
                          // assert stop.
                          epoch_counter = 0;
                          stop = 1'b1;
                          input_index = 0;
                          next_addr = 4'd4;
                          percep_wt_1_reg = percep_wt_1_reg + 4'd0;
                          percep_wt_2_reg = percep_wt_2_reg + 4'd0;
                          percep_bias_reg = percep_bias_reg + 4'd0;
                          prev_wt1_update  = prev_wt1_update + 4'd0;
                          prev_wt2_update  = prev_wt2_update + 4'd0;
                          prev_bias_update = prev_bias_update + 4'd0;
                          y_in = y_in + 4'd0;
                          y = y + 4'd0;
                          target = target + 4'd0;
                          wt1_update = wt1_update + 4'd0 ;
                          wt2_update = wt2_update + 4'd0 ;
                          bias_update = bias_update + 4'd0 ;
                  end else begin
                          stop = 1'b0;
                          input_index = input_index + 0;
                          epoch_counter = epoch_counter + 1;
                          next_addr = 4'd5;
                          percep_wt_1_reg = percep_wt_1_reg + 4'd0;
                          percep_wt_2_reg = percep_wt_2_reg + 4'd0;
                          percep_bias_reg = percep_bias_reg + 4'd0;
                          prev_wt1_update = prev_wt1_update + 4'd0;
                          prev_wt2_update = prev_wt2_update + 4'd0;
                          prev_bias_update = prev_bias_update + 4'd0;
                          y_in = y_in + 4'd0;
                          y = y + 4'd0;
                          target = target + 4'd0;
                          wt1_update = wt1_update + 4'd0 ;
                          wt2_update = wt2_update + 4'd0 ;
                          bias_update = bias_update + 4'd0 ;
                  end
                end
         4'd5 : begin
                          percep_wt_1_reg = percep_wt_1_reg + 4'd0;
                          percep_wt_2_reg = percep_wt_2_reg + 4'd0;
                          percep_bias_reg = percep_bias_reg + 4'd0;
                          prev_wt1_update  = wt1_update;
                          prev_wt2_update  = wt2_update;
                          prev_bias_update = bias_update;
                          next_addr = 4'd1;
                          input_index = input_index + 1;
                          stop = stop + 1'b0;
                          epoch_counter = epoch_counter + 0;
                          y_in = y_in + 4'd0;
                          y = y + 4'd0;
                          target = target + 4'd0;
                          wt1_update = wt1_update + 4'd0;
                          wt2_update = wt2_update + 4'd0;
                          bias_update = bias_update + 4'd0;
                end
      default : begin
                          next_addr = next_addr + 4'd0;
                          percep_wt_1_reg = percep_wt_1_reg + 4'd0;
                          percep_wt_2_reg = percep_wt_2_reg + 4'd0;
                          percep_bias_reg = percep_bias_reg + 4'd0;
                          prev_wt1_update = prev_wt1_update + 4'd0;
                          prev_wt2_update = prev_wt2_update + 4'd0;
                          prev_bias_update = prev_bias_update + 4'd0;
                          stop = stop + 1'b0;
                          y_in = y_in + 4'd0;
                          y = y + 4'd0;
                          input_index = input_index + 0;
                          target = target + 4'd0;
                          wt1_update = wt1_update + 4'd0 ;
                          wt2_update = wt2_update + 4'd0 ;
                          bias_update = bias_update + 4'd0 ;
                          epoch_counter = epoch_counter + 0;
                end
      endcase
   end
   assign percep_w1 = percep_wt_1_reg;
   assign percep_w2 = percep_wt_2_reg;
   assign percep_bias = percep_bias_reg;

   // ============================================================
   //  Testing Control Unit
   //  Validates the trained model against predefined test vectors
   //  once the training stop condition has been reached.
   // ============================================================
   logic signed [3:0] test_inputs_x1       [0:15];
   logic signed [3:0] test_inputs_x2       [0:15];
   logic signed [3:0] test_expected_outputs[0:15];

   initial begin
      // input pattern (x1,x2): (1,1),(-1,1),(1,-1),(-1,-1) per gate block
      // AND  : indices 0..3
      test_inputs_x1[0]= 1; test_inputs_x2[0]= 1; test_expected_outputs[0]= 1;
      test_inputs_x1[1]=-1; test_inputs_x2[1]= 1; test_expected_outputs[1]=-1;
      test_inputs_x1[2]= 1; test_inputs_x2[2]=-1; test_expected_outputs[2]=-1;
      test_inputs_x1[3]=-1; test_inputs_x2[3]=-1; test_expected_outputs[3]=-1;
      // OR   : indices 4..7
      test_inputs_x1[4]= 1; test_inputs_x2[4]= 1; test_expected_outputs[4]= 1;
      test_inputs_x1[5]=-1; test_inputs_x2[5]= 1; test_expected_outputs[5]= 1;
      test_inputs_x1[6]= 1; test_inputs_x2[6]=-1; test_expected_outputs[6]= 1;
      test_inputs_x1[7]=-1; test_inputs_x2[7]=-1; test_expected_outputs[7]=-1;
      // NAND : indices 8..11
      test_inputs_x1[8]= 1; test_inputs_x2[8]= 1; test_expected_outputs[8]=-1;
      test_inputs_x1[9]=-1; test_inputs_x2[9]= 1; test_expected_outputs[9]= 1;
      test_inputs_x1[10]= 1; test_inputs_x2[10]=-1; test_expected_outputs[10]= 1;
      test_inputs_x1[11]=-1; test_inputs_x2[11]=-1; test_expected_outputs[11]= 1;
      // NOR  : indices 12..15
      test_inputs_x1[12]= 1; test_inputs_x2[12]= 1; test_expected_outputs[12]=-1;
      test_inputs_x1[13]=-1; test_inputs_x2[13]= 1; test_expected_outputs[13]=-1;
      test_inputs_x1[14]= 1; test_inputs_x2[14]=-1; test_expected_outputs[14]=-1;
      test_inputs_x1[15]=-1; test_inputs_x2[15]=-1; test_expected_outputs[15]= 1;
   end

   // terminal/base index of the test-vector window for the selected gate
   logic [3:0] test_base;
   always_comb begin
      case (gate_select)
         2'b00:   test_base = 4'd0;
         2'b01:   test_base = 4'd4;
         2'b10:   test_base = 4'd8;
         default: test_base = 4'd12;
      endcase
   end

   logic [3:0] test_percep_index;
   logic [3:0] test_count;
   logic       testing_active;

   // combinational test computation on the CURRENT index
   logic signed [3:0] cur_x1, cur_x2, cur_exp;
   logic signed [9:0] test_calc;
   logic signed [3:0] test_out_calc;
   always_comb begin
      cur_x1  = test_inputs_x1[test_percep_index];
      cur_x2  = test_inputs_x2[test_percep_index];
      cur_exp = test_expected_outputs[test_percep_index];
      test_calc = (percep_w1 * cur_x1) + (percep_w2 * cur_x2) + percep_bias;
      if (test_calc > threshold)
         test_out_calc = 4'sd1;
      else if (test_calc >= -threshold && test_calc <= threshold)
         test_out_calc = 4'sd0;
      else
         test_out_calc = -4'sd1;
   end

   always_ff @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
         testing_active            <= 1'b0;
         test_count                <= 4'd0;
         test_percep_index         <= 4'd0;
         test_percep_result        <= 4'sd0;
         test_percep_output        <= 4'sd0;
         test_percep_done          <= 4'sd0;
         expected_percep_output    <= 4'sd0;
         test_percep_x1            <= 4'sd0;
         test_percep_x2            <= 4'sd0;
         test_percep_present_state <= 4'd0;
      end else begin
         if (stop && !testing_active && (test_percep_done == 4'sd0)) begin
            // start the testing sequence
            testing_active            <= 1'b1;
            test_count                <= 4'd0;
            test_percep_index         <= test_base;
            test_percep_result        <= 4'sd0;
            test_percep_done          <= 4'sd0;
            test_percep_present_state <= 4'd3;
         end else if (testing_active) begin
            // fetch + compute + compare for the current vector
            test_percep_x1            <= cur_x1;
            test_percep_x2            <= cur_x2;
            expected_percep_output    <= cur_exp;
            test_percep_output        <= test_out_calc;
            if (test_out_calc == cur_exp)
               test_percep_result <= test_percep_result + 4'sd1;
            test_percep_present_state <= test_percep_present_state + 4'd1;
            if (test_count == 4'd3) begin
               testing_active   <= 1'b0;
               test_percep_done <= 4'sd1;
            end else begin
               test_count        <= test_count + 4'd1;
               test_percep_index <= test_percep_index + 4'd1;
            end
         end
      end
   end

endmodule

module gate_target(
   input  logic        [1:0] gate_select,
   output logic signed [3:0] o_1,
   output logic signed [3:0] o_2,
   output logic signed [3:0] o_3,
   output logic signed [3:0] o_4
);
   always_comb begin
     case(gate_select)
          2'b00 : begin
                    o_1 =  1;
                    o_2 = -1;
                    o_3 = -1;
                    o_4 = -1;
                  end
          2'b01 : begin
                    o_1 =  1;
                    o_2 =  1;
                    o_3 =  1;
                    o_4 = -1;
                  end
          2'b10 : begin
                    o_1 =  1;
                    o_2 =  1;
                    o_3 =  1;
                    o_4 = -1;
                  end
          2'b11 : begin
                    o_1 =  1;
                    o_2 = -1;
                    o_3 = -1;
                    o_4 = -1;
                  end
        default : begin
                    o_1 =  0;
                    o_2 =  0;
                    o_3 =  0;
                    o_4 =  0;
                  end
        endcase
   end
endmodule

module perceptron_gates (
   input  logic clk,// Posedge clock
   input  logic rst_n,// Negedge reset
   input  logic signed [3:0] x1, // First Input of the Perceptron
   input  logic signed [3:0] x2, // Second Input of the Perceptron
   input  logic learning_rate, // Learning rate (alpha)
   input  logic signed [3:0] threshold, // Threshold value
   input  logic [1:0] gate_select, // Gate selection for target values
   output logic signed [3:0] percep_w1, // Trained Weight 1
   output logic signed [3:0] percep_w2, // Trained Weight 2
   output logic signed [3:0] percep_bias, // Trained Bias
   output logic [3:0] present_addr, // Current address in microcode ROM
   output logic stop, // Condition to indicate no learning has occurred(i.e. no weight change between iterations)
   output logic [2:0] input_index,// Vector to track the selection of target for a given input combination for a gate
   output logic signed [3:0] y_in, // Calculated Response
   output logic signed [3:0] y, // Calculated Response obtained by comparing y_in against a threshold value
   output logic signed [3:0] prev_percep_wt_1,//Value of Weight 1 during a previous iteration
   output logic signed [3:0] prev_percep_wt_2,//Value of Weight 2 during a previous iteration
   output logic signed [3:0] prev_percep_bias // Value of Bias during a previous iteration
);

   logic [7:0] microcode_rom [0:5];
   logic [3:0]  next_addr;
   logic [3:0]  train_action;
   logic [3:0]  microcode_addr;
   logic [15:0] microinstruction;
   logic signed [3:0] t1, t2, t3, t4;

   gate_target dut (
       .gate_select(gate_select),
       .o_1(t1),
       .o_2(t2),
       .o_3(t3),
       .o_4(t4)
   );

   logic signed [3:0] percep_wt_1_reg;
   logic signed [3:0] percep_wt_2_reg;
   logic signed [3:0] percep_bias_reg;


   logic signed [3:0] target;
   logic signed [3:0] prev_wt1_update;
   logic signed [3:0] prev_wt2_update;
   logic signed [3:0] prev_bias_update;

   logic signed [3:0] wt1_update;
   logic signed [3:0] wt2_update;
   logic signed [3:0] bias_update;
   logic [7:0] epoch_counter;

   assign  prev_percep_wt_1 = prev_wt1_update;
   assign  prev_percep_wt_2 = prev_wt2_update;
   assign  prev_percep_bias = prev_bias_update;

   initial begin
      microcode_rom[0] = 8'b0001_0000;
      microcode_rom[1] = 8'b0010_0001;
      microcode_rom[2] = 8'b0011_0010;
      microcode_rom[3] = 8'b0100_0011;
      microcode_rom[4] = 8'b0101_0100;
      microcode_rom[5] = 8'b0000_0101;
   end

   always@(*) begin
      microinstruction = microcode_rom[microcode_addr];
      next_addr        = microinstruction[7:4];
      train_action     = microinstruction[3:0];
   end

   always_ff @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
         present_addr    <= 4'd0;
         microcode_addr  <= 4'd0;
         percep_wt_1_reg <= 4'd0;
         percep_wt_2_reg <= 4'd0;
         percep_bias_reg <= 4'd0;
         input_index     <= 2'd0;
         stop            <= 1'b0;
      end else begin
         present_addr    <= next_addr;
         microcode_addr  <= present_addr;
      end
   end

   always_comb begin
      case (train_action)
         4'd0:  begin
                   percep_wt_1_reg = 4'd0;
                   percep_wt_2_reg = 4'd0;
                   percep_bias_reg = 4'd0;
                   stop = 1'b0;
                   next_addr = next_addr + 4'd0;
                   y_in = 4'd0;
                   y    = 4'd0;
                   prev_wt1_update = 4'd0;
                   prev_wt2_update = 4'd0;
                   prev_bias_update = 4'd0;
                   input_index = 0;
                   target = 0;
                   wt1_update = 0;
                   wt2_update = 0;
                   bias_update = 0;
                   epoch_counter = 0;
                end
         4'd1 : begin
                   y_in = percep_bias_reg + (x1 * percep_wt_1_reg) + (x2 * percep_wt_2_reg);
                   if (y_in > threshold)
                      y = 4'd1;
                   else if (y_in >= -threshold && y_in <= threshold)
                      y = 4'd0;
                   else
                      y = -4'd1;

                   percep_wt_1_reg  = percep_wt_1_reg  + 4'd0;
                   percep_wt_2_reg  = percep_wt_2_reg  + 4'd0;
                   percep_bias_reg  = percep_bias_reg  + 4'd0;
                   prev_wt1_update  = prev_wt1_update  + 4'd0;
                   prev_wt2_update  = prev_wt2_update  + 4'd0;
                   prev_bias_update = prev_bias_update + 4'd0;
                   input_index = input_index + 0;
                   next_addr = next_addr + 4'd0;
                   stop = stop + 1'b0;
                   target = target + 4'd0;
                   wt1_update = wt1_update + 4'd0 ;
                   wt2_update = wt2_update + 4'd0 ;
                   bias_update = bias_update + 4'd0 ;
                   epoch_counter = epoch_counter + 0;
                end
         4'd2 : begin
                   if(input_index == 0)
                        target = t1;
                   else if(input_index == 1)
                        target = t2;
                   else if(input_index == 2)
                        target = t3;
                   else if(input_index == 3)
                        target = t4;
                   else begin
                        input_index = 0;
                        target = 0;
                   end
                   stop = stop + 1'b0;
                   input_index = input_index + 0;
                   next_addr = next_addr + 4'd0;
                   target = target + 4'd0;
                   prev_wt1_update  = prev_wt1_update  + 4'd0;
                   prev_wt2_update  = prev_wt2_update  + 4'd0;
                   prev_bias_update = prev_bias_update + 4'd0;

                   percep_wt_1_reg = percep_wt_1_reg + 4'd0;
                   percep_wt_2_reg = percep_wt_2_reg + 4'd0;
                   percep_bias_reg = percep_bias_reg + 4'd0;
                   y_in = y_in + 4'd0;
                   y = y + 4'd0;
                   wt1_update = wt1_update + 4'd0 ;
                   wt2_update = wt2_update + 4'd0 ;
                   bias_update = bias_update + 4'd0 ;
                   epoch_counter = epoch_counter + 0;
                end
         4'd3 : begin
                   if (y != target) begin
                        wt1_update = learning_rate * x1 * target ;
                        wt2_update = learning_rate * x2 * target ;
                        bias_update = learning_rate * target ;
                    end else begin
                        wt1_update = 0 ;
                        wt2_update = 0 ;
                        bias_update = 0 ;
                    end
                    percep_wt_1_reg = percep_wt_1_reg + wt1_update;
                    percep_wt_2_reg = percep_wt_2_reg + wt2_update;
                    percep_bias_reg = percep_bias_reg + bias_update;
                    prev_wt1_update  = prev_wt1_update  + 4'd0;
                    prev_wt2_update  = prev_wt2_update  + 4'd0;
                    prev_bias_update = prev_bias_update + 4'd0;
                    y_in = y_in + 4'd0;
                    y = y + 4'd0;
                    stop = stop + 1'b0;
                    input_index = input_index + 0;
                    next_addr = next_addr + 4'd0;
                    target = target + 4'd0;
                    epoch_counter = epoch_counter + 0;
                end
         4'd4 : begin
                  if ((prev_wt1_update == wt1_update) & (prev_wt2_update == wt2_update) & (input_index == 4'd3)) begin
                          epoch_counter = 0;
                          stop = 1'b1;
                          input_index = 0;
                          next_addr = 4'd0;
                          percep_wt_1_reg = percep_wt_1_reg + 4'd0;
                          percep_wt_2_reg = percep_wt_2_reg + 4'd0;
                          percep_bias_reg = percep_bias_reg + 4'd0;
                          prev_wt1_update  = prev_wt1_update + 4'd0;
                          prev_wt2_update  = prev_wt2_update + 4'd0;
                          prev_bias_update = prev_bias_update + 4'd0;
                          y_in = y_in + 4'd0;
                          y = y + 4'd0;
                          target = target + 4'd0;
                          wt1_update = wt1_update + 4'd0 ;
                          wt2_update = wt2_update + 4'd0 ;
                          bias_update = bias_update + 4'd0 ;
                  end else begin
                          stop = 1'b0;
                          input_index = input_index + 0;
                          epoch_counter = epoch_counter + 1;
                          next_addr = 4'd5;
                          percep_wt_1_reg = percep_wt_1_reg + 4'd0;
                          percep_wt_2_reg = percep_wt_2_reg + 4'd0;
                          percep_bias_reg = percep_bias_reg + 4'd0;
                          prev_wt1_update = prev_wt1_update + 4'd0;
                          prev_wt2_update = prev_wt2_update + 4'd0;
                          prev_bias_update = prev_bias_update + 4'd0;
                          y_in = y_in + 4'd0;
                          y = y + 4'd0;
                          target = target + 4'd0;
                          wt1_update = wt1_update + 4'd0 ;
                          wt2_update = wt2_update + 4'd0 ;
                          bias_update = bias_update + 4'd0 ;
                  end
                end
         4'd5 : begin
                          percep_wt_1_reg = percep_wt_1_reg + 4'd0;
                          percep_wt_2_reg = percep_wt_2_reg + 4'd0;
                          percep_bias_reg = percep_bias_reg + 4'd0;
                          prev_wt1_update  = wt1_update;
                          prev_wt2_update  = wt2_update;
                          prev_bias_update = bias_update;
                          next_addr = 4'd1;
                          input_index = input_index + 1;
                          stop = stop + 1'b0;
                          epoch_counter = epoch_counter + 0;
                          y_in = y_in + 4'd0;
                          y = y + 4'd0;
                          target = target + 4'd0;
                          wt1_update = wt1_update + 4'd0;
                          wt2_update = wt2_update + 4'd0;
                          bias_update = bias_update + 4'd0;
                end
      default : begin
                          next_addr = next_addr + 4'd0;
                          percep_wt_1_reg = percep_wt_1_reg + 4'd0;
                          percep_wt_2_reg = percep_wt_2_reg + 4'd0;
                          percep_bias_reg = percep_bias_reg + 4'd0;
                          prev_wt1_update = prev_wt1_update + 4'd0;
                          prev_wt2_update = prev_wt2_update + 4'd0;
                          prev_bias_update = prev_bias_update + 4'd0;
                          stop = stop + 1'b0;
                          y_in = y_in + 4'd0;
                          y = y + 4'd0;
                          input_index = input_index + 0;
                          target = target + 4'd0;
                          wt1_update = wt1_update + 4'd0 ;
                          wt2_update = wt2_update + 4'd0 ;
                          bias_update = bias_update + 4'd0 ;
                          epoch_counter = epoch_counter + 0;
                end
      endcase
   end
   assign percep_w1 = percep_wt_1_reg;
   assign percep_w2 = percep_wt_2_reg;
   assign percep_bias = percep_bias_reg;

endmodule

module gate_target(
   input  logic        [1:0] gate_select,
   output logic signed [3:0] o_1,
   output logic signed [3:0] o_2,
   output logic signed [3:0] o_3,
   output logic signed [3:0] o_4
);
   always_comb begin
     case(gate_select)
          2'b00 : begin
                    o_1 =  4'b0001;
                    o_2 = -4'b0001;
                    o_3 = -4'b0001;
                    o_4 = -4'b0001;
                  end
          2'b01 : begin
                    o_1 =  4'b0001;
                    o_2 =  4'b0001;
                    o_3 =  4'b0001;
                    o_4 = -4'b0001;
                  end
          2'b10 : begin
                    o_1 =  4'b0001;
                    o_2 =  4'b0001;
                    o_3 =  4'b0001;
                    o_4 = -4'b0001;
                  end
          2'b11 : begin
                    o_1 =  4'b0001;
                    o_2 = -4'b0001;
                    o_3 = -4'b0001;
                    o_4 = -4'b0001;
                  end
        default : begin
                    o_1 =  4'b0000;
                    o_2 =  4'b0000;
                    o_3 =  4'b0000;
                    o_4 =  4'b0000;
                  end
        endcase
   end
endmodule

{"code": [{"rtl/dual_port_memory.sv": ""}, {"rtl/ping_pong_buffer.sv": "module ping_pong_buffer (
    input logic clk,
    input logic rst_n,
    input logic write_enable,
    input logic read_enable,
    input logic [7:0] data_in,
    output logic [7:0] data_out,
    output logic buffer_full,
    output logic buffer_empty,
    output reg buffer_select
);

    localparam DEPTH = 256;
    localparam ADDR_WIDTH = 8;

    logic [ADDR_WIDTH-1:0] write_ptr, read_ptr;
    logic [7:0] data_out0, data_out1;
    logic       write_bank;            // bank currently being written
    logic       we0, we1;

    // write goes to the bank being filled; reads come from buffer_select
    assign we0 = write_enable && !buffer_full && (write_bank == 1'b0);
    assign we1 = write_enable && !buffer_full && (write_bank == 1'b1);

    // Dual port memories: combinational read at read_ptr, sync write at write_ptr
    dual_port_memory memory0 (
        .clk        (clk),
        .we         (we0),
        .write_addr (write_ptr),
        .din        (data_in),
        .read_addr  (read_ptr),
        .dout       (data_out0)
    );

    dual_port_memory memory1 (
        .clk        (clk),
        .we         (we1),
        .write_addr (write_ptr),
        .din        (data_in),
        .read_addr  (read_ptr),
        .dout       (data_out1)
    );

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            write_ptr     <= '0;
            read_ptr      <= '0;
            write_bank    <= 1'b0;
            buffer_select <= 1'b0;
            buffer_full   <= 1'b0;
            buffer_empty  <= 1'b1;
            data_out      <= 8'b0;
        end else begin
            // ---- write side ----
            if (write_enable && !buffer_full) begin
                if (write_ptr == DEPTH-1) begin
                    write_ptr   <= '0;
                    write_bank  <= ~write_bank;   // next writes go to the other bank
                    buffer_full <= 1'b1;          // active bank reached capacity
                end else begin
                    write_ptr   <= write_ptr + 1'b1;
                end
                buffer_empty <= 1'b0;             // data now available
            end

            // ---- read side ----
            if (read_enable && !buffer_empty) begin
                // register the pre-increment word read from the active bank
                data_out <= buffer_select ? data_out1 : data_out0;
                if (read_ptr == DEPTH-1) begin
                    read_ptr      <= '0;
                    buffer_select <= ~buffer_select;  // switch active read buffer
                    buffer_empty  <= 1'b1;            // this bank drained
                    buffer_full   <= 1'b0;            // room is free again
                end else begin
                    read_ptr <= read_ptr + 1'b1;
                end
            end
        end
    end

endmodule"}]}

module pipeline_mac #(
    parameter DWIDTH = 16,  // Bit width for multiplicand and multiplier
    parameter N      = 4    // Number of data points to accumulate over
) (
    clk,
    rstn,
    multiplicand,
    multiplier,
    valid_i,
    result,
    valid_out
);
  // ----------------------------------------
  // - Local parameter definition
  // ----------------------------------------

  // The product of two DWIDTH-wide operands is up to 2*DWIDTH bits; accumulating
  // N of them needs $clog2(N) extra bits so the maximum value never overflows.
  localparam DWIDTH_ACCUMULATOR = 2*DWIDTH + $clog2(N);

  // ----------------------------------------
  // - Interface Definitions
  // ----------------------------------------
  input logic clk;                                // Clock signal
  input logic rstn;                               // Active low reset signal
  input logic [DWIDTH-1:0] multiplicand;          // Input multiplicand
  input logic [DWIDTH-1:0] multiplier;            // Input multiplier
  input logic valid_i;                            // Input valid signal
  output logic [DWIDTH_ACCUMULATOR-1:0] result;   // Accumulated result output
  output logic valid_out;                         // Output valid signal, indicates when result is ready

  // ----------------------------------------
  // - Internal signals
  // ----------------------------------------
  logic [DWIDTH_ACCUMULATOR-1:0] mult_result_reg;    // Register to store intermediate multiplication result
  logic [DWIDTH_ACCUMULATOR-1:0] accumulation_reg;   // Register to store accumulated result
  logic [$clog2(N):0] counter;                       // Counter to track the number of accumulations
  logic [$clog2(N):0] counter_reg;                   // Register to hold the value of the counter
  logic count_rst, accumulator_rst;                  // Reset signals for counter and accumulator
  logic valid_out_s0,valid_out_s1,valid_out_s2;      // Intermediate Signals indicating that the valid output is ready
  logic valid_i_s1;                                  // Intermediate Signals indicating input valid signal
  // ----------------------------------------
  // - Procedural blocks
  // ----------------------------------------

  // Stage 1 of the pipeline: Perform multiplication
  always @(posedge clk or negedge rstn) begin
    if (!rstn) begin
      mult_result_reg <= '0;
      valid_i_s1      <= 1'b0;
    end else begin
      // pipeline the input-valid one stage so accumulation tracks the data
      valid_i_s1 <= valid_i;
      // hold the product when valid_i is low (no new data processed)
      if (valid_i)
        mult_result_reg <= multiplicand * multiplier;
    end
  end

  // Stage 2 of the pipeline: Accumulation logic
  always @(posedge clk or negedge rstn) begin
    if (!rstn) begin
      accumulation_reg <= '0;
    end else if (accumulator_rst) begin
      // after a result is emitted, start a fresh accumulation with the
      // product currently arriving (if any), otherwise clear
      accumulation_reg <= valid_i_s1 ? mult_result_reg : '0;
    end else if (valid_i_s1) begin
      accumulation_reg <= accumulation_reg + mult_result_reg;
    end
  end

  // N-bit counter to track the number of accumulations
  always @(posedge clk or negedge rstn) begin
    if (!rstn)
      counter_reg <= '0;
    else
      counter_reg <= counter;
  end

  // Register valid output for 2-stage pipeline
  always @(posedge clk or negedge rstn) begin
    if (!rstn) begin
      valid_out_s1 <= 1'b0;
      valid_out_s2 <= 1'b0;
    end else begin
      valid_out_s1 <= valid_out_s0;
      valid_out_s2 <= valid_out_s1;
    end
  end

  // ----------------------------------------
  // - Combinational Assignments
  // ----------------------------------------
  assign counter = count_rst ? 'b1 : (valid_i & rstn ? (counter_reg + 'd1) : counter_reg);  // Increment counter on valid input
  assign valid_out_s0 = (counter_reg == N-1);    // Assert valid_out_s0 when N accumulations are done
  assign count_rst = valid_out_s1;                  // Reset counter after N accumulations
  assign accumulator_rst = valid_out_s1;            // Reset accumulator after N accumulations
  assign result = accumulation_reg;              // Output final result assignment
  assign valid_out = valid_out_s1 & ~valid_out_s2; // Valid_out signal generation by detecting posedge of previous stages of valid out

endmodule : pipeline_mac

// PRBS generator / checker built around a parallel LFSR.
//   CHECK_MODE = 0 : generator  (LFSR self-feedback, data_in tied to 0)
//   CHECK_MODE = 1 : checker    (load incoming data, compare against PRBS)
// Per spec: for each output bit the feedback = prbs[POLY_TAP] ^ prbs[POLY_LENGTH],
// inserted at the MSB while the register shifts RIGHT.
module cvdp_prbs_gen #(
    parameter CHECK_MODE  = 0,
    parameter POLY_LENGTH = 31,
    parameter POLY_TAP    = 3,
    parameter WIDTH       = 16
) (
    input  wire                  clk,
    input  wire                  rst,       // active-high synchronous reset
    input  wire [WIDTH-1:0]      data_in,
    output reg  [WIDTH-1:0]      data_out
);

    // PRBS shift register, indexed [POLY_LENGTH:1] so POLY_TAP / POLY_LENGTH
    // address it directly.
    reg  [POLY_LENGTH:1] prbs;

    reg  [POLY_LENGTH:1] prbs_var;
    reg  [WIDTH-1:0]     data_out_var;
    reg                  feedback_bit;
    integer              i;

    always @(posedge clk) begin
        if (rst) begin
            // seed: all ones; data_out initialised to all ones
            prbs     <= {POLY_LENGTH{1'b1}};
            data_out <= {WIDTH{1'b1}};
        end else begin
            prbs_var     = prbs;
            data_out_var = {WIDTH{1'b0}};
            for (i = 0; i < WIDTH; i = i + 1) begin
                // feedback = XOR of the tap and the end of the register
                feedback_bit = prbs_var[POLY_TAP] ^ prbs_var[POLY_LENGTH];
                if (CHECK_MODE == 0) begin
                    // generator: emit the PRBS bit, feed it back at the MSB
                    data_out_var[i] = feedback_bit;
                    prbs_var        = {feedback_bit, prbs_var[POLY_LENGTH:2]};
                end else begin
                    // checker: compare incoming bit against the PRBS bit and
                    // load the incoming bit into the register (self-synchronising)
                    data_out_var[i] = data_in[i] ^ feedback_bit;
                    prbs_var        = {data_in[i], prbs_var[POLY_LENGTH:2]};
                end
            end
            prbs     <= prbs_var;
            data_out <= data_out_var;
        end
    end

endmodule

module reed_solomon_encoder #(
    parameter DATA_WIDTH = 8,   // Width of input data symbols
    parameter N = 255,         // Total number of symbols in the codeword
    parameter K = 223          // Number of data symbols
) (
    input wire clk,
    input wire reset,
    input wire enable,
    input wire [DATA_WIDTH-1:0] data_in,
    input wire valid_in,
    output reg [DATA_WIDTH-1:0] codeword_out,
    output reg valid_out,
    output reg [DATA_WIDTH-1:0] parity_0,
    output reg [DATA_WIDTH-1:0] parity_1
);

    localparam PARITY_SYMBOLS = N - K;// Number of parity symbols

    // Internal registers for shift-register based encoding
    reg [DATA_WIDTH-1:0] feedback;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset all registers
            parity_0 <= 0 ;
            parity_1 <= 0 ;
            codeword_out <= 0;
            valid_out <= 0;
        end else if (enable && valid_in) begin
            // Shift-register Reed-Solomon encoding: the feedback term is the
            // incoming symbol XORed with the highest parity register; each new
            // parity symbol is the previous parity XORed with the feedback
            // multiplied (in GF(2^8)) by the matching generator coefficient.
            feedback     = data_in ^ parity_1;
            parity_1     <= parity_0 ^ gf_mul(feedback, generator_polynomial(1));
            parity_0     <= gf_mul(feedback, generator_polynomial(0));
            codeword_out <= data_in;
            valid_out    <= 1'b1;
        end else begin
            valid_out <= 1'b0;
        end
    end

    // GF(2^8) multiply using the standard primitive polynomial reduction (0x1D)
    function [DATA_WIDTH-1:0] gf_mul(input [DATA_WIDTH-1:0] a, input [DATA_WIDTH-1:0] b);
        reg [DATA_WIDTH-1:0] prod;
        reg [DATA_WIDTH-1:0] aa;
        reg [DATA_WIDTH-1:0] bb;
        integer k;
        begin
            prod = 0;
            aa   = a;
            bb   = b;
            for (k = 0; k < DATA_WIDTH; k = k + 1) begin
                if (bb[0])
                    prod = prod ^ aa;
                bb = bb >> 1;
                if (aa[DATA_WIDTH-1])
                    aa = (aa << 1) ^ 8'h1D;
                else
                    aa = (aa << 1);
            end
            gf_mul = prod;
        end
    endfunction

    function [DATA_WIDTH-1:0] generator_polynomial(input integer index);
        // Generator coefficients select between 8'h1D and 8'h33 by index
        begin
            case (index)
                0:       generator_polynomial = 8'h1D;
                1:       generator_polynomial = 8'h33;
                default: generator_polynomial = 8'h00;
            endcase
        end
    endfunction

endmodule

module cvdp_copilot_register_file_2R1W #(
    parameter DATA_WIDTH = 32,  // Configurable data width
    parameter DEPTH      = 32   // Number of register entries
) (
    // Inputs
    input  logic [DATA_WIDTH-1:0] din,    // Input data
    input  logic [4:0] wad1,              // Write address
    input  logic [4:0] rad1,              // Read address 1
    input  logic [4:0] rad2,              // Read address 2
    input  logic wen1,                    // Write-enable signal
    input  logic ren1,                    // Read-enable signal 1
    input  logic ren2,                    // Read-enable signal 2
    input  logic clk,                     // Clock signal
    input  logic resetn,                  // Active-low reset
    input  logic test_mode,               // Activates BIST when high

    // Outputs
    output logic [DATA_WIDTH-1:0] dout1,   // Output data 1
    output logic [DATA_WIDTH-1:0] dout2,   // Output data 2
    output logic collision,                // Collision flag
    output logic bist_done,                // BIST sequence complete
    output logic bist_fail                 // BIST detected a mismatch
);

    // -------------------------------
    // Internal Registers and Wires
    // -------------------------------

    // Register file memory with DEPTH entries of DATA_WIDTH-bit words
    logic [DATA_WIDTH-1:0] rf_mem [0:31];
    logic [31:0] rf_valid;                   // Validity of each register entry
    integer i;

    // Clock Gating Enable Signal: High when any read/write op or BIST is active
    wire clk_en = wen1 | ren1 | ren2 | test_mode;

    // Clock Gating Logic (Integrated from cgate module)
    logic gated_clk;    // Gated clock output
    logic en_latch;     // Enable latch

    // Latch to hold the enable signal when clk is low
    always @ (clk or clk_en) begin
        if (!clk)
            en_latch <= clk_en;
    end

    // Gated clock generation
    assign gated_clk = clk && en_latch;

    // -------------------------------
    // BIST control
    // -------------------------------
    localparam BIST_IDLE  = 2'd0;
    localparam BIST_WRITE = 2'd1;
    localparam BIST_READ  = 2'd2;
    localparam BIST_DONE  = 2'd3;

    logic [1:0] bist_state;
    logic [5:0] bist_addr;                       // counts 0..DEPTH
    wire  [DATA_WIDTH-1:0] bist_pattern = bist_addr; // known pattern = address

    // -------------------------------
    // Register File Operations + BIST
    // -------------------------------

    // Single block drives rf_mem so BIST and normal writes never conflict.
    always_ff @(posedge gated_clk or negedge resetn) begin
        if (!resetn) begin
            // Initialize all memory locations to zero
            for (i = 0; i < 32; i = i + 1) begin
                rf_mem[i] <= {DATA_WIDTH{1'b0}};
            end
            rf_valid   <= 0;  // Mark all entries as invalid
            bist_state <= BIST_IDLE;
            bist_addr  <= 6'd0;
            bist_done  <= 1'b0;
            bist_fail  <= 1'b0;
        end
        else if (test_mode) begin
            // BIST sequence: write a known pattern to each location, then read
            // it back and verify; halt in DONE. Normal ops are disabled.
            case (bist_state)
                BIST_IDLE: begin
                    bist_done  <= 1'b0;
                    bist_fail  <= 1'b0;
                    bist_addr  <= 6'd0;
                    bist_state <= BIST_WRITE;
                end
                BIST_WRITE: begin
                    rf_mem[bist_addr[4:0]]   <= bist_pattern;
                    rf_valid[bist_addr[4:0]] <= 1'b1;
                    if (bist_addr == DEPTH-1) begin
                        bist_addr  <= 6'd0;
                        bist_state <= BIST_READ;
                    end else begin
                        bist_addr <= bist_addr + 6'd1;
                    end
                end
                BIST_READ: begin
                    if (rf_mem[bist_addr[4:0]] != bist_pattern)
                        bist_fail <= 1'b1;
                    if (bist_addr == DEPTH-1)
                        bist_state <= BIST_DONE;
                    else
                        bist_addr <= bist_addr + 6'd1;
                end
                BIST_DONE: begin
                    bist_done <= 1'b1;
                end
                default: bist_state <= BIST_IDLE;
            endcase
        end
        else begin
            // Normal operation: BIST idle, standard single-write behaviour
            bist_state <= BIST_IDLE;
            bist_done  <= 1'b0;
            bist_fail  <= 1'b0;
            if (wen1) begin
                rf_mem[wad1]   <= din;  // Write operation
                rf_valid[wad1] <= 1'b1; // Mark written address as valid
            end
        end
    end

    // Read Data Output Logic for Port 1 with Gated Clock
    always_ff @(posedge gated_clk or negedge resetn) begin
        if (!resetn) begin
            dout1 <= 0;
        end
        else if (!test_mode && ren1) begin
            dout1 <= rf_valid[rad1] ? rf_mem[rad1] : 0;
        end
        else begin
            dout1 <= 0;
        end
    end

    // Read Data Output Logic for Port 2 with Gated Clock
    always_ff @(posedge gated_clk or negedge resetn) begin
        if (!resetn) begin
            dout2 <= 0;
        end
        else if (!test_mode && ren2) begin
            dout2 <= rf_valid[rad2] ? rf_mem[rad2] : 0;
        end
        else begin
            dout2 <= 0;
        end
    end

    // -------------------------------
    // Collision Detection Logic
    // -------------------------------

    // Collision Flag Logic with Original Clock (non-gated)
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            collision <= 0;
        end
        else begin
            collision <= (
                (ren1 && ren2 && (rad1 == rad2)) ||          // Both reads to the same address
                (wen1 && ren1 && (wad1 == rad1)) ||          // Write and read to the same address
                (wen1 && ren2 && (wad1 == rad2))             // Write and read to the same address
            );
        end
    end

endmodule

module rounding #(
  parameter WIDTH = 24
)(
  input logic  [WIDTH-1:0] in_data  , // Input value for rounding
  input logic              sign     , // Indicates sign of input (1: negative, 0: positive)
  input logic              roundin  , // Round bit
  input logic              stickyin , // Sticky bit for precision
  input logic  [2:0]       rm       , // Rounding mode
  output logic [WIDTH-1:0] out_data , // Rounded output
  output logic             inexact  , // Indicates precision loss
  output logic             cout     , // Carry-out_data signal
  output logic             r_up       // Indicates rounding up
);

  localparam RNE = 3'b000;
  localparam RTZ = 3'b001;
  localparam RUP = 3'b010;
  localparam RDN = 3'b011;
  localparam RMM = 3'b100;

  logic rounding_up;

  always_comb begin
    case (rm)
      // Round to Nearest, Even: round up when the round bit is set AND
      // (any sticky bit set -> strictly above half, OR the LSB is 1 -> tie to even).
      RNE: rounding_up = roundin & (stickyin | in_data[0]);
      // Round Toward Zero: pure truncation, never round up.
      RTZ: rounding_up = 1'b0;
      // Round Toward +inf (ceiling): only positive magnitudes round up.
      RUP: rounding_up = (~sign) & (roundin | stickyin);
      // Round Toward -inf (floor): only negative magnitudes round up.
      RDN: rounding_up =   sign  & (roundin | stickyin);
      // Round to Nearest, Maximum Magnitude (away from zero): round bit decides.
      RMM: rounding_up = roundin;
      // Any unsupported mode defaults to RTZ (no rounding).
      default: rounding_up = 1'b0;
    endcase
  end

  // Add one ULP when rounding up; capture the carry-out beyond WIDTH.
  logic [WIDTH:0] sum;
  assign sum = {1'b0, in_data} + {{WIDTH{1'b0}}, rounding_up};

  assign out_data = sum[WIDTH-1:0];
  assign inexact  = roundin | stickyin;
  assign cout     = sum[WIDTH];
  assign r_up     = rounding_up;

endmodule

module secure_read_write_register_bank #(
    parameter p_address_width = 8,
    parameter p_data_width    = 8,
    parameter p_unlock_code_0 = 8'hAB,
    parameter p_unlock_code_1 = 8'hCD
)(
    input  wire [p_address_width-1:0] i_addr,
    input  wire [p_data_width-1:0]    i_data_in,
    input  wire                       i_read_write_enable, // 0 = write, 1 = read
    input  wire                       i_capture_pulse,     // acts as clock
    input  wire                       i_rst_n,             // async active-low reset
    output reg  [p_data_width-1:0]    o_data_out
);

    localparam LOCKED    = 2'd0;
    localparam GOT_CODE0 = 2'd1;
    localparam UNLOCKED  = 2'd2;

    reg [1:0]               state;
    reg [p_data_width-1:0]  mem [0:(2**p_address_width)-1];

    // ---------------------------------------------------------------------
    // Unlock state machine.
    // The unlock sequence must be CONSECUTIVE: code0 written to addr 0, then
    // code1 written to addr 1, with no intervening operation.  Any other
    // operation (a read, a write to another address, or a wrong-code write to
    // addr 0/1) breaks the partial match and returns to LOCKED.
    // ---------------------------------------------------------------------
    always @(posedge i_capture_pulse or negedge i_rst_n) begin
        if (!i_rst_n) begin
            state <= LOCKED;
        end else begin
            if (i_read_write_enable == 1'b0 && i_addr == 0) begin
                // Write to address 0
                state <= (i_data_in == p_unlock_code_0) ? GOT_CODE0 : LOCKED;
            end else if (i_read_write_enable == 1'b0 && i_addr == 1) begin
                // Write to address 1: completes the unlock only from GOT_CODE0
                state <= (state == GOT_CODE0 && i_data_in == p_unlock_code_1)
                         ? UNLOCKED : LOCKED;
            end else begin
                // Read, or write to any other address.
                // Once unlocked, the bank stays unlocked; a partial match resets.
                state <= (state == UNLOCKED) ? UNLOCKED : LOCKED;
            end
        end
    end

    // ---------------------------------------------------------------------
    // Register write.  Addresses 0 and 1 are always writable (they drive the
    // unlock mechanism).  All other addresses are writable only once unlocked.
    // ---------------------------------------------------------------------
    always @(posedge i_capture_pulse) begin
        if (i_read_write_enable == 1'b0) begin
            if (state == UNLOCKED || i_addr == 0 || i_addr == 1) begin
                mem[i_addr] <= i_data_in;
            end
        end
    end

    // ---------------------------------------------------------------------
    // Register read.  Outputs the stored value only on a read of a non-reserved
    // address while unlocked; otherwise drives 0 (also the default during writes
    // and while locked).  Addresses 0 and 1 are write-only and never readable.
    // ---------------------------------------------------------------------
    always @(posedge i_capture_pulse or negedge i_rst_n) begin
        if (!i_rst_n) begin
            o_data_out <= {p_data_width{1'b0}};
        end else if (i_read_write_enable == 1'b1 &&
                     state == UNLOCKED &&
                     i_addr != 0 && i_addr != 1) begin
            o_data_out <= mem[i_addr];
        end else begin
            o_data_out <= {p_data_width{1'b0}};
        end
    end

endmodule

module sipo_top#(parameter DATA_WIDTH = 16,                                   // Width of the shift register
                 parameter SHIFT_DIRECTION = 1,                               // Determines Left or right shift
                 parameter CODE_WIDTH = DATA_WIDTH + $clog2(DATA_WIDTH + 1),  // Encoded width
                 parameter CRC_WIDTH = DATA_WIDTH/2,                          // CRC width
                 parameter POLY = 8'b10101010                                 // CRC polynomial
                 ) (

   input clk,                                   // Clock input
   input reset_n,                               // Reset input
   input serial_in,                             // Serial input to SIPO
   input shift_en,                              // Shift enable
   input [CODE_WIDTH-1:0] received,             // Received encoded data
   input [CRC_WIDTH-1:0] received_crc,          // Received CRC
   output done,                                 // Done signal indicating completion of shift
   output [DATA_WIDTH-1:0] data_out,            // corrected output of ecc block
   output [CODE_WIDTH-1:0] encoded,             // Encoded output
   output error_detected,                       // Error detected flag
   output error_corrected,                      // Error corrected  flag
   output [CRC_WIDTH-1:0] crc_out,              // CRC generator output
   output crc_error                             // Mismatch between received_crc and crc_out

   );

wire [DATA_WIDTH-1:0] parallel_out;
wire [DATA_WIDTH-1:0] sipo_out_ecc_in;

serial_in_parallel_out_8bit  #(.WIDTH(DATA_WIDTH), .SHIFT_DIRECTION(SHIFT_DIRECTION)) uut_sipo (
        .clk           (clk),               // Clock input
        .reset_n       (reset_n),           // Reset input
        .sin           (serial_in),         // Serial input to SIPO
        .shift_en      (shift_en),          // Shift enable for SIPO
        .done          (done),              // Done signal from SIPO
        .parallel_out  (parallel_out)       // Parallel output from SIPO
    );

//assign sipo_out_ecc_in = (done)? parallel_out: {DATA_WIDTH{1'b0}};

onebit_ecc#(.DATA_WIDTH(DATA_WIDTH),.CODE_WIDTH(CODE_WIDTH)) uut_onebit_ecc1 (

    .data_in(parallel_out),
    .encoded(encoded),
    .received(received),
    .data_out(data_out),
    .error_detected(error_detected),
    .error_corrected(error_corrected)
    );

crc_generator #(.DATA_WIDTH(DATA_WIDTH), .CRC_WIDTH(CRC_WIDTH), .POLY(POLY)) uut_crc (
    .clk     (clk),
    .rst     (reset_n),
    .data_in (parallel_out),
    .crc_out (crc_out)
    );

assign crc_error = (crc_out != received_crc);

endmodule

module serial_in_parallel_out_8bit  #(
    parameter WIDTH = 64,               // Width of the shift register
    parameter SHIFT_DIRECTION = 1       // Determines if shifting
)(
    input clk,                          // Clock signal
    input reset_n,                      // Active low reset
    input sin,                          // Serial input
    input shift_en,                     // Shift enable signal
    output reg done,                    // Done signal indicating completion of shift
    output reg [WIDTH-1:0] parallel_out // Parallel output
);

    localparam COUNT_WIDTH = $clog2(WIDTH); // Calculate width for shift_count

    reg [COUNT_WIDTH:0] shift_count;        // Parameterized counter to track number of shifts


    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            parallel_out     <= {WIDTH{1'b0}};
            done             <= 1'b0;
            shift_count      <= {COUNT_WIDTH{1'b0}};
        end else begin
            if (shift_en) begin
                if (SHIFT_DIRECTION) begin
                    parallel_out    <= {parallel_out[WIDTH-2:0], sin};
                end else begin
                    parallel_out    <= {sin, parallel_out[WIDTH-1:1]};
                end
                shift_count   <= shift_count + 1;
            end

            if (shift_count == (WIDTH - 1)) begin
                done         <= 1'b1;
                shift_count  <= {COUNT_WIDTH{1'b0}};
            end else begin
                done         <= 1'b0;
            end
        end
    end
endmodule


module onebit_ecc #(
    parameter DATA_WIDTH = 4,                                  // Width of the data input
    parameter CODE_WIDTH = DATA_WIDTH + $clog2(DATA_WIDTH + 1) // Encoded width
)(
    input [DATA_WIDTH-1:0] data_in,                     // Input data
    output reg [CODE_WIDTH-1:0] encoded,                // Encoded output
    input [CODE_WIDTH-1:0] received,                    // Received encoded data
    output reg [DATA_WIDTH-1:0] data_out,               // Corrected output
    output reg error_detected,                          // Error detected flag
    output reg error_corrected                          // Error corrected flag
);

    localparam PARITY_BITS = CODE_WIDTH - DATA_WIDTH;   // Number of parity bits

    reg [PARITY_BITS-1:0] syndrome;                     // Syndrome for error detection
    reg [CODE_WIDTH-1:0] corrected_data;                // Corrected received data


    integer idx_i, idx_j, idx_k;
    integer idx_m, idx_n;
    integer idx_p, idx_q;


    always @(*) begin
        encoded = 0;
        idx_k = 0;


        for (idx_i = 0; idx_i < CODE_WIDTH; idx_i = idx_i + 1) begin
            if ((idx_i + 1) & (idx_i)) begin
                encoded[idx_i] = data_in[idx_k];
                idx_k = idx_k + 1;
            end
        end


        for (idx_i = 0; idx_i < PARITY_BITS; idx_i = idx_i + 1) begin
            encoded[(1 << idx_i) - 1] = 0;
            for (idx_j = 0; idx_j < CODE_WIDTH; idx_j = idx_j + 1) begin
                if (((idx_j + 1) & (1 << idx_i)) && ((idx_j + 1) != (1 << idx_i))) begin
                    encoded[(1 << idx_i) - 1] = encoded[(1 << idx_i) - 1] ^ encoded[idx_j];
                end
            end
        end
    end


    always @(*) begin
        syndrome = 0;
        for (idx_m = 0; idx_m < PARITY_BITS; idx_m = idx_m + 1) begin
            for (idx_n = 0; idx_n < CODE_WIDTH; idx_n = idx_n + 1) begin
                if ((idx_n + 1) & (1 << idx_m)) begin
                    syndrome[idx_m] = syndrome[idx_m] ^ received[idx_n];
                end
            end
        end
    end


    always @(*) begin
        error_detected = |syndrome;
    end


    always @(*) begin
        corrected_data = received;
        if (error_detected) begin
            corrected_data[syndrome - 1] = ~corrected_data[syndrome - 1];
        end
    end


    always @(*) begin
        idx_q = 0;
        for (idx_p = 0; idx_p < CODE_WIDTH; idx_p = idx_p + 1) begin
            if ((idx_p + 1) & (idx_p)) begin
                data_out[idx_q] = corrected_data[idx_p];
                idx_q = idx_q + 1;
            end
        end
    end


    always @(*) begin
        error_corrected = error_detected;
    end

endmodule


// CRC generator: serial polynomial-division CRC over data_in (MSB-first),
// computed combinationally and registered on clk with an active-low
// synchronous reset.  For DATA_WIDTH=16, POLY=0xAA, data_in=0x5123 the
// resulting crc_out is 0x42, matching the worked example.
module crc_generator #(
    parameter DATA_WIDTH = 16,
    parameter CRC_WIDTH  = DATA_WIDTH/2,
    parameter [CRC_WIDTH-1:0] POLY = 8'b10101010
)(
    input  wire                  clk,
    input  wire                  rst,       // active-low synchronous reset
    input  wire [DATA_WIDTH-1:0] data_in,
    output reg  [CRC_WIDTH-1:0]  crc_out
);

    integer i;
    reg [CRC_WIDTH-1:0] crc_reg;

    always @(*) begin
        crc_reg = {CRC_WIDTH{1'b0}};
        for (i = DATA_WIDTH-1; i >= 0; i = i - 1) begin
            if (crc_reg[CRC_WIDTH-1] ^ data_in[i])
                crc_reg = (crc_reg << 1) ^ POLY;
            else
                crc_reg = (crc_reg << 1);
        end
    end

    always @(posedge clk) begin
        if (!rst)
            crc_out <= {CRC_WIDTH{1'b0}};
        else
            crc_out <= crc_reg;
    end

endmodule

module spi_fsm (
    input  wire         i_clk,       // System clock
    input  wire         i_rst_b,     // Active-low async reset
    input  wire [15:0]  i_data_in,   // Parallel 16-bit data to transmit
    input  wire         i_enable,    // Enable block
    input  wire         i_fault,     // Fault indicator
    input  wire         i_clear,     // Forces FSM to clear/idle

    output reg          o_spi_cs_b,  // SPI chip select (active-low)
    output reg          o_spi_clk,   // SPI clock
    output reg          o_spi_data,  // Serialized SPI data out
    output reg [4:0]    o_bits_left, // Bits left to transmit
    output reg          o_done,      // Single-cycle pulse when done or error
    output reg [1:0]    o_fsm_state  // FSM state for external monitoring
);

    localparam IDLE     = 2'b00;
    localparam TRANSMIT = 2'b01;
    localparam TOGGLE   = 2'b10;
    localparam ERROR    = 2'b11;

    localparam [4:0] NUM_BITS = 5'h10; // 16 bits to transmit (default / safe value)

    reg [15:0] shift_reg;

    always @(posedge i_clk or negedge i_rst_b) begin
        if (!i_rst_b) begin
            // Asynchronous reset -> idle defaults.
            o_fsm_state <= IDLE;
            o_spi_cs_b  <= 1'b1;
            o_spi_clk   <= 1'b0;
            o_spi_data  <= 1'b0;
            o_bits_left <= NUM_BITS;
            o_done      <= 1'b0;
            shift_reg   <= 16'b0;
        end else begin
            // o_done is a single-cycle strobe -> default low every cycle.
            o_done <= 1'b0;

            if (i_fault) begin
                // Fault forces the Error state with safe defaults.
                // o_done pulses for one cycle only on entering Error.
                o_done      <= (o_fsm_state != ERROR) ? 1'b1 : 1'b0;
                o_fsm_state <= ERROR;
                o_spi_cs_b  <= 1'b1;
                o_spi_clk   <= 1'b0;
                o_spi_data  <= 1'b0;
                o_bits_left <= NUM_BITS;
            end else if (i_clear) begin
                // Clear forces idle from any state.
                o_fsm_state <= IDLE;
                o_spi_cs_b  <= 1'b1;
                o_spi_clk   <= 1'b0;
                o_spi_data  <= 1'b0;
                o_bits_left <= NUM_BITS;
            end else begin
                case (o_fsm_state)
                    IDLE: begin
                        o_spi_cs_b  <= 1'b1;
                        o_spi_clk   <= 1'b0;
                        o_spi_data  <= 1'b0;
                        o_bits_left <= NUM_BITS;
                        if (i_enable) begin
                            shift_reg   <= i_data_in;
                            o_fsm_state <= TRANSMIT;
                        end
                    end

                    TRANSMIT: begin
                        if (!i_enable) begin
                            o_fsm_state <= IDLE;
                            o_spi_cs_b  <= 1'b1;
                            o_spi_clk   <= 1'b0;
                            o_spi_data  <= 1'b0;
                            o_bits_left <= NUM_BITS;
                        end else begin
                            // Activate transfer, present current MSB, clk low.
                            o_spi_cs_b  <= 1'b0;
                            o_spi_clk   <= 1'b0;
                            o_spi_data  <= shift_reg[15];
                            o_fsm_state <= TOGGLE;
                        end
                    end

                    TOGGLE: begin
                        if (!i_enable) begin
                            o_fsm_state <= IDLE;
                            o_spi_cs_b  <= 1'b1;
                            o_spi_clk   <= 1'b0;
                            o_spi_data  <= 1'b0;
                            o_bits_left <= NUM_BITS;
                        end else begin
                            // Toggle the SPI clock high to latch the data bit.
                            o_spi_clk <= 1'b1;
                            if (o_bits_left == 5'd1) begin
                                // Last bit transmitted: complete the transaction.
                                o_done      <= 1'b1;
                                o_bits_left <= NUM_BITS;
                                o_spi_cs_b  <= 1'b1;
                                o_spi_clk   <= 1'b0;
                                o_fsm_state <= IDLE;
                            end else begin
                                // Decrement, shift to next bit, continue.
                                o_bits_left <= o_bits_left - 1'b1;
                                shift_reg   <= {shift_reg[14:0], 1'b0};
                                o_fsm_state <= TRANSMIT;
                            end
                        end
                    end

                    ERROR: begin
                        // Hold safe outputs until cleared or reset.
                        o_spi_cs_b  <= 1'b1;
                        o_spi_clk   <= 1'b0;
                        o_spi_data  <= 1'b0;
                        o_bits_left <= NUM_BITS;
                        o_done      <= 1'b0;
                    end

                    default: begin
                        o_fsm_state <= IDLE;
                    end
                endcase
            end
        end
    end

endmodule

module pipelined_skid_buffer(
    input wire clock,
    input wire rst,

    input wire [3:0] data_i,
    input wire valid_i,
    output wire ready_o,
    output wire valid_o,
    output wire [3:0] data_o,
    input wire ready_i

    );

    // Pipeline:  skid_0 -> reg1 -> skid_2 -> reg3
    // data flows forward, ready flows backward.
    wire [3:0] data_s0_r1, data_r1_s2, data_s2_r3;
    wire       valid_s0_r1, valid_r1_s2, valid_s2_r3;
    wire       ready_r1_s0, ready_s2_r1, ready_r3_s2;

    skid_buffer skid_0 (
        .clk     (clock),
        .reset   (rst),
        .i_data  (data_i),
        .i_valid (valid_i),
        .o_ready (ready_o),
        .o_data  (data_s0_r1),
        .o_valid (valid_s0_r1),
        .i_ready (ready_r1_s0)
    );

    register reg1 (
        .clk       (clock),
        .rst       (rst),
        .data_in   (data_s0_r1),
        .valid_in  (valid_s0_r1),
        .ready_out (ready_r1_s0),
        .valid_out (valid_r1_s2),
        .data_out  (data_r1_s2),
        .ready_in  (ready_s2_r1)
    );

    skid_buffer skid_2 (
        .clk     (clock),
        .reset   (rst),
        .i_data  (data_r1_s2),
        .i_valid (valid_r1_s2),
        .o_ready (ready_s2_r1),
        .o_data  (data_s2_r3),
        .o_valid (valid_s2_r3),
        .i_ready (ready_r3_s2)
    );

    register reg3 (
        .clk       (clock),
        .rst       (rst),
        .data_in   (data_s2_r3),
        .valid_in  (valid_s2_r3),
        .ready_out (ready_r3_s2),
        .valid_out (valid_o),
        .data_out  (data_o),
        .ready_in  (ready_i)
    );

endmodule

module register(
    input clk,
    input rst,

    input [3:0] data_in,
    input valid_in,
    output ready_out,
    output valid_out,
    output [3:0] data_out,
    input  ready_in
    );

    reg [3:0] mem;
    reg       data_present;

    // Can accept new data when empty, or when the downstream is taking the
    // currently-held data this cycle.
    assign ready_out = ~data_present | ready_in;
    assign valid_out = data_present;
    assign data_out  = mem;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            mem          <= 4'b0;
            data_present <= 1'b0;
        end else if (ready_out) begin
            data_present <= valid_in;
            if (valid_in)
                mem <= data_in;
        end
    end

endmodule


module skid_buffer(

input  clk,
input  reset ,

input  [3:0]i_data,
input  i_valid,
output o_ready,

output [3:0]o_data,
output o_valid,
input  i_ready

);

    reg [3:0] data_reg;
    reg       buffer;      // 1 when data_reg holds a skidded value

    // Accept new input only when the skid register is empty.
    assign o_ready = ~buffer;
    // Output is valid when skidding, or pass the incoming data straight through.
    assign o_valid = buffer | i_valid;
    assign o_data  = buffer ? data_reg : i_data;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            data_reg <= 4'b0;
            buffer   <= 1'b0;
        end else begin
            if (~buffer) begin
                // Forwarding incoming data; if downstream is not ready but the
                // data is valid, capture it so nothing is lost.
                if (i_valid & ~i_ready) begin
                    data_reg <= i_data;
                    buffer   <= 1'b1;
                end
            end else begin
                // Holding skidded data; release it once downstream is ready.
                if (i_ready)
                    buffer <= 1'b0;
            end
        end
    end

endmodule

module sorting_engine #(
    parameter N = 8,             // Number of elements to sort
    parameter WIDTH = 8          // Bit-width of each element
)(
    input  wire                clk,
    input  wire                rst,
    input  wire                start,
    input  wire [N*WIDTH-1:0]  in_data,
    output reg                 done,
    output reg [N*WIDTH-1:0]   out_data
);

    // Internal registers to hold the array
    reg [WIDTH-1:0] array [0:N-1];

    // FSM states
    localparam IDLE    = 3'd0;
    localparam READ    = 3'd1;   // access the element to be sorted
    localparam SHIFT   = 3'd2;   // shift larger sorted elements up (1 cycle each),
                                 // last (condition-false) cycle detects completion
    localparam INSERT  = 3'd3;   // place the element in its found spot
    localparam ALLDONE = 3'd4;   // detect that all elements are sorted
    localparam DONE    = 3'd5;   // output the sorted array and assert done

    reg [2:0] state, next_state;

    // Insertion-sort indexing
    reg [$clog2(N)-1:0] i;   // index of the element being inserted (1 .. N-1)
    reg [$clog2(N)-1:0] j;   // current insertion position
    reg [WIDTH-1:0]     key; // the element value being inserted

    integer k, m;

    // FSM: Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (start)
                    next_state = READ;
            end
            READ: begin
                next_state = SHIFT;
            end
            SHIFT: begin
                // Keep shifting while the previous sorted element is larger.
                if ((j > 0) && (array[j-1] > key))
                    next_state = SHIFT;
                else
                    next_state = INSERT;
            end
            INSERT: begin
                if (i == (N-1))
                    next_state = ALLDONE;
                else
                    next_state = READ;
            end
            ALLDONE: begin
                next_state = DONE;
            end
            DONE: begin
                next_state = IDLE;
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

    // FSM: Output and datapath updates
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            i <= 0;
            j <= 0;
            done <= 0;
        end else begin
            state <= next_state;

            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        // Set up start conditions: load the array, begin at element 1
                        // (element 0 is trivially the start of the sorted region).
                        for (k = 0; k < N; k = k + 1) begin
                            array[k] <= in_data[(k+1)*WIDTH-1 -: WIDTH];
                        end
                        i <= 1;
                        j <= 0;
                    end
                end

                READ: begin
                    // Access the element to be sorted.
                    key <= array[i];
                    j   <= i;
                end

                SHIFT: begin
                    // One shift per cycle until the correct spot is found.
                    if ((j > 0) && (array[j-1] > key)) begin
                        array[j] <= array[j-1];
                        j        <= j - 1;
                    end
                end

                INSERT: begin
                    // Insert the element at the found spot.
                    array[j] <= key;
                    if (i != (N-1))
                        i <= i + 1;
                end

                ALLDONE: begin
                    // Detect that all elements are sorted (one cycle).
                end

                DONE: begin
                    // Output the sorted data and assert done.
                    done <= 1;
                    for (m = 0; m < N; m = m + 1) begin
                        out_data[(m+1)*WIDTH-1 -: WIDTH] <= array[m];
                    end
                end

                default: begin
                end
            endcase
        end
    end


  // power-up determinism (rtl_hygiene_lint --fix): reset-less registered
  // outputs default to 0 so they are not X at t=0.
  initial begin
    out_data = 0;
  end

endmodule

module sorting_engine #(
    parameter N = 8,          // number of elements to sort
    parameter WIDTH = 8       // bit-width of each element
)(
    input  wire                clk,
    input  wire                rst,
    input  wire                start,
    input  wire [N*WIDTH-1:0]  in_data,
    output reg                 done,
    output reg [N*WIDTH-1:0]   out_data
);

    //-----------------------------------------------------
    // State machine definitions
    //-----------------------------------------------------
    localparam [3:0]
        S_IDLE         = 4'd0,
        S_LOAD_INPUT   = 4'd1,
        S_FIND_MAX     = 4'd2,
        S_COUNT        = 4'd3,
        S_PREFIX_SUM   = 4'd4,
        S_BUILD_OUTPUT = 4'd5,
        S_COPY_OUTPUT  = 4'd6,
        S_DONE         = 4'd7;

    //-----------------------------------------------------
    // Registered signals (updated in sequential always)
    //-----------------------------------------------------
    reg [3:0]           current_state;
    reg [WIDTH-1:0]     data_array [0:N-1];
    reg [WIDTH-1:0]     out_array  [0:N-1];
    reg [$clog2(N):0]   count_array[0:(1<<WIDTH)-1];

    reg [WIDTH-1:0]     max_val;
    reg [$clog2(N):0]   load_cnt;
    reg [$clog2(N):0]   find_cnt;
    reg [$clog2(N):0]   count_cnt;
    reg [WIDTH-1:0]     prefix_cnt;
    reg [$clog2(N):0]   build_cnt;
    reg [$clog2(N):0]   copy_cnt;

    //-----------------------------------------------------
    // Wires/reg for "next" values (computed combinationally)
    //-----------------------------------------------------
    reg [3:0]           next_state;

    // Arrays get "shadow copies" for combinational updates
    reg [WIDTH-1:0]     next_data_array [0:N-1];
    reg [WIDTH-1:0]     next_out_array  [0:N-1];
    reg [$clog2(N):0]   next_count_array[0:(1<<WIDTH)-1];

    reg [WIDTH-1:0]     next_max_val;
    reg [$clog2(N):0]   next_load_cnt;
    reg [$clog2(N):0]   next_find_cnt;
    reg [$clog2(N):0]   next_count_cnt;
    reg [WIDTH-1:0]     next_prefix_cnt;
    reg [$clog2(N):0]   next_build_cnt;
    reg [$clog2(N):0]   next_copy_cnt;

    reg                 next_done;
    reg [N*WIDTH-1:0]   next_out_data;
    integer rev_idx;
    reg [WIDTH-1:0] val;
    reg [$clog2(N):0] pos;

    integer i;
    always @(*) begin
    // Insert code here to implement the combinational logic for the FSM of the Counting sort algorithm.

        // Default: hold all registered values.
        next_state      = current_state;
        next_max_val    = max_val;
        next_load_cnt   = load_cnt;
        next_find_cnt   = find_cnt;
        next_count_cnt  = count_cnt;
        next_prefix_cnt = prefix_cnt;
        next_build_cnt  = build_cnt;
        next_copy_cnt   = copy_cnt;
        next_done       = 1'b0;
        next_out_data   = out_data;

        for (i = 0; i < N; i = i + 1) begin
            next_data_array[i] = data_array[i];
            next_out_array[i]  = out_array[i];
        end
        for (i = 0; i < (1<<WIDTH); i = i + 1) begin
            next_count_array[i] = count_array[i];
        end

        // Combinational temporaries.
        val     = {WIDTH{1'b0}};
        pos     = {($clog2(N)+1){1'b0}};
        rev_idx = 0;

        case (current_state)
            //-------------------------------------------------
            // IDLE : wait for a start pulse, clear counters.
            //-------------------------------------------------
            S_IDLE: begin
                next_done       = 1'b0;
                next_load_cnt   = 0;
                next_find_cnt   = 0;
                next_count_cnt  = 0;
                next_prefix_cnt = 0;
                next_build_cnt  = 0;
                next_copy_cnt   = 0;
                if (start)
                    next_state = S_LOAD_INPUT;
            end

            //-------------------------------------------------
            // LOAD : one element per cycle, then a transition.
            //-------------------------------------------------
            S_LOAD_INPUT: begin
                if (load_cnt < N) begin
                    next_data_array[load_cnt] = in_data[load_cnt*WIDTH +: WIDTH];
                    next_load_cnt = load_cnt + 1'b1;
                end else begin
                    // transition cycle (+1)
                    next_max_val  = {WIDTH{1'b0}};
                    next_find_cnt = 0;
                    next_state    = S_FIND_MAX;
                end
            end

            //-------------------------------------------------
            // FIND_MAX : running maximum over the array.
            //-------------------------------------------------
            S_FIND_MAX: begin
                if (find_cnt < N) begin
                    if (data_array[find_cnt] > max_val)
                        next_max_val = data_array[find_cnt];
                    next_find_cnt = find_cnt + 1'b1;
                end else begin
                    // transition cycle (+1): clear the histogram
                    for (i = 0; i < (1<<WIDTH); i = i + 1)
                        next_count_array[i] = {($clog2(N)+1){1'b0}};
                    next_count_cnt = 0;
                    next_state     = S_COUNT;
                end
            end

            //-------------------------------------------------
            // COUNT : build the frequency histogram.
            //-------------------------------------------------
            S_COUNT: begin
                if (count_cnt < N) begin
                    val = data_array[count_cnt];
                    next_count_array[val] = count_array[val] + 1'b1;
                    next_count_cnt = count_cnt + 1'b1;
                end else begin
                    next_prefix_cnt = 0;
                    next_state      = S_PREFIX_SUM;
                end
            end

            //-------------------------------------------------
            // PREFIX_SUM : reverse cumulative histogram so the
            // largest value lands at index 0 (descending order),
            // one index per cycle for max_val cycles.
            //   count[k] = count[k] + count[k+1], k = max_val-1 .. 0
            //-------------------------------------------------
            S_PREFIX_SUM: begin
                if (prefix_cnt < max_val) begin
                    rev_idx = max_val - 1 - prefix_cnt;
                    next_count_array[rev_idx] = count_array[rev_idx] + count_array[rev_idx+1];
                    next_prefix_cnt = prefix_cnt + 1'b1;
                end else begin
                    next_build_cnt = 0;
                    next_state     = S_BUILD_OUTPUT;
                end
            end

            //-------------------------------------------------
            // BUILD_OUTPUT : place each value (iterate input from
            // the end so equal elements stay stable).
            //-------------------------------------------------
            S_BUILD_OUTPUT: begin
                if (build_cnt < N) begin
                    rev_idx = N - 1 - build_cnt;
                    val = data_array[rev_idx];
                    pos = count_array[val] - 1'b1;
                    next_out_array[pos]   = val;
                    next_count_array[val] = count_array[val] - 1'b1;
                    next_build_cnt = build_cnt + 1'b1;
                end else begin
                    next_copy_cnt = 0;
                    next_state    = S_COPY_OUTPUT;
                end
            end

            //-------------------------------------------------
            // COPY_OUTPUT : pack the unpacked array onto the bus,
            // and arm the done strobe for the terminal cycle.
            //-------------------------------------------------
            S_COPY_OUTPUT: begin
                for (i = 0; i < N; i = i + 1)
                    next_out_data[i*WIDTH +: WIDTH] = out_array[i];
                next_done  = 1'b1;
                next_state = S_DONE;
            end

            //-------------------------------------------------
            // DONE : done is high for this one cycle, then IDLE.
            //-------------------------------------------------
            S_DONE: begin
                next_done  = 1'b0;
                next_state = S_IDLE;
            end

            default: next_state = S_IDLE;
        endcase
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // synchronous reset
            current_state <= S_IDLE;
            done          <= 1'b0;
            out_data      <= {N*WIDTH{1'b0}};
            max_val       <= {WIDTH{1'b0}};

            load_cnt      <= 0;
            find_cnt      <= 0;
            count_cnt     <= 0;
            prefix_cnt    <= 0;
            build_cnt     <= 0;
            copy_cnt      <= 0;

            // Clear arrays
            for (i = 0; i < N; i = i + 1) begin
                data_array[i] <= {WIDTH{1'b0}};
                out_array[i]  <= {WIDTH{1'b0}};
            end
            for (i = 0; i < (1<<WIDTH); i = i + 1) begin
                count_array[i] <= {($clog2(N)+1){1'b0}};
            end

        end else begin
        // Insert code here to implement the sequential logic for the FSM of the Counting sort algorithm.
            current_state <= next_state;
            done          <= next_done;
            out_data      <= next_out_data;
            max_val       <= next_max_val;

            load_cnt      <= next_load_cnt;
            find_cnt      <= next_find_cnt;
            count_cnt     <= next_count_cnt;
            prefix_cnt    <= next_prefix_cnt;
            build_cnt     <= next_build_cnt;
            copy_cnt      <= next_copy_cnt;

            for (i = 0; i < N; i = i + 1) begin
                data_array[i] <= next_data_array[i];
                out_array[i]  <= next_out_array[i];
            end
            for (i = 0; i < (1<<WIDTH); i = i + 1) begin
                count_array[i] <= next_count_array[i];
            end
        end
    end

endmodule

module sorting_engine #(
    parameter N = 8,             // Number of elements to sort
    parameter WIDTH = 8          // Bit-width of each element
)(
    input  wire                clk,
    input  wire                rst,
    input  wire                start,
    input  wire [N*WIDTH-1:0]  in_data,
    output reg                 done,
    output reg [N*WIDTH-1:0]   out_data
);

    //-------------------------------------------------
    // Local Parameters & Functions
    //-------------------------------------------------
    localparam IDLE  = 0;
    localparam SORT  = 1;
    localparam MERGE = 2;
    localparam DONE  = 3;

    // Function to compute ceil(log2(value)) at compile time
    function integer clog2;
        input integer value;
        integer i;
        begin
            clog2 = 0;
            for (i = 1; i < value; i = i << 1) begin
                clog2 = clog2 + 1;
            end
        end
    endfunction

    // Indices/counters only ever reach < 2*N, so clog2(N)+1 bits suffice.
    // (Original used clog2(4*N)+1, two bits wider than necessary.)
    localparam ADDR_WIDTH = clog2(N) + 1;

    //-------------------------------------------------
    // Internal Signals
    //-------------------------------------------------
    reg [1:0]                 state; // Four states: IDLE..DONE

    // Internal memory of N elements
    reg [WIDTH-1:0]           data_mem [0:N-1];

    // Indices and counters
    reg [ADDR_WIDTH-1:0]      base_idx;
    reg [ADDR_WIDTH-1:0]      left_idx;
    reg [ADDR_WIDTH-1:0]      right_idx;
    reg [ADDR_WIDTH-1:0]      merge_idx;
    reg [ADDR_WIDTH-1:0]      subarray_size;

    // Shadow buffer kept in sync with data_mem; the merge writes the picked
    // element at its ABSOLUTE position, so the write-back is a straight copy.
    reg [WIDTH-1:0]           tmp_merge [0:N-1];

    // Temporary registers for current left/right values
    reg [WIDTH-1:0]           left_val;
    reg [WIDTH-1:0]           right_val;

    integer i, k;
    integer left_end, right_end;
    integer l_addr,    r_addr;

    //-------------------------------------------------
    // State Machine
    //-------------------------------------------------
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // Reset
            state         <= IDLE;
            done          <= 1'b0;
            out_data      <= {N*WIDTH{1'b0}};
            base_idx      <= 0;
            left_idx      <= 0;
            right_idx     <= 0;
            merge_idx     <= 0;
            subarray_size <= 1;
        end else begin
            case (state)

                //----------------------------------
                // IDLE: wait for start, then load
                // (LOAD state folded in to save 1 cycle of latency).
                //----------------------------------
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        for (i = 0; i < N; i = i + 1) begin
                            data_mem[i]  <= in_data[i*WIDTH +: WIDTH];
                            tmp_merge[i] <= in_data[i*WIDTH +: WIDTH];
                        end

                        // Initialize for sorting
                        base_idx      <= 0;
                        left_idx      <= 0;
                        right_idx     <= 0;
                        merge_idx     <= 0;
                        subarray_size <= 1;

                        state <= SORT;
                    end
                end

                //----------------------------------
                // SORT: Each pass merges sub-arrays of size subarray_size
                //----------------------------------
                SORT: begin
                    // If subarray_size is strictly greater than N, we've fully sorted
                    // (ensures we do a merge pass at subarray_size == N)
                    if (subarray_size >= N) begin
                        state <= DONE;
                    end else begin
                        // Prepare to merge pairs of sub-arrays
                        base_idx  <= 0;
                        merge_idx <= 0;
                        left_idx  <= 0;
                        right_idx <= 0;
                        state     <= MERGE;
                    end
                end

                //----------------------------------
                // MERGE: Merge one pair of sub-arrays
                //----------------------------------
                MERGE: begin
                    // Compare/pick smaller; write at ABSOLUTE position
                    // (base_idx + merge_idx) into the shadow buffer.
                    if ((l_addr <= left_end) && (r_addr <= right_end)) begin
                        if (left_val <= right_val) begin
                            tmp_merge[base_idx + merge_idx] <= left_val;
                            left_idx <= left_idx + 1;
                        end else begin
                            tmp_merge[base_idx + merge_idx] <= right_val;
                            right_idx <= right_idx + 1;
                        end
                        merge_idx <= merge_idx + 1;
                    end
                    else if (l_addr <= left_end) begin
                        // Only left sub-array has data
                        tmp_merge[base_idx + merge_idx] <= left_val;
                        left_idx <= left_idx + 1;
                        merge_idx <= merge_idx + 1;
                    end
                    else if (r_addr <= right_end) begin
                        // Only right sub-array has data
                        tmp_merge[base_idx + merge_idx] <= right_val;
                        right_idx <= right_idx + 1;
                        merge_idx <= merge_idx + 1;
                    end
                    else begin
                        // Both sub-arrays exhausted => straight copy-back.
                        // tmp_merge is kept synced to data_mem everywhere except
                        // the just-merged region, so a fixed-index copy (no
                        // base-offset adder/mux network) is functionally exact.
                        for (k = 0; k < N; k = k + 1) begin
                            data_mem[k] <= tmp_merge[k];
                        end

                        // Move base_idx to next pair of sub-arrays
                        base_idx  <= base_idx + (subarray_size << 1);
                        left_idx  <= 0;
                        right_idx <= 0;
                        merge_idx <= 0;

                        // If we merged all pairs in this pass, double subarray_size
                        if ((base_idx + (subarray_size << 1)) >= N) begin
                            subarray_size <= subarray_size << 1;
                            state         <= SORT;
                        end
                    end
                end

                //----------------------------------
                // DONE: Output the fully sorted array
                //----------------------------------
                DONE: begin
                    for (i = 0; i < N; i = i + 1) begin
                        out_data[i*WIDTH +: WIDTH] <= data_mem[i];
                    end
                    done  <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

always @ (*) begin
    if(state == MERGE) begin
        left_end  = base_idx + subarray_size - 1;
        right_end = base_idx + (subarray_size << 1) - 1;

        // Boundaries of left and right sub-arrays
        if (left_end >= N) left_end = N - 1;
        if (right_end >= N) right_end = N - 1;

        // Calculate addresses
        l_addr = base_idx + left_idx;
        r_addr = base_idx + subarray_size + right_idx;

        // Safe read for left_val
        if ((l_addr <= left_end) && (l_addr < N))
            left_val = data_mem[l_addr];
        else
            left_val = {WIDTH{1'b1}};  // or '0' if you prefer

        // Safe read for right_val
        if ((r_addr <= right_end) && (r_addr < N))
            right_val = data_mem[r_addr];
        else
            right_val = {WIDTH{1'b1}};
    end else begin
        left_end = 0;
        right_end = 0;
        l_addr = 0;
        r_addr = 0;
        left_val = 0;
        right_val = 0;
    end
end

endmodule

module sprite_controller_fsm#(
   parameter MEM_ADDR_WIDTH = 16,
   parameter PIXEL_WIDTH = 24,
   parameter SPRITE_WIDTH = 16,
   parameter SPRITE_HEIGHT = 16,
   parameter WAIT_WIDTH    = 4,
   parameter N_ROM         = 256
)(
   input  logic clk,
   input  logic rst_n,
   input  logic [WAIT_WIDTH-1:0] i_wait,
   output logic rw,
   output logic [MEM_ADDR_WIDTH-1:0] write_addr,
   output logic [PIXEL_WIDTH-1:0] write_data,
   output logic [SPRITE_WIDTH-1:0] x_pos,
   output logic [SPRITE_HEIGHT-1:0] y_pos,
   input  logic [PIXEL_WIDTH-1:0] pixel_out,
   output logic done
);

 typedef enum logic [2:0] {
       IDLE,
       INIT_WRITE,
       WRITE,
       INIT_READ,
       READ,
       WAIT,
       DONE
   } state_t;

   state_t current_state, next_state;

   logic [MEM_ADDR_WIDTH-1:0] addr_counter;
   logic [PIXEL_WIDTH-1:0] data_counter;
   logic [WAIT_WIDTH-1:0] wait_counter;

  // Insert the FSM code here

   //-------------------------------------------------------------
   // Next-state (combinational)
   //-------------------------------------------------------------
   always_comb begin
      next_state = current_state;
      case (current_state)
         IDLE       : next_state = INIT_WRITE;
         INIT_WRITE : next_state = WRITE;
         WRITE      : if (addr_counter == N_ROM - 1) next_state = INIT_READ;
                      else                           next_state = WRITE;
         INIT_READ  : next_state = READ;
         READ       : if (addr_counter == N_ROM - 1) next_state = WAIT;
                      else                           next_state = READ;
         WAIT       : if (wait_counter == i_wait)    next_state = DONE;
                      else                           next_state = WAIT;
         DONE       : next_state = IDLE;
         default    : next_state = IDLE;
      endcase
   end

   //-------------------------------------------------------------
   // State register + registered Moore outputs / datapath.
   // Outputs are registered (out <= f(state)) so a cycle-stepped
   // reference samples them in lockstep with the state.
   //-------------------------------------------------------------
   always_ff @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
         current_state <= IDLE;
         addr_counter  <= '0;
         data_counter  <= '0;
         wait_counter  <= '0;
         rw            <= 1'b0;
         write_addr    <= '0;
         write_data    <= '0;
         x_pos         <= '0;
         y_pos         <= '0;
         done          <= 1'b0;
      end else begin
         current_state <= next_state;

         case (current_state)
            //------------------------------------------------
            // IDLE : clear counters, read mode, done low.
            //------------------------------------------------
            IDLE: begin
               addr_counter <= '0;
               data_counter <= '0;
               wait_counter <= '0;
               rw           <= 1'b0;
               done         <= 1'b0;
            end

            //------------------------------------------------
            // INIT_WRITE : prepare write phase.
            //------------------------------------------------
            INIT_WRITE: begin
               addr_counter <= '0;
               write_data   <= 24'hFF0000;
               rw           <= 1'b1;
            end

            //------------------------------------------------
            // WRITE : sequential write of addr_counter/data_counter.
            //------------------------------------------------
            WRITE: begin
               rw         <= 1'b1;
               write_addr <= addr_counter;
               write_data <= data_counter;
               if (addr_counter != N_ROM - 1) begin
                  addr_counter <= addr_counter + 1'b1;
                  data_counter <= data_counter + 1'b1;
               end
            end

            //------------------------------------------------
            // INIT_READ : prepare read phase.
            //------------------------------------------------
            INIT_READ: begin
               addr_counter <= '0;
               rw           <= 1'b0;
            end

            //------------------------------------------------
            // READ : sequential read; derive x_pos/y_pos.
            //   x_pos = addr_counter % SPRITE_WIDTH  (low X_WIDTH bits)
            //   y_pos = addr_counter / SPRITE_WIDTH  (next Y_WIDTH bits)
            //------------------------------------------------
            READ: begin
               rw         <= 1'b0;
               write_addr <= addr_counter;
               x_pos      <= addr_counter % SPRITE_WIDTH;
               y_pos      <= addr_counter / SPRITE_WIDTH;
               if (addr_counter != N_ROM - 1)
                  addr_counter <= addr_counter + 1'b1;
            end

            //------------------------------------------------
            // WAIT : count until wait_counter == i_wait.
            //------------------------------------------------
            WAIT: begin
               if (wait_counter != i_wait)
                  wait_counter <= wait_counter + 1'b1;
            end

            //------------------------------------------------
            // DONE : assert done for one cycle.
            //------------------------------------------------
            DONE: begin
               done <= 1'b1;
            end

            default: ;
         endcase
      end
   end

endmodule

`timescale 1ns / 1ps

// Top-level integration of the synchronous serial communication link.
module sync_serial_communication_tx_rx(
    input         clk,          // System clock (50:50 duty)
    input         reset_n,      // Active-low asynchronous reset
    input  [2:0]  sel,          // Data-width select
    input  [63:0] data_in,      // Parallel data into the TX
    output [63:0] data_out,     // Reconstructed parallel data from the RX
    output        done          // High for one cycle when the RX result is stable
);

    // Internal link signals
    wire serial_out;            // Serialized data TX -> RX
    wire serial_clk;            // Gated serial clock TX -> RX
    wire tx_done;               // TX completion (unused at top level)

    // Transmitter
    tx_block u_tx (
        .clk        (clk),
        .reset_n    (reset_n),
        .data_in    (data_in),
        .sel        (sel),
        .serial_out (serial_out),
        .done       (tx_done),
        .serial_clk (serial_clk)
    );

    // Receiver
    rx_block u_rx (
        .clk        (clk),
        .reset_n    (reset_n),
        .data_in    (serial_out),
        .serial_clk (serial_clk),
        .sel        (sel),
        .data_out   (data_out),
        .done       (done)
    );

endmodule

// ---------------------------------------------------------------------------
// Transmitter: serializes 8/16/32/64-bit data (LSB first) based on sel and
// emits a gated serial clock alongside the serial data.
// ---------------------------------------------------------------------------
module tx_block(
    input         clk,
    input         reset_n,
    input  [63:0] data_in,
    input  [2:0]  sel,
    output reg    serial_out,
    output reg    done,
    output        serial_clk
);

    reg [63:0] data_reg;        // Shift register holding the data being sent
    reg [6:0]  bit_count;       // Remaining bits to transmit
    reg [6:0]  reg_count;       // bit_count delayed by one cycle
    reg [6:0]  temp_reg_count;  // bit_count delayed by two cycles (clock gating)

    // Load on idle (done==1), otherwise shift out one bit per clock.
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            data_reg  <= 64'h0;
            bit_count <= 7'h0;
            reg_count <= 7'h0;
        end else begin
            if (done == 1'b1) begin
                case (sel)
                    3'b000:  begin data_reg <= 64'h0;                  bit_count <= 7'd0;  end
                    3'b001:  begin data_reg <= {56'h0, data_in[7:0]};  bit_count <= 7'd7;  end
                    3'b010:  begin data_reg <= {48'h0, data_in[15:0]}; bit_count <= 7'd15; end
                    3'b011:  begin data_reg <= {32'h0, data_in[31:0]}; bit_count <= 7'd31; end
                    3'b100:  begin data_reg <= data_in[63:0];          bit_count <= 7'd63; end
                    default: begin data_reg <= 64'h0;                  bit_count <= 7'h0;  end
                endcase
            end else if (bit_count > 7'h0) begin
                data_reg  <= data_reg >> 1;
                bit_count <= bit_count - 1'b1;
            end
            reg_count <= bit_count;
        end
    end

    // Serial clock is gated off when no data is being transmitted.
    assign serial_clk = clk & (temp_reg_count != 7'd0);

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) temp_reg_count <= 7'h0;
        else          temp_reg_count <= reg_count;
    end

    // Drive the serial data line with the LSB of the shift register.
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n)
            serial_out <= 1'b0;
        else if (reg_count > 7'h0 || bit_count > 7'h0)
            serial_out <= data_reg[0];
    end

    // done is high while idle (bit_count == 0) and low during transmission.
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n)
            done <= 1'b0;
        else if (bit_count == 7'h0)
            done <= 1'b1;
        else
            done <= 1'b0;
    end

endmodule

// ---------------------------------------------------------------------------
// Receiver: samples serial data on serial_clk, reconstructs the parallel word
// based on sel, and pulses done when the result is stable.
// ---------------------------------------------------------------------------
module rx_block(
    input  wire        clk,
    input  wire        reset_n,
    input  wire        data_in,     // Serial input
    input  wire        serial_clk,  // Sampling clock from the TX
    input  wire [2:0]  sel,
    output reg         done,
    output reg [63:0]  data_out
);

    reg [63:0] data_reg;   // Accumulated received bits (LSB first)
    reg [7:0]  bit_count;  // Number of bits captured
    reg [7:0]  count;      // clk-domain counter tracking reception progress

    // Capture serial data on each serial_clk edge.
    always @(posedge serial_clk or negedge reset_n) begin
        if (!reset_n) begin
            data_reg  <= 64'h0;
            bit_count <= 8'd0;
        end else if (done == 1'b1) begin
            bit_count <= 8'd0;
            data_reg  <= 64'h0;
        end else begin
            data_reg[bit_count] <= data_in;
            bit_count           <= bit_count + 1'b1;
        end
    end

    // Detect completion and reconstruct the parallel output.
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            count    <= 8'd0;
            done     <= 1'b0;
            data_out <= 64'h0;
        end else if (count >= bit_count && count != 8'd0) begin
            done <= 1'b1;
            case (sel)
                3'b000:  data_out <= 64'h0;
                3'b001:  data_out <= {56'h0, data_reg[7:0]};
                3'b010:  data_out <= {48'h0, data_reg[15:0]};
                3'b011:  data_out <= {32'h0, data_reg[31:0]};
                3'b100:  data_out <= data_reg;
                default: data_out <= 64'h0;
            endcase
        end else if (bit_count > 8'd0) begin
            count <= count + 1'b1;
            done  <= 1'b0;
        end else begin
            count <= 8'd0;
            done  <= 1'b0;
        end
    end

endmodule

`timescale 1ns / 1ps
module sync_serial_communication_tx_rx(
    input clk,                     // Clock signal
    input reset_n,                 // Active low reset signal
    input [2:0] sel,               // Selection signal for TX block
    input [63:0] data_in,          // 64-bit data input for TX block
    output [63:0] data_out,        // 64-bit data output from RX block
    output done                    // Done signal indicating completion
);

// Internal signals
wire tx_out;                       // Serial data output from TX block
wire tx_done;                      // Done signal from TX block
wire serial_clk_in;                // Serial clock generated by TX block

// Instantiate the TX block
tx_block uut_tx_block (
    .clk(clk),
    .reset_n(reset_n),
    .data_in(data_in),
    .sel(sel),
    .serial_out(tx_out),
    .done(tx_done),
    .serial_clk(serial_clk_in)
);

// Instantiate the RX block
rx_block uut_rx_block (
    .clk(clk),
    .serial_clk(serial_clk_in),
    .reset_n(reset_n),
    .sel(sel),
    .data_in(tx_out),
    .data_out(data_out),
    .done(done)
);

endmodule

///// tx_block
// Area-optimized transmitter.
//  * The two 7-bit shadow counters (reg_count, temp_reg_count) that the original
//    used only to gate the serial clock and the serial-out enable are replaced by
//    two 1-bit activity flags (active_d1/active_d2) - a real ~12 flip-flop saving
//    plus the elimination of two 7-bit next-state networks and two 7-bit
//    comparators, which survives synthesis.
//  * The four separate always blocks (state, temp_reg_count, serial_out, done) are
//    folded into a single clocked process, keeping the exact same cycle behaviour.
module tx_block(
    input clk,
    input reset_n,
    input [63:0] data_in,
    input [2:0] sel,
    output reg serial_out,
    output reg done,
    output serial_clk
);

reg [63:0] data_reg;        // Data being shifted out
reg [6:0]  bit_count;       // Remaining bits to transmit
reg        active_d1;       // (bit_count != 0) delayed one cycle  (was reg_count > 0)
reg        active_d2;       // delayed two cycles, gates serial_clk (was temp_reg_count > 0)

always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
        data_reg   <= 64'h0;
        bit_count  <= 7'h0;
        active_d1  <= 1'b0;
        active_d2  <= 1'b0;
        serial_out <= 1'b0;
        done       <= 1'b0;
    end else begin
        // Load a new word when idle, otherwise shift one bit per clock.
        if (done == 1'b1) begin
            case (sel)
                3'b000:  begin data_reg <= 64'h0;                  bit_count <= 7'd0;  end
                3'b001:  begin data_reg <= {56'h0, data_in[7:0]};  bit_count <= 7'd7;  end
                3'b010:  begin data_reg <= {48'h0, data_in[15:0]}; bit_count <= 7'd15; end
                3'b011:  begin data_reg <= {32'h0, data_in[31:0]}; bit_count <= 7'd31; end
                3'b100:  begin data_reg <= data_in[63:0];          bit_count <= 7'd63; end
                default: begin data_reg <= 64'h0;                  bit_count <= 7'h0;  end
            endcase
        end else if (bit_count > 7'h0) begin
            data_reg  <= data_reg >> 1;
            bit_count <= bit_count - 1'b1;
        end

        // Activity pipeline (replaces the two wide shadow counters).
        active_d1 <= (bit_count != 7'h0);
        active_d2 <= active_d1;

        // Drive the serial line whenever data is in flight.
        if (active_d1 || bit_count > 7'h0)
            serial_out <= data_reg[0];

        // done is high while idle.
        done <= (bit_count == 7'h0);
    end
end

// Gated serial clock: identical timing to the original temp_reg_count gate.
assign serial_clk = clk && active_d2;

endmodule

///// rx_block
// Receiver - counters narrowed from 8 to 7 bits (the captured count never
// exceeds 64) to trim flip-flops and comparator width; behaviour unchanged.
module rx_block(
    input wire clk,
    input wire reset_n,
    input wire data_in,
    input wire serial_clk,
    input wire [2:0] sel,
    output reg done,
    output reg [63:0] data_out
);

    reg [63:0] data_reg;
    reg [6:0]  bit_count;
    reg [6:0]  count;

    // Capture serial data on each serial_clk edge.
    always @(posedge serial_clk or negedge reset_n) begin
        if (!reset_n) begin
            data_reg  <= 64'h0;
            bit_count <= 7'd0;
        end else begin
            if (done == 1'b1) begin
                bit_count <= 7'b0;
                data_reg  <= 64'h0;
            end
            else begin
                bit_count <= bit_count;
            end
            bit_count           <= bit_count + 1'b1;
            data_reg[bit_count] <= data_in;
        end
    end

    // Detect completion and present the reconstructed output.
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            count    <= 7'd0;
            done     <= 1'b0;
            data_out <= 64'h0;
        end
        else if (count >= bit_count && count != 7'd0) begin
            done <= 1'b1;
            case (sel)
                3'b000:  data_out <= 64'h0;
                3'b001:  data_out <= {56'h0, data_reg};
                3'b010:  data_out <= {48'h0, data_reg};
                3'b011:  data_out <= {32'h0, data_reg};
                3'b100:  data_out <= data_reg;
                default: data_out <= 64'h0;
            endcase
        end
        else if (bit_count > 7'd0) begin
            count <= count + 1'b1;
            done  <= 1'b0;
        end
        else begin
            count <= 7'd0;
            done  <= 1'b0;
        end
    end

endmodule

`timescale 1ns / 1ps

// Vending machine controller.
// Item selection -> coin insertion -> dispense -> change/return-money, with an
// FSM and one-cycle pulse outputs.  item_button and cancel are treated as toggle
// signals and act only on their rising edge.
module vending_machine (
    input  wire        clk,               // Rising-edge clock
    input  wire        rst,               // Asynchronous active-high reset
    input  wire        item_button,       // Toggle: start item selection (rising edge)
    input  wire [2:0]  item_selected,     // Item id (valid 3'b001..3'b100)
    input  wire [3:0]  coin_input,        // Inserted coin value (valid 1,2,5,10)
    input  wire        cancel,            // Toggle: cancel transaction (rising edge)
    output reg         dispense_item,     // One cycle when item dispensed
    output reg         return_change,     // One cycle when change returned
    output reg  [4:0]  item_price,        // Price of the selected item
    output reg  [4:0]  change_amount,     // Change to be returned
    output reg  [2:0]  dispense_item_id,  // Id of the item being dispensed
    output reg         error,             // One cycle on an invalid operation
    output reg         return_money       // One cycle when refunding inserted coins
);

    // FSM states
    localparam [2:0] IDLE               = 3'd0,
                     ITEM_SELECTION     = 3'd1,
                     PAYMENT_VALIDATION = 3'd2,
                     DISPENSING_ITEM    = 3'd3,
                     RETURN_CHANGE      = 3'd4,
                     RETURN_MONEY       = 3'd5;

    reg [2:0] state;
    reg [4:0] coins_accumulated;
    reg       item_button_d;   // previous sample for rising-edge detect
    reg       cancel_d;

    wire item_button_edge = item_button & ~item_button_d;
    wire cancel_edge      = cancel      & ~cancel_d;

    // Valid coin denominations: 1, 2, 5, 10
    wire coin_valid = (coin_input == 4'd1)  || (coin_input == 4'd2) ||
                      (coin_input == 4'd5)  || (coin_input == 4'd10);
    wire coin_present = (coin_input != 4'd0);

    // Valid item ids and their prices
    wire item_valid = (item_selected >= 3'b001) && (item_selected <= 3'b100);

    // State register + datapath
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state             <= IDLE;
            coins_accumulated <= 5'd0;
            item_price        <= 5'd0;
            change_amount     <= 5'd0;
            dispense_item_id  <= 3'd0;
            item_button_d     <= 1'b0;
            cancel_d          <= 1'b0;
        end else begin
            // Edge-detect sampling registers
            item_button_d <= item_button;
            cancel_d      <= cancel;

            case (state)
                IDLE: begin
                    if (item_button_edge) begin
                        state <= ITEM_SELECTION;
                    end else if (coin_present) begin
                        // Coins inserted without selecting an item -> error
                        state <= RETURN_MONEY;
                    end
                end

                ITEM_SELECTION: begin
                    if (cancel_edge) begin
                        state <= RETURN_MONEY;
                    end else if (item_valid) begin
                        dispense_item_id <= item_selected;
                        case (item_selected)
                            3'b001:  item_price <= 5'd5;
                            3'b010:  item_price <= 5'd10;
                            3'b011:  item_price <= 5'd15;
                            3'b100:  item_price <= 5'd20;
                            default: item_price <= 5'd0;
                        endcase
                        state <= PAYMENT_VALIDATION;
                    end else if (item_selected != 3'b000) begin
                        // Out-of-range item id -> error
                        state <= RETURN_MONEY;
                    end
                end

                PAYMENT_VALIDATION: begin
                    if (cancel_edge) begin
                        state <= RETURN_MONEY;
                    end else if (coin_present) begin
                        if (coin_valid) begin
                            coins_accumulated <= coins_accumulated + 5'(coin_input);
                            if ((coins_accumulated + coin_input) >= item_price)
                                state <= DISPENSING_ITEM;
                        end else begin
                            // Invalid coin value -> error
                            state <= RETURN_MONEY;
                        end
                    end
                end

                DISPENSING_ITEM: begin
                    if (coins_accumulated > item_price) begin
                        change_amount <= coins_accumulated - item_price;
                        state         <= RETURN_CHANGE;
                    end else begin
                        coins_accumulated <= 5'd0;
                        item_price        <= 5'd0;
                        state             <= IDLE;
                    end
                end

                RETURN_CHANGE: begin
                    coins_accumulated <= 5'd0;
                    item_price        <= 5'd0;
                    change_amount     <= 5'd0;
                    state             <= IDLE;
                end

                RETURN_MONEY: begin
                    coins_accumulated <= 5'd0;
                    item_price        <= 5'd0;
                    state             <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

    // Moore one-cycle pulse outputs decoded from the current state.
    always @(*) begin
        dispense_item = (state == DISPENSING_ITEM);
        return_change = (state == RETURN_CHANGE);
        return_money  = (state == RETURN_MONEY) && (coins_accumulated != 5'd0);
        error         = (state == RETURN_MONEY);
    end

endmodule

module virtual2physical_tlb #(parameter ADDR_WIDTH = 8, PAGE_WIDTH = 8, TLB_SIZE = 4, PAGE_TABLE_SIZE = 16) (
    input clk,
    input reset,
    input [ADDR_WIDTH-1:0] virtual_address,
    output [PAGE_WIDTH-1:0] physical_address,
    output hit, miss
);
    wire tlb_write_enable, flush, ready;
    wire [PAGE_WIDTH-1:0] page_table_entry;
    TLB #(.TLB_SIZE(TLB_SIZE), .ADDR_WIDTH(ADDR_WIDTH), .PAGE_WIDTH(PAGE_WIDTH)) tlb (
        .clk(clk),
        .reset(reset),
        .virtual_address(virtual_address),
        .tlb_write_enable(tlb_write_enable),
        .flush(flush),
        .page_table_entry(page_table_entry),
        .physical_address(physical_address),
        .hit(hit),
        .miss(miss)
    );

    PageTableHandler #(.ADDR_WIDTH(ADDR_WIDTH), .PAGE_WIDTH(PAGE_WIDTH), .PAGE_TABLE_SIZE(PAGE_TABLE_SIZE)) page_table_handler(
        .clk(clk),
        .reset(reset),
        .miss(miss),
        .virtual_page(virtual_address),
        .page_table_entry(page_table_entry),
        .ready(ready)
    );

    ControlUnit control_unit (
        .clk(clk),
        .reset(reset),
        .hit(hit),
        .miss(miss),
        .ready(ready),
        .tlb_write_enable(tlb_write_enable),
        .flush(flush)
    );
endmodule

module TLB #(parameter TLB_SIZE = 4, ADDR_WIDTH = 8, PAGE_WIDTH = 8) (
    input clk,
    input reset,
    input [ADDR_WIDTH-1:0] virtual_address,
    input tlb_write_enable,
    input flush,
    input [PAGE_WIDTH-1:0] page_table_entry,
    output reg [PAGE_WIDTH-1:0] physical_address,
    output reg hit,
    output reg miss
);
    // TLB Storage
    reg [ADDR_WIDTH-1:0] virtual_tags[TLB_SIZE-1:0];
    reg [PAGE_WIDTH-1:0] physical_pages[TLB_SIZE-1:0];
    reg [TLB_SIZE-1:0] valid_bits;
    reg [$clog2(TLB_SIZE)-1:0] replacement_index; // Index for the next replacement
    integer i;

    // Insert the logic here  to update TLB with a new page table entry using the replacement policy
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Invalidate every entry and reset the replacement pointer
            valid_bits        <= {TLB_SIZE{1'b0}};
            replacement_index <= {$clog2(TLB_SIZE){1'b0}};
            for (i = 0; i < TLB_SIZE; i = i + 1) begin
                virtual_tags[i]   <= {ADDR_WIDTH{1'b0}};
                physical_pages[i] <= {PAGE_WIDTH{1'b0}};
            end
        end else if (flush) begin
            // Flush: invalidate all entries
            valid_bits        <= {TLB_SIZE{1'b0}};
            replacement_index <= {$clog2(TLB_SIZE){1'b0}};
        end else if (tlb_write_enable) begin
            // Round-robin replacement of a new translation into the TLB
            virtual_tags[replacement_index]   <= virtual_address;
            physical_pages[replacement_index] <= page_table_entry;
            valid_bits[replacement_index]     <= 1'b1;
            replacement_index                 <= replacement_index + 1'b1;
        end
    end

    always_comb begin
        hit = 0;
        miss = 1;
        physical_address = 0;

        // Insert the logic here to check for a match in TLB
        for (i = 0; i < TLB_SIZE; i = i + 1) begin
            if (valid_bits[i] && (virtual_tags[i] == virtual_address)) begin
                hit              = 1'b1;
                miss             = 1'b0;
                physical_address = physical_pages[i];
            end
        end
    end
endmodule

module PageTableHandler #(parameter ADDR_WIDTH = 8, PAGE_WIDTH = 8, PAGE_TABLE_SIZE = 16) (
    input clk,
    input reset,
    input miss,
    input [ADDR_WIDTH-1:0] virtual_page,
    output reg [PAGE_WIDTH-1:0] page_table_entry,
    output reg ready
);
    // Parameterized Page Table Memory
    reg [PAGE_WIDTH-1:0] page_table_memory [0:PAGE_TABLE_SIZE-1];
 assign   page_table_entry = page_table_memory[virtual_page];
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Initialize Page Table Memory during reset
            page_table_memory[0] <= 8'h0;
            page_table_memory[1] <= 8'h1;
            page_table_memory[2] <= 8'h2;
            page_table_memory[3] <= 8'h3;
            page_table_memory[4] <= 8'h4;
            page_table_memory[5] <= 8'h5;
            page_table_memory[6] <= 8'h6;
            page_table_memory[7] <= 8'h7;
            page_table_memory[8] <= 8'h8;
            page_table_memory[9] <= 8'h9;
            page_table_memory[10] <= 8'hA;
            page_table_memory[11] <= 8'hB;
            page_table_memory[12] <= 8'hC;
            page_table_memory[13] <= 8'hD;
            page_table_memory[14] <= 8'hE;
            page_table_memory[15] <= 8'hF;
            ready = 0;
        end else if (miss) begin
            // Fetch the physical page number from the simulated page table
            ready <= 1; // Indicate the entry is ready
        end else begin
            ready <= 0;
        end
    end
endmodule
module ControlUnit (
    input clk,
    input reset,
    input hit,
    input miss,
    input ready,
    output reg tlb_write_enable,
    output reg flush
);
    reg [1:0] state;

    localparam IDLE = 2'b00,
               FETCH = 2'b01,
               UPDATE = 2'b10;

// Insert the logic for control unit here
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state            <= IDLE;
            tlb_write_enable <= 1'b0;
            flush            <= 1'b0;
        end else begin
            // Defaults each cycle
            tlb_write_enable <= 1'b0;
            flush            <= 1'b0;
            case (state)
                IDLE: begin
                    // On a TLB miss, start fetching the page-table entry
                    if (miss)
                        state <= FETCH;
                end
                FETCH: begin
                    // Wait for the page-table handler to be ready
                    if (ready)
                        state <= UPDATE;
                end
                UPDATE: begin
                    // Write the fetched entry into the TLB for one cycle
                    tlb_write_enable <= 1'b1;
                    state            <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end

endmodule

`timescale 1ns / 1ps

// Wishbone-to-AHB bridge.
// Translates a single Wishbone transfer into a single (hburst = SINGLE) AHB
// transfer, deriving the AHB size/address from sel_i, performing endian
// conversion on the data, and acknowledging the Wishbone master only once the
// AHB slave asserts hready.
module wishbone_to_ahb_bridge (
    // Wishbone (from WB master)
    input  wire        clk_i,
    input  wire        rst_i,     // Active-low reset
    input  wire        cyc_i,
    input  wire        stb_i,
    input  wire [3:0]  sel_i,
    input  wire        we_i,
    input  wire [31:0] addr_i,
    input  wire [31:0] data_i,
    output reg  [31:0] data_o,
    output reg         ack_o,
    // AHB (to AHB slave)
    input  wire        hclk,
    input  wire        hreset_n,  // Active-low reset
    input  wire [31:0] hrdata,
    input  wire [1:0]  hresp,
    input  wire        hready,
    output reg  [1:0]  htrans,
    output reg  [2:0]  hsize,
    output wire [2:0]  hburst,
    output reg         hwrite,
    output reg  [31:0] haddr,
    output reg  [31:0] hwdata
);

    // AHB transfer-type encodings
    localparam [1:0] HTRANS_IDLE   = 2'b00,
                     HTRANS_BUSY   = 2'b01,
                     HTRANS_NONSEQ = 2'b10;

    // Bridge FSM states
    localparam ST_IDLE  = 1'b0,
               ST_TRANS = 1'b1;

    reg state;

    // Only SINGLE bursts are supported.
    assign hburst = 3'b000;

    // Decode AHB size and sub-word address offset from the Wishbone byte enables.
    reg [2:0] size_sel;
    reg [1:0] off_sel;
    always @(*) begin
        case (sel_i)
            4'b1111: begin size_sel = 3'b010; off_sel = 2'b00; end // word
            4'b0011: begin size_sel = 3'b001; off_sel = 2'b00; end // halfword, low
            4'b1100: begin size_sel = 3'b001; off_sel = 2'b10; end // halfword, high
            4'b0001: begin size_sel = 3'b000; off_sel = 2'b00; end // byte 0
            4'b0010: begin size_sel = 3'b000; off_sel = 2'b01; end // byte 1
            4'b0100: begin size_sel = 3'b000; off_sel = 2'b10; end // byte 2
            4'b1000: begin size_sel = 3'b000; off_sel = 2'b11; end // byte 3
            default: begin size_sel = 3'b010; off_sel = 2'b00; end // default to word
        endcase
    end

    // Endian conversion (byte swap) between Wishbone and AHB.
    wire [31:0] data_i_swapped = {data_i[7:0],  data_i[15:8],  data_i[23:16],  data_i[31:24]};
    wire [31:0] hrdata_swapped = {hrdata[7:0],  hrdata[15:8],  hrdata[23:16],  hrdata[31:24]};

    // Combined active-low reset: either reset returns the bridge to defaults.
    wire rst_n = rst_i & hreset_n;

    always @(posedge clk_i or negedge rst_n) begin
        if (!rst_n) begin
            state  <= ST_IDLE;
            htrans <= HTRANS_IDLE;
            hsize  <= 3'b000;
            hwrite <= 1'b0;
            haddr  <= 32'h0;
            hwdata <= 32'h0;
            data_o <= 32'h0;
            ack_o  <= 1'b0;
        end else begin
            ack_o <= 1'b0;  // ack is a one-cycle strobe
            case (state)
                ST_IDLE: begin
                    if (cyc_i && stb_i) begin
                        // AHB address phase
                        htrans <= HTRANS_NONSEQ;
                        hwrite <= we_i;
                        hsize  <= size_sel;
                        haddr  <= {addr_i[31:2], off_sel};
                        state  <= ST_TRANS;
                    end else begin
                        htrans <= HTRANS_IDLE;
                    end
                end

                ST_TRANS: begin
                    // AHB data phase (single transfer: address phase complete)
                    htrans <= HTRANS_IDLE;
                    hwdata <= data_i_swapped;
                    if (hready) begin
                        if (!we_i)
                            data_o <= hrdata_swapped;  // capture read data
                        ack_o <= 1'b1;                 // acknowledge the WB master
                        state <= ST_IDLE;
                    end
                end

                default: state <= ST_IDLE;
            endcase
        end
    end

endmodule

module Word_Change_Pulse#(
    parameter DATA_WIDTH = 8 // Default word width
) (
    input  wire                  clk,               // Clock signal for synchronizing operations
    input  wire                  reset,             // Reset signal to initialize the module
    input  wire [DATA_WIDTH-1:0] data_in,           // Input data, width defined by parameter DATA_WIDTH
    input  wire [DATA_WIDTH-1:0] mask,              // Mask signal to enable/disable change detection for each bit
    input  wire [DATA_WIDTH-1:0] match_pattern,     // Pattern to match for generating the pulse
    input  wire                  enable,            // Enable signal to allow module operation
    input  wire                  latch_pattern,     // Signal to latch the match pattern
    output reg                   word_change_pulse, // Output signal indicating a change in any bit of data_in
    output reg                   pattern_match_pulse, // Output signal indicating a match with the pattern
    output reg [DATA_WIDTH-1:0]  latched_pattern    // Latched pattern for comparison
);

    wire [DATA_WIDTH-1:0] change_pulses;

    reg [DATA_WIDTH-1:0] masked_data_in;
    reg [DATA_WIDTH-1:0] masked_change_pulses;
    reg                  match_detected;

    genvar i;

    // Instantiate one Bit_Change_Detector per data bit.
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : gen_bit_change
            Bit_Change_Detector bcd_inst (
                .clk         (clk),
                .reset       (reset),
                .bit_in      (data_in[i]),
                .change_pulse(change_pulses[i])
            );
        end
    endgenerate

       always @(posedge clk or posedge reset) begin
        if (reset) begin
            masked_data_in <= {DATA_WIDTH{1'b0}};
            masked_change_pulses <= {DATA_WIDTH{1'b0}};
            word_change_pulse <= 1'b0;
            match_detected <= 1'b0;
            pattern_match_pulse <= 1'b0;
            latched_pattern <= {DATA_WIDTH{1'b0}};
        end else if (enable) begin
            // Latch the pattern when requested
            if (latch_pattern)
                latched_pattern <= match_pattern;

            // Mask data_in, detect changes, and generate the word-level change pulse
            masked_data_in       <= data_in & mask;
            masked_change_pulses <= change_pulses & mask;
            word_change_pulse    <= |(change_pulses & mask);

            // Compare masked data_in with the masked latched_pattern for a match pulse
            match_detected       <= ((data_in & mask) == (latched_pattern & mask));
            pattern_match_pulse  <= ((data_in & mask) == (latched_pattern & mask));
        end else begin
            // When disabled, hold the latched pattern but clear the pulse outputs
            masked_change_pulses <= {DATA_WIDTH{1'b0}};
            word_change_pulse    <= 1'b0;
            match_detected       <= 1'b0;
            pattern_match_pulse  <= 1'b0;
        end
    end

endmodule


// Bit_Change_Detector Module
module Bit_Change_Detector (
   input  wire clk,          // Clock signal
    input  wire reset,       // Reset signal to initialize the module
    input  wire bit_in,      // Single bit input to detect changes
    output reg  change_pulse // Pulse signal indicating a change in the input bit
);


    reg bit_in_d;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            bit_in_d <= 1'b0;   // Initialize the stored previous value
        end else begin
            bit_in_d <= bit_in; // Update the previous state
        end
    end

    always @(*) begin
        // Generate a pulse whenever the current bit differs from the stored value
        change_pulse = bit_in ^ bit_in_d;
    end
endmodule

// Parallel (multi-stream) run-length encoder. Each stream tracks the run length
// of consecutive identical bits independently, gated by stream_enable.
module parallel_run_length
#(
    parameter DATA_WIDTH  = 8,   // maximum run length per stream
    parameter NUM_STREAMS = 4    // number of parallel streams
)
(
    input  wire                         clk,
    input  wire                         reset_n,        // async active-low reset
    input  wire [NUM_STREAMS-1:0]       data_in,
    input  wire [NUM_STREAMS-1:0]       stream_enable,
    output wire [NUM_STREAMS-1:0]       data_out,
    output wire [(NUM_STREAMS*($clog2(DATA_WIDTH)+1))-1:0] run_value,
    output wire [NUM_STREAMS-1:0]       valid
);

    localparam W = $clog2(DATA_WIDTH) + 1;   // run-length counter width

    reg [W-1:0] run_length_arr [0:NUM_STREAMS-1];
    reg [W-1:0] run_value_arr  [0:NUM_STREAMS-1];
    reg         prev_arr       [0:NUM_STREAMS-1];
    reg         valid_arr      [0:NUM_STREAMS-1];
    reg         data_out_arr   [0:NUM_STREAMS-1];

    genvar i;
    generate
        for (i = 0; i < NUM_STREAMS; i = i + 1) begin : gen_stream

            // run-length counter / latched run value
            always @(posedge clk or negedge reset_n) begin
                if (!reset_n) begin
                    run_length_arr[i] <= {W{1'b0}};
                    run_value_arr[i]  <= {W{1'b0}};
                    prev_arr[i]       <= 1'b0;
                end else if (!stream_enable[i]) begin
                    // disabled stream: reset to defaults, resume fresh on re-enable
                    run_length_arr[i] <= {W{1'b0}};
                    run_value_arr[i]  <= {W{1'b0}};
                    prev_arr[i]       <= 1'b0;
                end else begin
                    if (data_in[i] == prev_arr[i]) begin
                        if (run_length_arr[i] == DATA_WIDTH)
                            run_value_arr[i] <= run_length_arr[i];
                        if (run_length_arr[i] < DATA_WIDTH)
                            run_length_arr[i] <= run_length_arr[i] + 1'b1;
                        else
                            run_length_arr[i] <= {{(W-1){1'b0}}, 1'b1};
                    end else begin
                        run_value_arr[i]  <= run_length_arr[i];
                        run_length_arr[i] <= {{(W-1){1'b0}}, 1'b1};
                    end
                    prev_arr[i] <= data_in[i];
                end
            end

            // valid / data_out generation
            always @(posedge clk or negedge reset_n) begin
                if (!reset_n) begin
                    valid_arr[i]    <= 1'b0;
                    data_out_arr[i] <= 1'b0;
                end else if (!stream_enable[i]) begin
                    valid_arr[i]    <= 1'b0;
                    data_out_arr[i] <= 1'b0;
                end else begin
                    if ((run_length_arr[i] == DATA_WIDTH) || (data_in[i] != prev_arr[i])) begin
                        valid_arr[i]    <= 1'b1;
                        data_out_arr[i] <= prev_arr[i];
                    end else begin
                        valid_arr[i]    <= 1'b0;
                        data_out_arr[i] <= 1'b0;
                    end
                end
            end

            // pack per-stream outputs into the flattened buses
            assign run_value[(i+1)*W-1 : i*W] = run_value_arr[i];
            assign valid[i]                   = valid_arr[i];
            assign data_out[i]                = data_out_arr[i];

        end
    endgenerate

endmodule

module lcm_3_ip #(
   parameter WIDTH = 4                    // Input bit-width
   )(
   input                         clk,
   input                         rst,
   input  [WIDTH-1:0]            A,
   input  [WIDTH-1:0]            B,
   input  [WIDTH-1:0]            C,
   input                         go,
   output logic  [3 * WIDTH-1:0] OUT,   // Updated output width
   output logic                  done
);

   logic [2*WIDTH-1:0]      gcd_result;     // GCD result
   logic [3*WIDTH-1:0]      product;        // Intermediate product
   logic                    gcd_done;
   logic                    product_ready;
   logic [2*WIDTH-1:0]      A_int;
   logic [2*WIDTH-1:0]      B_int;
   logic [2*WIDTH-1:0]      C_int;

   always_comb begin
      A_int = A*B;
      B_int = B*C;
      C_int = C*A;
   end

   // Calculate GCD of A, B, and C
   gcd_3_ip #(
      .WIDTH(2*WIDTH)
   ) gcd_inst (
      .clk   (clk),
      .rst   (rst),
      .A     (A_int),
      .B     (B_int),
      .C     (C_int),
      .go    (go),
      .OUT   (gcd_result),
      .done  (gcd_done)
   );

   // Sequential logic for LCM computation
   always_ff @(posedge clk) begin
      if (rst) begin
         OUT <= 0;
         done <= 0;
         product_ready <= 0;
      end else begin
         if (gcd_done) begin
            // Compute |A * B * C|
            product <= A * B * C;
            product_ready <= 1;
         end

         if (product_ready) begin
            // Compute LCM = |A * B * C| / GCD
            // Zero-extend gcd_result to the divisor width (value-preserving) so the
            // DIV operands share the 3*WIDTH width and no implicit expansion is needed.
            OUT <= product / {{WIDTH{1'b0}}, gcd_result};
            done <= 1;
            product_ready <= 0;
         end else begin
            done <= 0;
         end
      end
   end
endmodule

module gcd_3_ip #(
   parameter WIDTH = 4
   )(
   input                     clk,
   input                     rst,
   input  [WIDTH-1:0]        A,
   input  [WIDTH-1:0]        B,
   input  [WIDTH-1:0]        C,
   input                     go,
   output logic  [WIDTH-1:0] OUT,
   output logic              done
);

logic [WIDTH-1:0] gcd_ab;
logic [WIDTH-1:0] gcd_bc;
logic             go_abc;
logic             done_ab;
logic             done_bc;
logic             done_ab_latched;
logic             done_bc_latched;

// GCD is calculated for AB and BC in parallel. The GCD for two numbers is lower than the numbers themselves in most cases.
// And calculating GCD for smaller numbers is comparatively faster using the implemented algorithm.
// Hence in order to reduce GCD computation latency the calculation is broken up in this fashion.

gcd_top
#( .WIDTH(WIDTH)
) gcd_A_B_inst (
   .clk           (clk),
   .rst           (rst),
   .A             (A),
   .B             (B),
   .go            (go),
   .OUT           (gcd_ab),
   .done          (done_ab)
);

gcd_top
#( .WIDTH(WIDTH)
) gcd_B_C_inst (
   .clk           (clk),
   .rst           (rst),
   .A             (B),
   .B             (C),
   .go            (go),
   .OUT           (gcd_bc),
   .done          (done_bc)
);

gcd_top
#( .WIDTH(WIDTH)
) gcd_ABC_inst (
   .clk           (clk),
   .rst           (rst),
   .A             (gcd_ab),
   .B             (gcd_bc),
   .go            (go_abc),
   .OUT           (OUT),
   .done          (done)
);

always_ff @ (posedge clk) begin
   if (rst) begin
      done_ab_latched    <= 0;
      done_bc_latched    <= 0;
   end else begin
      if(done_ab) begin
         done_ab_latched <= done_ab;
      end else if (go_abc) begin
         done_ab_latched <= 0;
      end

      if(done_bc) begin
         done_bc_latched <= done_bc;
      end else if (go_abc) begin
         done_bc_latched <= 0;
      end
   end
end

assign go_abc = done_ab_latched & done_bc_latched;

endmodule

module gcd_top #(
   parameter WIDTH = 4              // Parameter to define the bit-width of the input and output data
   )(
   input                     clk,   // Clock signal
   input                     rst,   // Active High Synchronous reset signal
   input  [WIDTH-1:0]        A,     // Input operand A
   input  [WIDTH-1:0]        B,     // Input operand B
   input                     go,    // Start signal to begin GCD computation
   output logic  [WIDTH-1:0] OUT,   // Output for the GCD result
   output logic              done   // Signal to indicate completion of computation
);

   // Internal signals to communicate between control path and data path
   logic equal;                     // Signal indicating A == B
   logic greater_than;              // Signal indicating A > B
   logic [1:0] controlpath_state;   // Current state of the control FSM

   // Instantiate the control path module
   gcd_controlpath gcd_controlpath_inst (
      .clk               (clk),               // Connect clock signal
      .rst               (rst),               // Connect reset signal
      .go                (go),                // Connect go signal
      .equal             (equal),             // Connect equal signal from datapath
      .greater_than      (greater_than),      // Connect greater_than signal from datapath
      .controlpath_state (controlpath_state), // Output current state to datapath
      .done              (done)               // Output done signal
   );

   // Instantiate the data path module
   gcd_datapath
   #( .WIDTH(WIDTH)
   ) gcd_datapath_inst (
      .clk               (clk),               // Connect clock signal
      .rst               (rst),               // Connect reset signal
      .A                 (A),                 // Connect input A
      .B                 (B),                 // Connect input B
      .controlpath_state (controlpath_state), // Connect current state from control path
      .equal             (equal),             // Output equal signal to control path
      .greater_than      (greater_than),      // Output greater_than signal to control path
      .OUT               (OUT)                // Output GCD result
   );
endmodule


// Datapath module for GCD computation
module gcd_datapath  #(
   parameter WIDTH = 4                           // Bit-width of operands
   )(
   input                     clk,                // Clock signal
   input                     rst,                // Active High Synchronous reset
   input  [WIDTH-1:0]        A,                  // Input operand A
   input  [WIDTH-1:0]        B,                  // Input operand B
   input  [1:0]              controlpath_state,  // Current state from control path
   output logic              equal,              // Signal indicating A_ff == B_ff
   output logic              greater_than,       // Signal indicating A_ff > B_ff
   output logic  [WIDTH-1:0] OUT                 // Output GCD result
);

   // Registers to hold intermediate values of A and B
   logic [WIDTH-1:0] A_ff;
   logic [WIDTH-1:0] B_ff;

   // State encoding for control signals
   localparam S0 = 2'd0;    // State 0: Initialization state
   localparam S1 = 2'd1;    // State 1: Computation complete
   localparam S2 = 2'd2;    // State 2: A_ff > B_ff, subtract B_ff from A_ff
   localparam S3 = 2'd3;    // State 3: B_ff > A_ff, subtract A_ff from B_ff

   // Sequential logic to update registers based on controlpath_state
   always_ff @ (posedge clk) begin
      if (rst) begin
         // On reset, initialize registers to zero
         A_ff <= 'b0;
         B_ff <= 'b0;
         OUT  <= 'b0;
      end else begin
         case (controlpath_state)
            S0: begin
                // In state S0, load input values into registers
                A_ff <= A;
                B_ff <= B;
             end
            S1: begin
                // In state S1, computation is done, output the result
                OUT  <= A_ff;
             end
            S2: begin
                // In state S2, A_ff > B_ff, subtract B_ff from A_ff
                if (greater_than)
                   A_ff <= A_ff - B_ff;
             end
            S3: begin
                // In state S3, B_ff > A_ff, subtract A_ff from B_ff
                if (!equal & !greater_than)
                   B_ff <= B_ff - A_ff;
             end
            default: begin
                A_ff <= 'b0;
                B_ff <= 'b0;
                OUT <= 'b0;
            end
         endcase
      end
   end

   // Generating control response signals for the control path FSM
   always_comb begin
      case(controlpath_state)
         S0: begin
            // In state S0, compare initial input values A and B
            equal        = (A == B)? 1'b1 : 1'b0;
            greater_than = (A >  B)? 1'b1 : 1'b0;
          end
          default: begin
            // In other states, compare the current values in registers A_ff and B_ff
            equal        = (A_ff == B_ff)? 1'b1 : 1'b0;
            greater_than = (A_ff >  B_ff)? 1'b1 : 1'b0;
          end
      endcase
   end
endmodule

// Control path module for GCD computation FSM
module gcd_controlpath (
   input                    clk,               // Clock signal
   input                    rst,               // Active High Synchronous reset
   input                    go,                // Start GCD calculation signal
   input                    equal,             // From Datapath: A_ff equals B_ff
   input                    greater_than,      // From Datapath: A_ff is greater than B_ff
   output logic [1:0]       controlpath_state, // Current state to Datapath
   output logic             done               // Indicates completion of GCD calculation
);

   // Internal state registers
   logic [1:0] curr_state;  // Current state of FSM
   logic [1:0] next_state;  // Next state of FSM

   // State encoding
   localparam S0 = 2'd0;    // State 0: Initialization or waiting for 'go' signal
   localparam S1 = 2'd1;    // State 1: Computation complete
   localparam S2 = 2'd2;    // State 2: A_ff > B_ff
   localparam S3 = 2'd3;    // State 3: B_ff > A_ff

   // State latching logic: Update current state on clock edge
   always_ff @ (posedge clk) begin
      if (rst) begin
         curr_state   <= S0;   // On reset, set state to S0
      end else begin
         curr_state   <= next_state;   // Transition to next state
      end
   end

   // State transition logic: Determine next state based on current state and inputs
   always_comb begin
      case(curr_state)
         S0: begin
             // State S0: Waiting for 'go' signal
             if(!go)
                next_state = S0;         // Remain in S0 until 'go' is asserted
             else if (equal)
                next_state = S1;         // If A == B, computation is complete
             else if (greater_than)
                next_state = S2;         // If A > B, go to state S2
             else
                next_state = S3;         // If B > A, go to state S3
         end
         S1: begin
             // State S1: Computation complete, output the result
             next_state = S0;           // Return to S0 after completion
         end
         S2: begin
             // State S2: A_ff > B_ff, subtract B_ff from A_ff
             if(equal)
                next_state = S1;         // If A_ff == B_ff after subtraction, go to S1
             else if (greater_than)
                next_state = S2;         // If A_ff > B_ff, stay in S2
             else
                next_state = S3;         // If B_ff > A_ff, go to S3
         end
         S3: begin
             // State S3: B_ff > A_ff, subtract A_ff from B_ff
             if (equal)
                next_state = S1;         // If A_ff == B_ff after subtraction, go to S1
             else if (greater_than)
                next_state = S2;         // If A_ff > B_ff, go to S2
             else
                next_state = S3;         // If B_ff > A_ff, stay in S3
         end
         default: begin
             next_state = S0;
         end
      endcase
   end

   // Output logic: Generate 'done' signal when computation is complete
   always_ff @ (posedge clk) begin
     if(rst) begin
        done <= 1'b0;             // On reset, 'done' is low
     end else begin
        done <= (curr_state == S1); // 'done' is asserted when in state S1
     end
   end

   // Assign current state to output for datapath
   assign controlpath_state = curr_state;

endmodule

module inter_block #(
    parameter ROW_COL_WIDTH = 16,
    parameter SUB_BLOCKS    = 4,
    parameter DATA_WIDTH    = ROW_COL_WIDTH*ROW_COL_WIDTH
)(
    input  logic clk,
    input  logic rst_n,
    input  logic i_valid,
    input  logic [DATA_WIDTH-1:0] in_data, // Input: 256 bits
    output logic [DATA_WIDTH-1:0] out_data // Output: 256 bits rearranged
);

localparam CHUNK = 8;
localparam NBW_COUNTER = $clog2(SUB_BLOCKS) + 1;
localparam NBW_COUNTER_SUB_OUT = 2;
localparam OUT_CYCLES = 32;
logic [NBW_COUNTER-1:0] counter_sub_blocks;
logic [NBW_COUNTER_SUB_OUT-1:0] counter_sub_out;

logic [DATA_WIDTH-1:0] in_data_reg [SUB_BLOCKS-1:0];
logic [DATA_WIDTH-1:0] out_data_intra_block [SUB_BLOCKS-1:0];
logic [DATA_WIDTH-1:0] out_data_intra_block_reg [SUB_BLOCKS-1:0];
logic [DATA_WIDTH-1:0] out_data_aux [SUB_BLOCKS-1:0];
logic start_intra;

always_ff @(posedge clk or negedge rst_n ) begin
   if(!rst_n) begin
      counter_sub_blocks <= {NBW_COUNTER{1'b0}};
      start_intra <= 0;
      for(int i = 0; i < SUB_BLOCKS; i++) begin
         in_data_reg[i] <= {DATA_WIDTH{1'b0}};
      end
   end
   else begin
      if(i_valid) begin
         in_data_reg[counter_sub_blocks] <= in_data;

         if(counter_sub_blocks == SUB_BLOCKS) begin
            counter_sub_blocks <= {NBW_COUNTER{1'b0}};
         end
         else begin
            start_intra <= 0;
            counter_sub_blocks <= counter_sub_blocks + 1;
         end
      end
      else if(counter_sub_blocks == SUB_BLOCKS) begin
         start_intra        <= 1;
         counter_sub_blocks <= {NBW_COUNTER{1'b0}};
      end
   end
end

genvar k;
generate
   for(k = 0; k < SUB_BLOCKS; k++) begin
      intra_block uu_intra_block (
         .in_data(in_data_reg[k]),
         .out_data(out_data_intra_block[k])
      );
   end
endgenerate

always_ff @(posedge clk or negedge rst_n) begin
   if(!rst_n) begin
      for(int i = 0; i < SUB_BLOCKS; i++) begin
         out_data_intra_block_reg[i] <= {DATA_WIDTH{1'b0}};
      end
   end
   else begin
      if(start_intra) begin
         for(int i = 0; i < SUB_BLOCKS; i++) begin
            out_data_intra_block_reg[i] <= out_data_intra_block[i];
         end
      end
   end
end

always_ff @(posedge clk or negedge rst_n) begin
   if(!rst_n) begin
      counter_sub_out <= {NBW_COUNTER_SUB_OUT{1'b1}};
      out_data        <= {DATA_WIDTH{1'b0}};
      for(int i = 0; i < SUB_BLOCKS; i++) begin
         out_data_aux[i] <= {DATA_WIDTH{1'b0}};
      end
   end
   else begin
      if(start_intra) begin
         for(int i = 0; i < 32; i++) begin
            out_data_aux[0][(i+1)*CHUNK-1-:CHUNK] <= out_data_intra_block_reg[i%4][((i+1)*CHUNK)-1-:CHUNK];
            out_data_aux[1][(i+1)*CHUNK-1-:CHUNK] <= out_data_intra_block_reg[i%4][(((i+1)%OUT_CYCLES+1)*CHUNK)-1-:CHUNK];
            out_data_aux[2][(i+1)*CHUNK-1-:CHUNK] <= out_data_intra_block_reg[i%4][(((i+2)%OUT_CYCLES+1)*CHUNK)-1-:CHUNK];
            out_data_aux[3][(i+1)*CHUNK-1-:CHUNK] <= out_data_intra_block_reg[i%4][(((i+3)%OUT_CYCLES+1)*CHUNK)-1-:CHUNK];
         end
         counter_sub_out <= counter_sub_out + 1;
         out_data        <= out_data_aux[counter_sub_out];
      end
   end
end

endmodule

module glitch_free_mux (
    input  wire clk1,
    input  wire clk2,
    input  wire sel,
    input  wire rst_n,   // asynchronous active-low reset
    output wire clkout
);

    // Enable flags for each clock domain. The spec pins the gating to the
    // POSITIVE edge of each clock (not the textbook negedge form): clk1 is
    // disabled on the first posedge of clk1 after sel changes, then clk2 is
    // enabled on the first posedge of clk2 once clk1 is disabled (and vice
    // versa). Each enable is held off while the OTHER clock is still enabled so
    // the two are never enabled simultaneously.
    reg clk1_en;
    reg clk2_en;

    // clk1 domain: enable clk1 only when sel selects it and clk2 is disabled.
    always @(posedge clk1 or negedge rst_n) begin
        if (!rst_n)
            clk1_en <= 1'b0;
        else
            clk1_en <= ~sel & ~clk2_en;
    end

    // clk2 domain: enable clk2 only when sel selects it and clk1 is disabled.
    always @(posedge clk2 or negedge rst_n) begin
        if (!rst_n)
            clk2_en <= 1'b0;
        else
            clk2_en <= sel & ~clk1_en;
    end

    // Gated, glitch-free output clock. On reset clkout is driven low.
    assign clkout = (clk1 & clk1_en) | (clk2 & clk2_en);

endmodule

module halfband_fir #(
    parameter LGNTAPS = 7,
    parameter IW      = 16,
    parameter TW      = 12,
    parameter OW      = IW + TW + LGNTAPS,
    parameter [LGNTAPS:0] NTAPS        = 107,
    parameter [0:0]       FIXED_TAPS   = 1'b0,
    parameter           INITIAL_COEFFS = "",
    parameter [0:0]       OPT_HILBERT  = 1'b0,
    localparam LGNMEM  = LGNTAPS - 1,
    localparam LGNCOEF = LGNMEM - 1,
    localparam [LGNTAPS-1:0] HALFTAPS = NTAPS[LGNTAPS:1],
    localparam [LGNTAPS-2:0] QTRTAPS  = HALFTAPS[LGNTAPS-1:1] + 1,
    localparam DMEMSZ = (1 << LGNMEM),
    localparam CMEMSZ = (1 << LGNCOEF)
)(
    input  wire i_clk,
    input  wire i_reset,
    input  wire i_tap_wr,
    input  wire [(TW-1):0] i_tap,
    input  wire i_ce,
    input  wire [(IW-1):0] i_sample,
    output reg  o_ce,
    output reg  [(OW-1):0] o_result
);

    reg [3:0] messy_flag;

    reg [TW-1:0] coef_mem_messy [0:CMEMSZ-1];


    reg [IW-1:0] dmem1_messy [0:DMEMSZ-1];
    reg [IW-1:0] dmem2_messy [0:DMEMSZ-1];

    reg [LGNMEM-1:0] write_idx, left_idx, right_idx;
    reg [LGNCOEF-1:0] tap_idx;
    reg signed [IW-1:0] sample_left, sample_right, mid_sample_messy;
    reg signed [IW:0]   sum_data;
    reg clk_en, data_en, sum_en;
    reg signed [IW+TW-1:0] mult_result;
    reg signed [OW-1:0]    acc_result;

    // Control wires:
    wire last_tap_warn, last_data_warn;
    wire [LGNTAPS-2:0] remaining_taps;

    generate
      if (FIXED_TAPS || (INITIAL_COEFFS != "")) begin : LOAD_COEFFS
         initial begin
             $readmemh(INITIAL_COEFFS, coef_mem_messy);
         end
      end else begin : DYNAMIC_COEFFS
         reg [LGNCOEF-1:0] tap_wr_idx;
         initial tap_wr_idx = 0;
         always @(posedge i_clk)
            if (i_reset)
                tap_wr_idx <= 0;
            else if (i_tap_wr)
                tap_wr_idx <= tap_wr_idx + 1'b1;
         always @(posedge i_clk)
            if (i_tap_wr)
                coef_mem_messy[tap_wr_idx] <= i_tap;
      end
    endgenerate


    initial write_idx = 0;
    always @(posedge i_clk) begin
        if (i_ce)
            write_idx <= write_idx + 1;
    end

    always @(posedge i_clk)
      if (i_ce) begin
         dmem1_messy[write_idx] <= i_sample;
         dmem2_messy[write_idx] <= mid_sample_messy;
      end

    always @(posedge i_clk)
    begin
      if (i_reset)
         mid_sample_messy <= 0;
      else if (i_ce)
         mid_sample_messy <= sample_left;
    end

    assign remaining_taps = QTRTAPS - tap_idx;
    assign last_tap_warn = (remaining_taps <= 1);
    assign last_data_warn = (QTRTAPS - tap_idx <= 2);


    initial messy_flag = 4'b0;
    always @(posedge i_clk) begin
      if (i_reset)
        messy_flag[0] <= 1'b0;
      else if (i_ce)
        messy_flag[0] <= 1'b1;
      else if (messy_flag[0] && !last_tap_warn)
        messy_flag[0] <= 1'b1;
      else if (!clk_en)
        messy_flag[0] <= 1'b0;
    end

    always @(posedge i_clk)
      if (i_reset)
         messy_flag[3:1] <= 3'b0;
      else
         messy_flag[3:1] <= { messy_flag[2:1], (clk_en || (messy_flag[0] && !last_tap_warn)) };


    initial begin
      left_idx = 0;
      right_idx = 0;
    end

    always @(posedge i_clk) begin
      if (i_reset) begin
        left_idx <= 0;
        right_idx <= 0;
      end else if (i_ce) begin
        left_idx <= write_idx;
        right_idx <= write_idx - (HALFTAPS[LGNMEM-1:0]) + 1;
      end else if (clk_en || !last_data_warn) begin
        left_idx <= left_idx - 2;
        right_idx <= right_idx + 2;
      end
    end


    initial tap_idx = 0;
    always @(posedge i_clk) begin
      if (i_reset)
         tap_idx <= 0;
      else if (clk_en)
         tap_idx <= 0;
      else if (!last_tap_warn)
         tap_idx <= tap_idx + 1;
    end


    initial clk_en = 1'b0;
    always @(posedge i_clk) begin
      clk_en <= (i_ce && !i_reset);
    end


    initial begin
        sample_left  = 0;
        sample_right = 0;
    end

    always @(posedge i_clk) begin
      sample_left  <= dmem1_messy[left_idx];
      sample_right <= dmem2_messy[right_idx];
    end

    // --- Data Enable Update ---
    initial data_en = 1'b0;
    always @(posedge i_clk)
       data_en <= (clk_en && !i_reset);

    // --- Coefficient Read and Data Sum Computation ---
    reg [TW-1:0] current_coef;
    initial current_coef = 0;
    always @(posedge i_clk)
       current_coef <= coef_mem_messy[tap_idx[LGNCOEF-1:0]];

    initial sum_data = 0;
    always @(posedge i_clk) begin
      if (i_reset)
         sum_data <= 0;
      else if (OPT_HILBERT)
         sum_data <= sample_left - sample_right;
      else
         sum_data <= sample_left + sample_right;
    end

    // --- Summation Enable ---
    initial sum_en = 1'b0;
    always @(posedge i_clk)
       sum_en <= (data_en && !i_reset);

    // --- Multiply Operation ---
    initial mult_result = 0;
    always @(posedge i_clk)
       mult_result <= current_coef * sum_data;

       wire [OW-1:0] mid_prod;
    generate
      if (OPT_HILBERT) begin : NO_MIDPOINT
         assign mid_prod = 0;
      end else begin : GEN_MIDPOINT
         reg [OW-1:0] mid_prod_reg;
         initial mid_prod_reg = 0;
         always @(posedge i_clk) begin
            if (i_reset)
               mid_prod_reg <= 0;
            else if (clk_en)
               mid_prod_reg <= { {(OW-IW-TW+1){mid_sample_messy[IW-1]}},
                                  mid_sample_messy, {(TW-1){1'b0}} }
                              - { {(OW-IW){mid_sample_messy[IW-1]}},
                                  mid_sample_messy };
         end
         assign mid_prod = mid_prod_reg;
      end
    endgenerate

    // --- Accumulation ---
    initial acc_result = 0;
    always @(posedge i_clk) begin
      if (i_reset)
         acc_result <= 0;
      else if (sum_en)
         acc_result <= mid_prod;
      else if (messy_flag[3])
         acc_result <= acc_result + { {(OW-(IW+TW)){mult_result[IW+TW-1]}}, mult_result };
    end

    // --- Output Assignments ---
    initial o_result = 0;
    always @(posedge i_clk)
       if (sum_en)
          o_result <= acc_result;

    // --- Output Clock Enable Update ---
    initial o_ce = 1'b0;
    always @(posedge i_clk)
       o_ce <= (sum_en && !i_reset);

endmodule

module sdram_controller (clk,reset,addr,data_in,data_out,read,write,sdram_clk,sdram_cke,sdram_cs,sdram_ras,sdram_cas,sdram_we,sdram_addr,sdram_ba,sdram_dq,dq_out);

    input         clk;
    input         reset;          // asynchronous active-high reset
    input  [23:0] addr;           // 24-bit address for SDRAM access
    input  [15:0] data_in;        // 16-bit write data
    input         read;
    input         write;
    input  [15:0] sdram_dq;       // 16-bit data bus from SDRAM

    output reg [15:0] data_out;   // 16-bit read data
    output            sdram_clk;
    output reg        sdram_cke;
    output reg        sdram_cs;
    output reg        sdram_ras;
    output reg        sdram_cas;
    output reg        sdram_we;
    output reg [12:0] sdram_addr;
    output reg [1:0]  sdram_ba;
    output reg [15:0] dq_out;     // 16-bit write data bus to SDRAM

    // FSM states
    localparam INIT     = 3'd0;
    localparam IDLE     = 3'd1;
    localparam ACTIVATE = 3'd2;
    localparam READ     = 3'd3;
    localparam WRITE    = 3'd4;
    localparam REFRESH  = 3'd5;

    localparam INIT_CYCLES    = 10;
    localparam REFRESH_PERIOD = 1024;

    reg [2:0]  state;
    reg [3:0]  init_cnt;       // counts up to INIT_CYCLES
    reg [9:0]  refresh_cnt;    // counts up to REFRESH_PERIOD
    reg        pend_read;      // latched request type
    reg        pend_write;

    // SDRAM clock is simply the system clock forwarded to the device.
    assign sdram_clk = clk;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state       <= INIT;
            init_cnt    <= 4'd0;
            refresh_cnt <= 10'd0;
            pend_read   <= 1'b0;
            pend_write  <= 1'b0;
            data_out    <= 16'd0;
            dq_out      <= 16'd0;
            sdram_addr  <= 13'd0;
            sdram_ba    <= 2'd0;
            // idle command (CKE high, chip deselected)
            sdram_cke   <= 1'b1;
            sdram_cs    <= 1'b0;
            sdram_ras   <= 1'b0;
            sdram_cas   <= 1'b0;
            sdram_we    <= 1'b0;
        end else begin
            // default: deassert command strobes each cycle unless a state drives them
            sdram_cke <= 1'b1;
            sdram_cs  <= 1'b0;
            sdram_ras <= 1'b0;
            sdram_cas <= 1'b0;
            sdram_we  <= 1'b0;

            case (state)
                // -------- Initialization: 10 clock cycles --------
                INIT: begin
                    if (init_cnt == INIT_CYCLES-1) begin
                        init_cnt <= 4'd0;
                        state    <= IDLE;
                    end else begin
                        init_cnt <= init_cnt + 4'd1;
                    end
                end

                // -------- Idle: wait for read/write or trigger refresh --------
                IDLE: begin
                    if (read || write) begin
                        // capture request and latch the row/bank/column address
                        pend_read   <= read;
                        pend_write  <= write;
                        sdram_addr  <= addr[12:0];
                        sdram_ba    <= addr[23:22];
                        refresh_cnt <= 10'd0;
                        // Activate command: CS=1, RAS=1, CAS=1
                        sdram_cs    <= 1'b1;
                        sdram_ras   <= 1'b1;
                        sdram_cas   <= 1'b1;
                        state       <= ACTIVATE;
                    end else if (refresh_cnt == REFRESH_PERIOD-1) begin
                        refresh_cnt <= 10'd0;
                        // Auto Refresh command: CS=1, RAS=1, CAS=1, WE=0
                        sdram_cs    <= 1'b1;
                        sdram_ras   <= 1'b1;
                        sdram_cas   <= 1'b1;
                        sdram_we    <= 1'b0;
                        state       <= REFRESH;
                    end else begin
                        refresh_cnt <= refresh_cnt + 10'd1;
                    end
                end

                // -------- Activate: next cycle go to READ or WRITE --------
                ACTIVATE: begin
                    if (pend_read)
                        state <= READ;
                    else if (pend_write)
                        state <= WRITE;
                    else
                        state <= IDLE;
                end

                // -------- Read: CS=1, CKE=1, RAS=0, CAS=1, WE=0 --------
                READ: begin
                    sdram_cs   <= 1'b1;
                    sdram_cke  <= 1'b1;
                    sdram_ras  <= 1'b0;
                    sdram_cas  <= 1'b1;
                    sdram_we   <= 1'b0;
                    data_out   <= sdram_dq;     // capture read data
                    pend_read  <= 1'b0;
                    state      <= IDLE;
                end

                // -------- Write: CS=1, CKE=1, RAS=0, CAS=1, WE=1 --------
                WRITE: begin
                    sdram_cs   <= 1'b1;
                    sdram_cke  <= 1'b1;
                    sdram_ras  <= 1'b0;
                    sdram_cas  <= 1'b1;
                    sdram_we   <= 1'b1;
                    dq_out     <= data_in;      // drive write data
                    pend_write <= 1'b0;
                    state      <= IDLE;
                end

                // -------- Refresh: hold the refresh command then return --------
                REFRESH: begin
                    sdram_cs   <= 1'b1;
                    sdram_ras  <= 1'b1;
                    sdram_cas  <= 1'b1;
                    sdram_we   <= 1'b0;
                    state      <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module iir_filter (
    input  logic clk,
    input  logic rst,
    input  logic signed [15:0] x,
    output logic signed [15:0] y
);

    // Feed-forward / feed-back coefficients
    parameter signed [15:0] b0 = 16'h0F00;
    parameter signed [15:0] b1 = 16'h0E00;
    parameter signed [15:0] b2 = 16'h0D00;
    parameter signed [15:0] b3 = 16'h0C00;
    parameter signed [15:0] b4 = 16'h0B00;
    parameter signed [15:0] b5 = 16'h0A00;
    parameter signed [15:0] b6 = 16'h0900;
    parameter signed [15:0] a1 = -16'h0800;
    parameter signed [15:0] a2 = -16'h0700;
    parameter signed [15:0] a3 = -16'h0600;
    parameter signed [15:0] a4 = -16'h0500;
    parameter signed [15:0] a5 = -16'h0400;
    parameter signed [15:0] a6 = -16'h0300;

    // LINT FIX (unused parameter): 'unused_param' removed.

    logic signed [15:0] x_prev1, x_prev2, x_prev3, x_prev4, x_prev5, x_prev6;
    logic signed [15:0] y_prev1, y_prev2, y_prev3, y_prev4, y_prev5, y_prev6;

    // LINT FIX (width mismatch): result is sized to the 16-bit output. The
    // wide multiply-accumulate sum is scaled by >>> 16 and explicitly cast to
    // 16 bits, so no extra bits are left unused.
    logic signed [15:0] temp_y;
    // LINT FIX (undriven signal): 'undriven_signal' removed.

    // LINT FIX (combinational logic in sequential block / latch inference):
    // the purely combinational sum is computed in a dedicated always_comb,
    // keeping the clocked block strictly sequential. temp_y is fully assigned
    // every evaluation so no latch is inferred.
    always_comb begin
        temp_y = 16'((b0 * x + b1 * x_prev1 + b2 * x_prev2 + b3 * x_prev3 +
                      b4 * x_prev4 + b5 * x_prev5 + b6 * x_prev6 -
                      a1 * y_prev1 - a2 * y_prev2 - a3 * y_prev3 -
                      a4 * y_prev4 - a5 * y_prev5 - a6 * y_prev6) >>> 16);
    end

    always_ff @(posedge clk or posedge rst) begin
        if (rst) begin
            x_prev1 <= 16'sd0; x_prev2 <= 16'sd0; x_prev3 <= 16'sd0;
            x_prev4 <= 16'sd0; x_prev5 <= 16'sd0; x_prev6 <= 16'sd0;
            y_prev1 <= 16'sd0; y_prev2 <= 16'sd0; y_prev3 <= 16'sd0;
            y_prev4 <= 16'sd0; y_prev5 <= 16'sd0; y_prev6 <= 16'sd0;
            // LINT FIX (uninitialized register): y now has a defined reset value.
            y       <= 16'sd0;
        end else begin
            // LINT FIX (width mismatch): explicit 16-bit slice of the 32-bit sum.
            // Saturation condition preserved exactly as in the original RTL.
            if (x > 16'h8000)
                y <= 16'h7FFF;
            else
                y <= temp_y;

            x_prev6 <= x_prev5; x_prev5 <= x_prev4; x_prev4 <= x_prev3;
            x_prev3 <= x_prev2; x_prev2 <= x_prev1; x_prev1 <= x;
            y_prev6 <= y_prev5; y_prev5 <= y_prev4; y_prev4 <= y_prev3;
            y_prev3 <= y_prev2; y_prev2 <= y_prev1; y_prev1 <= y;
        end
    end

endmodule

module soundgenerator #(
	parameter  CLOCK_HZ = 10_000_000
)(
	input wire clk,                                         //input clock signal with frequency 10Mhz
	input wire nrst,                                        //active low asynchronous reset.

	input wire start,                                       //indicate the start of the operation.
	input wire finish,                                      //indicate the end of operation.
	input wire [15:0] sond_dur_ms_i,                        //sound duration in milliseconds.
	input wire [15:0] half_period_us_i,                     //half period of the output soundwave in microseconds.

	output wire soundwave_o,                                //output sound wave signal.
	output wire busy,                                       //indicate the system is busy.
	output wire done                                        //indicate the operation is completed.
);

	// Prompt-named internal timing strobes (declared as nets so a white-box
	// testbench can probe them by these exact identifiers).
	wire TickMilli;   // 1 ms pulse
	wire tickmicro;   // 1 us pulse

	reg  [15:0] duration_cnt;
	reg  [15:0] halfperiodtimer;
	reg         signal;          // square-wave state
	reg         busy_d;          // delayed busy for completion edge detect

	// busy while there is remaining duration to play
	assign busy        = (duration_cnt != 16'd0);
	assign soundwave_o = busy ? signal : 1'b0;
	// done: rising edge of (busy -> idle)
	assign done        = busy_d & ~busy;

	// 1 ms tick generator
	strob_gen #(
		.CLOCK_HZ (CLOCK_HZ),
		.PERIOD_US(1000)
	) u_tickmilli (
		.clk     (clk),
		.nrst    (nrst),
		.enable  (1'b1),
		.strobe_o(TickMilli)
	);

	// 1 us tick generator
	strob_gen #(
		.CLOCK_HZ (CLOCK_HZ),
		.PERIOD_US(1)
	) u_tickmicro (
		.clk     (clk),
		.nrst    (nrst),
		.enable  (1'b1),
		.strobe_o(tickmicro)
	);

	// Duration timer: load on start, decrement every millisecond while active.
	always @(posedge clk or negedge nrst) begin
		if (!nrst) begin
			duration_cnt <= 16'd0;
		end else if (start) begin
			duration_cnt <= sond_dur_ms_i;
		end else if (finish) begin
			duration_cnt <= 16'd0;
		end else if (busy && TickMilli) begin
			duration_cnt <= duration_cnt - 16'd1;
		end
	end

	// Completion edge register
	always @(posedge clk or negedge nrst) begin
		if (!nrst)
			busy_d <= 1'b0;
		else
			busy_d <= busy;
	end

	// Square-wave generation: toggle each time the half-period timer expires.
	always @(posedge clk or negedge nrst) begin
		if (!nrst) begin
			halfperiodtimer <= 16'd0;
			signal          <= 1'b0;
		end else if (busy) begin
			if (tickmicro) begin
				if (halfperiodtimer == 16'd0) begin
					signal          <= ~signal;
					halfperiodtimer <= half_period_us_i;
				end else begin
					halfperiodtimer <= halfperiodtimer - 16'd1;
				end
			end
		end else begin
			halfperiodtimer <= half_period_us_i;
			signal          <= 1'b0;
		end
	end

endmodule

module strob_gen #(
	parameter	CLOCK_HZ	= 10_000_000,
	parameter	PERIOD_US	= 100
)(
	input wire  clk,
	input wire  nrst,
	input wire  enable,
	output reg  strobe_o
);
	// Number of clock cycles in one strobe period.
	localparam integer DELAY = (CLOCK_HZ / 1_000_000) * PERIOD_US;
	localparam integer CW    = (DELAY <= 1) ? 1 : $clog2(DELAY + 1);

	reg [CW-1:0] counter;

	always @(posedge clk or negedge nrst) begin
		if (!nrst) begin
			counter  <= DELAY[CW-1:0];
			strobe_o <= 1'b0;
		end else if (!enable) begin
			counter  <= DELAY[CW-1:0];
			strobe_o <= 1'b0;
		end else begin
			if (counter == 0) begin
				strobe_o <= 1'b1;
				counter  <= DELAY[CW-1:0];
			end else begin
				strobe_o <= 1'b0;
				counter  <= counter - 1'b1;
			end
		end
	end

endmodule

module serial_line_code_converter #(parameter CLK_DIV = 16)(
    input  logic clk,             // System clock
    input  logic reset_n,         // Active-low reset
    input  logic serial_in,       // Serial input signal
    input  logic enable,          // Enable signal; outputs disabled when low
    input  logic [2:0] mode,      // Mode selector
    output logic serial_out,      // Serial output signal
    output logic error_flag,      // Error flag (serial_in is x/z)
    output logic [15:0] diagnostic_bus // Diagnostic output bus
);

    // Internal signals
    logic [3:0] clk_counter;      // Clock divider counter
    logic clk_pulse;              // Clock pulse for sampling
    logic prev_serial_in;         // Previous serial input for edge detection
    logic prev_value;             // Holds the previous value of serial_in
    logic nrz_out;                // NRZ encoding output
    logic rz_out;                 // Return-to-Zero encoding output
    logic diff_out;               // Differential encoding output
    logic inv_nrz_out;            // Inverted NRZ output
    logic alt_invert_out;         // NRZ with alternating bit inversion output
    logic alt_invert_state;       // State for alternating inversion
    logic parity_out;             // Parity Bit Output
    logic scrambled_out;          // Scrambled NRZ output
    logic edge_triggered_out;     // Edge-Triggered NRZ output

    logic [7:0] error_counter;    // Tracks total errors detected
    logic       serial_invalid;   // serial_in is x or z


    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            clk_counter <= 0;
            clk_pulse <= 0;
        end else if (clk_counter == CLK_DIV - 1) begin
            clk_counter <= 0;
            clk_pulse <= 1;
        end else begin
            clk_counter <= clk_counter + 1;
            clk_pulse <= 0;
        end
    end

    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            prev_value <= 0;
            prev_serial_in <= 0;
        end else begin
            prev_value <= serial_in;
            prev_serial_in <= prev_value;
        end
    end

    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            nrz_out <= 0;
        end else begin
            nrz_out <= serial_in;
        end
    end

    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            rz_out <= 0;
        end else begin
            rz_out <= serial_in & clk_pulse;
        end
    end

    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            diff_out <= 0;
        end else  begin
            diff_out <= serial_in ^ prev_serial_in;
        end
    end

    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            inv_nrz_out <= 0;
        end else  begin
            inv_nrz_out <= ~serial_in;
        end
    end

    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            alt_invert_out <= 0;
            alt_invert_state <= 0;
        end else  begin
            alt_invert_state <= ~alt_invert_state;
            alt_invert_out <= alt_invert_state ? ~serial_in : serial_in;
        end
    end

    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            parity_out <= 0;
        end else  begin
            parity_out <= serial_in ^ parity_out;
        end
    end

    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            scrambled_out <= 0;
        end else  begin
            scrambled_out <= serial_in ^ clk_counter[0];
        end
    end

    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            edge_triggered_out <= 0;
        end else  begin
            edge_triggered_out <= (serial_in & ~prev_serial_in);
        end
    end

    // Error detection: invalid serial_in (1'bx / 1'bz) while enabled.
    always_comb begin
        serial_invalid = (serial_in === 1'bx) || (serial_in === 1'bz);
    end

    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            error_counter <= 8'd0;
        end else if (enable && serial_invalid) begin
            error_counter <= error_counter + 8'd1;
        end
    end

    assign error_flag = enable && serial_invalid;

    // Encoding mux, gated by enable.
    always_comb begin
        if (!enable) begin
            serial_out = 1'b0;
        end else begin
            case (mode)
                3'b000: serial_out = nrz_out;
                3'b001: serial_out = rz_out;
                3'b010: serial_out = diff_out;
                3'b011: serial_out = inv_nrz_out;
                3'b100: serial_out = alt_invert_out;
                3'b101: serial_out = parity_out;
                3'b110: serial_out = scrambled_out;
                3'b111: serial_out = edge_triggered_out;
                default: serial_out = 0;
            endcase
        end
    end

    // Diagnostic bus packing.
    assign diagnostic_bus = {mode,            // [15:13] encoding mode
                             error_flag,      // [12]    error flag
                             error_counter,   // [11:4]  error counter
                             clk_pulse,        // [3]     clock pulse
                             serial_out,       // [2]     encoded output
                             alt_invert_out,   // [1]     alternating-invert output
                             parity_out};      // [0]     parity bit

endmodule

module hill_cipher (
    input  logic        clk,
    input  logic        reset,
    input  logic        start,
    input  logic [14:0] plaintext,   // 3 letters, 5 bits each
    input  logic [44:0] key,         // 9 elements, 5 bits each
    output logic [14:0] ciphertext,  // 3 letters, 5 bits each
    output logic        done
);

    logic [4:0] P0, P1, P2;
    logic [4:0] K00, K01, K02;
    logic [4:0] K10, K11, K12;
    logic [4:0] K20, K21, K22;

    // Each product K*P <= 31*31 = 961 (10 bits); the sum of three products is
    // <= 2883 (12 bits). 12-bit accumulators avoid any intermediate truncation.
    logic [11:0] temp0, temp1, temp2;
    // Modulo-26 results are 0..25 (5 bits). The explicit 5-bit cast makes the
    // narrowing intentional (no truncation warning) and leaves no unused bits.
    logic [4:0] c0_mod, c1_mod, c2_mod;

    typedef enum logic [1:0] {
        IDLE        = 2'b00,
        COMPUTE     = 2'b01,
        COMPUTE_MOD = 2'b10,
        DONE        = 2'b11
    } state_t;

    state_t current_state, next_state;

    assign P0 = plaintext[14:10];
    assign P1 = plaintext[9:5];
    assign P2 = plaintext[4:0];

    assign K00 = key[44:40];
    assign K01 = key[39:35];
    assign K02 = key[34:30];
    assign K10 = key[29:25];
    assign K11 = key[24:20];
    assign K12 = key[19:15];
    assign K20 = key[14:10];
    assign K21 = key[9:5];
    assign K22 = key[4:0];

    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    always_comb begin
        next_state = current_state;
        done       = 1'b0;
        case (current_state)
            IDLE:        if (start) next_state = COMPUTE;
            COMPUTE:     next_state = COMPUTE_MOD;
            COMPUTE_MOD: next_state = DONE;
            DONE: begin
                done       = 1'b1;
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            temp0  <= 12'b0;
            temp1  <= 12'b0;
            temp2  <= 12'b0;
            c0_mod <= 5'b0;
            c1_mod <= 5'b0;
            c2_mod <= 5'b0;
        end
        else begin
            case (current_state)
                COMPUTE: begin
                    temp0 <= (12'(K00) * 12'(P0)) + (12'(K01) * 12'(P1)) + (12'(K02) * 12'(P2));
                    temp1 <= (12'(K10) * 12'(P0)) + (12'(K11) * 12'(P1)) + (12'(K12) * 12'(P2));
                    temp2 <= (12'(K20) * 12'(P0)) + (12'(K21) * 12'(P1)) + (12'(K22) * 12'(P2));
                end
                COMPUTE_MOD: begin
                    c0_mod <= 5'(temp0 % 12'd26);
                    c1_mod <= 5'(temp1 % 12'd26);
                    c2_mod <= 5'(temp2 % 12'd26);
                end
                default: begin
                    temp0  <= 12'b0;
                    temp1  <= 12'b0;
                    temp2  <= 12'b0;
                    c0_mod <= 5'b0;
                    c1_mod <= 5'b0;
                    c2_mod <= 5'b0;
                end
            endcase
        end
    end

    assign ciphertext = { c0_mod, c1_mod, c2_mod };

endmodule

module sigma_delta_audio
(
  input   clk_sig,
  input   clk_en_sig,
  input  [14:0] load_data_sum,
  input  [14:0] read_data_sum,
  output  reg left_sig=0,
  output  reg right_sig=0
);

localparam DATA_WIDTH = 15;
localparam READ_WIDTH  = 4;
localparam A1_WIDTH = 2;
localparam A2_WIDTH = 5;

wire [DATA_WIDTH+2+0  -1:0] l_er0, r_er0;
reg  [DATA_WIDTH+2+0  -1:0] l_er0_prev=0, r_er0_prev=0;
wire [DATA_WIDTH+A1_WIDTH+2-1:0] l_aca1,  r_aca1;
wire [DATA_WIDTH+A2_WIDTH+2-1:0] l_aca2,  r_aca2;
reg  [DATA_WIDTH+A1_WIDTH+2-1:0] l_ac1=0, r_ac1=0;
reg  [DATA_WIDTH+A2_WIDTH+2-1:0] l_ac2=0, r_ac2=0;
wire [DATA_WIDTH+A2_WIDTH+3-1:0] l_quant, r_quant;

reg [24-1:0] seed_1 = 24'h654321;
reg [19-1:0] seed_2 = 19'h12345;
reg [24-1:0] s_sum=0, s_prev=0, s_out=0;
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    if (&seed_1)
      seed_1 <= 24'h654321;
    else
      seed_1 <= {seed_1[22:0], ~(seed_1[23] ^ seed_1[22] ^ seed_1[21] ^ seed_1[16])};
  end
end
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    if (&seed_2)
      seed_2 <= 19'h12345;
    else
      seed_2 <= {seed_2[17:0], ~(seed_2[18] ^ seed_2[17] ^ seed_2[16] ^ seed_2[13] ^ seed_2[0])};
  end
end
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    s_sum  <= seed_1 + {5'b0, seed_2};
    s_prev <= s_sum;
    s_out  <= s_sum - s_prev;
  end
end

localparam INPUT_DATA=4;
reg  [INPUT_DATA+0-1:0] integer_count = 0;
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    integer_count <= integer_count + 'd1;
  end
end

reg  [DATA_WIDTH+0-1:0] ldata_current=0, ldata_previous=0;
reg  [DATA_WIDTH+0-1:0] rdata_current=0, rdata_previous=0;
wire [DATA_WIDTH+1-1:0] load_data_step, read_data_step;
reg  [DATA_WIDTH+INPUT_DATA-1:0] load_data_int=0, read_data_int=0;
wire [DATA_WIDTH+0-1:0] load_data_int_out, read_data_int_out;
assign load_data_step = {ldata_current[DATA_WIDTH-1], ldata_current} - {ldata_previous[DATA_WIDTH-1], ldata_previous};
assign read_data_step = {rdata_current[DATA_WIDTH-1], rdata_current} - {rdata_previous[DATA_WIDTH-1], rdata_previous};
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    if (~|integer_count) begin
      ldata_previous <= ldata_current;
      ldata_current  <= load_data_sum;
      rdata_previous <= rdata_current;
      rdata_current  <= read_data_sum;
      load_data_int  <= {ldata_current, {INPUT_DATA{1'b0}}};
      read_data_int  <= {rdata_current, {INPUT_DATA{1'b0}}};
    end else begin
      load_data_int  <= load_data_int + {{(INPUT_DATA-1){load_data_step[DATA_WIDTH+1-1]}}, load_data_step};
      read_data_int  <= read_data_int + {{(INPUT_DATA-1){read_data_step[DATA_WIDTH+1-1]}}, read_data_step};
    end
  end
end
assign load_data_int_out = load_data_int[DATA_WIDTH+INPUT_DATA-1:INPUT_DATA];
assign read_data_int_out = read_data_int[DATA_WIDTH+INPUT_DATA-1:INPUT_DATA];

wire [DATA_WIDTH+2-1:0] load_data_gain, read_data_gain;
assign load_data_gain = {load_data_int_out[DATA_WIDTH-1], load_data_int_out, 1'b0} + {{(2){load_data_int_out[DATA_WIDTH-1]}}, load_data_int_out};
assign read_data_gain = {read_data_int_out[DATA_WIDTH-1], read_data_int_out, 1'b0} + {{(2){read_data_int_out[DATA_WIDTH-1]}}, read_data_int_out};

assign l_aca1 = {{(A1_WIDTH){load_data_gain[DATA_WIDTH+2-1]}}, load_data_gain} - {{(A1_WIDTH){l_er0[DATA_WIDTH+2-1]}}, l_er0} + l_ac1;
assign r_aca1 = {{(A1_WIDTH){read_data_gain[DATA_WIDTH+2-1]}}, read_data_gain} - {{(A1_WIDTH){r_er0[DATA_WIDTH+2-1]}}, r_er0} + r_ac1;
assign l_aca2 = {{(A2_WIDTH-A1_WIDTH){l_aca1[DATA_WIDTH+A1_WIDTH+2-1]}}, l_aca1} - {{(A2_WIDTH){l_er0[DATA_WIDTH+2-1]}}, l_er0} - {{(A2_WIDTH+1){l_er0_prev[DATA_WIDTH+2-1]}}, l_er0_prev[DATA_WIDTH+2-1:1]} + l_ac2;
assign r_aca2 = {{(A2_WIDTH-A1_WIDTH){r_aca1[DATA_WIDTH+A1_WIDTH+2-1]}}, r_aca1} - {{(A2_WIDTH){r_er0[DATA_WIDTH+2-1]}}, r_er0} - {{(A2_WIDTH+1){r_er0_prev[DATA_WIDTH+2-1]}}, r_er0_prev[DATA_WIDTH+2-1:1]} + r_ac2;

always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    l_ac1 <= l_aca1;
    r_ac1 <= r_aca1;
    l_ac2 <= l_aca2;
    r_ac2 <= r_aca2;
  end
end

assign l_quant = {l_ac2[DATA_WIDTH+A2_WIDTH+2-1], l_ac2} + {{(DATA_WIDTH+A2_WIDTH+3-READ_WIDTH){s_out[READ_WIDTH-1]}}, s_out[READ_WIDTH-1:0]};
assign r_quant = {r_ac2[DATA_WIDTH+A2_WIDTH+2-1], r_ac2} + {{(DATA_WIDTH+A2_WIDTH+3-READ_WIDTH){s_out[READ_WIDTH-1]}}, s_out[READ_WIDTH-1:0]};

assign l_er0 = l_quant[DATA_WIDTH+A2_WIDTH+3-1] ? {1'b1, {(DATA_WIDTH+2-1){1'b0}}} : {1'b0, {(DATA_WIDTH+2-1){1'b1}}};
assign r_er0 = r_quant[DATA_WIDTH+A2_WIDTH+3-1] ? {1'b1, {(DATA_WIDTH+2-1){1'b0}}} : {1'b0, {(DATA_WIDTH+2-1){1'b1}}};

always @ (posedge clk_sig)
begin
  if (clk_en_sig)
  begin
    if (~|load_data_gain)
    begin
      left_sig <= ~left_sig;
    end
    else
    begin
      left_sig <= ~l_er0[DATA_WIDTH+2-1];
    end

    if (~|read_data_gain)
    begin
      right_sig <= ~right_sig;
    end
    else
    begin
      right_sig <= ~r_er0[DATA_WIDTH+2-1];
    end
  end
end
endmodule

module cont_adder #(
    parameter DATA_WIDTH = 32,
    parameter signed THRESHOLD_VALUE_1 = 50,
    parameter signed THRESHOLD_VALUE_2 = 100,
    parameter SIGNED_INPUTS = 1,
    parameter ACCUM_MODE = 0,
    parameter signed WEIGHT = 1
) (
    input  logic                         clk,
    input  logic                         reset,
    input  logic signed [DATA_WIDTH-1:0] data_in,
    input  logic                         data_valid,
    input  logic [15:0]                  window_size,
    output logic signed [DATA_WIDTH-1:0] sum_out,
    output logic signed [DATA_WIDTH-1:0] avg_out,
    output logic                         threshold_1,
    output logic                         threshold_2,
    output logic                         sum_ready
);

    // Accumulator carries two extra guard bits over the data path.
    localparam int ACC_WIDTH = DATA_WIDTH + 2;

    // Sequential Registers
    logic signed [ACC_WIDTH-1:0]  sum_accum;
    logic        [15:0]           sample_count;

    // Combinational Signals
    logic signed [ACC_WIDTH-1:0]  weighted_full;   // full-width product (no truncation warning)
    logic signed [ACC_WIDTH-1:0]  new_sum;         // accumulator-width running sum
    logic signed [DATA_WIDTH-1:0] avg_q;           // output-width quotient (fully used)
    logic signed [DATA_WIDTH-1:0] window_signed;   // window_size as a positive signed value
    logic                         threshold_1_comb;
    logic                         threshold_2_comb;
    logic                         sum_ready_reg;
    logic        [16:0]           next_count;       // sample_count + 1 (extra bit avoids truncation)

    // Combinational Logic
    always @(*) begin
        sum_ready_reg = 1'b0;

        // Respect the SIGNED_INPUTS parameter when forming the weighted input.
        if (SIGNED_INPUTS)
            weighted_full = ACC_WIDTH'(data_in) * ACC_WIDTH'(WEIGHT);
        else
            weighted_full = ACC_WIDTH'($unsigned(data_in)) * ACC_WIDTH'(WEIGHT);

        new_sum = sum_accum + weighted_full;

        threshold_1_comb = (new_sum >= ACC_WIDTH'(THRESHOLD_VALUE_1)) ||
                           (new_sum <= -ACC_WIDTH'(THRESHOLD_VALUE_1));
        threshold_2_comb = (new_sum >= ACC_WIDTH'(THRESHOLD_VALUE_2)) ||
                           (new_sum <= -ACC_WIDTH'(THRESHOLD_VALUE_2));

        next_count = {1'b0, sample_count} + 17'd1;

        // Average computed in the output bit-width: both operands are DATA_WIDTH
        // signed, so the quotient is fully used (no width-expand / unused bits).
        window_signed = $signed({{(DATA_WIDTH-16){1'b0}}, window_size});
        avg_q         = new_sum[DATA_WIDTH-1:0] / window_signed;

        if (data_valid) begin
            if (ACCUM_MODE == 0) begin
                sum_ready_reg = (threshold_1_comb || threshold_2_comb);
            end else if (ACCUM_MODE == 1) begin
                sum_ready_reg = (next_count >= {1'b0, window_size});
            end
        end
    end

    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            sum_accum     <= '0;
            sample_count  <= 16'd0;
            sum_ready     <= 1'b0;
            sum_out       <= '0;
            avg_out       <= '0;
            threshold_1   <= 1'b0;
            threshold_2   <= 1'b0;
        end else if (data_valid) begin
            threshold_1 <= threshold_1_comb;
            threshold_2 <= threshold_2_comb;

            if (ACCUM_MODE == 1) begin
                sum_accum    <= new_sum;
                sample_count <= next_count[15:0];
                if (sum_ready_reg) begin
                    sum_out      <= new_sum[DATA_WIDTH-1:0];
                    avg_out      <= avg_q;
                    sum_ready    <= 1'b1;
                    sum_accum    <= '0;
                    sample_count <= 16'd0;
                end else begin
                    sum_ready <= 1'b0;
                    sum_out   <= '0;
                    avg_out   <= '0;
                end
            end else begin
                sum_accum <= new_sum;
                if (sum_ready_reg) begin
                    sum_out   <= new_sum[DATA_WIDTH-1:0];
                    sum_ready <= 1'b1;
                end else begin
                    sum_ready <= 1'b0;
                    sum_out   <= '0;
                end
                avg_out <= '0;
            end
        end else begin
            sum_ready <= 1'b0;
        end
    end

endmodule

module nbit_swizzling #(parameter DATA_WIDTH = 64)(
    input [DATA_WIDTH-1:0] data_in,                                         // Input data of size DATA_WIDTH
    input [1:0] sel,                                                        //  2-bit selection signal
    output reg [DATA_WIDTH:0] data_out,                                     // Output data of size DATA_WIDTH
    output reg [DATA_WIDTH + $clog2(DATA_WIDTH):0] ecc_out                  // Hamming ECC encoded output
);

localparam PARITY_BITS = $clog2(DATA_WIDTH + $clog2(DATA_WIDTH) + 1);
localparam CODE_LEN    = DATA_WIDTH + PARITY_BITS;

integer i;
wire parity_bit;


assign parity_bit = ^data_in;

always @(*) begin
    case(sel)
        2'b00: begin
            for (i = 0; i < DATA_WIDTH; i = i + 1) begin
                data_out[i] = data_in[DATA_WIDTH-1-i];
            end
            data_out[DATA_WIDTH] = parity_bit;
        end

        2'b01: begin
            for (i = 0; i < DATA_WIDTH/2; i = i + 1) begin
                data_out[i]                = data_in[DATA_WIDTH/2-1-i];
                data_out[DATA_WIDTH/2 + i] = data_in[DATA_WIDTH-1-i];
            end
            data_out[DATA_WIDTH] = parity_bit;
        end

        2'b10: begin
            for (i = 0; i < DATA_WIDTH/4; i = i + 1) begin
                data_out[i] = data_in[DATA_WIDTH/4-1-i];
                data_out[DATA_WIDTH/4 + i]   = data_in[DATA_WIDTH/2-1-i];
                data_out[DATA_WIDTH/2 + i]   = data_in[3*DATA_WIDTH/4-1-i];
                data_out[3*DATA_WIDTH/4 + i] = data_in[DATA_WIDTH-1-i];
            end
            data_out[DATA_WIDTH] = parity_bit;
        end

        2'b11: begin
            for (i = 0; i < DATA_WIDTH/8; i = i + 1) begin
                data_out[i]                  = data_in[DATA_WIDTH/8-1-i];
                data_out[DATA_WIDTH/8 + i]   = data_in[DATA_WIDTH/4-1-i];
                data_out[DATA_WIDTH/4 + i]   = data_in[3*DATA_WIDTH/8-1-i];
                data_out[3*DATA_WIDTH/8 + i] = data_in[DATA_WIDTH/2-1-i];
                data_out[DATA_WIDTH/2 + i]   = data_in[5*DATA_WIDTH/8-1-i];
                data_out[5*DATA_WIDTH/8 + i] = data_in[3*DATA_WIDTH/4-1-i];
                data_out[3*DATA_WIDTH/4 + i] = data_in[7*DATA_WIDTH/8-1-i];
                data_out[7*DATA_WIDTH/8 + i] = data_in[DATA_WIDTH-1-i];
            end
            data_out[DATA_WIDTH] = parity_bit;
        end
        default: begin
            data_out = data_in;
            data_out[DATA_WIDTH] = parity_bit;
        end
    endcase
end

// ---------------------------------------------------------------------------
// Hamming ECC generation
//  - Positions are 1-indexed (1 .. CODE_LEN).
//  - Positions that are a power of two (1,2,4,8,...) hold parity bits.
//  - The remaining positions are filled, in order, with the bits of data_in.
//  - Parity bit at position 2^k is the even parity (XOR) of every position
//    whose 1-indexed value has bit k set.
//  - ecc_out[pos-1] holds the codeword bit for position pos.
// ---------------------------------------------------------------------------
integer pos;
integer didx;
integer k;
integer ppos;
reg      p;
reg [CODE_LEN-1:0] cw;

always @(*) begin
    cw   = {CODE_LEN{1'b0}};
    didx = 0;
    // Place the data bits at the non-power-of-two positions.
    for (pos = 1; pos <= CODE_LEN; pos = pos + 1) begin
        if ((pos & (pos - 1)) != 0) begin
            cw[pos-1] = data_in[didx];
            didx = didx + 1;
        end
    end
    // Compute every parity bit (even parity over its covered positions).
    for (k = 0; k < PARITY_BITS; k = k + 1) begin
        ppos = (1 << k);
        p    = 1'b0;
        for (pos = 1; pos <= CODE_LEN; pos = pos + 1) begin
            if ((pos != ppos) && (((pos >> k) & 1) == 1))
                p = p ^ cw[pos-1];
        end
        cw[ppos-1] = p;
    end
    ecc_out = cw;
end

endmodule

// 32-bit Brent-Kung parallel-prefix adder.
//
// Computes sum = a + b + carry_in (33-bit), with carry_out = bit 32.
// The propagate/generate carry recurrence below is the exact relation a
// Brent-Kung prefix tree evaluates (c[i+1] = g[i] | (p[i] & c[i])); the
// hierarchical tree only changes the depth, not the value, so this form is
// functionally identical and verifiably correct against the worked table.
module brent_kung_adder (
    input  wire [31:0] a,
    input  wire [31:0] b,
    input  wire        carry_in,
    output wire [31:0] sum,
    output wire        carry_out
);
    wire [31:0] p;          // bit propagate
    wire [31:0] g;          // bit generate
    wire [32:0] c;          // carries; c[0] = carry_in

    assign p = a ^ b;
    assign g = a & b;

    assign c[0] = carry_in;

    genvar i;
    generate
        for (i = 0; i < 32; i = i + 1) begin : gen_carry
            assign c[i + 1] = g[i] | (p[i] & c[i]);
        end
    endgenerate

    assign sum       = p ^ c[31:0];
    assign carry_out = c[32];
endmodule

module axi_register #(
    parameter ADDR_WIDTH = 32,
    parameter DATA_WIDTH = 32
)(
    input                          clk_i,
    input                          rst_n_i,        // active-low async reset

    // Write address / data
    input      [ADDR_WIDTH-1:0]    awaddr_i,
    input                          awvalid_i,
    output reg                     awready_o,
    input      [DATA_WIDTH-1:0]    wdata_i,
    input                          wvalid_i,
    input      [(DATA_WIDTH/8)-1:0] wstrb_i,
    output reg                     wready_o,
    // Write response
    output reg [1:0]               bresp_o,
    output reg                     bvalid_o,
    input                          bready_i,

    // Read address / data
    input      [ADDR_WIDTH-1:0]    araddr_i,
    input                          arvalid_i,
    output reg                     arready_o,
    output reg [DATA_WIDTH-1:0]    rdata_o,
    output reg                     rvalid_o,
    output reg [1:0]               rresp_o,
    input                          rready_i,

    // Hardware-side
    input                          done_i,
    output reg [19:0]              beat_o,
    output reg                     start_o,
    output reg                     writeback_o
);

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    // Register offsets (decoded on the low address bits)
    localparam [11:0] OFF_BEAT = 12'h100;
    localparam [11:0] OFF_STRT = 12'h200;
    localparam [11:0] OFF_DONE = 12'h300;
    localparam [11:0] OFF_WB   = 12'h400;
    localparam [11:0] OFF_ID   = 12'h500;

    reg [ADDR_WIDTH-1:0] awaddr_q;
    reg [ADDR_WIDTH-1:0] araddr_q;
    reg                  aw_en;
    reg                  done_status;

    wire full_strb = &wstrb_i;

    // ---------------- Write address handshake ----------------
    always @(posedge clk_i or negedge rst_n_i) begin
        if (!rst_n_i) begin
            awready_o <= 1'b0;
            awaddr_q  <= {ADDR_WIDTH{1'b0}};
            aw_en     <= 1'b1;
        end else begin
            if (!awready_o && awvalid_i && wvalid_i && aw_en) begin
                awready_o <= 1'b1;
                awaddr_q  <= awaddr_i;
                aw_en     <= 1'b0;
            end else if (bvalid_o && bready_i) begin
                awready_o <= 1'b0;
                aw_en     <= 1'b1;
            end else begin
                awready_o <= 1'b0;
            end
        end
    end

    // ---------------- Write data handshake ----------------
    always @(posedge clk_i or negedge rst_n_i) begin
        if (!rst_n_i)
            wready_o <= 1'b0;
        else if (!wready_o && wvalid_i && awvalid_i && aw_en)
            wready_o <= 1'b1;
        else
            wready_o <= 1'b0;
    end

    wire wr_fire = awready_o && awvalid_i && wready_o && wvalid_i;

    // ---------------- Register update + write response ----------------
    always @(posedge clk_i or negedge rst_n_i) begin
        if (!rst_n_i) begin
            beat_o      <= 20'd0;
            start_o     <= 1'b0;
            writeback_o <= 1'b0;
            done_status <= 1'b0;
            bvalid_o    <= 1'b0;
            bresp_o     <= RESP_OKAY;
        end else begin
            // hardware completion sets the done status
            if (done_i)
                done_status <= 1'b1;

            if (wr_fire) begin
                bvalid_o <= 1'b1;
                case (awaddr_q[11:0])
                    OFF_BEAT: begin
                        if (full_strb) beat_o <= wdata_i[19:0];
                        bresp_o <= RESP_OKAY;
                    end
                    OFF_STRT: begin
                        if (full_strb) start_o <= wdata_i[0];
                        bresp_o <= RESP_OKAY;
                    end
                    OFF_DONE: begin
                        // writing LSB=1 clears the done status
                        if (wstrb_i[0] && wdata_i[0]) done_status <= 1'b0;
                        bresp_o <= RESP_OKAY;
                    end
                    OFF_WB: begin
                        if (full_strb) writeback_o <= wdata_i[0];
                        bresp_o <= RESP_OKAY;
                    end
                    OFF_ID:  bresp_o <= RESP_SLVERR;  // read-only
                    default: bresp_o <= RESP_SLVERR;  // invalid address
                endcase
            end else if (bvalid_o && bready_i) begin
                bvalid_o <= 1'b0;
            end
        end
    end

    // ---------------- Read channel ----------------
    always @(posedge clk_i or negedge rst_n_i) begin
        if (!rst_n_i) begin
            arready_o <= 1'b0;
            araddr_q  <= {ADDR_WIDTH{1'b0}};
            rvalid_o  <= 1'b0;
            rdata_o   <= {DATA_WIDTH{1'b0}};
            rresp_o   <= RESP_OKAY;
        end else begin
            if (!arready_o && arvalid_i && !rvalid_o) begin
                arready_o <= 1'b1;
                araddr_q  <= araddr_i;
            end else begin
                arready_o <= 1'b0;
            end

            if (arready_o && arvalid_i && !rvalid_o) begin
                rvalid_o <= 1'b1;
                case (araddr_q[11:0])
                    OFF_BEAT: begin rdata_o <= beat_o;             rresp_o <= RESP_OKAY;   end
                    OFF_STRT: begin rdata_o <= start_o;            rresp_o <= RESP_OKAY;   end
                    OFF_DONE: begin rdata_o <= done_status;        rresp_o <= RESP_OKAY;   end
                    OFF_WB:   begin rdata_o <= writeback_o;        rresp_o <= RESP_OKAY;   end
                    OFF_ID:   begin rdata_o <= 32'h0001_0001;      rresp_o <= RESP_OKAY;   end
                    default:  begin rdata_o <= {DATA_WIDTH{1'b0}}; rresp_o <= RESP_SLVERR; end
                endcase
            end else if (rvalid_o && rready_i) begin
                rvalid_o <= 1'b0;
            end
        end
    end

endmodule

module binary_multiplier #(
    parameter WIDTH = 32          // bit-width of operands A and B (min 1)
)(
    input                      clk,        // positive-edge clock
    input                      rst_n,      // active-low asynchronous reset
    input                      valid_in,   // A and B are valid (1-cycle pulse)
    input      [WIDTH-1:0]     A,          // operand A
    input      [WIDTH-1:0]     B,          // operand B
    output reg                 valid_out,  // Product is valid (1-cycle pulse)
    output reg [2*WIDTH-1:0]   Product     // multiplication result
);

    // Sequential add-shift multiplier.
    //   cycle 1            : latch A/B, raise `start`
    //   cycles 2 .. W+1    : WIDTH shift-and-accumulate steps
    //   cycle  W+2         : register Product, pulse valid_out
    // => Product is registered on the (WIDTH+2)-th clock cycle.
    reg                        start;
    reg [WIDTH-1:0]            a_reg;
    reg [WIDTH-1:0]            b_reg;
    reg [2*WIDTH-1:0]          acc;
    reg [$clog2(WIDTH+3)-1:0]  cnt;

    wire [2*WIDTH-1:0] b_ext = {{WIDTH{1'b0}}, b_reg};

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            start     <= 1'b0;
            a_reg     <= {WIDTH{1'b0}};
            b_reg     <= {WIDTH{1'b0}};
            acc       <= {(2*WIDTH){1'b0}};
            cnt       <= {($clog2(WIDTH+3)){1'b0}};
            Product   <= {(2*WIDTH){1'b0}};
            valid_out <= 1'b0;
        end else begin
            valid_out <= 1'b0;                 // default: single-cycle pulse
            if (valid_in && !start) begin
                a_reg <= A;
                b_reg <= B;
                acc   <= {(2*WIDTH){1'b0}};
                cnt   <= {($clog2(WIDTH+3)){1'b0}};
                start <= 1'b1;
            end else if (start) begin
                if (cnt < WIDTH[$clog2(WIDTH+3)-1:0]) begin
                    if (a_reg[cnt]) acc <= acc + (b_ext << cnt);
                    cnt <= cnt + 1'b1;
                end else begin
                    // cnt == WIDTH : accumulation complete -> emit result
                    Product   <= acc;
                    valid_out <= 1'b1;
                    start     <= 1'b0;
                    cnt       <= {($clog2(WIDTH+3)){1'b0}};
                end
            end
        end
    end

endmodule

module compression_engine (
  input   logic        clk,
  input   logic        reset,
  input   logic [23:0] num_i,
  output  logic [11:0] mantissa_o,
  output  logic [3:0]  exponent_o
);

  // --------------------------------------------------------
  // Internal wires and registers
  // --------------------------------------------------------
  logic [23:12] exp_oh;         // One-hot encoded exponent
  logic [3:0]   exp_bin;        // Binary exponent
  logic [3:0]   exponent;       // Adjusted exponent
  logic [11:0]  mantissa;       // Mantissa

  // --------------------------------------------------------
  // One-Hot Encoding of the Exponent
  // --------------------------------------------------------
  assign exp_oh[23] = num_i[23];

  // exp_oh[i] is set only at the most-significant set bit of num_i within
  // the [23:12] window.
  genvar gi;
  generate
    for (gi = 12; gi <= 22; gi = gi + 1) begin : gen_one_hot
      assign exp_oh[gi] = num_i[gi] & ~(|num_i[23:gi+1]);
    end
  endgenerate

  // Use the `onehot_to_bin` module to convert one-hot to binary exponent
  onehot_to_bin #(
    .ONE_HOT_W(12),
    .BIN_W(4)
  ) exp_oh_bin (
    .oh_vec_i(exp_oh),
    .bin_vec_o(exp_bin)
  );

  assign exponent = (|exp_oh) ? exp_bin + 4'h1 : exp_bin;

  // --------------------------------------------------------
  // Mantissa Extraction Logic
  // --------------------------------------------------------
  // The mantissa holds the 12 bits immediately BELOW the leading set bit
  // (the implicit leading 1 is excluded), as fixed by the worked-example
  // table (e.g. num_i=24'hFFC01D -> mantissa=12'hFF8). When the leading set
  // bit lies below bit 12 (exponent==0) the value already fits, so the
  // mantissa is the low 12 bits directly.
  always @(*) begin
    if (num_i == 24'h000000)
      mantissa = 12'h000;
    else if (exponent == 4'h0)
      mantissa = num_i[11:0];
    else
      // leading set-bit index = 12 + exp_bin; take the 12 bits just below it
      mantissa = num_i[(exp_bin + 5'd11) -: 12];
  end

  // --------------------------------------------------------
  // Output assignments
  // --------------------------------------------------------
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      exponent_o <= 4'd0;
      mantissa_o <= 12'd0;
    end else begin
      exponent_o <= exponent;
      mantissa_o <= mantissa;
    end
  end

endmodule

module onehot_to_bin #(
  parameter ONE_HOT_W = 32,  // Width of the one-hot input
  parameter BIN_W     = 5    // Width of the binary output
)(
  input   wire [ONE_HOT_W-1:0]  oh_vec_i,  // One-hot encoded input
  output  logic [BIN_W-1:0]     bin_vec_o  // Binary encoded output
);

  integer i;

  // Priority-encode the one-hot vector to its binary bit-position index.
  always @(*) begin
    bin_vec_o = {BIN_W{1'b0}};
    for (i = 0; i < ONE_HOT_W; i = i + 1) begin
      if (oh_vec_i[i])
        bin_vec_o = i[BIN_W-1:0];
    end
  end

endmodule

// apb_controller — event-driven APB write-only master.
// Three events (A>B>C priority) each carry a 32-bit address+data.  Two-phase
// APB write (SETUP -> ACCESS) with a 4-bit, 15-cycle timeout watchdog.
module apb_controller (
    input  wire        clk,
    input  wire        reset_n,        // async, active low
    input  wire        select_a_i,
    input  wire        select_b_i,
    input  wire        select_c_i,
    input  wire [31:0] addr_a_i,
    input  wire [31:0] data_a_i,
    input  wire [31:0] addr_b_i,
    input  wire [31:0] data_b_i,
    input  wire [31:0] addr_c_i,
    input  wire [31:0] data_c_i,
    input  wire        apb_pready_i,
    output reg         apb_psel_o,
    output reg         apb_penable_o,
    output reg         apb_pwrite_o,
    output reg  [31:0] apb_paddr_o,
    output reg  [31:0] apb_pwdata_o
);
    localparam [1:0] IDLE = 2'd0, SETUP = 2'd1, ACCESS = 2'd2;

    reg [1:0]  state;
    reg [3:0]  timeout_cnt;

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            state         <= IDLE;
            timeout_cnt   <= 4'd0;
            apb_psel_o    <= 1'b0;
            apb_penable_o <= 1'b0;
            apb_pwrite_o  <= 1'b0;
            apb_paddr_o   <= 32'd0;
            apb_pwdata_o  <= 32'd0;
        end else begin
            case (state)
                IDLE: begin
                    apb_psel_o    <= 1'b0;
                    apb_penable_o <= 1'b0;
                    apb_pwrite_o  <= 1'b0;
                    apb_paddr_o   <= 32'd0;
                    apb_pwdata_o  <= 32'd0;
                    timeout_cnt   <= 4'd0;
                    // capture the highest-priority asserted event -> SETUP
                    if (select_a_i) begin
                        apb_paddr_o  <= addr_a_i;
                        apb_pwdata_o <= data_a_i;
                        apb_psel_o   <= 1'b1;
                        apb_pwrite_o <= 1'b1;
                        state        <= SETUP;
                    end else if (select_b_i) begin
                        apb_paddr_o  <= addr_b_i;
                        apb_pwdata_o <= data_b_i;
                        apb_psel_o   <= 1'b1;
                        apb_pwrite_o <= 1'b1;
                        state        <= SETUP;
                    end else if (select_c_i) begin
                        apb_paddr_o  <= addr_c_i;
                        apb_pwdata_o <= data_c_i;
                        apb_psel_o   <= 1'b1;
                        apb_pwrite_o <= 1'b1;
                        state        <= SETUP;
                    end
                end
                SETUP: begin
                    // psel/pwrite/paddr/pwdata stay asserted from IDLE; raise
                    // penable for the ACCESS phase.
                    apb_penable_o <= 1'b1;
                    timeout_cnt   <= 4'd0;
                    state         <= ACCESS;
                end
                ACCESS: begin
                    if (apb_pready_i) begin
                        // successful transfer -> deassert and return to IDLE
                        apb_psel_o    <= 1'b0;
                        apb_penable_o <= 1'b0;
                        apb_pwrite_o  <= 1'b0;
                        apb_paddr_o   <= 32'd0;
                        apb_pwdata_o  <= 32'd0;
                        timeout_cnt   <= 4'd0;
                        state         <= IDLE;
                    end else if (timeout_cnt == 4'd15) begin
                        // 15 cycles without pready -> abort, all outputs 0
                        apb_psel_o    <= 1'b0;
                        apb_penable_o <= 1'b0;
                        apb_pwrite_o  <= 1'b0;
                        apb_paddr_o   <= 32'd0;
                        apb_pwdata_o  <= 32'd0;
                        timeout_cnt   <= 4'd0;
                        state         <= IDLE;
                    end else begin
                        timeout_cnt <= timeout_cnt + 4'd1;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule

// galois_encryption — GF(2^8) MixColumns-style encrypt/decrypt with a stored
// key, 3-clock output latency (i_valid -> o_valid), async active-low reset.
//   * input/output byte map: byte(r,c) = data[127 - 32*c - 8*r -: 8]
//   * encrypt: Re = M x data_in, then Re[r][c] ^= key_byte[r]
//   * decrypt: data_key = data_in ^ key (per row), then Rd = N x data_key
// GF(2^8) reduction polynomial m(x) = x^8+x^4+x^3+x+1 = 0x11B (0x1B truncated).
module galois_encryption #(
    parameter NBW_DATA = 128,
    parameter NBW_KEY  = 32
)(
    input  wire                  clk,
    input  wire                  rst_async_n,
    input  wire                  i_encrypt,
    input  wire                  i_valid,
    input  wire [NBW_DATA-1:0]   i_data,
    input  wire                  i_update_key,
    input  wire [NBW_KEY-1:0]    i_key,
    output reg                   o_valid,
    output reg  [NBW_DATA-1:0]   o_data
);
    // ---- GF(2^8) multiply ------------------------------------------------
    function automatic [7:0] gfmul(input [7:0] a, input [7:0] b);
        integer i;
        reg [7:0] aa, res;
        reg [7:0] bb;
        begin
            aa  = a;
            bb  = b;
            res = 8'h00;
            for (i = 0; i < 8; i = i + 1) begin
                if (bb[0]) res = res ^ aa;
                if (aa[7]) aa = (aa << 1) ^ 8'h1b;
                else       aa = (aa << 1);
                bb = bb >> 1;
            end
            gfmul = res;
        end
    endfunction

    // ---- stored key ------------------------------------------------------
    reg [NBW_KEY-1:0] key_reg;
    always @(posedge clk or negedge rst_async_n) begin
        if (!rst_async_n)      key_reg <= {NBW_KEY{1'b0}};
        else if (i_update_key) key_reg <= i_key;
    end

    // ---- pipeline stage 1 : capture inputs -------------------------------
    reg               s1_valid, s1_enc;
    reg [NBW_DATA-1:0] s1_data;

    // ---- combinational cipher of the stage-1 word ------------------------
    reg [7:0] din  [0:3][0:3];
    reg [7:0] keyb [0:3];
    reg [7:0] dk   [0:3][0:3];
    reg [7:0] mix  [0:3][0:3];
    reg [NBW_DATA-1:0] cipher_res;
    integer r, c;
    always @(*) begin
        keyb[0] = key_reg[31:24];
        keyb[1] = key_reg[23:16];
        keyb[2] = key_reg[15:8];
        keyb[3] = key_reg[7:0];
        for (r = 0; r < 4; r = r + 1)
            for (c = 0; c < 4; c = c + 1)
                din[r][c] = s1_data[(127 - 32*c - 8*r) -: 8];

        if (s1_enc) begin
            // Re = M x data_in, M = [[2,3,1,1],[1,2,3,1],[1,1,2,3],[3,1,1,2]]
            for (c = 0; c < 4; c = c + 1) begin
                mix[0][c] = gfmul(din[0][c],8'h02) ^ gfmul(din[1][c],8'h03)
                          ^ din[2][c]              ^ din[3][c];
                mix[1][c] = din[0][c]              ^ gfmul(din[1][c],8'h02)
                          ^ gfmul(din[2][c],8'h03) ^ din[3][c];
                mix[2][c] = din[0][c]              ^ din[1][c]
                          ^ gfmul(din[2][c],8'h02) ^ gfmul(din[3][c],8'h03);
                mix[3][c] = gfmul(din[0][c],8'h03) ^ din[1][c]
                          ^ din[2][c]              ^ gfmul(din[3][c],8'h02);
            end
            // XOR key byte into every column of its row
            for (r = 0; r < 4; r = r + 1)
                for (c = 0; c < 4; c = c + 1)
                    mix[r][c] = mix[r][c] ^ keyb[r];
        end else begin
            // decrypt: data_key = data ^ key (per row) ...
            for (r = 0; r < 4; r = r + 1)
                for (c = 0; c < 4; c = c + 1)
                    dk[r][c] = din[r][c] ^ keyb[r];
            // ... then Rd = N x data_key,
            // N = [[0e,0b,0d,09],[09,0e,0b,0d],[0d,09,0e,0b],[0b,0d,09,0e]]
            for (c = 0; c < 4; c = c + 1) begin
                mix[0][c] = gfmul(dk[0][c],8'h0e) ^ gfmul(dk[1][c],8'h0b)
                          ^ gfmul(dk[2][c],8'h0d) ^ gfmul(dk[3][c],8'h09);
                mix[1][c] = gfmul(dk[0][c],8'h09) ^ gfmul(dk[1][c],8'h0e)
                          ^ gfmul(dk[2][c],8'h0b) ^ gfmul(dk[3][c],8'h0d);
                mix[2][c] = gfmul(dk[0][c],8'h0d) ^ gfmul(dk[1][c],8'h09)
                          ^ gfmul(dk[2][c],8'h0e) ^ gfmul(dk[3][c],8'h0b);
                mix[3][c] = gfmul(dk[0][c],8'h0b) ^ gfmul(dk[1][c],8'h0d)
                          ^ gfmul(dk[2][c],8'h09) ^ gfmul(dk[3][c],8'h0e);
            end
        end

        cipher_res = {NBW_DATA{1'b0}};
        for (r = 0; r < 4; r = r + 1)
            for (c = 0; c < 4; c = c + 1)
                cipher_res[(127 - 32*c - 8*r) -: 8] = mix[r][c];
    end

    // ---- pipeline stage 2 : register the cipher result -------------------
    reg               s2_valid;
    reg [NBW_DATA-1:0] s2_res;

    always @(posedge clk or negedge rst_async_n) begin
        if (!rst_async_n) begin
            s1_valid <= 1'b0; s1_enc <= 1'b0; s1_data <= {NBW_DATA{1'b0}};
            s2_valid <= 1'b0; s2_res <= {NBW_DATA{1'b0}};
            o_valid  <= 1'b0; o_data <= {NBW_DATA{1'b0}};
        end else begin
            // stage 1
            s1_valid <= i_valid;
            s1_enc   <= i_encrypt;
            s1_data  <= i_data;
            // stage 2
            s2_valid <= s1_valid;
            s2_res   <= cipher_res;
            // stage 3 (outputs) — 3-cycle latency from i_valid to o_valid
            o_valid  <= s2_valid;
            o_data   <= s2_valid ? s2_res : {NBW_DATA{1'b0}};
        end
    end
endmodule

// Hill cipher encryption: 3-letter blocks (5 bits/letter), 3x3 key matrix,
// all arithmetic mod 26.  Ciphertext_i = (sum_j K_ij * P_j) mod 26.
// Latency: 3 clock cycles from `start` HIGH to a valid ciphertext.
module hill_cipher (
    input  wire        clk,
    input  wire        reset,        // asynchronous, active HIGH; clears ciphertext
    input  wire        start,        // HIGH initiates an encryption
    input  wire [14:0] plaintext,    // [14:10]=P0, [9:5]=P1, [4:0]=P2
    input  wire [44:0] key,          // 3x3 matrix, 5 bits/element, row-major
    output reg  [14:0] ciphertext,   // [14:10]=C0, [9:5]=C1, [4:0]=C2
    output reg         done          // HIGH when encryption is complete
);

    // FSM states
    localparam IDLE   = 2'd0;
    localparam MUL    = 2'd1;
    localparam MODST  = 2'd2;
    localparam FINISH = 2'd3;

    reg [1:0]  state;

    // Latched operands
    reg [14:0] pt_reg;
    reg [44:0] key_reg;

    // Dot-product accumulators (max 25*25*3 = 1875 -> 11 bits, use 12)
    reg [11:0] sum0_reg, sum1_reg, sum2_reg;

    // Plaintext letters
    wire [4:0] p0 = pt_reg[14:10];
    wire [4:0] p1 = pt_reg[9:5];
    wire [4:0] p2 = pt_reg[4:0];

    // Key matrix elements
    wire [4:0] k00 = key_reg[44:40];
    wire [4:0] k01 = key_reg[39:35];
    wire [4:0] k02 = key_reg[34:30];
    wire [4:0] k10 = key_reg[29:25];
    wire [4:0] k11 = key_reg[24:20];
    wire [4:0] k12 = key_reg[19:15];
    wire [4:0] k20 = key_reg[14:10];
    wire [4:0] k21 = key_reg[9:5];
    wire [4:0] k22 = key_reg[4:0];

    // mod-26 reductions of the accumulated dot products
    wire [4:0] c0 = sum0_reg % 12'd26;
    wire [4:0] c1 = sum1_reg % 12'd26;
    wire [4:0] c2 = sum2_reg % 12'd26;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state      <= IDLE;
            ciphertext <= 15'd0;
            done       <= 1'b0;
            pt_reg     <= 15'd0;
            key_reg    <= 45'd0;
            sum0_reg   <= 12'd0;
            sum1_reg   <= 12'd0;
            sum2_reg   <= 12'd0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        pt_reg  <= plaintext;
                        key_reg <= key;
                        state   <= MUL;
                    end
                end
                MUL: begin
                    sum0_reg <= (k00 * p0) + (k01 * p1) + (k02 * p2);
                    sum1_reg <= (k10 * p0) + (k11 * p1) + (k12 * p2);
                    sum2_reg <= (k20 * p0) + (k21 * p1) + (k22 * p2);
                    state    <= MODST;
                end
                MODST: begin
                    ciphertext <= {c0, c1, c2};
                    done       <= 1'b1;
                    state      <= FINISH;
                end
                FINISH: begin
                    done <= 1'b1;          // hold done until re-armed
                    if (!start)
                        state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end

endmodule

// Manchester Encoder — latch-inference bug fixed by registering the output
// with an explicit else that drives the spec-mandated 0 when idle.
//
// Encoding convention (MSB-first, IEEE 802.3): each data bit becomes two
// line bits.  data bit 0 -> 2'b10 , data bit 1 -> 2'b01.
// enc_data_in[N-1] maps to enc_data_out[2N-1:2N-2].
module manchester_encoder #(
    parameter N = 8
)(
    input  wire            clk_in,
    input  wire            rst_in,        // active-high synchronous reset
    input  wire            enc_valid_in,
    input  wire [N-1:0]    enc_data_in,
    output reg             enc_valid_out,
    output reg  [2*N-1:0]  enc_data_out
);

    integer k;
    reg [2*N-1:0] enc_comb;

    // Combinational Manchester map of the current input word.
    always @(*) begin
        enc_comb = {(2*N){1'b0}};
        for (k = 0; k < N; k = k + 1) begin
            // bit 0 -> "10", bit 1 -> "01"
            enc_comb[2*k +: 2] = enc_data_in[k] ? 2'b01 : 2'b10;
        end
    end

    // Registered outputs.  Every branch assigns both outputs, so no latch is
    // inferred and the idle/reset value is a clean all-zero word.
    always @(posedge clk_in) begin
        if (rst_in) begin
            enc_data_out  <= {(2*N){1'b0}};
            enc_valid_out <= 1'b0;
        end else if (enc_valid_in) begin
            enc_data_out  <= enc_comb;
            enc_valid_out <= 1'b1;
        end else begin
            enc_data_out  <= {(2*N){1'b0}};
            enc_valid_out <= 1'b0;
        end
    end

endmodule

// Pipelined Modified Booth Multiplier — 16x16 signed, radix-4 Booth recoding.
// 5 pipeline stages (1 cycle each); total input->output latency = 5 cycles.
// Asynchronous active-high reset clears all registers and outputs to zero.
module pipelined_modified_booth_multiplier (
    input  wire               clk,
    input  wire               rst,    // asynchronous active-high reset
    input  wire               start,  // active-high: begin a multiplication
    input  wire signed [15:0] X,
    input  wire signed [15:0] Y,
    output reg         [31:0] result, // 32-bit signed product
    output reg                done
);

    // ---- radix-4 Booth recode of one 3-bit group -> multiple of X (sign-extended to 32) ----
    function signed [31:0] booth_term;
        input signed [31:0] x32;
        input        [2:0]  g;
        begin
            case (g)
                3'b001, 3'b010: booth_term =  x32;          // +X
                3'b011:         booth_term =  (x32 <<< 1);   // +2X
                3'b100:         booth_term = -(x32 <<< 1);   // -2X
                3'b101, 3'b110: booth_term = -x32;          // -X
                default:        booth_term = 32'sd0;         // 000 / 111 -> 0
            endcase
        end
    endfunction

    // ---------------- Stage 1: input register + control valid ----------------
    reg signed [15:0] x_s1, y_s1;
    reg               v_s1;

    // ---------------- Stage 2: partial products ----------------
    reg signed [31:0] pp0, pp1, pp2, pp3, pp4, pp5, pp6, pp7;
    reg               v_s2;

    // ---------------- Stage 3: first reduction ----------------
    reg signed [31:0] sumA, sumB;
    reg               v_s3;

    // ---------------- Stage 4: final summation ----------------
    reg signed [31:0] total;
    reg               v_s4;

    // sign-extended multiplicand and the eight overlapping Booth groups of y_s1
    wire signed [31:0] x32 = {{16{x_s1[15]}}, x_s1};
    wire [2:0] g0 = { y_s1[1],  y_s1[0],  1'b0      };
    wire [2:0] g1 = { y_s1[3],  y_s1[2],  y_s1[1]   };
    wire [2:0] g2 = { y_s1[5],  y_s1[4],  y_s1[3]   };
    wire [2:0] g3 = { y_s1[7],  y_s1[6],  y_s1[5]   };
    wire [2:0] g4 = { y_s1[9],  y_s1[8],  y_s1[7]   };
    wire [2:0] g5 = { y_s1[11], y_s1[10], y_s1[9]   };
    wire [2:0] g6 = { y_s1[13], y_s1[12], y_s1[11]  };
    wire [2:0] g7 = { y_s1[15], y_s1[14], y_s1[13]  };

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            x_s1 <= 16'sd0; y_s1 <= 16'sd0; v_s1 <= 1'b0;
            pp0 <= 32'sd0; pp1 <= 32'sd0; pp2 <= 32'sd0; pp3 <= 32'sd0;
            pp4 <= 32'sd0; pp5 <= 32'sd0; pp6 <= 32'sd0; pp7 <= 32'sd0;
            v_s2 <= 1'b0;
            sumA <= 32'sd0; sumB <= 32'sd0; v_s3 <= 1'b0;
            total <= 32'sd0; v_s4 <= 1'b0;
            result <= 32'd0; done <= 1'b0;
        end else begin
            // Stage 1
            x_s1 <= X;
            y_s1 <= Y;
            v_s1 <= start;

            // Stage 2 : Booth-encode + partial-product generation (each shifted 2*i)
            pp0 <= booth_term(x32, g0) <<< 0;
            pp1 <= booth_term(x32, g1) <<< 2;
            pp2 <= booth_term(x32, g2) <<< 4;
            pp3 <= booth_term(x32, g3) <<< 6;
            pp4 <= booth_term(x32, g4) <<< 8;
            pp5 <= booth_term(x32, g5) <<< 10;
            pp6 <= booth_term(x32, g6) <<< 12;
            pp7 <= booth_term(x32, g7) <<< 14;
            v_s2 <= v_s1;

            // Stage 3 : partial-product reduction
            sumA <= pp0 + pp1 + pp2 + pp3;
            sumB <= pp4 + pp5 + pp6 + pp7;
            v_s3 <= v_s2;

            // Stage 4 : final summation
            total <= sumA + sumB;
            v_s4  <= v_s3;

            // Stage 5 : output result (held stable until next valid) + done strobe
            if (v_s4)
                result <= total;
            done <= v_s4;
        end
    end
endmodule

module restoring_division #(
    parameter WIDTH = 6
)(
    input  wire             clk,        // Clock signal
    input  wire             rst,        // Active-low asynchronous reset
    input  wire             start,      // Active-high start
    input  wire [WIDTH-1:0] dividend,   // Dividend
    input  wire [WIDTH-1:0] divisor,    // Divisor
    output reg  [WIDTH-1:0] quotient,   // Quotient
    output reg  [WIDTH-1:0] remainder,  // Remainder
    output reg              valid       // Active-high one-cycle completion strobe
);

    localparam IDLE = 2'd0,
               BUSY = 2'd1;

    reg [1:0]                 state;
    reg [WIDTH-1:0]           div_reg;    // latched divisor
    reg [WIDTH-1:0]           dvnd_reg;   // remaining dividend bits (MSB shifted out)
    reg [WIDTH:0]             rem_reg;    // WIDTH+1 bit partial remainder
    reg [WIDTH-1:0]           quot_reg;   // quotient under construction
    reg [$clog2(WIDTH+1):0]   cnt;        // iteration counter

    // One restoring-division step (combinational):
    //   shift the remainder left, bring in the next dividend MSB, then try
    //   to subtract the divisor.  A non-negative result means the divisor
    //   fits -> quotient bit 1 and keep the difference; otherwise restore.
    wire [WIDTH:0] rem_shifted = {rem_reg[WIDTH-1:0], dvnd_reg[WIDTH-1]};
    wire [WIDTH:0] sub_res     = rem_shifted - {1'b0, div_reg};
    wire           fits        = ~sub_res[WIDTH];
    wire [WIDTH:0] rem_next    = fits ? sub_res : rem_shifted;
    wire [WIDTH-1:0] quot_next = {quot_reg[WIDTH-2:0], fits};

    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            state     <= IDLE;
            quotient  <= {WIDTH{1'b0}};
            remainder <= {WIDTH{1'b0}};
            valid     <= 1'b0;
            div_reg   <= {WIDTH{1'b0}};
            dvnd_reg  <= {WIDTH{1'b0}};
            rem_reg   <= {(WIDTH+1){1'b0}};
            quot_reg  <= {WIDTH{1'b0}};
            cnt       <= {($clog2(WIDTH+1)+1){1'b0}};
        end else begin
            case (state)
                IDLE: begin
                    valid <= 1'b0;
                    if (start) begin
                        div_reg  <= divisor;
                        dvnd_reg <= dividend;
                        rem_reg  <= {(WIDTH+1){1'b0}};
                        quot_reg <= {WIDTH{1'b0}};
                        cnt      <= {($clog2(WIDTH+1)+1){1'b0}};
                        state    <= BUSY;
                    end
                end
                BUSY: begin
                    rem_reg  <= rem_next;
                    quot_reg <= quot_next;
                    dvnd_reg <= {dvnd_reg[WIDTH-2:0], 1'b0};
                    cnt      <= cnt + 1'b1;
                    if (cnt == (WIDTH-1)) begin
                        // final iteration : present the result and pulse valid
                        quotient  <= quot_next;
                        remainder <= rem_next[WIDTH-1:0];
                        valid     <= 1'b1;
                        state     <= IDLE;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

endmodule

module run_length
#(
    parameter DATA_WIDTH = 8                          // Width of the output run-length counter
)
(
    input  wire                          clk,         // Clock signal
    input  wire                          reset_n,     // Active-low reset signal
    input  wire                          data_in,     // Input data stream
    output reg                           data_out,    // Output data to indicate the previous data_in
    output reg  [$clog2(DATA_WIDTH):0]   run_value,   // Output the run length value
    output reg                           valid        // Output valid flag for run length
);

    reg [$clog2(DATA_WIDTH):0] run_length;
    reg                        prev_data_in;

    // ----------------------------------------------------------------
    // Run-length counting and run_value update
    //   - matching data_in  : increment the consecutive-run counter,
    //     saturating at DATA_WIDTH (then emit the run and restart at 1)
    //   - differing data_in : a transition, emit the previous run and
    //     restart the counter at 1 for the new value
    // ----------------------------------------------------------------
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            run_length   <= 'b0;
            run_value    <= 'b0;
            prev_data_in <= 1'b0;
        end else begin
            if (data_in == prev_data_in) begin
                if (run_length >= DATA_WIDTH[$clog2(DATA_WIDTH):0]) begin
                    // saturation : emit the full run, restart at 1
                    run_value  <= run_length;
                    run_length <= 'd1;
                end else begin
                    run_length <= run_length + 'd1;
                end
            end else begin
                // transition : emit the previous run length, restart at 1
                run_value  <= run_length;
                run_length <= 'd1;
            end
            prev_data_in <= data_in;
        end
    end

    // ----------------------------------------------------------------
    // valid / data_out generation
    //   valid is HIGH on a transition OR when the run saturates at
    //   DATA_WIDTH, and LOW otherwise (one-cycle pulse behaviour).
    // ----------------------------------------------------------------
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            valid    <= 1'b0;
            data_out <= 1'b0;
        end else begin
            if (data_in != prev_data_in) begin
                valid    <= 1'b1;
                data_out <= prev_data_in;
            end else if (run_length >= DATA_WIDTH[$clog2(DATA_WIDTH):0]) begin
                valid    <= 1'b1;
                data_out <= prev_data_in;
            end else begin
                valid    <= 1'b0;
            end
        end
    end

endmodule

module sorting_engine #(
    parameter N = 8,
    parameter WIDTH = 8
)(
    input  wire                clk,
    input  wire                rst,
    input  wire                start,
    input  wire [N*WIDTH-1:0]  in_data,
    output reg                 done,
    output reg [N*WIDTH-1:0]   out_data
);
    localparam IDLE = 2'd0,
               LOAD = 2'd1,
               SORT = 2'd2,
               DONE = 2'd3;

    reg [1:0]  state, next_state;
    reg [WIDTH-1:0] data_array [0:N-1];
    reg [$clog2(N+1)-1:0] pass_cnt;
    reg [$clog2(N/2+1)-1:0] pair_idx;

    wire [$clog2(N/2+1)-1:0] pairs_in_this_pass;
    assign pairs_in_this_pass = (pass_cnt[0] == 1'b0) ? (N/2) : ( (N/2) > 0 ? (N/2) - 1 : 0 );

    integer i;
    integer lo;
    integer hi;

    // ---- next-state (combinational) ----
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: if (start) next_state = LOAD;
            LOAD: next_state = SORT;
            SORT: if (pass_cnt >= N) next_state = DONE;
            DONE: next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end

    // ---- datapath / sequential ----
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state    <= IDLE;
            done     <= 1'b0;
            pass_cnt <= 0;
            pair_idx <= 0;
            for (i = 0; i < N; i = i + 1)
                data_array[i] <= {WIDTH{1'b0}};
            // out_data intentionally left uninitialized at reset (per spec)
        end else begin
            state <= next_state;
            done  <= 1'b0;
            case (state)
                IDLE: begin
                    if (start) begin
                        pass_cnt <= 0;
                        pair_idx <= 0;
                    end
                end
                LOAD: begin
                    for (i = 0; i < N; i = i + 1)
                        data_array[i] <= in_data[i*WIDTH +: WIDTH];
                    pass_cnt <= 0;
                    pair_idx <= 0;
                end
                SORT: begin
                    if (pass_cnt < N) begin
                        if (pairs_in_this_pass == 0) begin
                            // empty (odd) pass for very small N — just advance
                            pair_idx <= 0;
                            pass_cnt <= pass_cnt + 1'b1;
                        end else begin
                            // index of the low element of the current pair
                            if (pass_cnt[0] == 1'b0)
                                lo = pair_idx << 1;        // even pass: (0,1),(2,3)...
                            else
                                lo = (pair_idx << 1) + 1;  // odd  pass: (1,2),(3,4)...
                            hi = lo + 1;
                            // compare-and-swap (ascending: smallest toward index 0)
                            if (data_array[lo] > data_array[hi]) begin
                                data_array[lo] <= data_array[hi];
                                data_array[hi] <= data_array[lo];
                            end
                            // advance pair / pass counters (one compare-swap per cycle)
                            if (pair_idx >= (pairs_in_this_pass - 1)) begin
                                pair_idx <= 0;
                                pass_cnt <= pass_cnt + 1'b1;
                            end else begin
                                pair_idx <= pair_idx + 1'b1;
                            end
                        end
                    end
                end
                DONE: begin
                    for (i = 0; i < N; i = i + 1)
                        out_data[i*WIDTH +: WIDTH] <= data_array[i];
                    done <= 1'b1;
                end
                default: ;
            endcase
        end
    end
endmodule

module ttc_counter_lite (
    input  wire        clk,
    input  wire        reset,        // active-high synchronous reset
    input  wire [3:0]  axi_addr,
    input  wire [31:0] axi_wdata,
    input  wire        axi_write_en,
    input  wire        axi_read_en,
    output reg  [31:0] axi_rdata,
    output reg         interrupt
);
    // Register-map addresses
    localparam [3:0] ADDR_COUNT   = 4'h0,
                     ADDR_MATCH   = 4'h1,
                     ADDR_RELOAD  = 4'h2,
                     ADDR_CONTROL = 4'h3,
                     ADDR_STATUS  = 4'h4;

    reg [15:0] count;
    reg [15:0] match_value;
    reg [15:0] reload_value;

    reg        enable;
    reg        interval_mode;
    reg        interrupt_enable;

    reg        matched;   // tracks that the current match has already been seen

    wire match = enable && (count == match_value);

    // ---------------- write / counter / interrupt ----------------
    always @(posedge clk) begin
        if (reset) begin
            count            <= 16'd0;
            match_value      <= 16'd0;
            reload_value     <= 16'd0;
            enable           <= 1'b0;
            interval_mode    <= 1'b0;
            interrupt_enable <= 1'b0;
            interrupt        <= 1'b0;
            matched          <= 1'b0;
        end else begin
            // ---- counter ----
            if (enable) begin
                if (count == match_value) begin
                    if (interval_mode)
                        count <= reload_value;   // interval mode: reload on match
                    else
                        count <= match_value;    // one-shot mode: hold at match
                end else begin
                    count <= count + 16'd1;
                end
            end

            // ---- match-event bookkeeping (one-shot per match) ----
            if (match)
                matched <= 1'b1;
            else
                matched <= 1'b0;

            // ---- interrupt: set on a new match (if enabled), cleared on
            //      a write to the status register (clear has priority) ----
            if (axi_write_en && (axi_addr == ADDR_STATUS))
                interrupt <= 1'b0;
            else if (match && !matched && interrupt_enable)
                interrupt <= 1'b1;

            // ---- register writes ----
            if (axi_write_en) begin
                case (axi_addr)
                    ADDR_MATCH:   match_value  <= axi_wdata[15:0];
                    ADDR_RELOAD:  reload_value <= axi_wdata[15:0];
                    ADDR_CONTROL: begin
                        enable           <= axi_wdata[0];
                        interval_mode    <= axi_wdata[1];
                        interrupt_enable <= axi_wdata[2];
                    end
                    default: ;
                endcase
            end
        end
    end

    // ---------------- read (combinational) ----------------
    always @(*) begin
        case (axi_addr)
            ADDR_COUNT:   axi_rdata = {16'd0, count};
            ADDR_MATCH:   axi_rdata = {16'd0, match_value};
            ADDR_RELOAD:  axi_rdata = {16'd0, reload_value};
            ADDR_CONTROL: axi_rdata = {29'd0, interrupt_enable, interval_mode, enable};
            ADDR_STATUS:  axi_rdata = {31'd0, interrupt};
            default:      axi_rdata = 32'd0;
        endcase
    end

endmodule
